void freeMemory(void** ptr) {
    if (*ptr != NULL) {
        free(*ptr);
        *ptr = NULL;
    }
}

int main() {
    long* offsets = malloc(sizeof(long) * MAX_SIZE);
    int* keys = malloc(sizeof(int) * MAX_SIZE);
    Record* records = malloc(sizeof(Record) * MAX_SIZE);

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    int numRecords = 500;
    int minValue = 10;
    int maxValue = 100;

    populateRecords(records, numRecords, minValue, maxValue);

    // Use the records in your larger application context here

    freeMemory((void**)&offsets);
    freeMemory((void**)&keys);
    freeMemory((void**)&records);

    return 0;
}
