#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILES 100
#define PROGRESS_INTERVAL 1000

typedef struct {
    int line_count;
    FILE *output_file;
} FileData;

void print_usage() {
    fprintf(stderr, "Usage: program [options] [input_files]\n");
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  --manpage   Show this manual\n");
    fprintf(stderr, "  -cs         Custom option\n");
    fprintf(stderr, "  -o output_file Output to file instead of stdout\n");
}

void parse_arguments(int argc, char *argv[], FileData files[], int *file_count, int *show_manpage, int *custom_option, char **output_file) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            *show_manpage = 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            *custom_option = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            *output_file = argv[++i];
        } else {
            files[*file_count].output_file = NULL;
            if (*output_file != NULL) {
                files[*file_count].output_file = fopen(*output_file, "a");
            }
            files[*file_count].line_count = 0;
            files[(*file_count)++].output_file = *output_file ? fopen(argv[i], "r") : stdin;
        }
    }
}

void process_files(FileData files[], int file_count) {
    for (int i = 0; i < file_count; i++) {
        FILE *input_file = files[i].output_file == NULL ? stdin : files[i].output_file;
        if (input_file != NULL) {
            char buffer[1024];
            long lines_read = 0;
            while (fgets(buffer, sizeof(buffer), input_file) != NULL) {
                files[i].line_count++;
                if (++lines_read % PROGRESS_INTERVAL == 0) {
                    fprintf(stderr, "Processing file %d: Line %ld\r", i + 1, lines_read);
                }
            }
            if (input_file != stdin) {
                fclose(input_file);
            }
        } else {
            fprintf(stderr, "Error opening input file\n");
        }
    }
}

void output_results(FileData files[], int file_count) {
    for (int i = 0; i < file_count; i++) {
        if (files[i].output_file == NULL) {
            printf("File %d: %d lines\n", i + 1, files[i].line_count);
        }
    }
}

int main(int argc, char *argv[]) {
    FileData files[MAX_FILES];
    int file_count = 0;
    int show_manpage = 0;
    int custom_option = 0;
    char *output_file = NULL;

    parse_arguments(argc, argv, files, &file_count, &show_manpage, &custom_option, &output_file);

    if (show_manpage) {
        print_usage();
        return 0;
    }

    process_files(files, file_count);
    output_results(files, file_count);

    for (int i = 0; i < file_count; i++) {
        if (files[i].output_file != NULL && files[i].output_file != stdout) {
            fclose(files[i].output_file);
        }
    }

    return 0;
}
