#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/time.h>

#define MAX_IP_LEN 16
#define CACHE_SIZE 100
#define MAX_CONCURRENT_REQUESTS 50

typedef struct {
    char hostname[MAX_IP_LEN];
    uint32_t ip;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_mutex;
struct timeval last_log_time;

void log_event(const char* message) {
    struct timeval now;
    gettimeofday(&now, NULL);
    if (tv_subtract(&now, &last_log_time) > 1) {
        printf("%s\n", message);
        last_log_time = now;
    }
}

int tv_subtract(struct timeval *t2, const struct timeval *t1) {
    return t2->tv_sec - t1->tv_sec + (t2->tv_usec - t1->tv_usec) / 1000000.0;
}

void* dns_worker(void* arg) {
    char* hostname = (char*)arg;
    uint32_t ip;
    int ret;

    while (1) {
        ret = resolve_dns(hostname, &ip);
        if (ret == 0) {
            log_event("DNS resolution successful");
        } else {
            log_event("DNS resolution failed");
        }
        sleep(1); // Simulate work
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    char hostnames[MAX_CONCURRENT_REQUESTS][MAX_IP_LEN];

    pthread_mutex_init(&cache_mutex, NULL);
    gettimeofday(&last_log_time, NULL);

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        snprintf(hostnames[i], MAX_IP_LEN, "host%d.com", i % 10);
        pthread_create(&threads[i], NULL, dns_worker, hostnames[i]);
    }

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&cache_mutex);

    return 0;
}

int resolve_dns(const char* hostname, uint32_t* ip) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_event(gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        *ip = ipv4->sin_addr.s_addr;

        freeaddrinfo(res); // free the linked list

        return 0;
    }

    freeaddrinfo(res);
    return -1;
}
```

This code provides a basic structure for implementing a DNS resolver with caching, error handling, and concurrency. The `resolve_dns` function uses standard library functions to perform DNS resolution. The cache is implemented as a simple array of `CacheEntry` structures, and a mutex is used to ensure thread safety. The `main` function creates multiple threads to simulate concurrent DNS resolution requests. The code includes logging for successful and failed resolutions, and it can be extended with additional features such as dynamic adjustment of concurrent request limits based on system load.']

