#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024 * 1024 // 1MB
#define LOG_FILE_PATH "/var/log/myapp.log"
#define DUPLICATE_TIME_WINDOW 5 // seconds

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct {
    FILE* logFile;
    time_t lastLoggedTime[1024];
    char lastLogMessage[1024];
    pthread_mutex_t lock;
} LogContext;

void init_log(LogContext* context, const char* filePath) {
    context->logFile = fopen(filePath, "a");
    if (!context->logFile) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < 1024; ++i) {
        context->lastLoggedTime[i] = 0;
        context->lastLogMessage[i][0] = '\0';
    }
    pthread_mutex_init(&context->lock, NULL);
}

void log_message(LogContext* context, LogLevel level, const char* format, ...) {
    pthread_mutex_lock(&context->lock);

    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char buffer[MAX_LOG_SIZE];
    vsnprintf(buffer, sizeof(buffer), format, args);

    if (context->logFile) {
        fprintf(context->logFile, "[%s] [%s] %s\n", timestamp, level == LOG_ERROR ? "ERROR" : level == LOG_WARNING ? "WARNING" : "INFO", buffer);
        fflush(context->logFile);
    }

    va_end(args);

    // Check for duplicate entries within the time window
    size_t hash = 0;
    for (char* p = buffer; *p != '\0'; ++p) {
        hash += *p;
    }
    if (hash == context->lastLogMessage[log_message_id] && now - context->lastLoggedTime[log_message_id] < DUPLICATE_TIME_WINDOW) {
        pthread_mutex_unlock(&context->lock);
        return;
    }

    // Update last logged time and message
    strcpy(context->lastLogMessage[hash], buffer);
    context->lastLoggedTime[hash] = now;

    pthread_mutex_unlock(&context->lock);
}

void rotate_logs(LogContext* context) {
    pthread_mutex_lock(&context->lock);

    if (fseek(context->logFile, 0, SEEK_END) != 0 || ftell(context->logFile) > MAX_LOG_SIZE) {
        fclose(context->logFile);
        rename(LOG_FILE_PATH, "/var/log/myapp.log.old");
        context->logFile = fopen(LOG_FILE_PATH, "w");
    }

    pthread_mutex_unlock(&context->lock);
}

void cleanup_log(LogContext* context) {
    pthread_mutex_destroy(&context->lock);
    if (context->logFile) fclose(context->logFile);
}
