bool validate_oauth2_token(const char *json_string) {
    json_object *jobj = json_tokener_parse(json_string);
    if (!jobj) return false;

    json_object *access_token, *expires_in, *token_type, *refresh_token;
    if (json_object_object_get_ex(jobj, "access_token", &access_token) &&
        json_object_object_get_ex(jobj, "expires_in", &expires_in) &&
        json_object_object_get_ex(jobj, "token_type", &token_type)) {

        int expires_in_value;
        if (json_is_number(expires_in) && 
            json_object_get_int(&expires_in) > 0 &&
            strcmp(json_object_get_string(token_type), "Bearer") == 0) {

            if (json_object_object_get_ex(jobj, "refresh_token", &refresh_token)) {
                // Additional checks for refresh_token can be added here
                return true;
            } else {
                return true; // No refresh_token is optional
            }
        }
    }

    json_object_put(jobj);
    return false;
}
