public class KickstartModifier {

    public static String modifyKickstartConfig(Map<String, String> parameters, Pokemon pokemon) {
        try {
            // Modify Kickstart config file using sed commands
            executeSedCommand(parameters, "s/PLACEHOLDER_USERNAME/" + parameters.get("username") + "/");
            executeSedCommand(parameters, "s/PLACEHOLDER_PASSWORD/" + encryptPassword(parameters.get("password")) + "/");

            // Insert encrypted password as a new line in the Kickstart config file
            insertEncryptedPassword(parameters);

            // Determine Pokemon weaknesses based on its type
            return getPokemonWeaknesses(pokemon.getType());
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
            return "Error occurred while modifying Kickstart configuration.";
        }
    }

    private static void executeSedCommand(Map<String, String> parameters, String command) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec("sed -i '" + command + "' /path/to/kickstart/config");
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Sed command failed with exit code " + exitCode);
        }
    }

    private static String encryptPassword(String password) {
        // Placeholder for encryption logic
        return "ENC:" + password;
    }

    private static void insertEncryptedPassword(Map<String, String> parameters) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec("echo '" + encryptPassword(parameters.get("password")) + "' >> /path/to/kickstart/config");
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Failed to insert encrypted password with exit code " + exitCode);
        }
    }

    private static String getPokemonWeaknesses(String type) {
        switch (type.toLowerCase()) {
            case "fire":
                return "Water, Ground, Rock";
            case "water":
                return "Fire, Grass, Electric";
            case "grass":
                return "Fire, Ice, Flying, Bug, Rock";
            case "electric":
                return "Ground";
            case "ice":
                return "Fire, Fighting, Rock, Steel";
            case "fighting":
                return "Flying, Psychology, Fairy";
            case "poison":
                return "Psychology, Ground";
            case "ground":
                return "Water, Ice, Steel, Grass, Electric, Fire, Poison";
            case "flying":
                return "Electric, Ice, Rock";
            case "psychic":
                return "Bug, Ghost, Dark";
            case "bug":
                return "Fire, Flying, Rock";
            case "rock":
                return "Water, Ground, Steel, Fighting, Grass";
            case "ghost":
                return "Ghost, Psychology";
            case "dragon":
                return "Psychology, Ice, Dragon";
            case "dark":
                return "Fighting, Fairy";
            case "steel":
                return "Fire, Water, Flying, Psychic, Ice, Rock, Bug, Ghost, Dark, Dragon";
            default:
                return "Unknown type";
        }
    }

