import java.util.HashMap;
import java.util.Map;

public class PokemonReportGenerator {
    private static final Map<String, String> typeWeaks = new HashMap<>();
    private static final Map<String, String> typeResists = new HashMap<>();
    private static final Map<String, Boolean> cache = new HashMap<>();

    static {
        // Initialize type weaknesses and resistances
        initializeTypeData();
    }

    public static void main(String[] args) {
        Pokemon pokemon = new Pokemon("Pikachu", "Electric");
        System.out.println(generateReport(pokemon));
    }

    public static String generateReport(Pokemon pokemon) {
        String name = pokemon.getName();
        String type = pokemon.getType();
        String weaknesses = getWeaknesses(type);
        String resistances = getResistances(type);

        if (weaknesses == null || resistances == null) {
            return "Unsupported Pokemon type: " + type;
        }

        StringBuilder report = new StringBuilder();
        report.append("Name: ").append(name).append("\n");
        report.append("Type: ").append(type).append("\n");
        report.append("Weaknesses: ").append(weaknesses).append("\n");
        report.append("Resistances: ").append(resistances).append("\n");

        String habitat = fetchHabitat(pokemon);
        if (habitat != null) {
            report.append("Habitat: ").append(habitat).append("\n");
        }

        String evolutionLineage = fetchEvolutionLineage(pokemon);
        if (evolutionLineage != null) {
            report.append("Evolution Lineage: ").append(evolutionLineage).append("\n");
        }

        return report.toString();
    }

    private static String getWeaknesses(String type) {
        return cache.computeIfAbsent(type + "_weak", t -> determineWeaknesses(t));
    }

