bool validate_oauth_token(const char *json_str) {
    json_object *parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) return false;

    const char *access_token = json_object_get_string(json_object_object_get_ex(parsed_json, "access_token", &json_type));
    const char *token_type = json_object_get_string(json_object_object_get_ex(parsed_json, "token_type", &json_type));
    int expires_in;
    if (json_object_object_get_ex(parsed_json, "expires_in", &json_type)) {
        expires_in = json_object_get_int(json_type);
    } else {
        expires_in = -1;
    }

    bool is_valid = access_token != NULL && token_type != NULL && strcmp(token_type, "Bearer") == 0 && expires_in > 0;
    json_object_put(parsed_json);
    return is_valid;
}
