#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_RESOURCES 10

typedef struct {
    sem_t semaphore;
    int available_resources;
} ResourcePool;

void initialize_pool(ResourcePool *pool, int initial_size) {
    sem_init(&pool->semaphore, 0, initial_size);
    pool->available_resources = initial_size;
}

int allocate_resource(ResourcePool *pool) {
    if (sem_wait(&pool->semaphore) == -1) {
        perror("Semaphore wait error");
        return -1;
    }
    if (pool->available_resources > 0) {
        pool->available_resources--;
        return 0;
    } else {
        sem_post(&pool->semaphore);
        return -1; // No resources available
    }
}

void deallocate_resource(ResourcePool *pool) {
    sem_wait(&pool->semaphore);
    pool->available_resources++;
    sem_post(&pool->semaphore);
}

void destroy_pool(ResourcePool *pool) {
    sem_destroy(&pool->semaphore);
}
