fn detect_encoding(file_path: &str) -> Option<Encoding> {
    // Read the first few bytes to detect BOM
    let file = fs::File::open(file_path).expect("Failed to open file");
    let mut reader = BufReader::new(file);
    let mut buf = [0; 4];
    if reader.read(&mut buf).expect("Failed to read file") > 0 {
        match &buf[..] {
            [0xEF, 0xBB, 0xBF] => Some(UTF_8),
            _ => None,
        }
    } else {
        None
    }
}

fn get_encoding(file_path: &str) -> Encoding {
    if let Some(encoding) = detect_encoding(file_path) {
        encoding
    } else {
        UTF_8
    }
}

