namespace Logger {
    enum LogLevel { DEBUG, INFO, WARN, ERROR };

    class LogManager {
    public:
        static LogManager& getInstance() {
            static LogManager instance;
            return instance;
        }

        void init(const std::string& config) {
            // Parse the configuration and set up log settings
        }

        void setLevel(LogLevel level) {
            std::lock_guard<std::mutex> lock(mutex_);
            logLevel_ = level;
        }

        void log(LogLevel level, const std::string& message) {
            if (level >= logLevel_) {
                std::lock_guard<std::mutex> lock(mutex_);
                if (logToFile_) {
                    outputFile_.open("log.txt", std::ios_base::app);
                    outputFile_ << "[" << getLevelString(level) << "] " << message << std::endl;
                    outputFile_.close();
                } else {
                    std::cout << "[" << getLevelString(level) << "] " << message << std::endl;
                }
            }
        }

    private:
        LogManager() : logLevel_(INFO), logToFile_(true) {}

        LogLevel logLevel_;
        bool logToFile_;
        std::ofstream outputFile_;
        mutable std::mutex mutex_;

        std::string getLevelString(LogLevel level) {
            switch (level) {
                case DEBUG: return "DEBUG";
                case INFO:  return "INFO";
                case WARN:  return "WARN";
                case ERROR: return "ERROR";
                default:    return "UNKNOWN";
            }
        }
    };
}

int main() {
    Logger::LogManager& logger = Logger::LogManager::getInstance();
    logger.init("config.txt");

    logger.setLevel(Logger::DEBUG);
    logger.log(Logger::INFO, "This is an info message.");
    logger.log(Logger::ERROR, "This is an error message.");

    return 0;
}
