    private static readonly HttpClient client = new HttpClient();
    private static Dictionary<string, List<double>> cache = new Dictionary<string, List<double>>();
    private static object lockObject = new object();

    public async Task UpdateDashboardAsync()
    {
        string dataUrl = "https://api.example.com/datafeed";
        HttpResponseMessage response = await client.GetAsync(dataUrl);
        string jsonResponse = await response.Content.ReadAsStringAsync();
        JObject jsonData = JObject.Parse(jsonResponse);

        foreach (JToken item in jsonData["metrics"])
        {
            string metricName = item["name"].ToString();
            double value = Convert.ToDouble(item["value"]);

            lock (lockObject)
            {
                if (!cache.ContainsKey(metricName))
                {
                    cache[metricName] = new List<double>();
                }

                cache[metricName].Add(value);
                if (cache[metricName].Count > 100) // Limit to 100 data points
                {
                    cache[metricName]..RemoveAt(0);
                }
            }
        }

        UpdateGraph();
    }

    private void UpdateGraph()
    {
        // Code to update the graph with the cached data points
        Console.WriteLine("Graph updated with latest data.");
    }

    public static async Task Main(string[] args)
    {
        DataFetcher fetcher = new DataFetcher();
        while (true)
        {
            await fetcher.UpdateDashboardAsync();
            await Task.Delay(60000); // Update every minute
        }
    }
}
