from flask import Flask, request, jsonify
import uuid

app = Flask(__name__)

# In-memory storage for user profiles
user_profiles = {}

@app.route('/profiles/<profile_id>', methods=['PUT'])
def update_profile(profile_id):
    data = request.get_json()
    if profile_id in user_profiles:
        updated_profile = {**user_profiles[profile_id], **data}
        user_profiles[profile_id] = updated_profile
        return jsonify(updated_profile), 200
    else:
        return jsonify({'error': 'Profile not found'}), 404

@app.route('/profiles/bulk-delete', methods=['DELETE'])
def bulk_delete_profiles():
    delete_ids = request.json.get('ids', [])
    deleted_count = 0
    remaining_profiles = {}

    for profile_id in delete_ids:
        if profile_id in user_profiles:
            del user_profiles[profile_id]
            deleted_count += 1

    for profile_id, profile in user_profiles.items():
        remaining_profiles[profile_id] = profile

    return jsonify({'deleted': deleted_count, 'remaining': remaining_profiles}), 200

if __name__ == '__main__':
    app.run(debug=True)
```

