<?php

function handleUserRequest() {
    $response = array('message' => 'error');

    if (!isset($_SESSION['authenticated']) || $_SESSION['authenticated'] !== true) {
        // Unauthorized access attempt
        return json_encode($response);
    }

    $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
    $name = isset($_REQUEST['name']) ? trim(substr($_REQUEST['name'], 0, 50)) : '';
    $email = isset($_REQUEST['email']) ? trim($_REQUEST['email']) : '';
    $password = isset($_REQUEST['password']) ? $_REQUEST['password'] : '';

    if (empty($name) || empty($email) || empty($password)) {
        return json_encode($response);
    }

    // Validate email format
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode($response);
    }

    // Check password length
    if (strlen($password) < 8) {
        return json_encode($response);
    }

    $db = connectToDatabase();
    $cache = getCacheInstance();

    try {
        if ($id !== null && isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
            // Delete user
            $stmt = $db->prepare('DELETE FROM users WHERE id = :id');
            $stmt->bindParam(':id', $id);
            $stmt->execute();
        } elseif ($id !== null) {
            // Update user
            $existingUser = $cache->get("user:$id");
            if ($existingUser && $existingUser['email'] === $email) {
                return json_encode($response); // Email already exists for existing user
            }
            $stmt = $db->prepare('UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id');
            $stmt->bindParam(':id', $id);
        } else {
            // Create new user
            $existingUser = $cache->get("user:email:$email");
            if ($existingUser) {
                return json_encode($response); // Email already exists for existing user
            }
            $stmt = $db->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)');
        }

        $stmt->bindParam(':name', $name);
        $stmt->bindParam(':email', $email);
        $stmt->bindParam(':password', password_hash($password, PASSWORD_DEFAULT));

        if ($stmt->execute()) {
            logAction('success', 'User action', $id ? "Updated user with ID $id" : "Created new user");
            $response['message'] = 'success';
        } else {
            logAction('error', 'Database error', 'Failed to insert/update user');
        }
    } catch (PDOException $e) {
        logAction('error', 'Database error', 'Exception: ' . $e->getMessage());
    }

    return json_encode($response);
}

