public class ContentManager
{
    private readonly HttpClient _httpClient;
    private readonly CacheService _cacheService;
    private readonly BackgroundJobService _backgroundJobService;

    public ContentManager(HttpClient httpClient, CacheService cacheService, BackgroundJobService backgroundJobService)
    {
        _httpClient = httpClient;
        _cacheService = cacheService;
        _backgroundJobService = backgroundJobService;
    }

    public async Task<HttpResponseMessage> UpdateElementContentAsync(int userId, int sectionId, int elementId, string htmlContent)
    {
        // Validate user permissions
        if (!await _userService.HasPermission(userId, sectionId))
        {
            return new HttpResponseMessage(HttpStatusCode.Forbidden);
        }

        // Cache the updated content
        await _cacheService.CacheContent(sectionId, elementId, htmlContent);

        // Enqueue the request for processing by a background job service
        _backgroundJobService.EnqueueUpdateJob(sectionId, elementId, htmlContent);

        // Return a response indicating that the page should be refreshed
        var response = new HttpResponseMessage(HttpStatusCode.OK);
        response.Content = new StringContent("RefreshPage");
        return response;
    }
}
