const fs = require('fs').promises;
const path = require('path');

async function readFileAsync(filePath, maxRetries = 3, delay = 100) {
    let retries = 0;

    while (retries < maxRetries) {
        try {
            // Validate file path
            if (!path.isAbsolute(filePath)) {
                throw new Error('File path must be absolute.');
            }

            // Check if the file exists
            await fs.access(filePath, fs.constants.R_OK);

            // Read the file
            const contents = await fs.readFile(filePath, 'utf8');
            return contents;
        } catch (error) {
            retries++;
            if (retries < maxRetries && error.code === 'EIO') {
                console.log(`I/O error encountered. Retrying... (${retries}/${maxRetries})`);
                await new Promise(resolve => setTimeout(resolve, delay));
            } else {
                throw error;
            }
        }
    }

    throw new Error('Failed to read file after multiple retries.');
}

// Example usage:
(async () => {
    try {
        const filePath = '/absolute/path/to/your/file.txt';
        const contents = await readFileAsync(filePath);
        console.log(contents);
    } catch (error) {
        console.error(`Error reading file: ${error.message}`);
    }
})();
