const blueslip = require('blueslip');
const moment = require('moment');

function runTests(config, label, f) {
    let passed = 0;
    let failed = 0;
    let errors = [];

    const skipTest = (testName) => config.skip && config.skip.includes(testName);

    async function executeTest(testFunction, testName) {
        try {
            if (!skipTest(testName)) {
                await testFunction();
                passed++;
                blueslip.log(`${moment().format('YYYY-MM-DD HH:mm:ss')} - [${label}] ${testName} passed.`);
            }
        } catch (error) {
            failed++;
            errors.push({ testName, error });
            blueslip.error(`${moment().format('YYYY-MM-DD HH:mm:ss')} - [${label}] ${testName} failed: ${error.message}`);
        }
    }

    const testCases = f();
    for (const testCase of testCases) {
        executeTest(testCase.run, testCase.name);
        blueslip.reset(); // Reset mocks after each test
    }

    return { passed, failed, errors };
}
