function generateNavMenu(configs) {
    function renderMenuItem(item) {
        if (item.children && item.children.length > 0) {
            let childrenHtml = item.children.map(child => renderMenuItem(child)).join('');
            return `
                <li>
                    ${item.icon ? `<i class="${item.icon}"></i>` : ''}
                    <span>${item.name}</span>
                    <ul class="submenu">${childrenHtml}</ul>
                </li>
            `;
        } else {
            return `
                <li>
                    ${item.icon ? `<i class="${item.icon}"></i>` : ''}
                    <a href="${item.url}">${item.name}</a>
                </li>
            `;
        }
    }

    let menuHtml = configs.map(config => renderMenuItem(config)).join('');
    return `
        <nav>
            <button id="menu-toggle">Toggle Menu</button>
            <ul class="main-menu">${menuHtml}</ul>
        </nav>
        <style>
            .submenu { display: none; }
            .submenu.show { display: block; }
            @media (max-width: 600px) {
                .main-menu { display: none; }
                .main-menu.show { display: block; }
            }
        </style>
        <script>
            document.getElementById('menu-toggle').addEventListener('click', function() {
                let mainMenu = document.querySelector('.main-menu');
                mainMenu.classList.toggle('show');
                let submenus = document.querySelectorAll('.submenu');
                submenus.forEach(submenu => submenu.classList.remove('show'));
            });
        </script>
    `;
}
