class GraphDB {
  constructor() {
    this.graph = {};
    this.paused = false;
    this.streamDataQueue = [];
  }

  pauseStream() {
    this.paused = true;
  }

  resumeStream() {
    this.paused = false;
    this.processQueuedData();
  }

  addToStream(data) {
    if (!this.paused) {
      this.processData(data);
    } else {
      this.streamDataQueue.push(data);
    }
  }

  processData(data) {
    // Simulate adding vertices and edges with random properties
    const numVertices = Math.floor(Math.random() * 5) + 1;
    for (let i = 0; i < numVertices; i++) {
      const vertexId = `v${i}`;
      this.graph[vertexId] = { ...data, type: 'vertex', id: vertexId };
    }

    const numEdges = Math.floor(Math.random() * 3) + 1;
    for (let j = 0; j < numEdges; j++) {
      const source = `v${Math.floor(Math.random() * numVertices)}`;
      const target = `v${Math.floor(Math.random() * numVertices)}`;
      this.graph[`${source}-${target}`] = { ...data, type: 'edge', source, target };
    }
  }

  processQueuedData() {
    while (!this.paused && this.streamDataQueue.length > 0) {
      const data = this.streamDataQueue.shift();
      this.processData(data);
    }
  }
}

// Example usage:
const db = new GraphDB();

db.addToStream({ timestamp: Date.now(), value: 42 });
db.pauseStream();
db.addToStream({ timestamp: Date.now(), value: 77 });
db.resumeStream();
