function copyBufferedData(chunks, offset, length) {
  if (typeof chunks !== 'object' || !Array.isArray(chunks)) {
    throw new Error('Invalid input: chunks must be an array of Buffer objects');
  }

  if (typeof offset !== 'number' || typeof length !== 'number') {
    throw new Error('Invalid input: offset and length must be numbers');
  }

  const totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);

  if (offset < 0 || offset > totalLength - length) {
    throw new Error('Invalid input: offset out of bounds');
  }

  const newBuffer = Buffer.allocUnsafe(length);

  let writtenBytes = 0;
  for (let i = 0; i < chunks.length && writtenBytes < length; ++i) {
    if (offset >= chunks[i].length) {
      offset -= chunks[i].length;
      continue;
    }

    const chunkOffset = offset > 0 ? offset : 0;
    const toCopy = Math.min(length - writtenBytes, chunks[i].length - chunkOffset);
    chunks[i].copy(newBuffer, writtenBytes, chunkOffset, chunkOffset + toCopy);
    writtenBytes += toCopy;
    offset -= chunks[i].length;
  }

  return newBuffer.slice(0, length);
}
