function loadScripts(directory) {
  const scripts = Array.from(document.querySelectorAll('script'));
  const loadedScripts = new Set();

  function loadScript(url, callback) {
    const script = document.createElement('script');
    script.src = url;

    script.onload = () => {
      console.log(`Script ${url} has been loaded.`);
      if (callback) callback();
    };

    script.onerror = (error) => {
      console.error(`Failed to load script ${url}:`, error);
      // Implement error handling logic here
    };

    document.head.appendChild(script);
  }

  function executeScripts() {
    const nextScript = scripts.find(script => !loadedScripts.has(script.src));

    if (!nextScript) return;

    loadScript(nextScript.src, () => {
      loadedScripts.add(nextScript.src);
      executeScripts();
    });
  }

  executeScripts();
}

// Example usage:
loadScripts('path/to/scripts');
