import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class DirectoryNode {
    Map<String, DirectoryNode> children = new ConcurrentHashMap<>();
}

public class PathAnalyzer {

    public static int countUniqueDirectories(List<String> filePaths) {
        long startTime = System.currentTimeMillis();
        DirectoryNode root = buildDirectoryTree(filePaths);
        int uniqueCount = traverseAndCount(root, new HashSet<>());
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken for traversal: " + (endTime - startTime) + " ms");
        return uniqueCount;
    }

    private static DirectoryNode buildDirectoryTree(List<String> filePaths) {
        DirectoryNode root = new DirectoryNode();
        for (String path : filePaths) {
            Path fullPath = Paths.get(path).normalize();
            if (!fullPath.isAbsolute()) {
                continue; // Handle relative paths as needed
            }
            DirectoryNode current = root;
            for (String part : fullPath.getNameIterator().asList()) {
                current.children.putIfAbsent(part, new DirectoryNode());
                current = current.children.get(part);
            }
        }
        return root;
    }

    private static int traverseAndCount(DirectoryNode node, Set<String> seen) {
        int count = 0;
        for (Map.Entry<String, DirectoryNode> entry : node.children.entrySet()) {
            String directoryName = entry.getKey();
            if (!seen.contains(directoryName)) {
                seen.add(directoryName);
                count++;
                count += traverseAndCount(entry.getValue(), seen);
            }
        }
        return count;
    }

    public static void main(String[] args) {
        List<String> filePaths = Arrays.asList(
            "/home/user/documents/report.txt",
            "/home/user/images/photo.jpg",
            "/home/user/documents/archive/old_report.txt"
        );
        int uniqueDirectories = countUniqueDirectories(filePaths);
        System.out.println("Unique directories: " + uniqueDirectories);
    }
}
