#include <memory>

class ImageAssetCache {
public:
    ImageAssetCache(const std::string& defaultDirectory = "assets/images")
        : m_defaultDirectory(defaultDirectory) {
        if (m_defaultDirectory.empty()) {
            throw std::invalid_argument("Default directory cannot be empty.");
        }
    }

    void loadResource(const std::string& resourcePath, bool forceReload = false) {
        std::string fullpath = findFullImagePath(resourcePath);
        if (!forceReload && m_resourceCache.find(fullpath) != m_resourceCache.end()) {
            return;
        }

        try {
            // Simulate loading image from disk
            loadImageFromDisk(fullpath);
        } catch (const std::exception& e) {
            std::cerr << "Failed to load resource: " << e.what() << std::endl;
        }
    }

    void* getImage(const std::string& resourcePath) const {
        auto it = m_resourceCache.find(resourcePath);
        if (it != m_resourceCache.end()) {
            return it->second.get();
        }
        return nullptr;
    }

private:
    std::string findFullImagePath(const std::string& resourcePath) const {
        return m_defaultDirectory + "/" + resourcePath;
    }

    void loadImageFromDisk(const std::string& fullpath) {
