from functools import lru_cache

class Settings:
    def __init__(self):
        self._config = configparser.ConfigParser()
        self._config.read('settings.ini')
        self._env_vars = os.environ.copy()

    @lru_cache(maxsize=128)
    def get(self, key, default=None):
        if key in self._env_vars:
            return self._env_vars[key]
        elif key in self._config['DEFAULT']:
            return self._config['DEFAULT'][key]
        else:
            return default

def main():
    settings = Settings()
    db_host = settings.get('DB_HOST', 'localhost')
    db_port = int(settings.get('DB_PORT', 5432))
