use reqwest::{Client, RequestBuilder, Error};
use std::time::Duration;
use tokio::time::{sleep, DurationExt};

async fn create_http_client(url: &str, disable_certificate_validation: bool) -> Result<RequestBuilder, Error> {
    let mut client_builder = Client::builder();

    if disable_certificate_validation {
        client_builder = client_builder.dangerously_insecure();
    }

    let client = client_builder.build()?;

    Ok(client.request(reqwest::Method::GET, url))
}

async fn send_request_with_retry<T, F>(
    request: RequestBuilder,
    max_retries: u32,
    retry_interval: Duration,
    predicate: F,
) -> Result<T, Error>
where
    T: std::convert::TryFrom<reqwest::Response>,
    F: Fn(&Error) -> bool,
{
    let mut attempt = 0;
    loop {
        match request.send().await {
            Ok(response) => {
                if predicate(&response.error_for_status()) {
                    return Err(Error::from(response));
                }
                return T::try_from(response).map_err(|e| Error::from(e));
            }
            Err(err) if attempt < max_retries && predicate(&err) => {
                sleep(retry_interval.mul_f32(attempt as f32)).await;
                attempt += 1;
            }
            Err(err) => return Err(err),
        }
    }
}

