<?php

class PasswordUtils {
    private static $defaultCharset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

    public static function generateRandomString($length, $charset = self::$defaultCharset) {
        if ($length <= 0 || empty($charset)) {
            return "Invalid input";
        }

        $charactersLength = strlen($charset);
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset[rand(0, $charactersLength - 1)];
        }
        return $randomString;
    }

    public static function hashPassword($password) {
        if (empty($password)) {
            return "Invalid password";
        }

        return password_hash($password, PASSWORD_BCRYPT);
    }
}

// Unit tests for PasswordUtils class
class TestPasswordUtils extends PHPUnit\Framework\TestCase {
    public function testGenerateRandomString() {
        $length = 10;
        $charset = 'abc';
        $result = PasswordUtils::generateRandomString($length, $charset);

        $this->assertEquals($length, strlen($result));
        $this->assertTrue(strspn($result, $charset) == strlen($result));
    }

    public function testHashPassword() {
        $password = 'secure_password';
        $hashedPassword = PasswordUtils::hashPassword($password);

        $this->assertNotEmpty($hashedPassword);
        $this->assertTrue(password_verify($password, $hashedPassword));
    }
}

