#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 10000

typedef struct {
    int id;
    double value;
    clock_t timestamp;
} Transaction;

Transaction transactions[MAX_TRANSACTIONS];
int transaction_count = 0;

pthread_mutex_t transaction_log_lock;
clock_t now;

void init_transaction_log() {
    pthread_mutex_init(&transaction_log_lock, NULL);
}

void add_transaction(int id, double value) {
    pthread_mutex_lock(&transaction_log_lock);
    if (transaction_count >= MAX_TRANSACTIONS) {
        // Handle overflow by removing the oldest transaction
        for (int i = 1; i < transaction_count; i++) {
            transactions[i - 1] = transactions[i];
        }
        transaction_count--;
    }
    Transaction new_transaction;
    new_transaction.id = id;
    new_transaction.value = value;
    new_transaction.timestamp = clock();
    transactions[transaction_count++] = new_transaction;
    pthread_mutex_unlock(&transaction_log_lock);
}

void filter_transactions() {
    double max_weighted_sum = 0.0;
    int max_id = -1;
    double total_value = 0.0;

    pthread_mutex_lock(&transaction_log_lock);
    now = clock();
    for (int i = 0; i < transaction_count; i++) {
        clock_t current_time = transactions[i].timestamp;
        if (now - current_time > CLOCKS_PER_SEC / 2) {
            // Transaction is older than 5ms, skip
            continue;
        }
        double age = (double)(now - current_time) / CLOCKS_PER_SEC;
        total_value += transactions[i].value;
        double weighted_sum = transactions[i].value * (1.0 / (age + 1));
        if (weighted_sum > max_weighted_sum) {
            max_weighted_sum = weighted_sum;
            max_id = transactions[i].id;
        }
    }
    pthread_mutex_unlock(&transaction_log_lock);

    // Calculate average transaction value over the last second
    double average_value = total_value / transaction_count;

    printf("Max Weighted Sum: %f, Transaction ID: %d, Average Value: %f\n", max_weighted_sum, max_id, average_value);
}

int main() {
    init_transaction_log();

    // Simulate adding transactions
    for (int i = 0; i < 20; i++) {
        add_transaction(i, rand() / (double)RAND_MAX * 100.0);
    }

    filter_transactions();

    return 0;
}
```']

