std::mt19937 randomGenerator(std::random_device{}());
std::uniform_int_distribution<int> distribution(1, 2);

void selectAndLogAttack() {
    static int lastAttackTime = 0;
    const int cooldownSeconds = 9;

    auto now = std::chrono::system_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();

    if (duration - lastAttackTime >= cooldownSeconds) {
        int selectedAttack = distribution(randomGenerator);
        CombatLogger::logAttack(selectedAttack);
        lastAttackTime = duration;
    } else {
        std::this_thread::sleep_for(std::chrono::seconds(cooldownSeconds - (duration - lastAttackTime)));
    }
}

int main() {
    // Example usage
    for (int i = 0; i < 10; ++i) {
        selectAndLogAttack();
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate game loop
    }
    return 0;
}
