using System;
using System.Collections.Generic;

public class RandomValueGenerator
{
    private List<Tuple<float, float>> floatRanges;
    private List<Tuple<int, int>> intRanges;

    public RandomValueGenerator()
    {
        floatRanges = new List<Tuple<float, float>>();
        intRanges = new List<Tuple<int, int>>();
    }

    public void AddFloatRange(float min, float max, bool isExclusive)
    {
        if (min >= max)
        {
            throw new ArgumentException("Minimum value must be less than maximum value.");
        }
        floatRanges.Add(Tuple.Create(min, max));
    }

    public void AddIntRange(int min, int max, bool isExclusive)
    {
        if (min >= max)
        {
            throw new ArgumentException("Minimum value must be less than maximum value.");
        }
        intRanges.Add(Tuple.Create(min, max));
    }

    public float GetRandomFloat(bool includeMax = true)
    {
        if (floatRanges.Count == 0) return 0f;
        var range = floatRanges[Random.Range(0, floatRanges.Count)];
        Random rand = new Random();
        if (!includeMax && rand.NextDouble() < 1e-6)
        {
            return range.Item2;
        }
        return (float)(rand.NextDouble() * (range.Item2 - range.Item1) + range.Item1);
    }

    public int GetRandomInt(bool includeMax = true)
    {
        if (intRanges.Count == 0) return 0;
        var range = intRanges[Random.Range(0, intRanges.Count)];
        Random rand = new Random();
        int result = rand.Next(range.Item1, includeMax ? range.Item2 + 1 : range.Item2);
        return result;
    }

    public void ResetAllRanges()
    {
        floatRanges.Clear();
        intRanges.Clear();
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder("RandomValueGenerator State:\n");
        foreach (var range in floatRanges)
        {
            sb.Append($"Float Range: {range.Item1}-{range.Item2}\n");
        }
        foreach (var range in intRanges)
        {
            sb.Append($"Int Range: {range.Item1}-{range.Item2}\n");
        }
        return sb.ToString();
    }
}
