async function asyncReduce(array, initialValue, callback) {
  if (!Array.isArray(array)) {
    throw new Error('First argument must be an array');
  }
  if (typeof initialValue === 'undefined') {
    throw new Error('Initial value is required');
  }
  if (typeof callback !== 'function') {
    throw new Error('Callback function is required');
  }

  let result = initialValue;
  for (const item of array) {
    try {
      result = await callback(result, item);
    } catch (error) {
      console.error('Error during reduction:', error);
      return Promise.reject(error);
    }
  }
  return result;
}

// Example usage:
(async () => {
  const numbers = [1, 2, 3, 4, 5];
  try {
    const sum = await asyncReduce(numbers, 0, (acc, num) => acc + num);
    console.log('Sum:', sum); // Output: Sum: 15
  } catch (error) {
    console.error(error);
  }
})();
