['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ITEM_SIZE 4096
#define TOTAL_MEMORY_LIMIT 1024 * 1024

typedef struct ResourceItem {
    char* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem** items;
    int itemCount;
} ResourceBundle;

enum ErrorCode {
    SUCCESS = 0,
    FILE_ACCESS_ERROR = -1,
    MEMORY_ALLOCATION_FAILURE = -2,
    PARSING_ERROR = -3
};

int loadResourceBundle(const char* filePath, const char* format, ResourceBundle** bundle) {
    FILE* file = fopen(filePath, "r");
    if (!file) return FILE_ACCESS_ERROR;

    *bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!(*bundle)) {
        fclose(file);
        return MEMORY_ALLOCATION_FAILURE;
    }
    (*bundle)->items = NULL;
    (*bundle)->itemCount = 0;

    char* buffer = (char*)malloc(MAX_ITEM_SIZE);
    if (!buffer) {
        free((*bundle));
        fclose(file);
        return MEMORY_ALLOCATION_FAILURE;
    }

    while (fgets(buffer, MAX_ITEM_SIZE, file)) {
        // Trim newline character
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len - 1] == '\n') {
            buffer[len - 1] = '\0';
        }

        ResourceItem* item = (ResourceItem*)malloc(sizeof(ResourceItem));
        if (!item) {
            free(buffer);
            for (int i = 0; i < (*bundle)->itemCount; i++) {
                free((*bundle)->items[i]->data);
                free((*bundle)->items[i]);
            }
            free((*bundle)->items);
            fclose(file);
            return MEMORY_ALLOCATION_FAILURE;
        }

        item->data = strdup(buffer);
        if (!item->data) {
            free(item);
            for (int i = 0; i < (*bundle)->itemCount; i++) {
                free((*bundle)->items[i]->data);
                free((*bundle)->items[i]);
            }
            free((*bundle)->items);
            fclose(file);
            return MEMORY_ALLOCATION_FAILURE;
        }

        // Check memory limit
        size_t totalSize = 0;
        for (int i = 0; i < (*bundle)->itemCount; i++) {
            totalSize += strlen((*bundle)->items[i]->data) + 1;
        }
        if (totalSize + strlen(buffer) + 1 > TOTAL_MEMORY_LIMIT) {
            free(item->data);
            free(item);
            for (int i = 0; i < (*bundle)->itemCount; i++) {
                free((*bundle)->items[i]->data);
                free((*bundle)->items[i]);
            }
            free((*bundle)->items);
            fclose(file);
            return MEMORY_ALLOCATION_FAILURE;
        }

        // Resize items array
        (*bundle)->items = (ResourceItem**)realloc((*bundle)->items, ((*bundle)->itemCount + 1) * sizeof(ResourceItem*));
        if (!(*bundle)->items) {
            free(item->data);
            free(item);
            for (int i = 0; i < (*bundle)->itemCount; i++) {
                free((*bundle)->items[i]->data);
                free((*bundle)->items[i]);
            }
            fclose(file);
            return MEMORY_ALLOCATION_FAILURE;
        }

        (*bundle)->items[(*bundle)->itemCount++] = item;
    }

    free(buffer);
    fclose(file);

    // Handle different formats (CSV, JSON, XML)
    if (strcmp(format, "JSON") == 0) {
        for (int i = 0; i < (*bundle)->itemCount; i++) {
            // Parse JSON here
        }
    } else if (strcmp(format, "XML") == 0) {
        for (int i = 0; i < (*bundle)->itemCount; i++) {
            // Parse XML here
        }
    }

    return SUCCESS;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (int i = 0; i < bundle->itemCount; i++) {
        free(bundle->items[i]->data);
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}
