#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define BUFFER_SIZE 1024

void process_line(const char *line, int logging_enabled) {
    if (logging_enabled) {
        // Log the start of line processing
        printf("Processing line: %s\n", line);
    }

    double sum = 0;
    int count = 0;
    int value;

    const char *token = strtok(line, " ");
    while (token != NULL) {
        if (sscanf(token, "%d", &value) == 1) {
            sum += value;
            count++;
        }
        token = strtok(NULL, " ");
    }

    if (count >= 2) {
        double avg = sum / 2.0;
        printf("%.2f,", avg);

        token = strtok(line, " ");
        while (token != NULL) {
            printf("%s ", token);
            token = strtok(NULL, " ");
        }
        printf("\n");
    } else {
        printf("Malformed line: %s\n", line);
    }

    if (logging_enabled) {
        // Log the end of line processing
        printf("Finished processing line\n");
    }
}

int main() {
    FILE *file = fopen("large_text_file.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    int lines_processed = 0;
    time_t start_time = time(NULL);

    while (fgets(buffer, BUFFER_SIZE, file)) {
        process_line(buffer, 1); // Set logging_enabled to 1 for detailed logs
        lines_processed++;

        if (lines_processed % 1000 == 0) { // Flush memory periodically
            fflush(stdout);
        }
    }

    fclose(file);

    time_t end_time = time(NULL);
    double average_processing_time = difftime(end_time, start_time) / (double)lines_processed;
    printf("Total lines processed: %d\n", lines_processed);
    printf("Average processing time per line: %.4f seconds\n", average_processing_time);

    return EXIT_SUCCESS;
}
```

This code reads a large text file line by line, processes each line to calculate the average of the last two numeric fields, and prints the result. It handles memory management dynamically and periodically flushes memory to prevent excessive consumption. Logging is integrated to record processing metrics. The program also gracefully skips malformed lines without crashing.']

