char* modify_filename(const char* filename) {
    const int max_len = 256;
    char* new_filename = (char*)malloc(max_len);
    if (!new_filename) return NULL;

    int len = strlen(filename);
    if (len == 0) {
        strcpy(new_filename, "empty_file.txt");
        return new_filename;
    }

    // Determine the number of digits for the unique identifier
    int num_digits = 10;
    if (len > 100) {
        num_digits = 10 + (len - 100);
    } else if (len < 50) {
        num_digits -= len / 20;
    }

    // Handle filenames with spaces and special characters
    char* safe_filename = (char*)malloc(len * 2 + 1);
    if (!safe_filename) {
        free(new_filename);
        return NULL;
    }
    for (int i = 0, j = 0; filename[i] != '\0'; ++i) {
        if (filename[i] == ' ' || filename[i] < 32 || filename[i] > 126) {
            safe_filename[j++] = '_';
        } else {
            safe_filename[j++] = filename[i];
        }
    }
    safe_filename[j] = '\0';

    // Construct the new filename
    char* dot_pos = strrchr(safe_filename, '.');
    if (dot_pos == NULL || dot_pos - safe_filename + num_digits > max_len - 6) {
        dot_pos = safe_filename;
    }

    sprintf(new_filename, "%.*s_%d%s", (int)(dot_pos - safe_filename), safe_filename,
            rand() % (int)pow(10, num_digits), dot_pos);

    // Free temporary strings
    free(safe_filename);

    return new_filename;
}

// Example usage
int main() {
    char* new_name = modify_filename("example file.txt");
    if (new_name != NULL) {
        printf("New filename: %s\n", new_name);
        free(new_name);
    }
    return 0;
}
