#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_PATH_LEN 256

typedef struct {
    char source_dir[MAX_PATH_LEN];
    char target_dir[MAX_PATH_LEN];
    char file_extension[MAX_PATH_LEN];
} CopyTask;

int copy_file(const char *src, const char *dest) {
    FILE *source = fopen(src, "rb");
    if (!source) return 1;
    FILE *target = fopen(dest, "rb");
    if (target) fclose(target), fclose(source); // File exists, do not overwrite
    else {
        target = fopen(dest, "wb");
        if (!target) return 1;
        char buffer[4096];
        size_t bytes_read;
        while ((bytes_read = fread(buffer, 1, sizeof(buffer), source)) > 0) {
            fwrite(buffer, 1, bytes_read, target);
        }
        fclose(source);
        fclose(target);
    }
    return 0;
}

void* worker_thread(void *arg) {
    CopyTask *task = (CopyTask*) arg;
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir(task->source_dir)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char full_path[MAX_PATH_LEN];
            snprintf(full_path, sizeof(full_path), "%s/%s", task->source_dir, ent->d_name);
            if (ent->d_type == DT_DIR && strcmp(ent->d_name, ".") && strcmp(ent->d_name, "..")) {
                char target_subdir[MAX_PATH_LEN];
                snprintf(target_subdir, sizeof(target_subdir), "%s/%s", task->target_dir, ent->d_name);
                mkdir(target_subdir, 0755);
            } else if (ent->d_type == DT_REG && strstr(ent->d_name, task->file_extension)) {
                char target_path[MAX_PATH_LEN];
                snprintf(target_path, sizeof(target_path), "%s/%s", task->target_dir, ent->d_name);
                copy_file(full_path, target_path);
            }
        }
        closedir(dir);
    } else perror("opendir");
    return NULL;
}

int copy_files(const char *source, const char *target, const char *extension) {
    DIR *dir = opendir(source);
    if (!dir) return 1;

    int num_threads = 0;
    pthread_t threads[10]; // Assuming max 10 subdirectories
    CopyTask tasks[10];

    while (num_threads < 10 && (struct dirent *ent = readdir(dir)) != NULL) {
        if (ent->d_type == DT_DIR && strcmp(ent->d_name, ".") && strcmp(ent->d_name, "..")) {
            snprintf(tasks[num_threads].source_dir, MAX_PATH_LEN, "%s/%s", source, ent->d_name);
            snprintf(tasks[num_threads].target_dir, MAX_PATH_LEN, "%s/%s", target, ent->d_name);
            strcpy(tasks[num_threads].file_extension, extension);
            pthread_create(&threads[num_threads], NULL, worker_thread, (void*)&tasks[num_threads]);
            num_threads++;
        }
    }

    closedir(dir);

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
