#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>

#define MAX_COMMANDS 10
#define MAX_LOG_SIZE 500

typedef struct {
    char command[256];
    int pid;
} Command;

Command commands[MAX_COMMANDS];
int command_count = 0;
FILE *log_file;

void log_command(const char *command) {
    fprintf(log_file, "Executing: %s\n", command);
}

int run_command_in_background(const char *command) {
    if (command_count >= MAX_COMMANDS) {
        return 0; // Too many commands running
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        int log_fd = open("command_log.txt", O_WRONLY | O_CREAT, 0644);
        dup2(log_fd, STDOUT_FILENO);
        close(log_fd);

        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else {
        commands[command_count].pid = pid;
        strcpy(commands[command_count].command, command);
        command_count++;
        log_command(command);
        return 1;
    }
}

void manage_commands() {
    for (int i = 0; i < command_count; i++) {
        int status;
        waitpid(commands[i].pid, &status, WNOHANG);
        if (WIFEXITED(status)) {
            log_command("Finished: ");
            log_command(commands[i].command);
            command_count--;
        }
    }
}

int main() {
    log_file = fopen("execution_log.txt", "w");
    if (!log_file) {
        perror("Failed to open execution log file");
        return 1;
    }

    // Example usage
    run_command_in_background("ls -l > output.txt");
    run_command_in_background("echo 'Hello, World!' >> output.txt");

    manage_commands(); // Periodically call this function

    fclose(log_file);
    return 0;
}
```

This code snippet defines a simple system to run commands in the background using `fork` and `wait`. It includes basic error handling, logging, and concurrent command management. The `run_command_in_background` function runs a given command in the background, logs its execution, and returns 1 if successful or 0 otherwise. The `manage_commands` function checks for completed commands and cleans up their entries from the array. Note that this example does not include advanced features like output redirection to separate files for each command or limiting the total number of concurrent processes, as implementing these would significantly increase the complexity of the code.']

