using System;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;

public class SiteManager
{
    public static string AddAndStartSite(string directoryPath, string siteName, ServerConfig config)
    {
        if (!Directory.Exists(directoryPath))
        {
            return "Directory does not exist";
        }

        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            return "";
        }

        if (config.IsSiteOccupied(siteName))
        {
            LogError($"Site {siteName} is already occupied");
            return null;
        }

        try
        {
            config.AddSite(siteName, directoryPath);

            ProcessStartInfo startInfo = new ProcessStartInfo("dotnet", $"run --project {directoryPath}");
            startInfo.RedirectStandardOutput = true;
            startInfo.RedirectStandardError = true;
            startInfo.UseShellExecute = false;

            using (Process process = new Process { StartInfo = startInfo })
            {
                process.Start();
                DateTime startTime = DateTime.Now;

                while (!process.HasExited && DateTime.Now - startTime < TimeSpan.FromSeconds(30))
                {
                    Task.Delay(100).Wait(); // Avoid busy-waiting
                }

                if (process.HasExited)
                {
                    LogSuccess($"Site {siteName} started successfully");
                    return siteName;
                }
                else
                {
                    LogError($"Failed to start site {siteName} within 30 seconds");
                    process.Kill();
                    return null;
                }
            }
        }
        catch (Exception ex)
        {
            LogError($"An error occurred: {ex.Message}");
            return null;
        }
    }

    private static void LogSuccess(string message)
    {
        Console.WriteLine($"SUCCESS: {message}");
    }

    private static void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}

public class ServerConfig
{
    private Dictionary<string, string> sites = new Dictionary<string, string>();

    public bool IsSiteOccupied(string siteName)
    {
        return sites.ContainsKey(siteName);
    }

    public void AddSite(string siteName, string directoryPath)
    {
        sites[siteName] = directoryPath;
    }
}
```

