typedef struct {
    bool relaxed_validation;
} OAuthConfig;

bool validate_oauth_token(const char* json_string, const OAuthConfig* config) {
    struct json_object *parsed_json = NULL;
    struct json_object *access_token_obj = NULL;
    struct json_object *expires_in_obj = NULL;
    struct json_object *token_type_obj = NULL;
    struct json_object *refresh_token_obj = NULL;

    // Parse the JSON string
    parsed_json = json_tokener_parse(json_string);
    if (!parsed_json) {
        return false; // Malformed JSON
    }

    // Check for access_token field
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token_obj)) {
        const char* access_token = json_object_get_string(access_token_obj);
        if (strlen(access_token) == 0 || (config->relaxed_validation && strcmp(access_token, "") != 0)) {
            return false; // Empty or invalid access token
        }
    } else {
        return false; // Missing access_token field
    }

    // Check for expires_in field
    if (!json_object_object_get_ex(parsed_json, "expires_in", &expires_in_obj) || !json_object_is_type(expires_in_obj, json_type_int)) {
        return false; // Missing or invalid expires_in field
    }
    int expires_in = json_object_get_int(expires_in_obj);
    if (expires_in <= 0 && !config->relaxed_validation) {
        return false; // Invalid expires_in value
    }

    // Check for token_type field
    if (!json_object_object_get_ex(parsed_json, "token_type", &token_type_obj)) {
        return false; // Missing token_type field
    }
    const char* token_type = json_object_get_string(token_type_obj);
    if (strcmp(token_type, "Bearer") != 0 && !config->relaxed_validation) {
        return false; // Invalid token_type value
    }

    // Check for refresh_token field if present
    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token_obj)) {
        const char* refresh_token = json_object_get_string(refresh_token_obj);
        if (strlen(refresh_token) == 0 && !config->relaxed_validation) {
            return false; // Empty refresh token
        }
    }

    // Clean up JSON object
    json_object_put(parsed_json);

    return true; // Token is valid
}
