        try
        {
            byte[] encryptedData = EncryptData(data);
            string serverResponse = await _httpClient.PostAsJsonAsync("https://remote-server.com/encrypt", encryptedData);
            return $"Encryption successful. Server response: {serverResponse}";
        }
        catch (Exception ex)
        {
            LogError(ex);
            return "Encryption failed.";
        }
    }

    private byte[] EncryptData(byte[] data)
    {
        using (ICryptoTransform encryptor = _symmetricAlgorithm.CreateEncryptor(_symmetricAlgorithm.Key, _symmetricAlgorithm.IV))
        {
            using (MemoryStream msEncrypt = new MemoryStream())
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    csEncrypt.Write(data, 0, data.Length);
                }
                return msEncrypt.ToArray();
            }
