using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public AesCbcDecryptor(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public async Task<byte[]> DecryptAsync(Stream ciphertextStream, byte[] hmacKey, CancellationToken cancellationToken = default)
    {
        using (var memoryStream = new MemoryStream())
        {
            await Parallel.ForEachAsync(
                ciphertextStream,
                buffer =>
                {
                    if (buffer.Length == 0) return Task.CompletedTask;

                    var aes = Aes.Create();
                    aes.Key = _key;
                    aes.IV = _iv;
                    aes.Mode = CipherMode.CBC;
                    aes.Padding = PaddingMode.PKCS7;

                    using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
                    using (var cryptoStream = new CryptoStream(buffer.AsReadOnlyMemory().AsStream(), decryptor, CryptoStreamMode.Read))
                        await cryptoStream.CopyToAsync(memoryStream);

                    return Task.CompletedTask;
                },
                1024,
                cancellationToken
            );

            var decryptedBytes = memoryStream.ToArray();
            if (!VerifyHmac(decryptedBytes, hmacKey))
                throw new InvalidOperationException("Decryption integrity check failed.");

            return decryptedBytes;
        }
    }

    private bool VerifyHmac(byte[] data, byte[] hmacKey)
    {
        using (var hmacsha256 = HMACSHA256.Create())
        {
            hmacsha256.Key = hmacKey;
            var hash = hmacsha256.ComputeHash(data);
            // Assume the last 32 bytes of the data is the HMAC
            return hash.SequenceEqual(data.Skip(data.Length - 32).ToArray());
        }
    }
}
