void copyFile(const char* srcPath, const char* destPath) {
    int srcFd = open(srcPath, O_RDONLY);
    if (srcFd == -1) {
        perror("Error opening source file");
        return;
    }

    struct stat fileInfo;
    if (fstat(srcFd, &fileInfo) == -1) {
        perror("Error getting file info");
        close(srcFd);
        return;
    }

    int destFd = open(destPath, O_WRONLY | O_CREAT | O_EXCL, fileInfo.st_mode);
    if (destFd == -1) {
        perror("Error opening destination file");
        close(srcFd);
        return;
    }

    char buffer[4096];
    ssize_t bytesRead;
    while ((bytesRead = read(srcFd, buffer, sizeof(buffer))) > 0) {
        if (write(destFd, buffer, bytesRead) != bytesRead) {
            perror("Error writing to destination file");
            close(srcFd);
            close(destFd);
            return;
        }
    }

    if (bytesRead == -1) {
        perror("Error reading source file");
    }

    close(srcFd);
    close(destFd);
}

void* deserializeObject(const unsigned char* byteArray, size_t size) {
    FILE* memoryFile = fmemopen((char*)byteArray, size, "r");
    if (!memoryFile) {
        perror("Error opening memory file for deserialization");
        return NULL;
    }

    void* obj = deserialize(memoryFile);
    fclose(memoryFile);

    if (!obj) {
        throw std::runtime_error("Deserialization failed");
    }

    return obj;
}

int copyAndDeserialize(const char* srcDir, const char* destDir, const char* ext, const unsigned char* byteArray, size_t byteSize) {
    DIR* dir = opendir(srcDir);
    if (!dir) {
        perror("Error opening source directory");
        return 1;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char srcPath[256], destPath[256];
        snprintf(srcPath, sizeof(srcPath), "%s/%s", srcDir, entry->d_name);
        snprintf(destPath, sizeof(destPath), "%s/%s", destDir, entry->d_name);

        if (entry->d_type == DT_DIR) {
            mkdir(destPath, 0755);
            copyAndDeserialize(srcPath, destPath, ext, byteArray, byteSize);
        } else if (strstr(entry->d_name, ext)) {
            copyFile(srcPath, destPath);

            void* obj = deserializeObject(byteArray, byteSize);
            if (!obj) {
                closedir(dir);
                return 1;
            }
        }
    }

    closedir(dir);
    return 0;
}

int main() {
    const char* srcDir = "source_directory";
    const char* destDir = "destination_directory";
    const char* ext = ".txt";
    unsigned char byteArray[] = {/* Your byte array here */};
    size_t byteSize = sizeof(byteArray) / sizeof(byteArray[0]);

    return copyAndDeserialize(srcDir, destDir, ext, byteArray, byteSize);
}
