    let retryCount = 3;

    function uploadChunk(startByte, endByte) {
      fetch(url, {
        method: 'PUT',
        headers: {
          'Content-Range': `bytes ${startByte}-${endByte}/${fileSize}`,
          // Add other necessary headers for authentication and content type
        },
        body: file.slice(startByte, endByte + 1),
      })
        .then(response => {
          if (response.ok) {
            uploadedBytes = endByte + 1;
            if (uploadedBytes < fileSize) {
              logUploadProgress();
              uploadChunk(uploadedBytes, Math.min(fileSize - 1, uploadedBytes + chunkSize));
            } else {
              resolve(url);
            }
          } else {
            reject(new Error('Upload failed'));
          }
        })
        .catch(error => {
          if (retryCount > 0) {
            retryCount--;
            setTimeout(() => uploadChunk(startByte, endByte), 1000); // Retry after 1 second
          } else {
            reject(error);
          }
        });
    }

    function logUploadProgress() {
      console.log(`Uploaded ${uploadedBytes / chunkSize} MB of ${fileSize / chunkSize} MB`);
