    const fileSize = file.size;

    if (fileSize > 10 * 1024 * 1024 * 1024) {
      reject(new Error('File size exceeds 10 GB'));
    }

    uploadChunk(0, Math.min(fileSize - 1, chunkSize));
  });
}
