const { exec, spawn } = require('child_process');

class ShellCommandExecutor {
  constructor() {
    this.contexts = {};
    this.defaultContext = {
      type: 'exec',
      format: 'raw'
    };
  }

  addContext(name, config = {}) {
    this.contexts[name] = { ...this.defaultContext, ...config };
  }

  execute(command, contextName = 'default') {
    if (!this.contexts[contextName]) {
      throw new Error(`Invalid context: ${contextName}`);
    }
    const { type, format } = this.contexts[contextName];
    return new Promise((resolve, reject) => {
      let child;
      switch (type) {
        case 'exec':
          child = exec(command, (error, stdout, stderr) => {
            if (error) {
              reject(error);
            } else {
              resolve(format === 'raw' ? stdout : JSON.parse(stdout));
            }
          });
          break;
        case 'spawn':
          child = spawn(command.split(' ')[0], command.split(' ').slice(1), { shell: true });
          let data = '';
          child.stdout.on('data', (chunk) => {
            data += chunk;
          });
          child.stderr.on('data', (chunk) => {
            reject(new Error(chunk.toString()));
          });
          child.on('close', (code) => {
            resolve(format === 'raw' ? data : JSON.parse(data));
          });
          break;
        default:
          throw new Error(`Unsupported command type: ${type}`);
      }
    });
  }

  resetContext(contextName = 'default') {
    if (!this.contexts[contextName]) {
      throw new Error(`Invalid context: ${contextName}`);
    }
    this.contexts[contextName] = { ...this.defaultContext };
  }

  toString() {
    return Object.keys(this.contexts)
      .map(key => `Context: ${key}, Type: ${this.contexts[key].type}, Format: ${this.contexts[key].format}`)
      .join('\n');
  }
}

// Example usage
const executor = new ShellCommandExecutor();
executor.addContext('docker', { type: 'spawn', format: 'json' });
executor.execute('echo hello', 'default').then(console.log);
executor.execute('docker ps -a', 'docker').then(console.log);
executor.resetContext('docker');
console.log(executor.toString());
