use std::fs::{create_dir_all, Permissions};
use std::os::unix::fs::PermissionsExt;
use std::sync::Mutex;

lazy_static! {
    static ref DIR_LOCK: Mutex<()> = Mutex::new(());
}

fn manage_directory(path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir_lock = DIR_LOCK.lock().unwrap();

    if !std::path::Path::new(&path).exists() {
        create_dir_all(path)?;
        println!("Directory created at {}", path);

        // Set permissions and ownership (example: 0o755, UID 1000, GID 1000)
        let mut perms = Permissions::from_mode(0o755);
        std::fs::set_permissions(path, perms)?;
    } else {
        println!("Directory already exists at {}", path);
    }

    if let Err(_) = env::var("MY_DIR_PATH") {
        env::set_var("MY_DIR_PATH", &path);
        println!("Environment variable MY_DIR_PATH set to {}", path);
    } else {
        let stored_path = env::var("MY_DIR_PATH")?;
        if stored_path != path {
            env::set_var("MY_DIR_PATH", &path);
            println!("Updated environment variable MY_DIR_PATH to {}", path);
        } else {
            println!("Environment variable MY_DIR_PATH is already set correctly");
        }
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    manage_directory("/tmp/my_directory")?;
    Ok(())
}
