import json

class JSONHandler:
    _registry = {}

    @classmethod
    def add_factory(cls, factory_id, factory_function):
        cls._registry[factory_id] = factory_function

    @classmethod
    def create_instance(cls, factory_id, data):
        if factory_id in cls._registry:
            return cls._registry[factory_id](data)
        raise ValueError(f"No factory found for ID: {factory_id}")

    def to_json(self):
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_string):
        data = json.loads(json_string)
        return cls(**data)

class CustomJSONHandler(JSONHandler):
    pass

