        fprintf(stderr, "Invalid token_type. Expected 'Bearer'.\n");
        goto error;
    }

    expires_in = json_object_get_int(json_object_object_get_ex(config, "expires_in", &config));
    if (expires_in <= 0) {
        fprintf(stderr, "Invalid expires_in value.\n");
        goto error;
