EVP_CIPHER_CTX* create_custom_cipher(EVP_CIPHER** cipher, int mode) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    switch (mode) {
        case 1: // CBC
            *cipher = EVP_aes_256_cbc();
            break;
        case 2: // GCM
            *cipher = EVP_aes_256_gcm();
            break;
        case 3: // CTR
            *cipher = EVP_aes_256_ctr();
            break;
        default:
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, *cipher, NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
