void modify_filename(const char* original_filename, const char* extension_prefix) {
    int num_digits = 0;
    for (const char* p = original_filename; *p != '\0'; ++p) {
        if (*p >= '0' && *p <= '9') {
            ++num_digits;
        }
    }

    char new_filename[256];
    sprintf(new_filename, "%s_%d.%s", original_filename, num_digits, extension_prefix);
    printf("New filename: %s\n", new_filename);
}

