import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_chunk_hash(file_path, chunk_size=64*1024):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def process_file(file_path):
    try:
        file_hash = calculate_chunk_hash(file_path)
        print(f"Processed {file_path}: {file_hash}")
    except Exception as e:
        print(f"Error processing {file_path}: {e}")

def process_files_concurrently(file_paths, max_workers=4):
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(process_file, file_path): file_path for file_path in file_paths}
        for future in as_completed(futures):
            file_path = futures[future]
            try:
                future.result()
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

if __name__ == "__main__":
    # Example usage
    single_file_path = "large_file.txt"
    batch_file_paths = ["file1.txt", "file2.txt", "file3.txt"]

    process_files_concurrently([single_file_path] + batch_file_paths)
```

