#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALGORITHM_AES "AES-256-CBC"
#define ALGORITHM_CAMELLIA "Camellia-256-CBC"
#define ALGORITHM_MD5 "MD5"
#define ALGORITHM_SHA1 "SHA1"
#define ALGORITHM_SHA256 "SHA256"
#define ALGORITHM_RSA "RSA"

void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}

EVP_CIPHER_CTX *createCipherCtx(const char *algorithm, int encrypt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx)
        handleErrors();

    if (1 != EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(algorithm), NULL, NULL, NULL))
        handleErrors();

    if (!encrypt && 1 != EVP_CIPHER_CTX_set_padding(ctx, 0))
        handleErrors();

    return ctx;
}

void encryptData(EVP_CIPHER_CTX *ctx, const unsigned char *plaintext, int plaintextLen,
                unsigned char *ciphertext) {
    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintextLen))
        handleErrors();
    ciphertext += len;

    int ciphertextLen;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext, &ciphertextLen))
        handleErrors();

    *ciphertext += ciphertextLen;
}

void decryptData(EVP_CIPHER_CTX *ctx, const unsigned char *ciphertext, int ciphertextLen,
                unsigned char *plaintext) {
    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertextLen))
        handleErrors();
    plaintext += len;

    int plaintextLen;
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext, &plaintextLen))
        handleErrors();

    *plaintext += plaintextLen;
}

unsigned char* optimizeStringHandler(const char *str, size_t sizeLimit, int optimized) {
    if (!str)
        return NULL;

    size_t len = strlen(str);
    if (len < sizeLimit && !optimized) {
        unsigned char *result = malloc(len + 2);
        if (!result)
            return NULL;
        memcpy(result, str, len);
        result[len] = '/';
        result[len + 1] = '\0';
        return result;
    } else {
        // Handle optimized mode or other operations
        return NULL;
    }
}

int main() {
    // Example usage of the library functions
    EVP_CIPHER_CTX *ctx = createCipherCtx(ALGORITHM_AES, 1);
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv)))
        handleErrors();

    unsigned char plaintext[] = "Hello, World!";
    size_t ciphertextLen = sizeof(plaintext) + EVP_CIPHER_block_size(EVP_aes_256_cbc());
    unsigned char *ciphertext = malloc(ciphertextLen);
    if (!ciphertext)
        handleErrors();

    encryptData(ctx, (unsigned char *)plaintext, sizeof(plaintext), ciphertext);

    // Decrypt data here
    // ...

    EVP_CIPHER_CTX_free(ctx);
    free(ciphertext);

    return 0;
