int parseEncryptionConfig(const char *configJson, EncryptionConfig *config) {
    json_object *jsonObj = json_tokener_parse(configJson);
    if (!jsonObj) {
        return -1; // Invalid JSON
    }

    const char *cipherMode = json_object_get_string(json_object_object_get_ex(jsonObj, "mode", NULL));
    const char *keyStr = json_object_get_string(json_object_object_get_ex(jsonObj, "key", NULL));

    if (strcmp(cipherMode, "ECB") == 0) {
        config->cipher = EVP_aes_256_ecb();
    } else if (strcmp(cipherMode, "EDE") == 0) {
        config->cipher = EVP_aes_256_cbc();
    } else if (strcmp(cipherMode, "EDE3") == 0) {
        config->cipher = EVP_aes_192_ecb();
    } else if (strcmp(cipherMode, "CFB") == 0) {
        config->cipher = EVP_aes_256_cfb();
    } else if (strcmp(cipherMode, "NULL") == 0) {
        return 0; // No encryption
    } else {
        json_object_put(jsonObj);
        return -1; // Invalid cipher mode
    }

    memcpy(config->key, keyStr, sizeof(config->key));

    json_object_put(jsonObj);
    return 0;
