<?php
class CryptoUtils {
    private $chars;

    public function __construct($charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        $this->chars = $charset;
    }

    public function generateString($length) {
        if (!is_int($length) || $length < 1) {
            throw new InvalidArgumentException('Length must be a positive integer.');
        }
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->chars[random_int(0, strlen($this->chars) - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password) {
        if (!is_string($password)) {
            throw new InvalidArgumentException('Password must be a string.');
        }
        $salt = bin2hex(random_bytes(32));
        return password_hash($password . $salt, PASSWORD_BCRYPT);
    }
}

// Example usage:
$utils = new CryptoUtils();
echo "Random String: " . $utils->generateString(10) . "\n";
echo "Password Hash: " . $utils->hashPassword('mysecretpassword') . "\n";
?>
