### PHP Code (CryptoUtils Class)

```php
class CryptoUtils {
    public static function generateRandomString($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        if ($length < 1) throw new InvalidArgumentException("Length must be greater than 0");
        if (empty($charset)) throw new InvalidArgumentException("Character set cannot be empty");

        return substr(str_shuffle(str_repeat($charset, ceil($length / strlen($charset)))), 0, $length);
    }

    public static function hashPassword($password) {
        $salt = bin2hex(random_bytes(16));
        return password_hash($password . $salt, PASSWORD_BCRYPT);
    }

    public static function encryptData($data, $key, $iv = null) {
        if ($iv === null) $iv = openssl_random_pseudo_bytes(openssl_cipher_iv_length('aes-256-cbc'));
        $encrypted = openssl_encrypt($data, 'aes-256-cbc', $key, OPENSSL_RAW_DATA, $iv);
        return base64_encode($encrypted . '::' . bin2hex($iv));
    }

    public static function decryptData($data, $key) {
        list($encrypted_data, $iv_hex) = explode('::', base64_decode($data), 2);
        $iv = hex2bin($iv_hex);
        return openssl_decrypt($encrypted_data, 'aes-256-cbc', $key, OPENSSL_RAW_DATA, $iv);
    }
}
```

