    int *keys = (int *)malloc(num_records * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * 1024;
        keys[i] = rand() % 1000;  // Random value between 0 and 999

        // Calculate total memory usage
        if (i == num_records - 1 && ((size_t)((char *)keys + num_records * sizeof(int)) - (size_t)offsets) > max_size) {
            fprintf(stderr, "Memory allocation exceeds maximum size limit.\n");
            free(offsets);
            free(keys);
            return;
        }
    }

    // Integrate with larger application context

    // Free allocated memory
    free(offsets);
    free(keys);
}

int main() {
