#include <openssl/evp.h>
#include <openssl/pem.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to add cryptographic primitives
void add_cryptographic_primitives() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest(EVP_sha3(256));
}

// Secure key loading routine
EVP_PKEY* load_key(const char* filename, const char* passphrase) {
    FILE* fp = fopen(filename, "rb");
    if (!fp) return NULL;

    EVP_PKEY* pkey = PEM_read_PrivateKey(fp, NULL, NULL, (void*)passphrase);
    fclose(fp);

    return pkey;
}

// Data verification using SHA-256
int verify_data_integrity(const unsigned char* data, size_t len, const unsigned char* stored_hash) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, data, len);
    SHA256_Final(hash, &sha256);

    return memcmp(hash, stored_hash, SHA256_DIGEST_LENGTH) == 0;
}

// Main function for cryptographic operations
unsigned char* decrypt_data(const unsigned char* encrypted_data, size_t len, const EVP_PKEY* pkey, size_t* output_len) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    if (!verify_data_integrity(encrypted_data, len, hash)) return NULL;

    unsigned char decrypted_data[len];
    int decrypted_len = 0;
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (EVP_OpenInit_ex(ctx, EVP_aes_256_cbc(), NULL, pkey->pkey.rsa->n, pkey->pkey.rsa->d, encrypted_data, &decrypted_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_OpenUpdate(ctx, decrypted_data + decrypted_len, &decrypted_len, encrypted_data + SHA256_DIGEST_LENGTH, len - SHA256_DIGEST_LENGTH) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_OpenFinal_ex(ctx, decrypted_data + decrypted_len, &decrypted_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    *output_len = decrypted_len;
    EVP_CIPHER_CTX_free(ctx);
    return decrypted_data;
}
```

