#include <asio.hpp>
#include <boost/serialization/string.hpp>
#include <boost/archive/text_iarchive.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/shared_ptr.hpp>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <random>
#include <chrono>
#include <iostream>

class TaskDispatcher {
public:
    virtual void SubmitTask(const std::string& task) = 0;
};

class MockTaskDispatcher : public TaskDispatcher {
public:
    void SubmitTask(const std::string& task) override {
        // Simulate different failure modes
        static std::mt19937 gen(std::random_device{}());
        static std::uniform_int_distribution<> dis(1, 5);
        int failureMode = dis(gen);

        if (failureMode == 1) {
            std::cout << "Task submitted successfully: " << task << std::endl;
        } else if (failureMode == 2) {
            std::cout << "Timeout for task: " << task << std::endl;
        } else {
            std::cerr << "Resource exhaustion in task submission: " << task << std::endl;
        }
    }
};

class TaskQueueManager {
private:
    asio::io_context ioContext_;
    boost::shared_ptr<TaskDispatcher> dispatcher_;
    std::queue<std::string> tasks_;
    std::mutex queueMutex_;
    std::condition_variable notEmpty_;
    int activeWorkers_;
    int maxWorkers_;
    int successCount_;
    int pendingCount_;
    int failedCount_;

public:
    TaskQueueManager(int maxWorkers) : ioContext_(), dispatcher_(new MockTaskDispatcher()), maxWorkers_(maxWorkers), activeWorkers_(0), successCount_(0), pendingCount_(0), failedCount_(0) {}

    void AddTask(const std::string& task, bool prioritize = false) {
        std::unique_lock<std::mutex> lock(queueMutex_);
        if (prioritize) {
            // Insert at the front for prioritization
            tasks_.emplace_front(task);
        } else {
            tasks_.push(task);
        }
        notEmpty_.notify_one();
    }

    void StartWorkers() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            notEmpty_.wait(lock, [this] { return !tasks_.empty() || activeWorkers_ == 0; });

            if (activeWorkers_ == maxWorkers_) {
                break;
            }

            ++activeWorkers_;
            ioContext_.post([this]() {
                try {
                    std::string task = tasks_.front();
                    tasks_.pop();

                    // Simulate network latency and packet loss
                    std::this_thread::sleep_for(std::chrono::milliseconds(100 + rand() % 50));

                    dispatcher_->SubmitTask(task);

                    ++successCount_;
                } catch (...) {
                    ++failedCount_;
                    std::cerr << "Unhandled exception in task processing" << std::endl;
                }

                --activeWorkers_;

                // Notify workers to continue
                if (!tasks_.empty()) {
                    notEmpty_.notify_one();
                }
            });
        }
    }

    void StopWorkers() {
        ioContext_.stop();
    }

    void PrintStatistics() const {
        std::cout << "Statistics: Success=" << successCount_
                  << ", Pending=" << pendingCount_
                  << ", Failed=" << failedCount_ << std::endl;
    }
};

int main() {
    TaskQueueManager manager(4);
    manager.AddTask("Task 1", true);
    manager.AddTask("Task 2");
    manager.StartWorkers();
    manager.StopWorkers();
    manager.PrintStatistics();
    return 0;
}
