import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;

public class StringProcessor {

    public static List<String> processAndInsertStrings(List<String> forwardList, String firstString, String secondString) {
        List<String> validHashes = new ArrayList<>();
        List<CompletableFuture<String>> futures = new ArrayList<>();

        // Process strings using parallel streams
        for (String input : forwardList) {
            CompletableFuture<String> future = CompletableFuture.supplyAsync(() -> computeMd5(input), 
                    CompletableFuture.delayedExecutor(0, TimeUnit.MILLISECONDS));
            futures.add(future);
        }

        // Collect valid hashes and handle exceptions
        CompletableFuture<Void> allFutures = CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]));
        allFutures.thenRun(() -> {
            for (CompletableFuture<String> future : futures) {
                try {
                    String result = future.get();
                    if (isValidHash(result)) {
                        validHashes.add(result);
                    }
                } catch (Exception e) {
                    // Log exception without crashing
                    System.err.println("Error processing string: " + e.getMessage());
                }
            }
        });

        // Insert the second string after the first occurrence of the first string
        int index = forwardList.indexOf(firstString);
        if (index != -1) {
            forwardList.add(index + 1, secondString);
        } else {
            forwardList.add(secondString);
        }

        return validHashes;
    }

    private static String computeMd5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(no.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private static boolean isValidHash(String hash) {
        // Validate MD5 hash format
        return hash.matches("[a-fA-F0-9]{32}");
    }

    public static void main(String[] args) {
        List<String> forwardList = Arrays.asList("input1", "input2", "malformedInput!");
        String firstString = "input1";
        String secondString = "insertedString";

        List<String> validHashes = processAndInsertStrings(forwardList, firstString, secondString);
        System.out.println("Valid MD5 hashes: " + validHashes);
    }
}
