public class SecurityUtils {

    // Method to generate a random string
    public static String generateRandomString(int length, String charset) {
        SecureRandom random = new SecureRandom();
        StringBuilder sb = new StringBuilder(length);
        for (int i = 0; i < length; i++) {
            int index = random.nextInt(charset.length());
            sb.append(charset.charAt(index));
        }
        return sb.toString();
    }

    // Method to securely hash a password
    public static String hashPassword(String password) {
        String salt = BCrypt.gensalt();
        return BCrypt.hashpw(password, salt);
    }

    // Method to validate an OAuth2 access token
    public static boolean validateAccessToken(String accessTokenJson) {
        ObjectMapper mapper = new ObjectMapper();
        try {
            Access-Token token = mapper.readValue(accessTokenJson, Access-Token.class);
            if ("Bearer".equals(token.getToken_type()) && token.getExpires_in() > 0) {
                return true;
            }
        } catch (Exception e) {
            // Handle JSON parsing errors gracefully
        }
        return false;
