#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to encrypt data using OpenSSL
int encryptData(unsigned char *plaintext, int plaintext_len, unsigned char *key,
                unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto end;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto end;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto end;
    ciphertext_len += len;

end:
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len < 0 ? -1 : ciphertext_len;
}

// Function to send encrypted data to database
DataTableReader* sendEncryptedDataToDatabase(const char *filePath, const char *cmdOption,
                                            const char *dbConnectionString) {
    // Read file content and perform encryption based on cmdOption
    FILE *file = fopen(filePath, "rb");
    if (!file)
        return create_error_data_table_reader("Failed to open file");

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char *plaintext = (unsigned char *)malloc(fileSize);
    if (!plaintext) {
        fclose(file);
        return create_error_data_table_reader("Memory allocation failed");
    }

    fread(plaintext, 1, fileSize, file);
    fclose(file);

    unsigned char key[32], iv[16];
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    int encryptedLen = encryptData(plaintext, fileSize, key, iv, plaintext);
    if (encryptedLen < 0) {
        free(plaintext);
        return create_error_data_table_reader("Encryption failed");
    }

    // Create SQL command for inserting encrypted data
    char sql[1024];
    snprintf(sql, sizeof(sql), "INSERT INTO encrypted_data (data, key, iv) VALUES (?, ?, ?)");

    // Execute SQL command and retrieve result set
    DataTableReader *result = execute_sql_command(sql, plaintext, encryptedLen, key, iv);

    free(plaintext);
    return result;
}
