#define MAX_FILENAME_LEN 256

void generateUniqueFilename(const char* inputFilename, const char* fileType, int numDigits, const char* directory, char* outputFilename) {
    struct dirent** namelist;
    int n = scandir(directory, &namelist, NULL, alphasort);
    if (n < 0) perror("scandir");

    int suffix = 1;
    char baseFilename[MAX_FILENAME_LEN];
    char extension[MAX_FILENAME_LEN];
    strncpy(baseFilename, inputFilename, MAX_FILENAME_LEN);
    baseFilename[MAX_FILENAME_LEN - 1] = '\0';
    char* lastDot = strrchr(baseFilename, '.');
    if (lastDot) {
        strcpy(extension, lastDot + 1);
        *lastDot = '\0';
    } else {
        strcpy(extension, "");
    }

    snprintf(outputFilename, MAX_FILENAME_LEN, "%s_%.*d.%s", baseFilename, numDigits, suffix++, extension);

    while (directory != NULL) {
        if (strcmp(namelist[i]->d_name, outputFilename) == 0) {
            snprintf(outputFilename, MAX_FILENAME_LEN, "%s_%.*d.%s", baseFilename, numDigits, suffix++, extension);
            i = -1;
        }
        free(namelist[i]);
    }

    if (n >= 0) free(namelist);
}

int main() {
    const char* inputFilename = "example.txt";
    const char* fileType = "log";
    int numDigits = 3;
    const char* directory = "/path/to/directory";
    char outputFilename[MAX_FILENAME_LEN];

    generateUniqueFilename(inputFilename, fileType, numDigits, directory, outputFilename);
    printf("Generated unique filename: %s\n", outputFilename);

    return 0;
}
