void initializeOctreeAndEncryptFile(const std::string& configJson, const std::string& inputFile) {
    // Parse JSON configuration
    Json::Value config = Json::parse(configJson);

    // Initialize encryption settings from JSON
    std::string cipherMode = config["cipher_mode"].asString();
    std::string key = config["key"].asString();
    std::string iv = config["iv"].asString();

    // Load input file and read content
    std::ifstream inFile(inputFile);
    if (!inFile.is_open()) {
        std::cerr << "Error opening file: " << inputFile << std::endl;
        return;
    }
    std::string fileContent((std::istreambuf_iterator<char>(inFile)), std::istreambuf_iterator<char>());

    // Encrypt file content
    EVP_CIPHER* cipher = nullptr;
    if (cipherMode == "ECB") {
        cipher = EVP_aes_256_ecb();
    } else if (cipherMode == "EDE") {
        cipher = EVP_aes_256_cbc();
    } else if (cipherMode == "EDE3") {
        cipher = EVP_aes_192_cbc();
    } else if (cipherMode == "CFB") {
        cipher = EVP_aes_128_cfb();
    }

    if (!cipher) {
        std::cerr << "Unsupported cipher mode: " << cipherMode << std::endl;
        return;
    }

    unsigned char encryptedContent[fileContent.size()];
    int encryptedLen;
    if (EVP_EncryptInit_ex(EVP_CIPHER_CTX_new(), cipher, nullptr, (unsigned char*)key.c_str(), (unsigned char*)iv.c_str()) != 1) {
        std::cerr << "Error initializing encryption context" << std::endl;
        return;
    }

    if (EVP_EncryptUpdate(EVP_CIPHER_CTX_new(), encryptedContent, &encryptedLen, (unsigned char*)fileContent.c_str(), fileContent.size()) != 1) {
        std::cerr << "Error encrypting content" << std::endl;
        return;
