    int bearerCount;
    pthread_mutex_t mutex;
    time_t lastActivityTime;
} UeContext;

UeContext* ueContexts[MAX_UE_CONTEXTS];
int nextUeId = 0;
pthread_mutex_t contextManagerMutex;

void initializeUeContext(UeContext **ueContext, int *bearerIds, int bearerCount) {
    *ueContext = (UeContext *)malloc(sizeof(UeContext));
    (*ueContext)->ueId = nextUeId++;
    (*ueContext)->rrcState = RRC_IDLE;
    (*ueContext)->bearers = (RadioBearer *)malloc(bearerCount * sizeof(RadioBearer));
    (*ueContext)->bearerCount = bearerCount;

    for (int i = 0; i < bearerCount; i++) {
        (*ueContext)->bearers[i].bearerId = bearerIds[i];
        (*ueContext)->bearers[i].qosParameters = /* Initialize QoS parameters */;
        (*ueContext)->bearers[i].securityContext = /* Initialize security context */;
    }

    pthread_mutex_init(&(*ueContext)->mutex, NULL);
    time_t currentTime;
    time(&currentTime);
    (*ueContext)->lastActivityTime = currentTime;

    pthread_mutex_lock(&contextManagerMutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ueContexts[i] == NULL) {
            ueContexts[i] = *ueContext;
            break;
        }
    }
    pthread_mutex_unlock(&contextManagerMutex);
}

void reclaimInactiveUeContexts() {
    time_t currentTime;
    time(&currentTime);

    pthread_mutex_lock(&contextManagerMutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ueContexts[i] != NULL && difftime(currentTime, ueContexts[i]->lastActivityTime) > INACTIVE_TIMEOUT) {
            free(ueContexts[i]->bearers);
            free(ueContexts[i]);
            ueContexts[i] = NULL;
        }
    }
    pthread_mutex_unlock(&contextManagerMutex);
}

void *manageUeContexts(void *arg) {
    while (1) {
        reclaimInactiveUeContexts();
        sleep(1); // Check every second
    }
}

