typedef enum {
    EVP_ENCRYPT,
    EVP_DECRYPT
} EVP_CIPHER_MODE;

typedef struct {
    const EVP_CIPHER *cipher;
    int block_size;
    EVP_CIPHER_MODE mode;
} CipherSuite;

typedef struct {
    CipherSuite suite;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    void (*encrypt)(unsigned char *, size_t, unsigned char *);
    void (*decrypt)(unsigned char *, size_t, unsigned char *);
} EncryptionModule;

void null_encrypt(unsigned char *data, size_t len, unsigned char *key) {
    (void)data;
    (void)len;
    (void)key;
}

void null_decrypt(unsigned char *data, size_t len, unsigned char *key) {
    (void)data;
    (void)len;
    (void)key;
}

EncryptionModule create_encryption_module(CipherSuite suite, unsigned char *key, unsigned char *iv) {
    EncryptionModule module = { suite, key, iv, null_encrypt, null_decrypt };

    if (suite.cipher == EVP_aes_128_ecb) {
        module.encrypt = EVP_EncryptUpdate;
        module.decrypt = EVP_DecryptUpdate;
    } else if (suite.cipher == EVP_aes_192_ecb) {
        // Handle AES-192 ECB
