public class DynamicRangeGenerator
{
    private Dictionary<string, (float min, float max, RangeType type, BoundaryMode mode)> ranges;
    private static readonly string defaultFloatRange = "0-1";
    private static readonly string defaultIntRange = "0-100";

    public DynamicRangeGenerator()
    {
        ranges = new Dictionary<string, (float, float, RangeType, BoundaryMode)>();
    }

    // Method to add a new range
    public void AddRange(string name, float min, float max, RangeType type, BoundaryMode mode)
    {
        if (IsValidRange(min, max, type))
        {
            ranges[name] = (min, max, type, mode);
            LogOperation($"Added range {name}: Min={min}, Max={max}, Type={type}, Mode={mode}");
        }
        else
        {
            throw new ArgumentException("Invalid range values.");
        }
    }

    // Method to remove a range
    public void RemoveRange(string name)
    {
        if (ranges.ContainsKey(name))
        {
            ranges.Remove(name);
            LogOperation($"Removed range {name}");
        }
    }

    // Method to modify an existing range
    public void ModifyRange(string name, float min, float max, RangeType type, BoundaryMode mode)
    {
        if (IsValidRange(min, max, type) && ranges.ContainsKey(name))
        {
            ranges[name] = (min, max, type, mode);
            LogOperation($"Modified range {name}: Min={min}, Max={max}, Type={type}, Mode={mode}");
        }
        else
        {
            throw new ArgumentException("Invalid range values or range does not exist.");
        }
    }

    // Method to reset a range to default
    public void ResetRangeToDefault(string name)
    {
        if (ranges.ContainsKey(name))
        {
            ranges[name] = (name == "defaultFloat" ? ParseRange(defaultFloatRange) : ParseRange(defaultIntRange));
            LogOperation($"Reset range {name} to default");
        }
    }

    // Method to serialize the state of ranges
    public void SerializeToFile(string filePath)
    {
        string data = Serialize();
        File.WriteAllText(filePath, data);
        LogOperation("Serialized ranges to file");
    }

    // Method to deserialize the state of ranges from a file
    public void DeserializeFromFile(string filePath)
    {
        if (File.Exists(filePath))
        {
            string data = File.ReadAllText(filePath);
            Deserialize(data);
            LogOperation("Deserialized ranges from file");
        }
    }

    private bool IsValidRange(float min, float max, RangeType type)
    {
        // Implement validation logic based on the range type and boundaries
        return true;
