    {
        // Implement parsing logic to convert a string range into a tuple of values
        return (0, 1, RangeType.Float, BoundaryMode.Inclusive);
    }

    private string Serialize()
    {
        StringBuilder sb = new StringBuilder();
        foreach (var range in ranges)
        {
            sb.AppendLine($"{range.Key}:{range.Value.min}-{range.Value.max},{(int)range.Value.type},{(int)range.Value.mode}");
        }
        return sb.ToString();
    }

    private void Deserialize(string data)
    {
        string[] lines = data.Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries);
        foreach (var line in lines)
        {
            string[] parts = line.Split(':');
            if (parts.Length == 2)
            {
