                    float max = float.Parse(rangeParts[1]);
                    RangeType type = (RangeType)int.Parse(rangeParts[2]);
                    BoundaryMode mode = (BoundaryMode)int.Parse(rangeParts[3]);
                    ranges[parts[0]] = (min, max, type, mode);
                }
