```java
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.concurrent.ConcurrentHashMap;

public class LoggerManager {
    private ConcurrentHashMap<String, Logger> loggers = new ConcurrentHashMap<>();
    private static final SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    public void setupLogger(String name) {
        if (!loggers.containsKey(name)) {
            loggers.put(name, new Logger(name));
        }
    }

    public void log(String loggerName, String level, String message) {
        Logger logger = loggers.get(loggerName);
        if (logger != null) {
            logger.log(level, message);
        } else {
            System.err.println("Logger not found: " + loggerName);
        }
    }

    static class Logger {
        private final String name;
        private final ThreadLocal<String> threadId = new ThreadLocal<>();

        public Logger(String name) {
            this.name = name;
        }

        public void log(String level, String message) {
            if (threadId.get() == null) {
                threadId.set(Thread.currentThread().getId() + "");
            }
            String timestamp = dateFormat.format(new Date());
            System.out.println(timestamp + " [" + level + "] [" + name + "] [" + threadId.get() + "] " + message);
        }
    }

    public static void main(String[] args) {
        LoggerManager manager = new LoggerManager();
        manager.setupLogger("my_logger");
        manager.log("my_logger", "INFO", "This is an info message");
    }
}
