        }

        ScaleDimensions(mediaFile, getOptimalResolution());

        Response* uploadResponse = uploadToCloud(mediaFile, cloudUrl);

        if (uploadResponse->status == SUCCESS) {
            response.data = uploadResponse->data;
            response.size = uploadResponse->size;
        } else {
            fprintf(stderr, "Failed to upload media to cloud: %s\n", uploadResponse->error);
