char* optimizeStringHandler(const char* str, size_t sizeLimit, int mode) {
    if (str == NULL || sizeLimit == 0) {
        return NULL;
    }

    size_t len = strlen(str);
    if (mode && len < sizeLimit - 1) {
        // Create a new string with space for the additional character
        char* result = malloc(len + 2);
        if (result != NULL) {
            strcpy(result, str);
            result[len] = '/';
            result[len + 1] = '\0';
        }
        return result;
    } else if (!mode && len < sizeLimit - 1) {
        // Append a slash to the original string
        char* newStr = realloc((char*)str, len + 2);
        if (newStr != NULL) {
            strcpy(newStr + len, "/");
            newStr[len + 1] = '\0';
        }
        return newStr;
