// Custom alias for AES encryption
void aes_encrypt(const unsigned char *plaintext, size_t plaintext_len, const unsigned char *key, const unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, (int *)&plaintext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// Custom alias for Camellia encryption
void camellia_encrypt(const unsigned char *plaintext, size_t plaintext_len, const unsigned char *key, const unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, (int *)&plaintext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// Custom alias for MD5 hashing
void md5_hash(const unsigned char *data, size_t data_len, unsigned char *digest) {
    MD5(data, data_len, digest);
}

// Custom alias for SHA-256 hashing
void sha256_hash(const unsigned char *data, size_t data_len, unsigned char *digest) {
    SHA256(data, data_len, digest);
}

// Custom alias for RSA encryption with PKCS#1 padding
int rsa_encrypt(const unsigned char *plaintext, size_t plaintext_len, RSA *rsa, unsigned char *ciphertext) {
    return RSA_public_encrypt(plaintext_len, plaintext, ciphertext, rsa, RSA_PKCS1_PADDING);
}
