    union {
        FILE* file;
        int console_fd;
        // Network connection details
    };
    char output_file[256];
} LogDestination;

// Logging buffer structure
typedef struct {
    LogMessage messages[1000];
    int head;
    int tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int size;
} LogBuffer;

// Initialize logging buffer
void init_log_buffer(LogBuffer* buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 1000;
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->cond, NULL);
}

// Add log message to buffer
void add_to_log_buffer(LogBuffer* buffer, LogMessage msg) {
    pthread_mutex_lock(&buffer->mutex);
    while (buffer->size == (buffer->tail - buffer->head + 1000) % 1000) {
        pthread_cond_wait(&buffer->cond, &buffer->mutex);
    }
    buffer->messages[buffer->tail] = msg;
    buffer->tail = (buffer->tail + 1) % 1000;
    pthread_cond_signal(&buffer->cond);
    pthread_mutex_unlock(&buffer->mutex);
}

// Log message to destination
void log_to_destination(LogDestination* dest, LogMessage msg) {
    switch (dest->type) {
        case FILE_OUTPUT:
            fprintf(dest->file, "%s\n", msg.message);
            break;
        case CONSOLE_OUTPUT:
            printf("%s\n", msg.message);
            break;
        case NETWORK_OUTPUT:
            // Implement network logging
            break;
    }
}

// Asynchronous log thread function
void* async_log_thread(void* arg) {
    LogBuffer* buffer = (LogBuffer*)arg;
    while (1) {
        pthread_mutex_lock(&buffer->mutex);
        while (buffer->head == buffer->tail) {
            pthread_cond_wait(&buffer->cond, &buffer->mutex);
        }
        LogMessage msg = buffer->messages[buffer->head];
        buffer->head = (buffer->head + 1) % 1000;
        pthread_mutex_unlock(&buffer->mutex);

        for (int i = 0; i < num_destinations; i++) {
            log_to_destination(destinations + i, msg);
        }
    }
}

// Initialize logging system
void init_logging_system(int num_threads) {
    buffer = (LogBuffer*)malloc(sizeof(LogBuffer));
    init_log_buffer(buffer);

    for (int i = 0; i < num_threads; i++) {
        pthread_create(&log_thread[i], NULL, async_log_thread, buffer);
    }
}

// Log a message
void log_message(LogLevel level, char* format, ...) {
    va_list args;
    va_start(args, format);
    vsnprintf(msg.message, 1024, format, args);
    msg.level = level;

    add_to_log_buffer(buffer, msg);
}

// Main function for demonstration
int main() {
    init_logging_system(5);

    log_message(INFO, "Application started");

    // Simulate logging messages
    for (int i = 0; i < 100; i++) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "Processing message %d", i);
        log_message(DEBUG, "%s", buffer);
    }

    log_message(INFO, "Application finished");

    return 0;
}
