// Function to modify filename extension
char* modify_filename_extension(const char* filename, const char* file_type) {
    // Allocate memory for the new filename
    size_t new_length = strlen(filename) + 10 + strlen(file_type); // Allow for unique identifier and type
    char* new_filename = malloc(new_length * sizeof(char));
    if (new_filename == NULL) {
        return NULL; // Handle memory allocation failure
    }

    // Copy the original filename to the new buffer
    strcpy(new_filename, filename);

    // Find the last dot in the filename to replace with the unique identifier and file type
    char* dot_position = strrchr(new_filename, '.');
    if (dot_position != NULL) {
        *dot_position = '\0'; // Null-terminate at the dot
        size_t digits_needed = strlen(new_filename); // Determine number of digits needed based on length
        if (digits_needed > 10) {
            digits_needed = 10; // Cap the number of digits to 10 if longer than necessary
        }
        char unique_id[12]; // Buffer for the unique identifier
        sprintf(unique_id, "_%.*d%s", (int)digits_needed, rand() % 999999999 + 1, file_type);
        strcat(new_filename, unique_id); // Append the unique identifier and type to the filename
    } else {
        // If no dot is found, append the entire file type as the extension
        strcat(new_filename, file_type);
    }

    return new_filename;
}

