#include <stdlib.h>
#include <pthread.h>

typedef struct TransportChannel {
    int qos;
    int flowControl;
} TransportChannel;

typedef struct NetworkService {
    int serviceID;
    int connectionState;
    TransportChannel* channels;
    int channelCount;
    pthread_mutex_t lock;
} NetworkService;

NetworkService* createNetworkService(int id, int initialState, TransportChannel* channels, int count) {
    NetworkService* service = (NetworkService*)malloc(sizeof(NetworkService));
    if (service == NULL) {
        return NULL; // Handle memory allocation failure
    }
    service->serviceID = id;
    service->connectionState = initialState;
    service->channels = channels;
    service->channelCount = count;
    pthread_mutex_init(&service->lock, NULL);
    return service;
}

void updateConnectionState(NetworkService* service, int newState) {
    pthread_mutex_lock(&service->lock);
    service->connectionState = newState;
    pthread_mutex_unlock(&service->lock);
}

int getChannelQoS(NetworkService* service, int index) {
    if (index < 0 || index >= service->channelCount) {
        return -1; // Invalid channel index
    }
    pthread_mutex_lock(&service->lock);
    int qos = service->channels[index].qos;
    pthread_mutex_unlock(&service->lock);
    return qos;
}

void setChannelQoS(NetworkService* service, int index, int newQoS) {
    if (index < 0 || index >= service->channelCount) {
        return; // Invalid channel index
    }
    pthread_mutex_lock(&service->lock);
    service->channels[index].qos = newQoS;
    pthread_mutex_unlock(&service->lock);
}
