    if (size == 0) {
        fprintf(stderr, "Empty input\n");
        exit(1);
    }
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

