    printf("Enter the number of integers: ");
    scanf("%d", &size);

    int arr[size];
    printf("Enter the integers:\n");
    for (int i = 0; i < size; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Invalid input\n");
