public class StringProcessor {

    public static List<String> processAndInsertStrings(CopyOnWriteArrayList<String> forwardList, String firstString, String secondString) {
        List<String> validMD5Hashes = new ArrayList<>();

        try {
            // Process and filter MD5 hashes in parallel
            for (String input : forwardList.parallelStream().filter(s -> isValidInput(s)).toList()) {
                String md5Hash = computeMD5(input);
                if (isValidMD5(md5Hash)) {
                    validMD5Hashes.add(md5Hash);
                }
            }

            // Find the index of the first occurrence of the first string
            int index = forwardList.indexOf(firstString);

            // Insert the second string after the first occurrence or at the end
            if (index != -1) {
                forwardList.add(index + 1, secondString);
            } else {
                forwardList.add(secondString);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return validMD5Hashes;
    }

    private static boolean isValidInput(String input) {
        // Implement validation logic here
        return true;
    }

    private static String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static boolean isValidMD5(String md5) {
        // Implement validation logic here
