typedef struct {
    time_t timestamp;
    int event_id;
    int status_code;
} data_entry;

// Function to dynamically allocate and initialize an array of data_entry structures
data_entry* create_data_entries(time_t start_time, int num_events, int min_event_id, int max_event_id, int* status_codes, int status_count) {
    // Allocate memory for the array of data_entry structures
    data_entry* entries = (data_entry*)malloc(num_events * sizeof(data_entry));
    if (entries == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    // Populate the array with initial values and random status codes
    for (int i = 0; i < num_events; i++) {
        entries[i].timestamp = start_time + i;
        entries[i].event_id = rand() % (max_event_id - min_event_id + 1) + min_event_id;
        int random_index = rand() % status_count;
        entries[i].status_code = status_codes[random_index];
    }

    return entries;
}

// Example usage
int main() {
    time_t start_time = time(NULL);
    int num_events = 5000000;
    int min_event_id = 100;
    int max_event_id = 200;
    int status_codes[] = {200, 404, 500};
    int status_count = sizeof(status_codes) / sizeof(status_codes[0]);

    data_entry* entries = create_data_entries(start_time, num_events, min_event_id, max_event_id, status_codes, status_count);

    if (entries != NULL) {
        // Process the entries
        free(entries);
    }

    return 0;
}
