#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t timestamp;
    uint16_t event_id;
    uint8_t status_code;
} data_entry;

void generate_random_status(data_entry *entry, const uint8_t *status_codes, size_t status_count) {
    entry->status_code = status_codes[rand() % status_count];
}

int parse_and_generate_output(const char *input_file, const char *output_file,
                             const uint32_t start_timestamp, const uint16_t event_id_range[],
                             const uint8_t status_code_list[], size_t status_count,
                             int argc, char **argv) {
    FILE *ifp = fopen(input_file, "rb");
    if (!ifp) {
        perror("Failed to open input file");
        return -1;
    }

    // Calculate the number of entries based on event ID range
    size_t num_entries = (event_id_range[1] - event_id_range[0]) + 1;

    data_entry *entries = malloc(num_entries * sizeof(data_entry));
    if (!entries) {
        fclose(ifp);
        perror("Failed to allocate memory for entries");
        return -1;
    }

    // Populate the entries with random statuses
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < num_entries; ++i) {
        entries[i].timestamp = start_timestamp + i;
        entries[i].event_id = event_id_range[0] + i;
        generate_random_status(&entries[i], status_code_list, status_count);
    }

    // Apply transformation rules based on command-line arguments
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-uppercase") == 0) {
            for (size_t j = 0; j < num_entries; ++j) {
                entries[j].status_code += ('A' - 'a');
            }
        } else if (strcmp(argv[i], "-increment_timestamp") == 0) {
            for (size_t j = 0; j < num_entries; ++j) {
                entries[j].timestamp++;
            }
        }
    }

    // Write the transformed data to the output file
    FILE *ofp = fopen(output_file, "wb");
    if (!ofp) {
        free(entries);
        fclose(ifp);
        perror("Failed to open output file");
        return -1;
    }

    size_t bytes_written = fwrite(entries, sizeof(data_entry), num_entries, ofp);
    if (bytes_written != num_entries) {
        free(entries);
        fclose(ifp);
        perror("Failed to write data to output file");
        return -1;
    }

    // Clean up
    free(entries);
    fclose(ofp);
    fclose(ifp);

    return 0;
}
