from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import rsa

def load_cipher(name, key, iv=None):
    if name == 'AES':
        return Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
    elif name == 'Camellia':
        return Cipher(algorithms.Camellia(key), modes.CBC(iv), backend=default_backend())
    else:
        raise ValueError("Unsupported cipher: {}".format(name))

def load_digest(name):
    if name == 'MD5':
        return hashes.MD5()
    elif name == 'SHA':
        return hashes.SHA256()  # Default to SHA-256
    else:
        raise ValueError("Unsupported digest: {}".format(name))

def load_asymmetric_algorithm(name, **kwargs):
    if name == 'RSA':
        key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=2048,
            backend=default_backend()
        )
        return key
    else:
        raise ValueError("Unsupported asymmetric algorithm: {}".format(name))

# Example usage:
cipher = load_cipher('AES', b'key12345678901234', b'iv12345678901234')
digest = load_digest('SHA')
asymmetric_key = load_asymmetric_algorithm('RSA')
