import abc
from collections import defaultdict

class Logger(abc.ABC):
    @abc.abstractmethod
    def log(self, level, message):
        pass

class FileLogger(Logger):
    def __init__(self, file_path):
        self.file_path = file_path

    def log(self, level, message):
        with open(self.file_path, 'a') as file:
            file.write(f"{level}: {message}\n")

class SyslogLogger(Logger):
    import syslog
    def __init__(self, facility):
        self.facility = facility

    def log(self, level, message):
        priority = getattr(self.syslog, level.upper())
        self.syslog.openlog(facility=self.facility)
        self.syslog.syslog(priority, message)
        self.syslog.closelog()

class RotatingFileLogger(Logger):
    import logging
    from logging.handlers import RotatingFileHandler

    def __init__(self, file_path, max_bytes=1024*1024*5, backup_count=3):
        self.logger = logging.getLogger('RotatingLogger')
        handler = RotatingFileHandler(file_path, maxBytes=max_bytes, backupCount=backup_count)
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        self.logger.setLevel(logging.DEBUG)

    def log(self, level, message):
        if hasattr(self.logger, level):
            getattr(self.logger, level)(message)

class LoggingFramework:
    _loggers = defaultdict(list)

    @classmethod
    def register_logger(cls, name, logger_instance):
        cls._loggers[name].append(logger_instance)

    @classmethod
    def get_loggers(cls, names=None):
        if not names:
            return {name: loggers for name, loggers in cls._loggers.items()}
        return {name: cls._loggers.get(name, []) for name in names}

    @classmethod
    def log_message(cls, level, message, logger_names=None):
        if not logger_names:
            logger_names = list(cls._loggers.keys())
        for name in logger_names:
            for logger in cls._loggers[name]:
                try:
                    logger.log(level, message)
                except Exception as e:
                    print(f"Error logging to {name}: {e}")

# Example usage
file_logger = FileLogger('app.log')
syslog_logger = SyslogLogger(syslog.LOG_LOCAL0)
rotating_file_logger = RotatingFileLogger('app_rotated.log')

LoggingFramework.register_logger('file', file_logger)
LoggingFramework.register_logger('syslog', syslog_logger)
LoggingFramework.register_logger('rotating_file', rotating_file_logger)

LoggingFramework.log_message('info', 'This is an info message')
```

This code provides a basic structure for a flexible logging framework that supports dynamic configuration and runtime selection of loggers. It includes support for file, syslog, and rotating file logging, as well as methods for registering, retrieving, and using these loggers. The `LoggingFramework` class ensures backward compatibility while allowing for easy updates and extensions.']

