#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>

#define MAX_FILENAME_LENGTH 1024
#define MAX_EXTENSION_LENGTH 16

int generate_unique_suffix(const char *directory, const char *filename, int digits) {
    DIR *dir;
    struct dirent *entry;
    int suffix = 0;
    int found = 1;

    while (found) {
        found = 0;
        for (suffix = 0; suffix < 1000; suffix++) { // Limiting to 1000 unique files
            char new_filename[MAX_FILENAME_LENGTH];
            snprintf(new_filename, sizeof(new_filename), "%s_%d.%s", filename, suffix, "ext");
            dir = opendir(directory);
            if (dir) {
                while ((entry = readdir(dir)) != NULL) {
                    if (strcmp(entry->d_name, new_filename) == 0) {
                        found = 1;
                        break;
                    }
                }
                closedir(dir);
                if (found) {
                    continue; // Try next suffix
                }
            } else {
                perror("opendir");
                exit(EXIT_FAILURE);
            }
        }
    }

    return suffix - 1; // Return the last successful suffix used
}

char* modify_file_extension(const char *filename, const char *digits, const char *suffix) {
    char new_filename[MAX_FILENAME_LENGTH];
    snprintf(new_filename, sizeof(new_filename), "%s_%.*s.%s", filename,
             digits ? atoi(digits) : 0, strrchr(filename, '.') + 1, suffix);
    return strdup(new_filename); // Return a dynamically allocated string
}

void apply_rules_to_directory(const char *directory) {
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(directory)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            const char *filename = entry->d_name;
            // Apply rules to each file in the directory
            char *new_filename = modify_file_extension(filename, "3", "txt");
            printf("Renaming '%s' to '%s'\n", filename, new_filename);
            free(new_filename); // Free dynamically allocated string
        }
        closedir(dir);
    } else {
        perror("opendir");
        exit(EXIT_FAILURE);
    }
}

int main() {
    const char *directory = "/path/to/directory";
    apply_rules_to_directory(directory);
    return 0;
}
