#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024
#define LOG_ERROR "error"
#define LOG_WARNING "warning"
#define LOG_INFO "info"

typedef struct {
    char message[MAX_LOG_SIZE];
    time_t timestamp;
} LogEntry;

typedef struct {
    FILE *file;
    size_t max_size;
    time_t rotation_interval;
    LogEntry last_log[MAX_LOG_SIZE];
    int last_log_count;
    pthread_mutex_t mutex;
} Logger;

Logger* create_logger(const char *filename, size_t max_size, time_t rotation_interval) {
    Logger *logger = (Logger *)malloc(sizeof(Logger));
    logger->file = fopen(filename, "a");
    if (!logger->file) {
        perror("Failed to open log file");
        free(logger);
        return NULL;
    }
    logger->max_size = max_size;
    logger->rotation_interval = rotation_interval;
    logger->last_log_count = 0;
    pthread_mutex_init(&logger->mutex, NULL);
    return logger;
}

void destroy_logger(Logger *logger) {
    if (logger->file) {
        fclose(logger->file);
    }
    pthread_mutex_destroy(&logger->mutex);
    free(logger);
}

void rotate_log_file(Logger *logger) {
    time_t now = time(NULL);
    char new_filename[256];
    strftime(new_filename, sizeof(new_filename), "log_%Y%m%d_%H%M%S.txt", localtime(&now));
    if (rename(logger->file, new_filename) != 0) {
        perror("Failed to rotate log file");
    }
    logger->file = fopen(new_filename, "a");
}

void append_log_entry(Logger *logger, const char *message, const char *severity) {
    pthread_mutex_lock(&logger->mutex);
    time_t now = time(NULL);

    // Check for duplicate entries within the last 5 minutes
    if (logger->last_log_count > 0 && strcmp(logger->last_log[logger->last_log_count - 1].message, message) == 0 &&
        difftime(now, logger->last_log[logger->last_log_count - 1].timestamp) < 300) {
        pthread_mutex_unlock(&logger->mutex);
        return;
    }

    LogEntry entry = { .message = (char *)message, .timestamp = now };
    fprintf(logger->file, "[%s] [%s] %s\n", severity, ctime(&now), message);
    fflush(logger->file);

    // Store the last log entry for duplicate check
    if (logger->last_log_count < MAX_LOG_SIZE) {
        logger->last_log[logger->last_log_count++] = entry;
    } else {
        memmove(logger->last_log, logger->last_log + 1, sizeof(LogEntry) * (MAX_LOG_SIZE - 1));
        logger->last_log[MAX_LOG_SIZE - 1] = entry;
    }

    // Rotate log file if necessary
    fseek(logger->file, 0, SEEK_END);
    if (ftell(logger->file) > logger->max_size) {
        rotate_log_file(logger);
    }

    pthread_mutex_unlock(&logger->mutex);
}

int main() {
    Logger *logger = create_logger("app.log", 1024 * 1024, 86400); // 1MB max size, daily rotation
    if (!logger) {
        return EXIT_FAILURE;
    }

    append_log_entry(logger, "This is an error message.", LOG_ERROR);
    append_log_entry(logger, "This is a warning message.", LOG_WARNING);
    append_log_entry(logger, "This is an info message.", LOG_INFO);

    destroy_logger(logger);
    return EXIT_SUCCESS;
}
```

This code provides a basic framework for a flexible logging system in C. It includes functions to create and destroy the logger, log messages with severity levels, and handle log file rotation based on size and time intervals. The logger also checks for duplicate entries within a configurable time window (5 minutes in this example) and uses a mutex to prevent race conditions when writing logs from multiple threads. Note that network availability and integration with external data sources are not implemented in this basic version.']

