#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef enum { LOW, MEDIUM, HIGH } TaskPriority;

typedef struct {
    void (*task_func)(void*);
    void* arg;
    time_t deadline;
    TaskPriority priority;
} Task;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    Task** task_queue;
    int queue_size;
    int front, rear;
    int active_threads;
    int max_active_threads;
} ThreadPool;

void thread_pool_init(ThreadPool* pool, int max_threads) {
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->task_queue = (Task**)malloc(max_threads * sizeof(Task*));
    pool->queue_size = 0;
    pool->front = pool->rear = -1;
    pool->active_threads = 0;
    pool->max_active_threads = max_threads;
}

void thread_pool_destroy(ThreadPool* pool) {
    for (int i = pool->front; i != -1; i = (i + 1) % pool->queue_size) {
        free(pool->task_queue[i]);
    }
    free(pool->task_queue);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
}

void thread_pool_submit_task(ThreadPool* pool, Task* task) {
    pthread_mutex_lock(&pool->lock);
    while (pool->active_threads >= pool->max_active_threads && pool->queue_size > 0) {
        pthread_cond_wait(&pool->cond, &pool->lock);
    }
    int next_rear = (pool->rear + 1) % pool->queue_size;
    if (next_rear == pool->front) {
        // Queue is full, need to resize
        Task** new_queue = (Task**)realloc(pool->task_queue, 2 * pool->queue_size * sizeof(Task*));
        for (int i = 0; i < pool->queue_size; ++i) {
            new_queue[(pool->front + i) % pool->queue_size] = pool->task_queue[(pool->front + i) % pool->queue_size];
        }
        free(pool->task_queue);
        pool->task_queue = new_queue;
        pool->front = 0;
        next_rear = pool->queue_size;
        pool->queue_size *= 2;
    }
    pool->task_queue[next_rear] = task;
    if (pool->rear == -1) {
        pool->front = pool->rear = 0;
    } else {
        pool->rear = next_rear;
    }
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
}

void* worker_thread(void* arg) {
    ThreadPool* pool = (ThreadPool*)arg;
    while (1) {
        Task* task;
        pthread_mutex_lock(&pool->lock);
        while (pool->front == -1) {
            pthread_cond_wait(&pool->cond, &pool->lock);
        }
        int next_front = (pool->front + 1) % pool->queue_size;
        task = pool->task_queue[next_front];
        pool->front = next_front;
        if (pool->front == pool->rear) {
            pool->front = pool->rear = -1;
        } else {
            pool->front = next_front;
        }
        pool->active_threads++;
        pthread_mutex_unlock(&pool->lock);

        task->task_func(task->arg);
        free(task);

        pthread_mutex_lock(&pool->lock);
        pool->active_threads--;
        if (pool->queue_size > 0) {
            pthread_cond_signal(&pool->cond);
        }
        pthread_mutex_unlock(&pool->lock);
    }
    return NULL;
}

void thread_pool_start(ThreadPool* pool, int num_threads) {
    for (int i = 0; i < num_threads; ++i) {
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, worker_thread, (void*)pool);
        pthread_detach(thread_id); // Detach to automatically clean up
    }
}
