    std::string mode;
    std::string key;
    bool isNullEncryption;
};

struct OAuth2Response {
    std::string token_type;
    int expires_in;
};

bool validateOAuth2Token(const OAuth2Response& response) {
    return response.token_type == "Bearer" && response.expires_in > 0;
