std::string encryptFileContent(const std::string& content, const EncryptionSettings& settings) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) throw std::runtime_error("Failed to create cipher context");

    if (settings.isNullEncryption) return content;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, reinterpret_cast<const unsigned char*>(settings.key.c_str()), NULL) != 1)
        throw std::runtime_error("Failed to initialize encryption");

    std::vector<unsigned char> encrypted(content.size() + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    int len;
    if (EVP_EncryptUpdate(ctx, encrypted.data(), &len, reinterpret_cast<const unsigned char*>(content.c_str()), content.size()) != 1)
        throw std::runtime_error("Encryption failed");

    int final_len;
    if (EVP_EncryptFinal_ex(ctx, encrypted.data() + len, &final_len) != 1)
        throw std::runtime_error("Final encryption failed");

    EVP_CIPHER_CTX_free(ctx);
    encrypted.resize(len + final_len);

    return std::string(reinterpret_cast<char*>(encrypted.data()), encrypted.size());
}

