        // Parse encryption settings from JSON
        settings.mode = root["encryption"]["mode"].asString();
        settings.key = root["encryption"]["key"].asString();
        settings.isNullEncryption = root["encryption"]["null_encryption"].asBool();

        std::ifstream file(filePath);
