#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_LINE_LENGTH 1024

typedef struct {
    char* log_chunk;
    size_t chunk_size;
    int thread_id;
} LogChunk;

void* process_log_chunk(void* arg) {
    LogChunk* chunk = (LogChunk*)arg;
    // Process the log chunk here
    printf("Thread %d processing chunk of size %zu\n", chunk->thread_id, chunk->chunk_size);
    return NULL;
}

void generate_summary_report(const char* input_file, const char* output_file, const char* filter_criteria, const char* format_specifier, double memory_threshold) {
    FILE* log_file = fopen(input_file, "r");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    // Read and process the log file in chunks
    size_t total_size = 0;
    char buffer[MAX_LOG_LINE_LENGTH];
    int thread_count = 4; // Example number of threads
    pthread_t threads[thread_count];

    while (fgets(buffer, sizeof(buffer), log_file)) {
        LogChunk chunk;
        chunk.log_chunk = strdup(buffer);
        chunk.chunk_size = strlen(chunk.log_chunk);
        chunk.thread_id = total_size % thread_count;

        if (pthread_create(&threads[chunk.thread_id], NULL, process_log_chunk, &chunk) != 0) {
            perror("Failed to create thread");
            return;
        }

        free(chunk.log_chunk);

        total_size += chunk.chunk_size;

        // Check memory usage and handle constraints
        if (total_size > memory_threshold) {
            for (int i = 0; i < thread_count; i++) {
                pthread_join(threads[i], NULL);
            }
            total_size = 0;
        }
    }

    // Join any remaining threads
    for (int i = 0; i < thread_count; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return;
        }
    }

    fclose(log_file);
    printf("Summary report generated successfully\n");
}

int main(int argc, char* argv[]) {
    if (argc < 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <filter_criteria> <format_specifier> <memory_threshold>\n", argv[0]);
        return 1;
    }

    generate_summary_report(argv[1], argv[2], argv[3], argv[4], atof(argv[5]));

    return 0;
}
```

This code provides a basic structure for the `generate_summary_report` function, which reads and processes a log file in chunks. Each chunk is then processed by a separate thread to support parallelism. The function also includes basic memory usage checks to ensure that it does not exceed the specified threshold. Note that this is a simplified example and would need to be expanded and optimized for real-world use cases.']

