// Define sensor node structure
typedef struct {
    int id;
    int operational_status;
    float readings[10]; // Array to hold sensor readings
} SensorNode;

// Define time-series database structure
typedef struct {
    SensorNode* nodes;
    int size;
    pthread_mutex_t lock;
} TimeSeriesDB;

// Initialize the time-series database
void init_time_series_db(TimeSeriesDB* db, int size) {
    db->nodes = (SensorNode*)malloc(size * sizeof(SensorNode));
    db->size = size;
    pthread_mutex_init(&db->lock, NULL);
}

// Add or update sensor node data
void add_update_sensor_data(TimeSeriesDB* db, SensorNode* new_node) {
    pthread_mutex_lock(&db->lock);
    // Find the correct index to update or insert the new node
    int index = -1;
    for (int i = 0; i < db->size; i++) {
        if (db->nodes[i].id == new_node->id) {
            index = i;
            break;
        }
    }

    if (index != -1) {
        // Update existing node
        db->nodes[index] = *new_node;
    } else {
        // Add new node to the database
        for (int i = 0; i < db->size; i++) {
            if (db->nodes[i].id == 0) { // Assuming id 0 indicates an empty slot
                db->nodes[i] = *new_node;
                break;
            }
        }
    }

    pthread_mutex_unlock(&db->lock);
}

// Function to simulate data collection and aggregation
void* collect_and_aggregate_data(void* arg) {
    TimeSeriesDB* db = (TimeSeriesDB*)arg;

    while (1) {
        // Simulate data collection from sensor nodes
        SensorNode new_node;
        new_node.id = 1; // Example ID
        new_node.operational_status = 1; // Assume operational
        for (int i = 0; i < 10; i++) {
            new_node.readings[i] = rand() / (float)RAND_MAX * 100; // Random readings
        }

        // Add or update sensor data in the database
        add_update_sensor_data(db, &new_node);

        // Simulate aggregation process
        // ...

        // Sleep for a short interval before next iteration
        sleep(5);
    }

    return NULL;
}

int main() {
    TimeSeriesDB db;
    init_time_series_db(&db, 10); // Initialize database with capacity for 10 nodes

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, collect_and_aggregate_data, (void*)&db);

    pthread_join(thread_id, NULL);

    return 0;
}
