    ctx->bearers = (int*)realloc(ctx->bearers, (ctx->bearer_count + 1) * sizeof(int));
    if (ctx->bearers == NULL) {
        return;
    }
    ctx->bearers[ctx->bearer_count++] = bearer_id;
}

EVP_CIPHER* get_cipher(const char* mode) {
    if (strcmp(mode, "ECB") == 0) {
        return EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        return EVP_des_ede_cbc();
    } else if (strcmp(mode, "EDE3") == 0) {
        return EVP_des_ede3_cbc();
    } else if (strcmp(mode, "CFB") == 0) {
        return EVP_des_cfb8();
    } else if (strcmp(mode, "NULL") == 0) {
        return NULL;
    }
    return NULL;
}

int find_largest_integer(const int* array, int size) {
    if (size <= 0 || array == NULL) {
        return -1; // Error code for invalid input
    }
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int main() {
    int* numbers = NULL;
    int count = 0;
    int num;

    while (scanf("%d", &num) == 1) {
        numbers = realloc(numbers, (count + 1) * sizeof(int));
        if (numbers == NULL) {
            return 1;
        }
        numbers[count++] = num;
    }

    int largest = find_largest_integer(numbers, count);
    printf("The largest number is: %d\n", largest);

    free(numbers);
    return 0;
}
