#include <sys/socket.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <jansson.h>

#define MAX_CONNECTIONS 1024
#define BUFFER_SIZE 4096

typedef enum {
    ESTABLISHED,
    FIN_WAIT
} ConnectionState;

typedef struct Connection {
    int id;
    ConnectionState state;
    int socket_fd;
    pthread_mutex_t mutex;
} Connection;

typedef struct MemoryPool {
    void *blocks[MAX_CONNECTIONS];
    size_t block_size;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

Connection connections[MAX_CONNECTIONS] = {0};
MemoryPool pool = {0};

EVP_CIPHER_CTX *initialize_cipher_ctx() {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Failed to create cipher context");
        return NULL;
    }
    // Initialize the cipher context with AES-256-GCM
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        perror("Failed to initialize cipher context");
        return NULL;
    }
    return ctx;
}

void *memory_pool_alloc(size_t size) {
    pthread_mutex_lock(&pool.lock);
    if (pool.count >= MAX_CONNECTIONS || pool.block_size < size) {
        pthread_mutex_unlock(&pool.lock);
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    void *block = malloc(size);
    if (!block) {
        pthread_mutex_unlock(&pool.lock);
        perror("Failed to allocate memory from pool");
        return NULL;
    }
    pool.blocks[pool.count++] = block;
    pthread_mutex_unlock(&pool.lock);
    return block;
}

void memory_pool_free(void *ptr) {
    pthread_mutex_lock(&pool.lock);
    for (size_t i = 0; i < pool.count; ++i) {
        if (pool.blocks[i] == ptr) {
            free(ptr);
            memmove(pool.blocks + i, pool.blocks + i + 1, (pool.count - i - 1) * sizeof(void *));
            --pool.count;
            break;
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

void handle_connection_event(json_t *event) {
    int id = json_integer_value(json_object_get(event, "id"));
    const char *state_str = json_string_value(json_object_get(event, "state"));
    ConnectionState new_state = (strcmp(state_str, "ESTABLISHED") == 0) ? ESTABLISHED : FIN_WAIT;
    int socket_fd = json_integer_value(json_object_get(event, "socket_fd"));

    if (id < 0 || id >= MAX_CONNECTIONS) {
        fprintf(stderr, "Invalid connection ID\n");
        return;
    }

    pthread_mutex_lock(&connections[id].mutex);
    connections[id].state = new_state;
    connections[id].socket_fd = socket_fd;
    pthread_mutex_unlock(&connections[id].mutex);
}

void *connection_thread(void *arg) {
    int id = *(int *)arg;
    free(arg);

    // Simulate connection handling
    while (1) {
        pthread_mutex_lock(&connections[id].mutex);
        ConnectionState state = connections[id].state;
        int socket_fd = connections[id].socket_fd;
        pthread_mutex_unlock(&connections[id].mutex);

        if (state == ESTABLISHED) {
            char buffer[BUFFER_SIZE];
            ssize_t bytes_read = read(socket_fd, buffer, BUFFER_SIZE - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                printf("Received data: %s\n", buffer);

                // Simulate encryption
                EVP_CIPHER_CTX *ctx = initialize_cipher_ctx();
                if (ctx) {
                    uint8_t key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
                    if (1 == RAND_bytes(key, sizeof(key)) && 1 == RAND_bytes(iv, sizeof(iv))) {
                        // Encrypt data using the cipher context
                        EVP_EncryptUpdate(ctx, NULL, &bytes_read, buffer, bytes_read);
                        EVP_EncryptFinal_ex(ctx, buffer, &bytes_read);

                        // Send encrypted data
                        write(socket_fd, buffer, bytes_read);
                    }
                    EVP_CIPHER_CTX_free(ctx);
                }
            } else if (bytes_read == 0) {
                break; // Connection closed
            } else {
                perror("Error reading from socket");
                break;
            }
        }

        sleep(1); // Simulate work
    }

    pthread_mutex_lock(&connections[id].mutex);
    connections[id].state = FIN_WAIT;
    pthread_mutex_unlock(&connections[id].mutex);

    return NULL;
}

int main() {
    pthread_t threads[MAX_CONNECTIONS] = {0};
    int id = 0;

    while (1) {
        char buffer[BUFFER_SIZE];
        if (fgets(buffer, BUFFER_SIZE, stdin)) {
            json_error_t error;
            json_t *event = json_loads(buffer, JSON_REJECT_DUPLICATES, &error);
            if (!event) {
                fprintf(stderr, "Error parsing JSON: %s on line %d\n", error.text, error.line);
                continue;
            }

            handle_connection_event(event);
            json_decref(event);

            // Simulate new connection
            pthread_mutex_lock(&connections[id].mutex);
            connections[id].id = id;
            pthread_mutex_unlock(&connections[id].mutex);

            if (pthread_create(&threads[id], NULL, connection_thread, memory_pool_alloc(sizeof(int)))) {
                perror("Failed to create thread");
            } else {
                ++id;
                if (id >= MAX_CONNECTIONS) {
                    id = 0; // Wrap around
                }
            }
        } else {
            break;
        }
    }

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
