    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    pthread_t threads[MAX_CONNECTIONS];
    int connection_id = 0;

    while (1) {
        new_socket = accept4(server_fd, (struct sockaddr *)&address,
                             (socklen_t*)&addrlen, SOCK_NONBLOCK);
        if (new_socket < 0) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("accept");
                break;
            }
        } else {
            add_connection(&manager, connection_id++, "ESTABLISHED", new_socket);
            pthread_create(&threads[connection_id - 1], NULL, handle_connection, &manager);
        }
    }

    for (int i = 0; i < connection_id; ++i) {
        pthread_join(threads[i], NULL);
    }

    close(server_fd);
    return 0;
}
