#include <iostream>
#include <string>
#include <map>
#include <dlfcn.h>

class DynamicLibraryLoader {
public:
    struct Config {
        std::string libraryPath;
        // Add more configuration parameters as needed
    };

    DynamicLibraryLoader() = default;

    ~DynamicLibraryLoader() {
        unloadAllLibraries();
    }

    bool loadLibrary(const std::string& libraryPath, const Config& config) {
        void* handle = dlopen(libraryPath.c_str(), RTLD_LAZY);
        if (!handle) {
            std::cerr << "Failed to load library: " << dlerror() << std::endl;
            return false;
        }

        libraries[libraryPath] = handle;
        return true;
    }

    void unloadAllLibraries() {
        for (const auto& lib : libraries) {
            dlclose(lib.second);
        }
        libraries.clear();
    }

    template<typename T>
    T getSymbol(const std::string& libraryPath, const std::string& symbolName) {
        if (libraries.find(libraryPath) == libraries.end()) {
            std::cerr << "Library not loaded: " << libraryPath << std::endl;
            return nullptr;
        }

        void* handle = libraries[libraryPath];
        T symbol = reinterpret_cast<T>(dlsym(handle, symbolName.c_str()));
        if (!symbol) {
            std::cerr << "Failed to load symbol: " << dlerror() << std::endl;
        }
        return symbol;
    }

private:
    std::map<std::string, void*> libraries;
};
```

This C++ class `DynamicLibraryLoader` provides methods for loading and unloading shared libraries at runtime. It supports optional configuration parameters through a nested `Config` struct and handles memory management efficiently by properly unloading all libraries when the application exits. The class also includes a template method to retrieve symbol addresses based on these configurations, preventing leaks and ensuring that all loaded libraries are unloaded.']

