int validate_metadata(xmlNodePtr metadata, const char *schema_path) {
    xmlSchemaPtr schema;
    xmlSchemaParserCtxtPtr parser_ctxt;
    int result = 0;

    parser_ctxt = xmlSchemaNewParserCtxt(schema_path);
    if (!parser_ctxt) {
        fprintf(stderr, "Failed to create XML Schema parser context\n");
        return -1;
    }

    schema = xmlSchemaParse(parser_ctxt);
    if (!schema) {
        fprintf(stderr, "Failed to parse XML Schema\n");
        xmlSchemaFreeParserCtxt(parser_ctxt);
        return -1;
    }

    result = xmlSchemaValidateNode(schema, metadata);
    if (result != 0) {
        fprintf(stderr, "Metadata validation failed\n");
    }

    xmlSchemaFree(schema);
    xmlSchemaFreeParserCtxt(parser_ctxt);

    return result;
}

