        xmlParserCtxtPtr parser_ctxt = xmlCreateMemoryParserCtxt(buffer, strlen(buffer));
        if (!parser_ctxt) {
            fprintf(stderr, "Failed to create XML parser context\n");
            continue;
        }

        xmlDocPtr doc = xmlParseMemory(parser_ctxt, buffer, strlen(buffer), NULL, 0);
        if (!doc) {
            fprintf(stderr, "Failed to parse XML document\n");
            xmlFreeParserCtxt(parser_ctxt);
            continue;
        }

        op.metadata = xmlDocGetRootElement(doc);
        xmlFreeDoc(doc);

        // Validate the metadata against a predefined schema
        const char *schema_path = "example_schema.xsd";
        if (validate_metadata(op.metadata, schema_path) != 0) {
            fprintf(stderr, "Validation failed for operation ID: %d\n", op.operation_id);
        }

        xmlFreeParserCtxt(parser_ctxt);
    }
}

