    virtual void send(const std::string& data) = 0;
};

class NetworkClient {
private:
    std::shared_ptr<Connection> connection;
public:
    NetworkClient(std::shared_ptr<Connection> conn) : connection(conn) {}
    void sendData(const std::string& data) {
        connection->send(data);
    }
};

class ConnectionPool {
private:
    std::vector<std::shared_ptr<Connection>> pool;
    std::mutex pool_mutex;

public:
    void addConnection(std::shared_ptr<Connection> conn) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        pool.push_back(conn);
    }

    std::shared_ptr<Connection> getConnection() {
        std::lock_guard<std::mutex> lock(pool_mutex);
        if (!pool.empty()) {
            auto conn = pool.back();
            pool.pop_back();
            return conn;
        }
        return nullptr; // No available connections
    }

    void releaseConnection(std::shared_ptr<Connection> conn) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        pool.push_back(conn);
    }
};

class NetworkManager {
private:
    ConnectionPool connection_pool;

public:
    NetworkClient connect() {
        auto conn = connection_pool.getConnection();
        if (!conn) {
            // Create new connection (simplified for example)
            conn = std::make_shared<Connection>();
        }
        return NetworkClient(conn);
    }

    void disconnect(NetworkClient& client) {
        auto conn = client.connection;
        if (conn) {
            connection_pool.releaseConnection(conn);
        }
    }
};
