#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <unordered_map>

class NetworkConnection {
public:
    virtual ~NetworkConnection() {}
    virtual void send(const std::string& data) = 0;
    virtual void receive(std::string& data) = 0;
    virtual void close() = 0;
};

class ConnectionPool {
public:
    ConnectionPool(int maxConnections, int timeout)
        : maxConnections(maxConnections), timeout(timeout) {}

    ~ConnectionPool() {
        for (auto conn : connections) {
            conn->close();
        }
    }

    NetworkConnection* getConnection(const std::string& clientID) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !idleConnections.empty(); });

        NetworkConnection* conn = idleConnections.front();
        idleConnections.pop();

        activeConnections[clientID].push_back(conn);

        return conn;
    }

    void releaseConnection(const std::string& clientID, NetworkConnection* conn) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = activeConnections.find(clientID);
        if (it != activeConnections.end()) {
            it->second.erase(std::remove(it->second.begin(), it->second.end(), conn), it->second.end());
        }

        idleConnections.push(conn);
        condition.notify_one();
    }

private:
    int maxConnections;
    int timeout;
    std::mutex mutex;
    std::condition_variable condition;
    std::queue<NetworkConnection*> idleConnections;
    std::unordered_map<std::string, std::vector<NetworkConnection*>> activeConnections;
};
