    private final AtomicLong messageIdCounter = new AtomicLong(0);

    public void addMessage(String queueName, String message) {
        queues.computeIfAbsent(queueName, k -> new Queue()).enqueue(message);
    }

    public void startBroker() {
        // Logic to start a new broker
    }

    public void stopBroker() {
        // Logic to stop an existing broker
    }

    private static class Queue {
        private final ConcurrentHashMap<Long, Message> messages = new ConcurrentHashMap<>();

        public void enqueue(String message) {
            long messageId = messageIdCounter.incrementAndGet();
            messages.put(messageId, new Message(messageId, message));
        }

        public String dequeue() {
            return messages.pollFirstEntry().getValue().content;
        }
    }

    private static class Message {
        private final long id;
        private final String content;

        public Message(long id, String content) {
            this.id = id;
            this.content = content;
        }
    }

