#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_FILES 10000

typedef struct {
    int id;
    char timestamp[50];
    float value;
} record;

void parse_and_generate_output(int file_count, char* files[], const char* delimiter) {
    record** records = (record**)malloc(file_count * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Process each CSV file and populate records
    for (int i = 0; i < file_count; ++i) {
        FILE* file = fopen(files[i], "r");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        char line[1024];
        int record_index = 0;

        while (fgets(line, sizeof(line), file)) {
            record* rec = (record*)malloc(sizeof(record));
            if (!rec) {
                fprintf(stderr, "Memory allocation failed for record\n");
                fclose(file);
                continue;
            }

            // Parse the line into fields
            char *token = strtok(line, delimiter);
            if (token) {
                rec->id = atoi(token);
                token = strtok(NULL, delimiter);
                if (token) {
                    strncpy(rec->timestamp, token, sizeof(rec->timestamp) - 1);
                    token = strtok(NULL, delimiter);
                    if (token) {
                        rec->value = atof(token);
                        records[record_index++] = rec;
                    }
                }
            }
        }

        fclose(file);
    }

    // Generate and output JSON
    printf("[\n");
    for (int i = 0; i < record_index; ++i) {
        if (i > 0) printf(",\n");
        printf("{\"id\": %d, \"timestamp\": \"%s\", \"value\": %.2f}", records[i]->id, records[i]->timestamp, records[i]->value);
        free(records[i]);
    }
    printf("\n]\n");

    // Free allocated memory
    free(records);

    // Progress indicator (simplified)
    for (int i = 0; i < file_count; ++i) {
        usleep(100000); // Simulate processing time
        printf("\rProcessed %d/%d files", i + 1, file_count);
        fflush(stdout);
    }
    printf("\n");
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [--help] [--json_output] [--delimiter=<char>]\n", argv[0]);
        return 1;
    }

    int file_count = 0;
    char* files[MAX_FILES];
    const char* delimiter = ",";

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Help message here\n");
            return 0;
        } else if (strcmp(argv[i], "--json_output") == 0) {
            // Handle JSON output option
        } else if (strncmp(argv[i], "--delimiter=", 12) == 0) {
            delimiter = argv[i] + 12;
        } else {
            files[file_count++] = argv[i];
        }
    }

    parse_and_generate_output(file_count, files, delimiter);

    return 0;
}
