#include <pthread.h>
#include <stdlib.h>

#define MAX_UE_CONTEXTS 1024
#define MAX_RADIO_BEARERS 8

typedef enum {
    RRC_CONNECTED,
    RRC_IDLE
} RrcState;

typedef struct {
    int bearer_id;
    int qos_class;
    void* security_context; // Placeholder for actual security context
} RadioBearer;

typedef struct {
    int ue_id;
    RrcState rrc_state;
    RadioBearer bearers[MAX_RADIO_BEARERS];
    int bearer_count;
    pthread_mutex_t mutex;
} UeContext;

UeContext* ue_contexts[MAX_UE_CONTEXTS];
int next_free_index = 0;

void initialize_ue_contexts() {
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        ue_contexts[i] = malloc(sizeof(UeContext));
        pthread_mutex_init(&ue_contexts[i]->mutex, NULL);
        ue_contexts[i]->bearer_count = 0;
    }
}

void lock_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_contexts[ue_id]->mutex);
}

void unlock_ue_context(int ue_id) {
    pthread_mutex_unlock(&ue_contexts[ue_id]->mutex);
}

int find_free_ue_index() {
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (next_free_index == MAX_UE_CONTEXTS - 1)
            next_free_index = 0;
        else
            next_free_index++;
        if (ue_contexts[next_free_index]->bearer_count == 0) {
            return next_free_index;
        }
    }
    return -1; // No free UE context available
}

int add_ue_context(int ue_id, RrcState rrc_state) {
    int index = find_free_ue_index();
    if (index == -1) {
        return -1; // Unable to allocate new UE context
    }

    lock_ue_context(index);
    UeContext* ctx = ue_contexts[index];
    ctx->ue_id = ue_id;
    ctx->rrc_state = rrc_state;
    unlock_ue_context(index);

    return index;
}

int add_radio_bearer(int ue_index, int bearer_id, int qos_class, void* security_context) {
    if (ue_index < 0 || ue_index >= MAX_UE_CONTEXTS) {
        return -1; // Invalid UE context index
    }

    lock_ue_context(ue_index);
    UeContext* ctx = ue_contexts[ue_index];
    if (ctx->bearer_count >= MAX_RADIO_BEARERS) {
        unlock_ue_context(ue_index);
        return -1; // Too many radio bearers for this UE
    }

    RadioBearer* bearer = &ctx->bearers[ctx->bearer_count++];
    bearer->bearer_id = bearer_id;
    bearer->qos_class = qos_class;
    bearer->security_context = security_context;
    unlock_ue_context(ue_index);

    return 0;
}

void free_ue_context(int ue_id) {
    lock_ue_context(ue_id);
    UeContext* ctx = ue_contexts[ue_id];
    pthread_mutex_destroy(&ctx->mutex);
    memset(ctx, 0, sizeof(UeContext));
    unlock_ue_context(ue_id);
}
```

This code provides a basic implementation for managing LTE UE contexts in a multi-threaded environment. It includes functions to initialize and configure UE contexts, add radio bearers with QoS parameters and security contexts, and handle concurrency using mutexes. The `initialize_ue_contexts` function sets up the initial state of all UE contexts, while `add_ue_context` and `add_radio_bearer` manage the creation and updates of individual UE contexts and their bearers. Error handling is included to check for valid parameters and available resources.']

