void parse_and_aggregate(const std::vector<std::string>& log_files, const Json::Value& config, std::atomic<int>& processed_count, std::mutex& progress_mutex, std::condition_variable& progress_cv) {
    EventManager event_manager;
    OctreeBuilder octree_builder(config["octree"]);

    for (const auto& file : log_files) {
        LogParser parser(file);
        if (parser.is_valid()) {
            auto events = parser.parse(config["time_range"]);
            for (auto& event : events) {
                event_manager.add_event(event);
                octree_builder.insert(event);
            }
        }
    }

    std::lock_guard<std::mutex> lock(progress_mutex);
    processed_count.fetch_add(log_files.size());
    progress_cv.notify_all();
}

