    const char *input_format = "json";

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--logging-level") == 0) {
            logging_level = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--schema-path") == 0) {
            schema_path = argv[++i];
        } else if (strcmp(argv[i], "--input-format") == 0) {
            input_format = argv[++i];
        }
    }

    // Set up logging
    FILE *log_file = fopen("error_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    // Process input data
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        LTE_UE_Context ue = {0};
        HTTP_Request http = {0};

        // Parse and validate JSON string into LTE UE context and HTTP request
        json_object *json_obj = json_tokener_parse(buffer);
        if (!json_obj) {
            fprintf(log_file, "Malformed JSON: %s\n", buffer);
            continue;
        }

        // Extract fields from JSON object to populate LTE_UE_Context and HTTP_Request structures
        // (Assuming json_object_get_int and json_object_object_get_ex are used)
        int id = json_object_get_int(json_obj);

        if (!strcmp(input_format, "json")) {
            json_object *config_obj;
            if (json_object_object_get_ex(json_obj, "config", &config_obj)) {
                http.config = config_obj;
            } else {
                fprintf(log_file, "Missing 'config' field in JSON: %s\n", buffer);
                continue;
            }
        }

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, process_thread, &ue) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return EXIT_FAILURE;
        }

        if (pthread_join(thread_id, NULL) != 0) {
            fprintf(stderr, "Failed to join thread\n");
            return EXIT_FAILURE;
        }
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}
