NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications_from_binary_file(const char* input_file_path, time_t start_timestamp, int event_id_start, int event_id_end, const int* status_codes, int num_status_codes) {
    FILE* file = fopen(input_file_path, "rb");
    if (!file) {
        perror("Failed to open input file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int num_elements = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_elements; ++i) {
        fread(&crc_indications[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crc_indications[i].RNTI = rand() % 256;
        int random_index = rand() % num_status_codes;
        crc_indications[i].CRC_INDICATION_REL8_TAG = status_codes[random_index];
    }

    fclose(file);
    return crc_indications;
}
