LTE_UPLINK_NAS_TRANSPORT* initialize_lte_array(int size, int* error_code) {
    if (size <= 0) {
        *error_code = -1; // Invalid size
        return NULL;
    }

    LTE_UPLINK_NAS_TRANSPORT* array = (LTE_UPLINK_NAS_TRANSPORT*)malloc(size * sizeof(LTE_UPLINK_NAS_TRANSPORT));
    if (array == NULL) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    const char* message_contents[] = {"Content1", "Content2", "Content3"};
    NAS_MESSAGE_TYPE message_types[] = {MESSAGE_TYPE_1, MESSAGE_TYPE_2, MESSAGE_TYPE_3};

    for (int i = 0; i < size; i++) {
        if (i > 0 && array[i - 1].type == message_types[(i % sizeof(message_types) / sizeof(NAS_MESSAGE_TYPE))]) {
            *error_code = -3; // Same message type consecutively
            free(array);
            return NULL;
        }

        array[i].type = message_types[(i % sizeof(message_types) / sizeof(NAS_MESSAGE_TYPE))];
        array[i].content = strdup(message_contents[(i % sizeof(message_contents) / sizeof(char*))]);
    }

    *error_code = 0; // Success
    return array;
}

void free_lte_array(LTE_UPLINK_NAS_TRANSPORT* array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i].content);
    }
    free(array);
}
