#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAX_MESSAGES 100
#define MAX_MESSAGE_SIZE 500
#define BOOK_NAME_PATTERN "\\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Ruth|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\\b"
#define MAX_BOOK_NAME_LENGTH 20

typedef struct {
    NAS_MESSAGE_TYPE type;
    NAS_MESSAGE message;
} LTE_UPLINK_NAS_TRANSPORT;

typedef struct {
    char bookName[MAX_BOOK_NAME_LENGTH];
    int count;
} BookFrequency;

struct MessageAndBookInfo {
    LTE_UPLINK_NAS_TRANSPORT *messages;
    BookFrequency *bookFrequencies;
    size_t messageCount;
};

struct MessageAndBookInfo initializeAndValidateMessages(NAS_MESSAGE_TYPE initialTypes[], NAS_MESSAGE initialContents[], size_t typeCount) {
    struct MessageAndBookInfo result = {NULL, NULL, 0};
    regex_t bookPattern;
    int ret;

    // Compile the regex pattern
    ret = regcomp(&bookPattern, BOOK_NAME_PATTERN, REG_EXTENDED);
    if (ret) {
        fprintf(stderr, "Could not compile regex\n");
        return result;
    }

    LTE_UPLINK_NAS_TRANSPORT *messages = malloc(sizeof(LTE_UPLINK_NAS_TRANSPORT) * MAX_MESSAGES);
    BookFrequency *bookFrequencies = calloc(MAX_BOOK_NAME_LENGTH, sizeof(BookFrequency));
    if (!messages || !bookFrequencies) {
        fprintf(stderr, "Memory allocation failed\n");
        regfree(&bookPattern);
        free(messages);
        return result;
    }

    for (size_t i = 0; i < typeCount && result.messageCount < MAX_MESSAGES; ++i) {
        LTE_UPLINK_NAS_TRANSPORT newMessage = {initialTypes[i], initialContents[i]};
        // Validate uniqueness and non-repetition of message types
        int isUnique = 1;
        for (size_t j = 0; j < result.messageCount && isUnique; ++j) {
            if (result.messages[j].type == newMessage.type) {
                isUnique = 0;
            }
        }

        if (isUnique) {
            // Extract book names from message
            regmatch_t matches[MAX_BOOK_NAME_LENGTH];
            const char *messageText = newMessage.message.text;
            while ((ret = regexec(&bookPattern, messageText, MAX_BOOK_NAME_LENGTH, matches, 0)) == REG_OKAY) {
                size_t matchLength = matches[0].rm_eo - matches[0].rm_so;
                if (matchLength > 0 && matchLength < MAX_BOOK_NAME_LENGTH) {
                    strncpy(bookFrequencies[result.messageCount % MAX_BOOK_NAME_LENGTH].bookName, messageText + matches[0].rm_so, matchLength);
                    bookFrequencies[result.messageCount % MAX_BOOK_NAME_LENGTH].count++;
                }
                // Move to the next match
                messageText += matches[0].rm_eo;
            }

            // Add new message to array
            messages[result.messageCount++] = newMessage;
        } else {
            fprintf(stderr, "Duplicate message type detected\n");
        }
    }

    result.messages = messages;
    result.bookFrequencies = bookFrequencies;
    regfree(&bookPattern);
    return result;
}

void freeResult(struct MessageAndBookInfo *result) {
    free(result->messages);
    free(result->bookFrequencies);
}
