    // Initialize regex pattern
    regcomp(&pattern, "\\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy)\\b", REG_EXTENDED);

    for (int i = 0; i < typeCount; i++) {
        if (messages.count > 0 && messages.messages[messages.count - 1].nas_message_type == messageTypes[i]) {
            continue; // Skip if same type as previous
        }

        NAS_UPLINK_NAS_TRANSPORT *new_msg = malloc(sizeof(NAS_UPLINK_NAS_TRANSPORT));
        if (!new_msg) {
            fprintf(stderr, "Memory allocation failed\n");
            return messages;
        }

        new_msg->nas_message_type = messageTypes[i];
        strcpy(new_msg->nas_message, payloads[i]);

        int size = strlen(new_msg->nas_message);
        if (size > MAX_MESSAGE_SIZE) {
            new_msg->nas_message[MAX_MESSAGE_SIZE - 1] = '\0'; // Truncate
        }

        regexec(&pattern, new_msg->nas_message, sizeof(matches) / sizeof(matches[0]), matches, 0);
        for (int j = 0; j < book_count; j++) {
            if (strcmp(books[j], new_msg->nas_message + matches[1].rm_so) == 0) {
                book_freq[j].frequency++;
                break;
            }
        }

        messages.messages = realloc(messages.messages, (messages.count + 1) * sizeof(NAS_UPLINK_NAS_TRANSPORT));
        if (!messages.messages) {
            fprintf(stderr, "Memory reallocation failed\n");
            free(new_msg);
            return messages;
        }
        memcpy(&messages.messages[messages.count], new_msg, sizeof(NAS_UPLINK_NAS_TRANSPORT));
        free(new_msg);
        messages.count++;
    }

    regfree(&pattern);

    // Return the initialized messages and book frequencies
    LTE_UPLINK_MESSAGES result = {messages.messages, messages.count};
    return result;
}
```

This code snippet defines a function `initializeAndValidateMessages` that takes an array of message types and payloads, initializes a dynamic array of `LTE_UPLINK_NAS_TRANSPORT` structures with these messages, ensures no two consecutive messages have the same type, truncates messages exceeding `MAX_MESSAGE_SIZE`, and extracts book names from the text using regular expressions. It also handles memory allocation errors, logs warnings, and manages concurrent access through thread safety considerations. The function returns a struct containing both the initialized messages array and the extracted book names along with their frequency counts.']

