MessageArray *create_message_array() {
    MessageArray *array = malloc(sizeof(MessageArray));
    if (!array) {
        log_error("Failed to allocate memory for message array");
        return NULL;
    }
    array->messages = malloc(MAX_MESSAGES * sizeof(LTE_UPLINK_NAS_TRANSPORT));
    if (!array->messages) {
        free(array);
        log_error("Failed to allocate memory for messages in the array");
        return NULL;
    }
    array->count = 0;
    array->capacity = MAX_MESSAGES;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int add_message(MessageArray *array, NAS_MESSAGE_TYPE type) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity - 1) {
        // Handle memory reallocation
        LTE_UPLINK_NAS_TRANSPORT *new_messages = realloc(array->messages, (array->capacity + MAX_MESSAGES) * sizeof(LTE_UPLINK_NAS_TRANSPORT));
        if (!new_messages) {
            log_error("Failed to reallocate memory for messages in the array");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->messages = new_messages;
        array->capacity += MAX_MESSAGES;
    }

    if (array->count > 0 && array->messages[array->count - 1].type == type) {
        log_error("Attempted to add duplicate message type");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->messages[array->count].type = type;
    // Initialize NAS message payload here
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_message_array(MessageArray *array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->messages);
        pthread_mutex_unlock(&array->lock);
        free(array);
    }
}
