        // Logic to dynamically select VNIs using Mersenne Twister for load balancing
        vnis.clear();
        int numVNIs = 1 + rng() % 5; // Randomly generate between 1 and 5 VNIs per VNF
        for (int i = 0; i < numVNIs; ++i) {
            vnis.push_back(rng());
        }
        is_allocated = true;
    }

    void updateResource() {
        // Logic to handle dynamic policy updates from the NFVO
        allocateResource();
