#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1024
#define MAX_ROLES 64

typedef struct {
    char session_id[32];
    int auth_state;
    char roles[MAX_ROLES][32];
} Session;

Session sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t session_lock;

void initialize_session_management() {
    pthread_mutex_init(&session_lock, NULL);
}

int create_session(char* session_id, int auth_state) {
    pthread_mutex_lock(&session_lock);
    if (session_count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&session_lock);
        return -1; // Maximum sessions reached
    }
    strncpy(sessions[session_count].session_id, session_id, 32);
    sessions[session_count].auth_state = auth_state;
    sessions[session_count].roles[0][0] = '\0';
    session_count++;
    pthread_mutex_unlock(&session_lock);
    return 0;
}

void add_role(char* session_id, char* role) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].session_id, session_id) == 0) {
            int j;
            for (j = 0; j < MAX_ROLES && strlen(sessions[i].roles[j]) > 0; j++);
            if (j < MAX_ROLES) {
                strncpy(sessions[i].roles[j], role, 32);
            }
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void remove_role(char* session_id, char* role) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].session_id, session_id) == 0) {
            int j;
            for (j = 0; j < MAX_ROLES && strcmp(sessions[i].roles[j], role) != 0; j++);
            if (j < MAX_ROLES) {
                strcpy(&sessions[i].roles[j][0], sessions[i].roles[j + 1]);
            }
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void update_session_auth_state(char* session_id, int new_state) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].session_id, session_id) == 0) {
            sessions[i].auth_state = new_state;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void close_session(char* session_id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].session_id, session_id) == 0) {
            sessions[i] = sessions[--session_count];
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

