use std::env;
use std::fs::{File, OpenOptions};
use std::io::{self, BufRead, BufReader, Write};
use std::path::PathBuf;
use tokio::task;

#[derive(Debug)]
enum Error {
    Io(io::Error),
    InvalidBatchSize,
}

impl From<io::Error> for Error {
    fn from(err: io::Error) -> Self {
        Error::Io(err)
    }
}

fn main() -> Result<(), Error> {
    let args: Vec<String> = env::args().collect();
    let mut manpage_mode = false;
    let mut input_file_path: Option<PathBuf> = None;
    let mut output_file_path: Option<PathBuf> = None;
    let mut batch_size = 1024;

    for arg in args.iter().skip(1) {
        match arg.as_str() {
            "--manpage" => manpage_mode = true,
            "-cs" | "-c -s" => {},
            "-o" if let Some(path) = args.get(args.iter().position(|x| x == &"-o").unwrap() + 1) => {
                output_file_path = Some(PathBuf::from(path));
            },
            _ => return Err(Error::InvalidBatchSize),
        }
    }

    if manpage_mode {
        println!("Man page mode");
        return Ok(());
    }

    let input_file_path = input_file_path.ok_or(Error::InvalidBatchSize)?;
    let input_file = OpenOptions::new().read(true).open(&input_file_path)?;
    let reader = BufReader::new(input_file);

    if let Some(output_file_path) = output_file_path {
        let mut output_file = OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .open(&output_file_path)?;

        for (i, line) in reader.lines().enumerate() {
            let line = line?;
            writeln!(output_file, "Line {}: {}", i + 1, line)?;
        }
    } else {
        for (i, line) in reader.lines().enumerate() {
            println!("Line {}: {}", i + 1, line?);
        }
    }

    Ok(())
}
