#include <random>

class Connection {
public:
    Connection(int id) : id(id), active(true), health(100) {}
    void use() { if (active) health -= 5; }
    void repair() { if (!active) active = true; health = 100; }
    bool isHealthy() { return health > 0; }
    int getId() const { return id; }

private:
    int id;
    bool active;
    int health;
};

class ConnectionPool {
public:
    ConnectionPool(int maxConnections) : maxConnections(maxConnections), currentConnections(0) {}

    void requestConnection(int clientId) {
        std::unique_lock<std::mutex> lock(mutex);
        while (currentConnections >= maxConnections) {
            backpressureClients.push_back(clientId);
            cv.wait(lock, [this]() { return currentConnections < maxConnections; });
        }
        if (backpressureClients.empty()) {
            connections.emplace_back(++nextConnectionId);
        } else {
            int client = backpressureClients.front();
            backpressureClients.pop_front();
            connections.emplace_back(Connection(client));
        }
        ++currentConnections;
    }

    void releaseConnection(int clientId) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = connections.begin(); it != connections.end(); ++it) {
            if (it->getId() == clientId) {
                connections.erase(it);
                --currentConnections;
                cv.notify_one();
                break;
            }
        }
    }

private:
    int maxConnections;
    int currentConnections;
    int nextConnectionId = 0;
    std::vector<Connection> connections;
    std::queue<int> backpressureClients;
    std::mutex mutex;
    std::condition_variable cv;
};

int main() {
    ConnectionPool pool(5);
    // Simulate client requests
    for (int i = 0; i < 10; ++i) {
        pool.requestConnection(i);
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        pool.releaseConnection(i);
    }
    return 0;
}
