#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DEVICE_STREAMS 1024
#define MAX_SENSOR_ID_LEN 64

typedef enum {
    CONNECTION_STATE_DISCONNECTED,
    CONNECTION_STATE_CONNECTED
} ConnectionState;

typedef struct {
    char id[MAX_SENSOR_ID_LEN];
    int sampling_rate;
    int encryption_enabled;
} SensorStream;

typedef struct {
    int device_id;
    ConnectionState connection_state;
    SensorStream sensor_streams[MAX_DEVICE_STREAMS];
    int stream_count;
    pthread_mutex_t mutex;
} DeviceContext;

DeviceContext* create_device_context(int device_id) {
    DeviceContext* ctx = (DeviceContext*)malloc(sizeof(DeviceContext));
    if (!ctx) return NULL;
    ctx->device_id = device_id;
    ctx->connection_state = CONNECTION_STATE_DISCONNECTED;
    ctx->stream_count = 0;
    pthread_mutex_init(&ctx->mutex, NULL);
    return ctx;
}

void destroy_device_context(DeviceContext* ctx) {
    pthread_mutex_destroy(&ctx->mutex);
    free(ctx);
}

int add_sensor_stream(DeviceContext* ctx, const char* sensor_id, int sampling_rate, int encryption_enabled) {
    pthread_mutex_lock(&ctx->mutex);
    if (ctx->stream_count >= MAX_DEVICE_STREAMS) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1; // Error: Too many streams
    }
    SensorStream* stream = &ctx->sensor_streams[ctx->stream_count++];
    strncpy(stream->id, sensor_id, MAX_SENSOR_ID_LEN-1);
    stream->id[MAX_SENSOR_ID_LEN-1] = '\0';
    stream->sampling_rate = sampling_rate;
    stream->encryption_enabled = encryption_enabled;
    pthread_mutex_unlock(&ctx->mutex);
    return 0; // Success
}

int remove_sensor_stream(DeviceContext* ctx, const char* sensor_id) {
    pthread_mutex_lock(&ctx->mutex);
    for (int i = 0; i < ctx->stream_count; i++) {
        if (strcmp(ctx->sensor_streams[i].id, sensor_id) == 0) {
            for (int j = i+1; j < ctx->stream_count; j++) {
                ctx->sensor_streams[j-1] = ctx->sensor_streams[j];
            }
            ctx->stream_count--;
            pthread_mutex_unlock(&ctx->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&ctx->mutex);
    return -1; // Error: Stream not found
}

