#define MAX_DEVICES 1024
#define MAX_SENSORS 64

typedef struct {
    char id[32];
    int connection_status;
} DeviceContext;

typedef struct {
    char sensor_id[32];
    int sampling_rate;
    int encryption_enabled;
} SensorStream;

typedef struct {
    DeviceContext devices[MAX_DEVICES];
    SensorStream sensors[MAX_SENSORS * MAX_DEVICES];
    int device_count;
    int sensor_count;
    pthread_mutex_t mutex;
} IoTDeviceContextSystem;

IoTDeviceContextSystem iot_system = {0};

void init_iot_device_context() {
    pthread_mutex_init(&iot_system.mutex, NULL);
}

void add_device(const char* id) {
    pthread_mutex_lock(&iot_system.mutex);
    if (iot_system.device_count < MAX_DEVICES) {
        strcpy(iot_system.devices[iot_system.device_count].id, id);
        iot_system.devices[iot_system.device_count].connection_status = 1;
        iot_system.device_count++;
    }
    pthread_mutex_unlock(&iot_system.mutex);
}

void remove_device(const char* id) {
    pthread_mutex_lock(&iot_system.mutex);
    for (int i = 0; i < iot_system.device_count; i++) {
        if (strcmp(iot_system.devices[i].id, id) == 0) {
            for (int j = i; j < iot_system.device_count - 1; j++) {
                iot_system.devices[j] = iot_system.devices[j + 1];
            }
            iot_system.device_count--;
            break;
        }
    }
    pthread_mutex_unlock(&iot_system.mutex);
}

void add_sensor_stream(const char* device_id, const char* sensor_id, int sampling_rate, int encryption_enabled) {
    pthread_mutex_lock(&iot_system.mutex);
    if (iot_system.sensor_count < MAX_SENSORS * MAX_DEVICES) {
        for (int i = 0; i < iot_system.device_count; i++) {
            if (strcmp(iot_system.devices[i].id, device_id) == 0) {
                strcpy(iot_system.sensors[iot_system.sensor_count].sensor_id, sensor_id);
                iot_system.sensors[iot_system.sensor_count].sampling_rate = sampling_rate;
                iot_system.sensors[iot_system.sensor_count].encryption_enabled = encryption_enabled;
                iot_system.sensor_count++;
                break;
            }
        }
    }
    pthread_mutex_unlock(&iot_system.mutex);
}

void remove_sensor_stream(const char* device_id, const char* sensor_id) {
    pthread_mutex_lock(&iot_system.mutex);
    for (int i = 0; i < iot_system.sensor_count; i++) {
        if (strcmp(iot_system.sensors[i].sensor_id, sensor_id) == 0 && strcmp(iot_system.devices[i / MAX_SENSORS].id, device_id) == 0) {
            for (int j = i; j < iot_system.sensor_count - 1; j++) {
                iot_system.sensors[j] = iot_system.sensors[j + 1];
            }
            iot_system.sensor_count--;
            break;
        }
    }
    pthread_mutex_unlock(&iot_system.mutex);
}

void update_sensor_sampling_rate(const char* device_id, const char* sensor_id, int new_rate) {
    pthread_mutex_lock(&iot_system.mutex);
    for (int i = 0; i < iot_system.sensor_count; i++) {
        if (strcmp(iot_system.sensors[i].sensor_id, sensor_id) == 0 && strcmp(iot_system.devices[i / MAX_SENSORS].id, device_id) == 0) {
            iot_system.sensors[i].sampling_rate = new_rate;
            break;
        }
    }
    pthread_mutex_unlock(&iot_system.mutex);
}

void toggle_sensor_encryption(const char* device_id, const char* sensor_id, int enable) {
    pthread_mutex_lock(&iot_system.mutex);
    for (int i = 0; i < iot_system.sensor_count; i++) {
        if (strcmp(iot_system.sensors[i].sensor_id, sensor_id) == 0 && strcmp(iot_system.devices[i / MAX_SENSORS].id, device_id) == 0) {
            iot_system.sensors[i].encryption_enabled = enable;
            break;
        }
    }
    pthread_mutex_unlock(&iot_system.mutex);
}

