using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml.XPath;

class FileAnalyzer
{
    static void Main(string[] args)
    {
        // Parse command-line arguments
        var options = new Dictionary<string, string>();
        for (int i = 0; i < args.Length; i++)
        {
            if (args[i] == "--manpage" || args[i] == "-h")
            {
                ShowManPage();
                return;
            }
            else if (i + 1 < args.Length && args[i].StartsWith("--") && !args[i + 1].StartsWith("--"))
            {
                options[args[i]] = args[++i];
            }
        }

        string[] inputFiles = options.ContainsKey("-f") ? options["-f"].Split(',') : Array.Empty<string>();
        string outputFileName = options.ContainsKey("-o") ? options["-o"] : "summary_report.txt";

        if (inputFiles.Length == 0)
        {
            ShowManPage();
            return;
        }

        var dataEntries = new List<DataEntry>();
        foreach (var file in inputFiles)
        {
            dataEntries.AddRange(ParseAndGenerateOutput(file, "EventID"));
        }

        GenerateReport(dataEntries, outputFileName);
    }

    static void ShowManPage()
    {
        Console.WriteLine("file_analyzer - A robust XML log file analyzer.");
        Console.WriteLine("Usage: file_analyzer [-f input_files] [--manpage|-h] [-o output_file]");
        Console.WriteLine("Options:");
        Console.WriteLine("  --manpage, -h  Display this help message.");
        Console.WriteLine("  -f              Specify input files (comma-separated).");
        Console.WriteLine("  -o              Specify output file for the summary report.");
    }

    static List<DataEntry> ParseAndGenerateOutput(string filePath, string eventName)
    {
        var dataEntries = new List<DataEntry>();
        using (var reader = XmlReader.Create(filePath))
        {
            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && reader.Name == "Event")
                {
                    var startTimestamp = DateTime.Parse(reader.GetAttribute("TimeCreated"));
                    var eventData = GetEventData(reader, eventName);

                    dataEntries.Add(new DataEntry
                    {
                        StartTimestamp = startTimestamp,
                        EventIDRange = new Range<int>(eventData.EventID),
                        StatusCodeList = eventData.StatusCodes
                    });
                }
            }
        }

        return dataEntries;
    }

    static (int EventID, List<int> StatusCodes) GetEventData(XmlReader reader, string eventName)
    {
        int eventID = -1;
        var statusCodes = new List<int>();

        while (reader.Read())
        {
            if (reader.NodeType == XmlNodeType.Element && reader.Name == eventName)
            {
                eventID = int.Parse(reader.Value);
            }
            else if (reader.NodeType == XmlNodeType.Element && reader.Name == "StatusCode")
            {
                statusCodes.Add(int.Parse(reader.Value));
            }
        }

        if (eventID == -1 || statusCodes.Count > 0)
        {
            throw new Exception("Invalid XML structure.");
        }

        return (eventID, statusCodes);
    }

    static void GenerateReport(List<DataEntry> dataEntries, string outputFileName)
    {
        using (var writer = new StreamWriter(outputFileName))
        {
            foreach (var entry in dataEntries)
            {
                writer.WriteLine($"Event ID: {entry.EventIDRange}, Start Time: {entry.StartTimestamp}");
                writer.WriteLine("Status Codes:");
                foreach (var code in entry.StatusCodeList)
                {
                    writer.WriteLine(code);
                }
                writer.WriteLine();
            }
        }
    }

    struct DataEntry
    {
        public DateTime StartTimestamp;
        public Range<int> EventIDRange;
        public List<int> StatusCodeList;
    }

    struct Range<T>
    {
        public T Start { get; init; }
        public T End { get; init; }

        public Range(T start, T end)
        {
            Start = start;
            End = end;
        }
    }
}
