#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define BUFFER_SIZE 1024

void print_help() {
    printf("Usage: program [options] <input_file>\n");
    printf("Options:\n");
    printf("  -h, --help          Display detailed usage information.\n");
    printf("  -c, --count         Output only the total number of lines in the file.\n");
    printf("  -s, --stats         Display statistics about the file.\n");
    printf("  -o, --output <file> Specify an output file for results.\n");
    printf("  -v, --verbose       Enable verbose mode.\n");
}

void process_file(const char *input_file, const char *output_file, int count_lines, int show_stats, int output_mode, int verbose) {
    FILE *input = fopen(input_file, "r");
    if (!input) {
        perror("Error opening input file");
        return;
    }

    FILE *output = output_file ? fopen(output_file, "w") : stdout;

    char buffer[BUFFER_SIZE];
    size_t total_length = 0;
    int line_count = 0;
    size_t max_line_length = 0;

    while (fgets(buffer, BUFFER_SIZE, input)) {
        line_count++;
        size_t length = strlen(buffer);
        if (length > 0 && buffer[length - 1] == '\n') {
            buffer[length - 1] = '\0';
            length--;
        }
        total_length += length;
        max_line_length = (length > max_line_length) ? length : max_line_length;

        if (output_mode == 2) { // Verbose mode
            printf("Line %d: %s\n", line_count, buffer);
        } else {
            fprintf(output, "Line %d: %s\n", line_count, buffer);
        }
    }

    fclose(input);

    if (show_stats || output_mode != 2) {
        double average_length = (line_count > 0) ? ((double)total_length / line_count) : 0;
        fprintf(output, "Total lines: %d\n", line_count);
        fprintf(output, "Average line length: %.2f\n", average_length);
        fprintf(output, "Max line length: %zu\n", max_line_length);
    }

    if (output != stdout) {
        fclose(output);
    }
}

int main(int argc, char *argv[]) {
    int count_lines = 0;
    int show_stats = 0;
    int output_mode = 1; // Default mode
    int verbose = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_help();
            return 0;
        } else if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count") == 0) {
            count_lines = 1;
        } else if (strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--stats") == 0) {
            show_stats = 1;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            output_mode = 2;
            i++;
            if (i >= argc) {
                fprintf(stderr, "Error: Missing output file name\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--verbose") == 0) {
            verbose = 1;
        } else {
            process_file(argv[i], NULL, count_lines, show_stats, output_mode, verbose);
            return 0;
        }
    }

    if (output_mode != 2) {
        process_file(NULL, stdout, count_lines, show_stats, output_mode, verbose);
    }

    return 0;
}
