    for (int i = 0; i < count; i++) {
        fwrite(configs[i], sizeof(NetworkConfig), 1, file);
    }
    fclose(file);
}

void deserialize_config(const char *filename, NetworkConfig **configs, int *count) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }
    fread(count, sizeof(int), 1, file);
    configs = (NetworkConfig**)malloc(*count * sizeof(NetworkConfig*));
    for (int i = 0; i < *count; i++) {
        configs[i] = (NetworkConfig*)malloc(sizeof(NetworkConfig));
        fread(configs[i], sizeof(NetworkConfig), 1, file);
    }
    fclose(file);
}

void free_configs(NetworkConfig **configs, int count) {
    for (int i = 0; i < count; i++) {
        free(configs[i]);
    }
    free(configs);
