} LTE_Uplink_NAS_Transport_T;

typedef struct QoSFlowAllocator {
    size_t block_size;
    void* free_blocks;
    pthread_mutex_t lock;
} QoSFlowAllocator;

LTE_Uplink_NAS_Transport_T** initialize_and_populate_array(int num_messages, QoSFlowAllocator* allocator) {
    LTE_Uplink_NAS_Transport_T** array = (LTE_Uplink_NAS_Transport_T**)malloc(num_messages * sizeof(LTE_Uplink_NAS_Transport_T*));
    if (!array) return NULL;

    for (int i = 0; i < num_messages; i++) {
        LTE_Uplink_NAS_Transport_T* transport = (LTE_Uplink_NAS_Transport_T*)malloc(sizeof(LTE_Uplink_NAS_Transport_T));
        if (!transport) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) free(array[j]);
            free(array);
            return NULL;
        }

        transport->qfi = get_next_qfi(allocator); // Assume this function exists
        transport->sequence_number = generate_sequence_number(); // Assume this function exists

        array[i] = transport;
    }

    return array;
}

int get_next_qfi(QoSFlowAllocator* allocator) {
    pthread_mutex_lock(&allocator->lock);
    int qfi = find_unused_qfi(allocator); // Assume this function exists
    if (qfi == -1) {
        void* new_block = realloc(allocator->free_blocks, allocator->block_size + sizeof(int));
        if (!new_block) {
            pthread_mutex_unlock(&allocator->lock);
            return -1; // Handle memory allocation failure
        }
        allocator->free_blocks = new_block;
        qfi = (int)((char*)allocator->free_blocks - (char*)malloc(sizeof(int)));
        *(int*)qfi = 0; // Initialize QoS flow identifier
    }
    pthread_mutex_unlock(&allocator->lock);
    return qfi;
}

void free_array(LTE_Uplink_NAS_Transport_T** array, int num_messages) {
    for (int i = 0; i < num_messages; i++) free(array[i]);
    free(array);
}

