#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct LTE_PHY_RX_FRAME_INFO {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int PHY_RX_FRAME_STATUS;
    int CRC_FLAG;
    struct LTE_PHY_RX_FRAME_INFO *next, *prev;
} LTE_PHY_RX_FRAME_INFO;

typedef struct {
    pthread_mutex_t lock;
    LTE_PHY_RX_FRAME_INFO *head;
} DoublyLinkedList;

void init_list(DoublyLinkedList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

LTE_PHY_RX_FRAME_INFO* create_node(int RX_UE_INFORMATION_TAG, unsigned int RNTI, int PHY_RX_FRAME_STATUS, int CRC_FLAG) {
    LTE_PHY_RX_FRAME_INFO *new_node = (LTE_PHY_RX_FRAME_INFO*)malloc(sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!new_node) return NULL;
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->PHY_RX_FRAME_STATUS = PHY_RX_FRAME_STATUS;
    new_node->CRC_FLAG = CRC_FLAG;
    new_node->next = new_node->prev = NULL;
    return new_node;
}

void add_frame(DoublyLinkedList *list, int RX_UE_INFORMATION_TAG, unsigned int RNTI, int PHY_RX_FRAME_STATUS) {
    pthread_mutex_lock(&list->lock);
    LTE_PHY_RX_FRAME_INFO *new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, PHY_RX_FRAME_STATUS, rand() % 2); // Random CRC_FLAG
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->next = list->head;
    if (list->head)
        list->head->prev = new_node;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

LTE_PHY_RX_FRAME_INFO* get_head(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    LTE_PHY_RX_FRAME_INFO *head = list->head;
    pthread_mutex_unlock(&list->lock);
    return head;
}

void garbage_collection(DoublyLinkedList *list, unsigned int rnti_range_start, unsigned int rnti_range_end) {
    pthread_mutex_lock(&list->lock);
    LTE_PHY_RX_FRAME_INFO *current = list->head;
    LTE_PHY_RX_FRAME_INFO *prev = NULL;
    while (current) {
        if (current->RNTI < rnti_range_start || current->RNTI > rnti_range_end) {
            if (prev)
                prev->next = current->next;
            if (current->next)
                current->next->prev = prev;
            LTE_PHY_RX_FRAME_INFO *temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}
