typedef struct nfa_array_t {
    NFAPI_MESSAGE_T **messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_ARRAY_T;

NFAPI_ARRAY_T* nfa_init(size_t initial_capacity) {
    NFAPI_ARRAY_T *array = malloc(sizeof(NFAPI_ARRAY_T));
    array->messages = malloc(initial_capacity * sizeof(NFAPI_MESSAGE_T *));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void nfa_destroy(NFAPI_ARRAY_T *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->messages[i]->crc_ind_rel8);
        free(array->messages[i]);
    }
    free(array->messages);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

void nfa_add(NFAPI_ARRAY_T *array, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        array->messages = realloc(array->messages, new_capacity * sizeof(NFAPI_MESSAGE_T *));
        array->capacity = new_capacity;
    }
    NFAPI_MESSAGE_T *new_message = malloc(sizeof(NFAPI_MESSAGE_T));
    new_message->ue_info = ue_info;
    new_message->rnti = rnti;
    new_message->crc_ind_rel8 = malloc(sizeof(CRC_INDICATION_REL8_TAG));
    srand(time(NULL));
    new_message->crc_ind_rel8->crcflag = rand() % 2;
    array->messages[array->size++] = new_message;
    pthread_mutex_unlock(&array->mutex);
}

void nfa_update(NFAPI_ARRAY_T *array, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i]->ue_info == ue_info && array->messages[i]->rnti == rnti) {
            free(array->messages[i]->crc_ind_rel8);
            array->messages[i]->crc_ind_rel8 = malloc(sizeof(CRC_INDICATION_REL8_TAG));
            srand(time(NULL));
            array->messages[i]->crc_ind_rel8->crcflag = rand() % 2;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}
