typedef struct {
    NFAPIMessageWrapper *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
} DynamicArray;

void initDynamicArray(DynamicArray *arr, size_t initial_capacity) {
    arr->array = (NFAPIMessageWrapper *)malloc(initial_capacity * sizeof(NFAPIMessageWrapper));
    arr->capacity = initial_capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    arr->log_file = fopen("nfapi_log.txt", "w");
}

void destroyDynamicArray(DynamicArray *arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->array[i].crc_indication);
    }
    free(arr->array);
    pthread_mutex_destroy(&arr->lock);
    fclose(arr->log_file);
}

void addOrUpdateEntry(DynamicArray *arr, size_t index, RX_UE_INFORMATION_TAG info_tag, uint16_t RNTI) {
    pthread_mutex_lock(&arr->lock);
    if (index >= arr->count) {
        while (arr->capacity <= index) {
            arr->array = realloc(arr->array, 2 * arr->capacity * sizeof(NFAPIMessageWrapper));
            arr->capacity *= 2;
        }
        for (size_t i = arr->count; i < index; ++i) {
            arr->array[i].valid = 0;
        }
    } else {
        free(arr->array[index].crc_indication);
    }

    arr->array[index].info_tag = info_tag;
    arr->array[index].RNTI = RNTI;
    arr->array[index].crc_indication = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    arr->array[index].crc_indication->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    arr->array[index].valid = 1;

    fprintf(arr->log_file, "Added/Updated entry at index %zu\n", index);
    pthread_mutex_unlock(&arr->lock);
}

void compactArray(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);
    size_t new_capacity = arr->count;
    NFAPIMessageWrapper *new_array = (NFAPIMessageWrapper *)malloc(new_capacity * sizeof(NFAPIMessageWrapper));
    for (size_t i = 0, j = 0; i < arr->capacity; ++i) {
        if (arr->array[i].valid) {
            new_array[j++] = arr->array[i];
        }
    }
    free(arr->array);
    arr->array = new_array;
    arr->capacity = new_capacity;

    fprintf(arr->log_file, "Array compacted\n");
    pthread_mutex_unlock(&arr->lock);
}
