#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

// Define global variables for shared resources
int total_lines = 0;
double total_length = 0.0;
int max_line_length = 0;

// Function to process a single file
void* process_file(void* arg) {
    char* filename = (char*)arg;
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    int line_count = 0;
    double length_sum = 0.0;
    int max_line_len = 0;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
        length_sum += strlen(buffer);
        if (strlen(buffer) > max_line_len) {
            max_line_len = strlen(buffer);
        }
    }

    fclose(file);

    // Update global variables with thread-specific results
    pthread_mutex_lock(&global_mutex);
    total_lines += line_count;
    total_length += length_sum;
    if (max_line_len > max_line_length) {
        max_line_length = max_line_len;
    }
    pthread_mutex_unlock(&global_mutex);

    return NULL;
}

// Function to process multiple files in a directory
void process_directory(const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (!dir) {
        perror("Error opening directory");
        return;
    }

    struct dirent* ent;
    int file_count = 0;

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }
        char filename[1024];
        snprintf(filename, sizeof(filename), "%s/%s", dir_path, ent->d_name);
        process_file(filename);
        file_count++;
    }

    closedir(dir);

    // Output summary report
    printf("Total files processed: %d\n", file_count);
    printf("Total lines: %d\n", total_lines);
    printf("Average line length: %.2f\n", total_length / total_lines);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] input_file...\n", argv[0]);
        return 1;
    }

    // Initialize global variables
    pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Parse command line arguments and process files accordingly
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            printf("Detailed usage information...\n");
            return 0;
        } else if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count") == 0) {
            // Output only the total number of lines
            for (int j = i + 1; j < argc && argv[j][0] != '-'; j++) {
                FILE* file = fopen(argv[j], "r");
                if (!file) {
                    perror("Error opening file");
                    return 1;
                }
                int line_count = 0;
                char buffer[1024];
                while (fgets(buffer, sizeof(buffer), file)) {
                    line_count++;
                }
                fclose(file);
                printf("Lines in %s: %d\n", argv[j], line_count);
            }
        } else if (strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--stats") == 0) {
            // Display statistics about the file
            for (int j = i + 1; j < argc && argv[j][0] != '-'; j++) {
                FILE* file = fopen(argv[j], "r");
                if (!file) {
                    perror("Error opening file");
                    return 1;
                }
                int line_count = 0;
                double length_sum = 0.0;
                int max_line_len = 0;
                char buffer[1024];
                while (fgets(buffer, sizeof(buffer), file)) {
                    line_count++;
                    length_sum += strlen(buffer);
                    if (strlen(buffer) > max_line_len) {
                        max_line_len = strlen(buffer);
                    }
                }
                fclose(file);
                printf("File: %s\n", argv[j]);
                printf("Lines: %d\n", line_count);
                printf("Average Length: %.2f\n", length_sum / line_count);
                printf("Max Line Length: %d\n", max_line_len);
            }
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            // Specify an output file
        } else if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--verbose") == 0) {
            // Enable verbose mode
        } else {
            // Process files in the directory or individual files
            if (access(argv[i], F_OK) == 0) {
                if (S_ISDIR(stat(argv[i]).st_mode)) {
                    process_directory(argv[i]);
                } else {
                    pthread_t thread;
                    if (pthread_create(&thread, NULL, process_file, argv[i]) != 0) {
                        perror("Error creating thread");
                        return 1;
                    }
                    pthread_join(thread, NULL);
                }
            } else {
                fprintf(stderr, "File not found: %s\n", argv[i]);
                return 1;
            }
        }
    }

    // Clean up and exit
    pthread_mutex_destroy(&global_mutex);
    return 0;
}
