#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>
#include <pthread.h>

#define MAX_THREADS 10

typedef struct {
    int id;
    char *filename;
    FILE *file;
    int line_count;
    size_t total_length;
} FileData;

typedef struct {
    pthread_mutex_t lock;
    int thread_count;
} ThreadCounter;

void* process_file(void *arg) {
    FileData *data = (FileData *)arg;
    size_t line_length;
    char buffer[1024];

    while (fgets(buffer, sizeof(buffer), data->file)) {
        line_length = strlen(buffer);
        pthread_mutex_lock(&counter.lock);
        data->line_count++;
        data->total_length += line_length;
        pthread_mutex_unlock(&counter.lock);

        if (verbose) {
            printf("File %d: Line length: %zu\n", data->id, line_length);
        }
    }

    fclose(data->file);
    return NULL;
}

void init_thread_counter(ThreadCounter *tc) {
    pthread_mutex_init(&tc->lock, NULL);
    tc->thread_count = 0;
}

void increment_thread_counter(ThreadCounter *tc) {
    pthread_mutex_lock(&tc->lock);
    tc->thread_count++;
    pthread_mutex_unlock(&tc->lock);
}

void decrement_thread_counter(ThreadCounter *tc) {
    pthread_mutex_lock(&tc->lock);
    tc->thread_count--;
    pthread_mutex_unlock(&tc->lock);
}

int main(int argc, char *argv[]) {
    // Command line argument parsing and usage information display
    if (argc <= 1 || strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [options] [files...]\n", argv[0]);
        printf("-h, --help       Display this message\n");
        printf("-c, --count      Output only the total number of lines in the file(s)\n");
        printf("-s, --stats      Display statistics about the file(s)\n");
        printf("-o, --output     Specify an output file where results can be written\n");
        printf("-v, --verbose    Enable verbose mode\n");
        return 0;
    }

    // Initialize thread counter
    ThreadCounter counter;
    init_thread_counter(&counter);

    pthread_t threads[MAX_THREADS];
    int num_threads = 0;

    for (int i = 1; i < argc; i++) {
        FileData *data = malloc(sizeof(FileData));
        data->id = i - 1;
        data->filename = argv[i];

        if ((data->file = fopen(data->filename, "r")) == NULL) {
            perror("Error opening file");
            continue;
        }

        increment_thread_counter(&counter);
        pthread_create(&threads[num_threads++], NULL, process_file, data);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Calculate and print summary statistics
    printf("Total lines: %d\n", total_lines);
    printf("Average line length: %.2f\n", (float)total_length / total_lines);

    return 0;
}
