typedef struct {
    NetworkService *services[MAX_SERVICES];
    int count;
    pthread_mutex_t lock;
    // Additional fields as needed
} ServiceManager;

NetworkService* create_service(int id) {
    NetworkService *service = (NetworkService*) malloc(sizeof(NetworkService));
    service->id = id;
    service->state = STATE_INIT;
    pthread_mutex_init(&service->lock, NULL);
    // Initialize other fields as needed
    return service;
}

void destroy_service(NetworkService *service) {
    pthread_mutex_destroy(&service->lock);
    free(service);
}

void add_service(ServiceManager *manager, NetworkService *service) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_SERVICES) {
        manager->services[manager->count++] = service;
    }
    pthread_mutex_unlock(&manager->lock);
}

void remove_service(ServiceManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->services[i]->id == id) {
            destroy_service(manager->services[i]);
            for (; i < manager->count - 1; i++) {
                manager->services[i] = manager->services[i + 1];
            }
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void update_service_state(ServiceManager *manager, int id, ServiceState new_state) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->services[i]->id == id) {
            pthread_mutex_lock(&manager->services[i]->lock);
            manager->services[i]->state = new_state;
            // Additional state update logic as needed
            pthread_mutex_unlock(&manager->services[i]->lock);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

