    channel->id = id;
    channel->qos_level = qos_level;
    channel->flow_control = flow_control;
}

// Function to initialize a network service instance with a set of transport channels
NetworkServiceInstance* init_network_service_instance(int service_id, int num_channels) {
    NetworkServiceInstance *service = (NetworkServiceInstance*)malloc(sizeof(NetworkServiceInstance));
    service->service_id = service_id;
    service->connection_state = 0; // Assuming initial state is disconnected
    service->num_channels = num_channels;
    service->channels = (TransportChannel*)malloc(num_channels * sizeof(TransportChannel));
    pthread_mutex_init(&service->lock, NULL);

    for(int i = 0; i < num_channels; i++) {
        init_transport_channel(&service->channels[i], i, 1, 1); // Default QoS and flow control settings
    }

    return service;
}

// Function to update the connection state of a network service instance with thread safety
void update_service_state(NetworkServiceInstance *service, int new_state) {
    pthread_mutex_lock(&service->lock);
    service->connection_state = new_state;
    pthread_mutex_unlock(&service->lock);
}

// Function to clean up and free resources for a network service instance
void cleanup_network_service_instance(NetworkServiceInstance *service) {
    pthread_mutex_destroy(&service->lock);
    free(service->channels);
    free(service);
}
