#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct QoSParameters {
    int priority;
    int bandwidth;
} QoSParameters;

typedef enum SessionHealthStatus {
    HEALTHY,
    WARNING,
    CRITICAL
} SessionHealthStatus;

typedef struct ActiveSession {
    char *sessionID;
    QoSParameters qos;
    SessionHealthStatus health;
    struct ActiveSession *next;
} ActiveSession;

typedef struct UEStatusReport {
    char *IMEI;
    ActiveSession *sessionsHead;
    pthread_mutex_t lock;
} UEStatusReport;

UEStatusReport* createUEStatusReport(char *IMEI) {
    UEStatusReport *report = (UEStatusReport*)malloc(sizeof(UEStatusReport));
    report->IMEI = strdup(IMEI);
    report->sessionsHead = NULL;
    pthread_mutex_init(&report->lock, NULL);
    return report;
}

void addActiveSession(UEStatusReport *report, char *sessionID, QoSParameters qos, SessionHealthStatus health) {
    pthread_mutex_lock(&report->lock);
    ActiveSession *newSession = (ActiveSession*)malloc(sizeof(ActiveSession));
    newSession->sessionID = strdup(sessionID);
    newSession->qos = qos;
    newSession->health = health;
    newSession->next = report->sessionsHead;
    report->sessionsHead = newSession;
    pthread_mutex_unlock(&report->lock);
}

void logSessionStatusChange(UEStatusReport *report, char *sessionID, SessionHealthStatus oldHealth, SessionHealthStatus newHealth) {
    printf("IMEI: %s, Session ID: %s, Health Change from %d to %d\n", report->IMEI, sessionID, oldHealth, newHealth);
}

void updateSessionHealth(UEStatusReport *report, char *sessionID, SessionHealthStatus health) {
    pthread_mutex_lock(&report->lock);
    ActiveSession *current = report->sessionsHead;
    while (current != NULL) {
        if (strcmp(current->sessionID, sessionID) == 0) {
            SessionHealthStatus oldHealth = current->health;
            current->health = health;
            logSessionStatusChange(report, sessionID, oldHealth, health);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&report->lock);
}

void freeUEStatusReport(UEStatusReport *report) {
    pthread_mutex_lock(&report->lock);
    ActiveSession *current = report->sessionsHead;
    while (current != NULL) {
        ActiveSession *temp = current;
        current = current->next;
        free(temp->sessionID);
        free(temp);
    }
    free(report->IMEI);
    pthread_mutex_destroy(&report->lock);
    free(report);
}
