#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>

struct UserActivityLog {
    int userId;
    std::time_t lastActivityTime;
    std::vector<std::string> recentInteractions;
    bool activityStatus;
};

class ActivityManager {
public:
    void addUserActivity(int userId, const std::vector<std::string>& interactions) {
        std::lock_guard<std::mutex> lock(mutex_);
        userLogs_[userId] = UserActivityLog{userId, std::time(nullptr), interactions, false};
        notifyChange(userId);
    }

    void updateActivityStatus(int userId, bool status) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (userLogs_.find(userId) != userLogs_.end()) {
            userLogs_[userId].activityStatus = status;
            notifyChange(userId);
        }
    }

private:
    std::unordered_map<int, UserActivityLog> userLogs_;
    std::mutex mutex_;
    std::condition_variable condVar_;

    void notifyChange(int userId) {
        condVar_.notify_one();
    }

    void logActivityChanges() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condVar_.wait(lock, [this] { return !userLogs_.empty(); });
            auto userId = userLogs_.begin()->first;
            UserActivityLog& log = userLogs_[userId];
            std::cout << "User ID: " << log.userId << ", Activity Status: " << (log.activityStatus ? "Active" : "Inactive") << std::endl;
            userLogs_.erase(userId);
        }
    }

public:
    ActivityManager() {
        std::thread([this] { logActivityChanges(); }).detach();
    }
};

int main() {
    ActivityManager manager;
    manager.addUserActivity(1, {"login", "upload"});
    std::this_thread::sleep_for(std::chrono::seconds(2));
    manager.updateActivityStatus(1, true);
    return 0;
}
