['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* password;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    void (*callback)(void);
} connectionInfo;

typedef struct {
    int totalCRCs;
    double averageCRCFLAG;
} statistics;

NFAPI_STATUS validateAndPopulateCRCList(int N, connectionInfo* connInfo, statistics& stats) {
    if (connInfo->password == NULL || strlen(connInfo->password) == 0 || connInfo->pdu == NULL || connInfo->pdu->rx_ue_information_tag == NULL || connInfo->pdu->rnti == 0 || connInfo->callback == NULL) {
        return NFAPI_STATUS_INVALID_PARAMETER;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* pduArray[N];
    int totalCRCFLAGSum = 0;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newPdu == NULL) {
            pthread_mutex_unlock(&mutex);
            return NFAPI_STATUS_MEMORY_ERROR;
        }
        memcpy(newPdu, connInfo->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newPdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
        pduArray[i] = newPdu;

        totalCRCFLAGSum += newPdu->crc_indication_rel8_tag.crcflag;
    }

    stats.totalCRCs += N;
    stats.averageCRCFLAG = (double)totalCRCFLAGSum / N;

    for (int i = 0; i < N; i++) {
        connInfo->callback();
    }

    pthread_mutex_unlock(&mutex);

    return NFAPI_STATUS_SUCCESS;
}
