#define MAX_UE_CONTEXTS 1024

typedef struct {
    int ue_id;
    int rrc_state;
    pthread_mutex_t lock;
} UeContext;

UeContext* g_ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t g_context_lock;

int initialize_ue_context(int ue_id, int rrc_state) {
    pthread_mutex_lock(&g_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (g_ue_contexts[i] == NULL) {
            g_ue_contexts[i] = malloc(sizeof(UeContext));
            if (g_ue_contexts[i] == NULL) {
                pthread_mutex_unlock(&g_context_lock);
                return -1;
            }
            pthread_mutex_init(&g_ue_contexts[i]->lock, NULL);
            g_ue_contexts[i]->ue_id = ue_id;
            g_ue_contexts[i]->rrc_state = rrc_state;
            pthread_mutex_unlock(&g_context_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&g_context_lock);
    return -1; // No available slots
}

int update_rrc_state(int ue_id, int new_state) {
    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (g_ue_contexts[i] != NULL && g_ue_contexts[i]->ue_id == ue_id) {
            pthread_mutex_lock(&g_ue_contexts[i]->lock);
            g_ue_contexts[i]->rrc_state = new_state;
            pthread_mutex_unlock(&g_ue_contexts[i]->lock);
            return 0;
        }
    }
    return -1; // UE context not found
}

void free_all_ue_contexts() {
    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (g_ue_contexts[i] != NULL) {
            pthread_mutex_destroy(&g_ue_contexts[i]->lock);
            free(g_ue_contexts[i]);
            g_ue_contexts[i] = NULL;
        }
    }
}
