// RandomValueGenerator.cs
using System;

public class RandomValueGenerator {
    private struct Range {
        public int Min { get; set; }
        public int Max { get; set; }
    }

    private Dictionary<string, Range> ranges = new Dictionary<string, Range>();

    public RandomValueGenerator() {
        ResetAllRanges();
    }

    public void ResetAllRanges() {
        ranges.Clear();
        AddRange("float", 0, 1);
        AddRange("int", 0, 100);
    }

    public void AddRange(string name, int min, int max) {
        if (min > max) throw new ArgumentException("Min cannot be greater than Max");
        ranges[name] = new Range { Min = min, Max = max };
    }

    public float GetRandomFloat(string name, bool inclusive = false) {
        var range = ranges[name];
        Random random = new Random();
        float value = (float)(random.NextDouble() * (range.Max - range.Min + (inclusive ? 1 : 0))) + range.Min;
        return value;
    }

    public int GetRandomInt(string name, bool inclusive = false) {
        var range = ranges[name];
        Random random = new Random();
        int value = random.Next(range.Min, inclusive ? range.Max + 1 : range.Max);
        return value;
    }

    public override string ToString() {
        StringBuilder sb = new StringBuilder();
        foreach (var range in ranges) {
            sb.AppendLine($"{range.Key}: Min={range.Value.Min}, Max={range.Value.Max}");
        }
        return sb.ToString();
    }
}
