// Function to initialize memory pool
void* init_memory_pool(size_t size) {
    return malloc(size);
}

// Function to allocate memory from pool
void* allocate_from_pool(void* pool, size_t size) {
    return realloc(pool, size);
}

// Function to deallocate memory in pool
void deallocate_to_pool(void** pool, void* ptr) {
    free(ptr);
}

// Helper function to calculate average of integers in an array
double calculate_average(int *array, int count) {
    if (count == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += array[i];
    }
    return sum / count;
}

// Function to handle signals
void handle_signal(int sig) {
    switch(sig) {
        case SIGINT:
            printf("Received SIGINT, exiting gracefully...\n");
            exit(0);
        case SIGHUP:
            printf("Received SIGHUP, saving state and exiting gracefully...\n");
            exit(0);
        default:
            printf("Received signal %d\n", sig);
    }
}

int main() {
    // Initialize memory pool
    void* memory_pool = init_memory_pool(1024 * 1024); // 1 MB initial size

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGHUP, handle_signal);

    // Read integers from standard input
    int count;
    printf("Enter the number of integers: ");
    scanf("%d", &count);
    int *array = (int*)allocate_from_pool(memory_pool, sizeof(int) * count);

    printf("Enter %d integers:\n", count);
    for (int i = 0; i < count; i++) {
        scanf("%d", &array[i]);
    }

    // Calculate average
    double avg = calculate_average(array, count);
    printf("Average: %.2f\n", avg);

    // Deallocate memory and free resources
    deallocate_to_pool(&memory_pool, array);
    free(memory_pool);

    return 0;
}
