#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPILIST_T;

NFAPILIST_T *NFAPICreateList(size_t initial_capacity) {
    NFAPILIST_T *list = (NFAPILIST_T *)malloc(sizeof(NFAPILIST_T));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

void NFAFDeleteList(NFAPILIST_T *list) {
    if (!list) return;
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

bool NFAPushBack(NFAPILIST_T *list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (!list) return false;

    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->count++] = item;
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Other functions as per requirements
