    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST_T;

int is_valid_rnti(unsigned short rnti, const CRC_LIST_T *list) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].rnti == rnti) {
            return 0;
        }
    }
    return 1;
}

int add_crc_pdu(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }
    if (!is_valid_rnti(pdu.rnti, list)) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Duplicate RNTI
    }
    list->list[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int export_list_to_file(const CRC_LIST_T *list, const char *filename, int binary) {
    FILE *file = fopen(filename, binary ? "wb" : "w");
    if (!file) {
        return -1; // Failed to open file
    }
    for (size_t i = 0; i < list->count; ++i) {
        if (binary) {
            if (fwrite(&list->list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
                fclose(file);
                return -2; // Write error
            }
        } else {
            fprintf(file, "RX_UE_INFO: %d, RNTI: %u, CRC_FLAG: %d\n",
                    list->list[i].rx_ue_information_tag,
                    list->list[i].rnti,
                    list->list[i].crc_indication_rel8_tag);
        }
    }
    fclose(file);
    return 0;
}

void clear_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->list);
    list->list = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    CRC_LIST_T list;
    pthread_mutex_init(&list.lock, NULL);
    list.list = NULL;
    list.capacity = 0;
    list.count = 0;

    NFAPI_CRC_INDICATION_PDU_T pdu = {123, 4567, 1};
    if (add_crc_pdu(&list, pdu) == 0) {
        export_list_to_file(&list, "output.bin", 1);
    }

    clear_crc_list(&list);
    pthread_mutex_destroy(&list.lock);

    return 0;
}
