double calculate_average(int *array, int count) {
    if (count == 0) {
        return 0.0; // Handle empty input case
    }
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += array[i];
    }
    return (double)sum / count;
}

// Main function to read integers from stdin and calculate their average
