    int *numbers = NULL;
    int count = 0;

    // Read integers from standard input
    while (1) {
        int num;
        if (scanf("%d", &num) != 1) {
            break; // Exit loop on non-integer input or end of file
        }
        numbers = realloc(numbers, sizeof(int) * (count + 1));
        numbers[count++] = num;
    }

    // Calculate and print the average
    double avg = calculate_average(numbers, count);
    printf("Average: %.2f\n", avg);

    // Free dynamically allocated memory
    free(numbers);

    return 0;
}
