typedef struct {
    int service_id;
    int connection_state;
    // Other fields for service instance
} NetworkService;

typedef struct {
    NetworkService *service;
    // Other fields for transport channel
} TransportChannel;

typedef struct {
    TransportChannel **channels;
    int num_channels;
} ServiceInstance;

typedef struct {
    ServiceInstance **instances;
    int num_instances;
    pthread_mutex_t lock;
} NetworkManager;

NetworkManager* create_network_manager() {
    NetworkManager *manager = (NetworkManager*)malloc(sizeof(NetworkManager));
    manager->instances = NULL;
    manager->num_instances = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_network_manager(NetworkManager *manager) {
    for (int i = 0; i < manager->num_instances; ++i) {
        free(manager->instances[i]->channels);
        free(manager->instances[i]);
    }
    free(manager->instances);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_service_instance(NetworkManager *manager, NetworkService *service) {
    pthread_mutex_lock(&manager->lock);
    manager->num_instances++;
    manager->instances = realloc(manager->instances, manager->num_instances * sizeof(ServiceInstance*));
    ServiceInstance *instance = (ServiceInstance*)malloc(sizeof(ServiceInstance));
    instance->service = service;
    instance->channels = NULL;
    instance->num_channels = 0;
    manager->instances[manager->num_instances - 1] = instance;
    pthread_mutex_unlock(&manager->lock);
}

void remove_service_instance(NetworkManager *manager, int service_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->num_instances; ++i) {
        if (manager->instances[i]->service->service_id == service_id) {
            free(manager->instances[i]->channels);
            free(manager->instances[i]);
            for (int j = i; j < manager->num_instances - 1; ++j) {
                manager->instances[j] = manager->instances[j + 1];
            }
            manager->num_instances--;
            manager->instances = realloc(manager->instances, manager->num_instances * sizeof(ServiceInstance*));
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void update_service_state(NetworkManager *manager, int service_id, int new_state) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->num_instances; ++i) {
        if (manager->instances[i]->service->service_id == service_id) {
            manager->instances[i]->service->connection_state = new_state;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

