#include <stdlib.h>
#include <pthread.h>

typedef struct SensorNode {
    int id;
    int operational_status;
    void* calibration_params;
    void* sensor_fusion_algorithm;
    struct SensorNode** connected_sensors;
    int num_connected_sensors;
    float noise_tolerance;
    pthread_mutex_t state_lock;
} SensorNode;

SensorNode* create_sensor_node(int id) {
    SensorNode* node = (SensorNode*)malloc(sizeof(SensorNode));
    if (node == NULL) return NULL;
    node->id = id;
    node->operational_status = 1;
    node->calibration_params = NULL;
    node->sensor_fusion_algorithm = NULL;
    node->connected_sensors = NULL;
    node->num_connected_sensors = 0;
    node->noise_tolerance = 1.0f;
    pthread_mutex_init(&node->state_lock, NULL);
    return node;
}

void destroy_sensor_node(SensorNode* node) {
    if (node == NULL) return;
    pthread_mutex_destroy(&node->state_lock);
    free(node->calibration_params);
    free(node->sensor_fusion_algorithm);
    for (int i = 0; i < node->num_connected_sensors; i++) {
        destroy_sensor_node(node->connected_sensors[i]);
    }
    free(node->connected_sensors);
    free(node);
}

void update_sensor_status(SensorNode* node, int new_status) {
    pthread_mutex_lock(&node->state_lock);
    node->operational_status = new_status;
    pthread_mutex_unlock(&node->state_lock);
}
