        return 1;
    }

    // Parse command-line arguments
    char *inputs[9];
    for (int i = 0; i < 9; ++i) {
        inputs[i] = argv[i + 1];
    }
    char *output_report = argv[10];
    char *filter_criteria = argv[11];
