    char *session_id = argv[16];
    char *user_id = argv[17];

    // Allocate memory for data structures
    TimestampMetadata *timestamps_metadata = (TimestampMetadata*)malloc(1024 * sizeof(TimestampMetadata));
    Event *events = (Event*)malloc(1024 * sizeof(Event));
    User *users = (User*)malloc(1024 * sizeof(User));

