        strcpy(users[i].user_id, "");
        strcpy(users[i].session_id, "");
    }

    // Initialize pthread mutex for thread-safe access
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Start asynchronous processing threads
    pthread_t threads[concurrency_level];
    for (int i = 0; i < concurrency_level; ++i) {
        pthread_create(&threads[i], NULL, process_data, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < concurrency_level; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    free(timestamps_metadata);
    free(events);
    free(users);

    return 0;
}
