#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef enum {
    STATE_ACTIVE,
    STATE_INACTIVE,
    STATE_FAILED
} ServiceState;

typedef struct {
    int id;
    ServiceState state;
    pthread_mutex_t lock;
    sem_t resource_semaphore;
} NetworkService;

NetworkService* create_service(int id) {
    NetworkService* service = (NetworkService*)malloc(sizeof(NetworkService));
    if (service == NULL) return NULL;

    service->id = id;
    service->state = STATE_INACTIVE;
    pthread_mutex_init(&service->lock, NULL);
    sem_init(&service->resource_semaphore, 0, 1); // Assuming initial resource availability

    return service;
}

void destroy_service(NetworkService* service) {
    if (service != NULL) {
        pthread_mutex_destroy(&service->lock);
        sem_destroy(&service->resource_semaphore);
        free(service);
    }
}

void update_service_state(NetworkService* service, ServiceState new_state) {
    pthread_mutex_lock(&service->lock);

    // Simulate state transition logic
    if (new_state == STATE_ACTIVE && service->state != STATE_FAILED) {
        // Check resource availability and other conditions before activating
        sem_wait(&service->resource_semaphore);
        service->state = STATE_ACTIVE;
    } else if (new_state == STATE_INACTIVE) {
        service->state = STATE_INACTIVE;
        sem_post(&service->resource_semaphore); // Release resources
    } else if (new_state == STATE_FAILED) {
        service->state = STATE_FAILED;
    }

    pthread_mutex_unlock(&service->lock);
}

void* service_thread(void* arg) {
    NetworkService* service = (NetworkService*)arg;

    while (1) {
        update_service_state(service, STATE_ACTIVE);
        // Simulate service operations
        sleep(1);
        update_service_state(service, STATE_INACTIVE);

        // Check for resource constraints and request additional resources if needed
    }

    return NULL;
}

int main() {
    NetworkService* services[10];
    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        services[i] = create_service(i);
        pthread_create(&threads[i], NULL, service_thread, (void*)services[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
        destroy_service(services[i]);
    }

    return 0;
}
```

This code snippet provides a basic structure for managing network service instances in C. It includes functions to create, destroy, and update the state of services while handling resource management using semaphores and mutexes to prevent deadlocks. The main function demonstrates creating multiple service instances and starting them in separate threads. This example is simplified and lacks many features such as QoS settings, failover mechanisms, and detailed statistics collection, which would need to be implemented for a full-fledged solution.']

