typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    size_t max_size;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_linked_list(size_t max_size) {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) {
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size > 0 ? max_size : SIZE_MAX;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    if (!list) {
        return;
    }
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->size >= list->max_size) {
        return -1; // Failure
    }
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        return -1; // Failure
    }
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void log_allocation(LinkedList* list, int success, const char* message) {
    // Implement logging mechanism here
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL));
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

int main() {
