import java.util.*;
import java.util.concurrent.*;

public class IntegerProcessor {

    public static List<Long> processAndInsertIntegers(
            ForwardList<Integer> forwardList,
            int insertAfterValue,
            int valueToInsert) {

        // Step 1: Process integers to compute factorials using parallel streams
        List<Long> factorialResults = new CopyOnWriteArrayList<>();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (int num : forwardList) {
            if (num > 0) {
                Future<Long> future = executor.submit(() -> computeFactorial(num));
                future.addListener(() -> {
                    try {
                        Long result = future.get();
                        factorialResults.add(result);
                    } catch (Exception e) {
                        System.err.println("Error computing factorial: " + e.getMessage());
                    }
                }, executor);
            }
        }

        // Step 2: Wait for all factorials to be computed
        try {
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.HOURS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Factorial computation interrupted");
        }

        // Step 3: Insert the second integer after the first occurrence of the first integer
        int index = forwardList.indexOf(insertAfterValue);
        if (index != -1) {
            forwardList.add(index + 1, valueToInsert);
        } else {
            forwardList.add(valueToInsert);
        }

        return factorialResults;
    }

    private static long computeFactorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }
}

interface ForwardList<T> extends List<T>, Iterable<T> {
    // Custom implementation of ForwardList interface
}
