void generateRandomPDU(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    srand(time(0));
    pdu->RX_UE_INFORMATION_TAG = rand() % 100;
    pdu->RNTI = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
