LinkedListNode* createLinkedList(int size, int maxSize) {
    LinkedListNode* head = NULL;
    for (int i = 0; i < size && i < maxSize; i++) {
        LinkedListNode* newNode = malloc(sizeof(LinkedListNode));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed.\n");
            return head;
        }
        generateRandomPDU(&newNode->data);
        newNode->next = head;
        head = newNode;
    }
    return head;
}

void freeLinkedList(LinkedListNode* head) {
    while (head) {
        LinkedListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

