    // Add metadata fields here if needed
} LTE_UE_Context_Info;

typedef struct Node {
    LTE_UE_Context_Info data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    size_t max_size; // Maximum allowed size of the list
} LinkedList;

LinkedList* create_linked_list(size_t max_size) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
    return list;
}

int add_to_list(LinkedList* list, LTE_UE_Context_Info info) {
    if (list->size >= list->max_size) {
        printf("List is full. Cannot add more elements.\n");
        return -1; // List is full
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        return -2; // Memory allocation error
    }
    new_node->data = info;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    return 0; // Success
}

// Implement other functions like delete_from_list, get_element_by_index, etc.

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

// Add other necessary functions and data structures as per the requirements
