#define MAX_THREADS 10

typedef struct {
    char* file_path;
    int verbose;
} FileTask;

void process_file(void* arg) {
    FileTask* task = (FileTask*)arg;
    FILE* file = fopen(task->file_path, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
        if (task->verbose) {
            printf("%s", buffer);
        }
    }

    fclose(file);
    printf("File: %s, Lines: %d\n", task->file_path, line_count);
}

int main(int argc, char* argv[]) {
    int opt;
    int count_lines = 0;
    int detailed_stats = 0;
    char* output_file = NULL;
    int verbose_mode = 0;
    DIR* dir = NULL;
    struct dirent* entry;
    FileTask tasks[MAX_THREADS];
    pthread_t threads[MAX_THREADS];

    while ((opt = getopt(argc, argv, "hc:s:o:v")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [-c] [-s] [-o file] [-v]\n", argv[0]);
                return 0;
            case 'c':
                count_lines = 1;
                break;
            case 's':
                detailed_stats = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'v':
                verbose_mode = 1;
                break;
        }
    }

    if (optind < argc) {
        for (int i = optind; i < argc; i++) {
            FileTask task = { argv[i], verbose_mode };
            tasks[i - optind] = task;
        }
    } else if ((dir = opendir(".")) != NULL) {
        int index = 0;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG && strstr(entry->d_name, ".txt")) {
                FileTask task = { entry->d_name, verbose_mode };
                tasks[index++] = task;
                if (index >= MAX_THREADS) break;
            }
        }
        closedir(dir);
    }

    for (int i = 0; i < argc - optind; i++) {
        pthread_create(&threads[i], NULL, process_file, &tasks[i]);
    }

    for (int i = 0; i < argc - optind; i++) {
        pthread_join(threads[i], NULL);
    }

    if (output_file) {
        FILE* out = fopen(output_file, "w");
        // Write results to output file
        fclose(out);
    }

    return 0;
}
