#define NFAPI_CRC_INDICATION_PDU_T struct nfaip_pdu_t
#define RX_UE_INFORMATION_TAG 1
#define RNTI 2
#define CRC_INDICATION_REL8_TAG 3

typedef struct {
    int tag;
    u_char data[4];
} NFCI_TAG;

typedef struct {
    NFCI_TAG tags[2];
    u_char crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

int create_and_populate_list(NFAPI_CRC_INDICATION_PDU_T **list, int n) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        return -1;
    }
    for (int i = 0; i < n; i++) {
        (*list)[i].tags[0].tag = RX_UE_INFORMATION_TAG;
        (*list)[i].tags[1].tag = RNTI;
        (*list)[i].crc_flag = rand() % 256;
    }
    return 0;
}

int dns_resolution(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return status;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), 4);
        break;
    }

    freeaddrinfo(res); // all done with this structure
    return 0;
}

void limit_capabilities() {
    if (setrlimit(RLIMIT_NOFILE, &((struct rlimit){ .rlim_cur = 10, .rlim_max = 10 }))) perror("Failed to limit file descriptors");
    if (prctl(PR_SET_DUMPABLE, 0)) perror("Failed to disable core dumps");
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *list;
    int n = 5;
    u_char ip_address[4];

    limit_capabilities();

    if (create_and_populate_list(&list, n) != 0) {
        fprintf(stderr, "Failed to create and populate list\n");
        return 1;
    }

    for (int i = 0; i < n; i++) {
        printf("CRC_INDICATION_PDU_T %d: RX_UE_INFORMATION_TAG, RNTI, CRC_FLAG: %d, %d, %u\n", i, 
               list[i].tags[0].tag, list[i].tags[1].tag, list[i].crc_flag);
    }

    if (dns_resolution("example.com", ip_address) != 0) {
        fprintf(stderr, "DNS resolution failed\n");
        return 1;
    }

    printf("IP Address: %d.%d.%d.%d\n", ip_address[0], ip_address[1], ip_address[2], ip_address[3]);

    free(list);
    return 0;
}
