u_char* resolve_hostname_async(const char* hostname, int timeout) {
    struct addrinfo hints, *res, *p;
    u_char* ip_address = malloc(16); // IPv4 or IPv6
    if (!ip_address) return NULL;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_CANONNAME;
    hints.ai_protocol = IPPROTO_TCP;

    int status;
    struct timeval tv;
    tv.tv_sec = timeout;
    tv.tv_usec = 0;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        free(ip_address);
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
        if (p->ai_family == AF_INET) {
            memcpy(ip_address, &(ipv4->sin_addr), sizeof(in_addr_t));
            freeaddrinfo(res);
            return ip_address;
        }
    }

    freeaddrinfo(res);
    free(ip_address);
    return NULL;
}

int main() {
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T* array = create_and_populate_nfaipdu_array(n);
    if (!array) return -1;

    const char* hostname = "example.com";
    u_char* ip_address = resolve_hostname_async(hostname, 5);
    if (!ip_address) {
        free(array);
        return -1;
    }

    // Process array and IP address
    free(ip_address);
    free(array);

    return 0;
}
