#define MAX_SESSIONS 1024
#define DEFAULT_MAX_STRUCTS_PER_SESSION 16

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structs;
    int count;
    int max_count;
} SessionData;

typedef struct {
    SessionData sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
} NFAPIMultiplexor;

NFAPIMultiplexor multiplexor;

int allocate_session_data(int session_index, int max_structs) {
    if (session_index >= MAX_SESSIONS) return -1;

    SessionData *sd = &multiplexor.sessions[session_index];
    sd->max_count = max_structs;
    sd->structs = malloc(sd->max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!sd->structs) return -1;
    sd->count = 0;

    return 0;
}

int free_session_data(int session_index) {
    if (session_index >= MAX_SESSIONS) return -1;

    SessionData *sd = &multiplexor.sessions[session_index];
    free(sd->structs);
    memset(sd, 0, sizeof(SessionData));

    return 0;
}

int add_crc_indication(int session_index, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (session_index >= MAX_SESSIONS) return -1;

    SessionData *sd = &multiplexor.sessions[session_index];
    if (sd->count >= sd->max_count) return -1;

    NFAPI_CRC_INDICATION_PDU_T *new_struct = &sd->structs[sd->count++];
    new_struct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_struct->RNTI = RNTI;
    new_struct->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    return 0;
}

void init_multiplexor() {
    pthread_mutex_init(&multiplexor.lock, NULL);
}

void destroy_multiplexor() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        free_session_data(i);
    }
    pthread_mutex_destroy(&multiplexor.lock);
}

// Additional functions and data structures can be added here to support the requirements
