using System;
using System.IO;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Microsoft.Extensions.Logging;

public class MessageBrokerClient
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<MessageBrokerClient> _logger;
    private readonly string _brokerUrl;
    private const int MaxRetries = 5;
    private static readonly Random _random = new Random();

    public MessageBrokerClient(HttpClient httpClient, ILogger<MessageBrokerClient> logger, string brokerUrl)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _brokerUrl = brokerUrl ?? throw new ArgumentNullException(nameof(brokerUrl));
    }

    public async Task<string> SendMessageAsync(string jsonPayload)
    {
        byte[] messageBytes = Encoding.UTF8.GetBytes(jsonPayload);
        string acknowledgmentToken = null;

        for (int attempt = 0; attempt <= MaxRetries; attempt++)
        {
            try
            {
                _logger.LogInformation("Serializing message and sending to broker...");

                using (var content = new ByteArrayContent(messageBytes))
                {
                    var response = await _httpClient.PostAsync(_brokerUrl, content);
                    response.EnsureSuccessStatusCode();

                    acknowledgmentToken = await response.Content.ReadAsStringAsync();
                    _logger.LogInformation("Message sent successfully with acknowledgment token: {token}", acknowledgmentToken);
                }

                return acknowledgmentToken;
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Failed to send message. Attempt {attempt}/{maxAttempts}.", attempt + 1, MaxRetries);

                if (ShouldRetry(attempt))
                {
                    await Task.Delay(GetBackoffTime(attempt));
                }
                else
                {
                    throw;
                }
            }
        }

        throw new Exception("Failed to send message after multiple attempts.");
    }

    private bool ShouldRetry(int attempt)
    {
        return attempt < MaxRetries;
    }

    private TimeSpan GetBackoffTime(int attempt)
    {
        int delayBase = 100; // milliseconds
        int jitter = _random.Next(0, delayBase);
        int delay = (int)Math.Pow(2, attempt) * delayBase + jitter;

        return TimeSpan.FromMilliseconds(delay);
    }
}
