#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define MAX_SIZE 1024

typedef struct {
    long offset;
    int key;
    double value;
    time_t timestamp;
    bool status;
} record;

// Function to calculate checksum for a record
unsigned int calculate_checksum(record *rec) {
    return (unsigned int)(rec->offset ^ rec->key ^ *(int *)&rec->value ^
                          *(unsigned int *)&rec->timestamp ^ (rec->status ? 1 : 0));
}

// Function to initialize records and calculate checksums
record* init_records(int count, int min_key, int max_key) {
    record *records = malloc(count * sizeof(record));
    if (!records) return NULL;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < count; i++) {
        records[i].offset = rand() % MAX_SIZE;
        records[i].key = min_key + rand() % (max_key - min_key + 1);
        records[i].value = ((double)rand()) / RAND_MAX * 2.0 - 1.0;
        records[i].timestamp = time(NULL);
        records[i].status = (rand() % 2 == 0);

        records[i].checksum = calculate_checksum(&records[i]);
    }

    return records;
}

// Function to free allocated memory
void free_records(record *records, int count) {
    if (records) {
        free(records);
    }
}

int main() {
    int num_records = 5;

    record *records = init_records(num_records, 10, 20);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Offset=%ld, Key=%d, Value=%.2f, Timestamp=%ld, Status=%s, Checksum=%u\n",
               i, records[i].offset, records[i].key, records[i].value, records[i].timestamp,
               records[i].status ? "True" : "False", records[i].checksum);
    }

    free_records(records, num_records);

    return 0;
}
