#include <mutex>
#include <atomic>

struct data_entry {
    std::time_t start_time;
    int event_id_range[2];
    std::vector<int> status_code;
};

class RandomValueGenerator {
private:
    struct Range {
        double min, max;
        bool inclusive;
    };
    std::vector<Range> ranges;

public:
    void addRange(double min, double max, bool inclusive) {
        // Validate range inputs
        if (min > max) {
            std::cerr << "Error: Invalid range. Min should be less than or equal to Max." << std::endl;
            return;
        }
        ranges.push_back({min, max, inclusive});
    }

    int generateInt(int rangeIndex) {
        auto& range = ranges[rangeIndex];
        if (range.inclusive) {
            return static_cast<int>((rand() / (RAND_MAX + 1.0)) * (range.max - range.min + 1)) + range.min;
        } else {
            return static_cast<int>((rand() / (RAND_MAX + 1.0)) * (range.max - range.min)) + range.min + 1;
        }
    }

    float generateFloat(int rangeIndex) {
        auto& range = ranges[rangeIndex];
        if (range.inclusive) {
            return static_cast<float>((rand() / (RAND_MAX + 1.0)) * (range.max - range.min + 1)) + range.min;
        } else {
            return static_cast<float>((rand() / (RAND_MAX + 1.0)) * (range.max - range.min)) + range.min + 1;
        }
    }

    void resetAllRanges() {
        ranges.clear();
    }

    std::string toString() const {
        std::ostringstream oss;
        for (const auto& range : ranges) {
            oss << "Range: Min=" << range.min << ", Max=" << range.max << ", Inclusive=" << range.inclusive << "\n";
        }
        return oss.str();
    }
};

int main(int argc, char* argv[]) {
    // Main program logic
    RandomValueGenerator generator;
    generator.addRange(0, 1, true);
    generator.addRange(0, 100, false);

    std::cout << "Generated Int: " << generator.generateInt(0) << "\n";
    std::cout << "Generated Float: " << generator.generateFloat(1) << "\n";

    return 0;
}
```

