    pthread_mutex_init(&pool_lock, NULL);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        ue_contexts[i] = malloc(sizeof(LteUeContext));
        pthread_mutex_init(&ue_contexts[i]->mutex, NULL);
    }
}

LteUeContext *acquire_ue_context(int ue_id) {
    LteUeContext *ctx = NULL;
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS && ctx == NULL; i++) {
        if (ue_contexts[i]->ue_id == -1 || ue_contexts[i]->ue_id == ue_id) {
            ctx = ue_contexts[i];
            ctx->ue_id = ue_id;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return ctx;
}

void release_ue_context(LteUeContext *ctx) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] == ctx) {
            ctx->ue_id = -1;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

