#define MAX_INTERFACES 10
#define MAX_PACKETS 1000

typedef struct {
    time_t timestamp;
    int interface_id;
    int tcp_packets;
    int udp_packets;
    int icmp_packets;
} traffic_entry;

traffic_entry* parse_and_generate_alerts(const char* log_file, const char* interfaces[], int num_interfaces) {
    FILE* file = fopen(log_file, "r");
    if (!file) {
        perror("Failed to open log file");
        return NULL;
    }

    traffic_entry* entries = (traffic_entry*)malloc(MAX_PACKETS * sizeof(traffic_entry));
    if (!entries) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    int entry_count = 0;
    while (entry_count < MAX_PACKETS && fscanf(file, "%ld %d %d %d %d", 
                                               &entries[entry_count].timestamp,
                                               &entries[entry_count].interface_id,
                                               &entries[entry_count].tcp_packets,
                                               &entries[entry_count].udp_packets,
                                               &entries[entry_count].icmp_packets) == 5) {
        entry_count++;
    }

    fclose(file);
    return entries;
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <log_file> <interface1> <interface2> ... <interfaceN> <sample_rate> <alert_threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* log_file = argv[1];
    int num_interfaces = argc - 4;
    char** interfaces = &argv[4];

    traffic_entry* entries = parse_and_generate_alerts(log_file, (const char**)interfaces, num_interfaces);
    if (!entries) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < entry_count && entries[i].timestamp != 0; i++) {
        printf("Timestamp: %ld, Interface ID: %d, TCP Packets: %d, UDP Packets: %d, ICMP Packets: %d\n",
               entries[i].timestamp,
               entries[i].interface_id,
               entries[i].tcp_packets,
               entries[i].udp_packets,
               entries[i].icmp_packets);
    }

    free(entries);
    return EXIT_SUCCESS;
}
