int add_lte_ue_context(int ue_id) {
    pthread_mutex_lock(&mutex);
    if (num_ue_contexts >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    LTE_UE_Context *new_context = &ue_contexts[num_ue_contexts++];
    new_context->ue_id = ue_id;
    new_context->rrc_state = RRC_STATE_IDLE;
    memset(new_context->radio_bearers, 0, sizeof(int) * MAX_RADIO_BEARERS);
    pthread_mutex_unlock(&mutex);
    return 0;
