    for (int i = 0; i < num_ue_contexts; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            ue_contexts[i].rrc_state = rrc_state;
            if (radio_bearer != -1 && radio_bearer < MAX_RADIO_BEARERS) {
                ue_contexts[i].radio_bearers[radio_bearer] = 1;
            }
            pthread_mutex_unlock(&mutex);
            return 0;
        }
