#include <iostream>
#include <map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <string>

struct SessionContext {
    std::string sessionId;
    enum ConnectionState { Connected, Disconnected };
    ConnectionState state;
    double bandwidthUsage;
    std::vector<std::pair<std::time_t, ConnectionState>> stateHistory;
};

class TCPSessionManager {
public:
    void addSession(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_[id] = {id, SessionContext::Connected, 0.0};
    }

    void updateState(const std::string& id, SessionContext::ConnectionState newState) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions_.find(id) != sessions_.end()) {
            auto& session = sessions_[id];
            time_t now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
            session.stateHistory.push_back({now, newState});
            while (session.stateHistory.size() > 365) {
                session.stateHistory.erase(session.stateHistory.begin());
            }
            session.state = newState;
        }
    }

    void updateBandwidth(const std::string& id, double usage) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions_.find(id) != sessions_.end()) {
            sessions_[id].bandwidthUsage += usage;
        }
    }

    void removeSession(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_.erase(id);
    }

private:
    std::map<std::string, SessionContext> sessions_;
    std::mutex mutex_;
};
