#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define RRC_IDLE 0
#define RRC_CONNECTED 1

typedef struct {
    int ue_id;
    int rrc_state;
    pthread_mutex_t mutex;
} LTE_UE_Context;

typedef struct {
    time_t connection_time;
    int qos_params;
} Connection_History;

typedef struct {
    Connection_History history[30];
    int head, tail, count;
} QoS_History;

typedef struct {
    LTE_UE_Context *ue_contexts;
    pthread_mutex_t ue_context_mutex;
    QoS_History *qos_history;
    pthread_mutex_t qos_history_mutex;
} Region;

Region* create_region(int num_ues) {
    Region *region = (Region*)malloc(sizeof(Region));
    region->ue_contexts = (LTE_UE_Context*)malloc(num_ues * sizeof(LTE_UE_Context));
    region->qos_history = (QoS_History*)malloc(num_ues * sizeof(QoS_History));

    for(int i = 0; i < num_ues; i++) {
        pthread_mutex_init(&region->ue_contexts[i].mutex, NULL);
        pthread_mutex_init(&region->qos_history[i].mutex, NULL);
        region->ue_contexts[i].rrc_state = RRC_IDLE;
        region->qos_history[i].head = 0;
        region->qos_history[i].tail = 0;
        region->qos_history[i].count = 0;
    }

    pthread_mutex_init(&region->ue_context_mutex, NULL);
    pthread_mutex_init(&region->qos_history_mutex, NULL);

    return region;
}

void update_ue_context(Region *region, int ue_id, int new_state) {
    pthread_mutex_lock(&region->ue_context_mutex);
    pthread_mutex_lock(&region->ue_contexts[ue_id].mutex);

    // Update RRC state
    if(region->ue_contexts[ue_id].rrc_state != new_state) {
        region->ue_contexts[ue_id].rrc_state = new_state;

        // Add connection history entry
        pthread_mutex_lock(&region->qos_history[ue_id].mutex);
        time_t now = time(NULL);
        if(region->qos_history[ue_id].count < 30) {
            region->qos_history[ue_id].history[region->qos_history[ue_id].tail] = (Connection_History){now, new_state};
            region->qos_history[ue_id].tail = (region->qos_history[ue_id].tail + 1) % 30;
            region->qos_history[ue_id].count++;
        } else {
            region->qos_history[ue_id].head = (region->qos_history[ue_id].head + 1) % 30;
        }
        pthread_mutex_unlock(&region->qos_history[ue_id].mutex);
    }

    pthread_mutex_unlock(&region->ue_contexts[ue_id].mutex);
    pthread_mutex_unlock(&region->ue_context_mutex);
}

// Additional functions for managing the Region structure, handling asynchronous operations,
// implementing back-off strategies and retry logic, optimizing performance under load,
