}

int add_crc_to_list(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *crc) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(list->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->pool = new_pool;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (list->pool[i].rnti == crc->rnti) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI
        }
    }

    memcpy(&list->pool[list->size], crc, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;
