EVP_CIPHER* create_cipher(const char *cipher_name, const unsigned char *key, int key_length, const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (strcmp(cipher_name, "des_ecb") == 0) {
        if (key_length != DES_KEY_LENGTH) goto error;
        if (EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, key, NULL) != 1) goto error;
    } else if (strcmp(cipher_name, "des_cbc") == 0) {
        if (key_length != DES_KEY_LENGTH || iv_len != DES_BLOCK_SIZE) goto error;
        if (EVP_EncryptInit_ex(ctx, EVP_des_cbc(), NULL, key, iv) != 1) goto error;
    } else if (strcmp(cipher_name, "des_cfb") == 0) {
        if (key_length != DES_KEY_LENGTH || iv_len != DES_BLOCK_SIZE) goto error;
        if (EVP_EncryptInit_ex(ctx, EVP_des_cfb(), NULL, key, iv) != 1) goto error;
    } else if (strcmp(cipher_name, "des_ctr") == 0) {
        if (key_length != DES_KEY_LENGTH) goto error;
        if (EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv) != 1) goto error;
    } else if (strcmp(cipher_name, "des_ede") == 0) {
        if (!(key_length == DES_KEY_LENGTH * 2 || key_length == DES_KEY_LENGTH * 3)) goto error;
        if (iv_len != DES_BLOCK_SIZE) goto error;
        if (EVP_EncryptInit_ex(ctx, EVP_des_ede(), NULL, key, iv) != 1) goto error;
    } else if (strcmp(cipher_name, "des_ede2") == 0) {
        if (!(key_length == DES_KEY_LENGTH * 2)) goto error;
        if (iv_len != DES_BLOCK_SIZE) goto error;
        if (EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv) != 1) goto error;
    } else if (strcmp(cipher_name, "des_ede3") == 0) {
        if (!(key_length == DES_KEY_LENGTH * 2 || key_length == DES_KEY_LENGTH * 3)) goto error;
        if (iv_len != DES_BLOCK_SIZE) goto error;
        if (EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv) != 1) goto error;
    } else {
        goto error;
    }

    CipherContext *cipher_ctx = malloc(sizeof(CipherContext));
    if (!cipher_ctx) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    cipher_ctx->ctx = ctx;
    memcpy(cipher_ctx->iv, iv, iv_len);

    return (EVP_CIPHER*)cipher_ctx;

error:
    EVP_CIPHER_CTX_free(ctx);
    free(cipher_ctx);
    return NULL;
}
