    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        fprintf(stderr, "Memory allocation failed for data\n");
        return NULL;
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void napi_crc_list_free(NFAPI_CRC_LIST *list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

