#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <openssl/buffer.h>

EVP_CIPHER* create_cipher(const char* cipher_mode, const unsigned char* master_key, size_t key_len, const unsigned char* salt, size_t salt_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Select cipher based on mode
    EVP_CIPHER* cipher;
    if (strcmp(cipher_mode, "aes-256-gcm") == 0) {
        cipher = EVP_aes_256_gcm();
    } else if (strcmp(cipher_mode, "aes-128-ccm") == 0) {
        cipher = EVP_aes_128_ccm();
    } else if (strcmp(cipher_mode, "aes-256_xts") == 0) {
        cipher = EVP_aes_256_xts();
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Derive key using HKDF-SHA256
    unsigned char derived_key[32];
    size_t derived_len;
    if (HKDF(derived_key, sizeof(derived_key), EVP_sha256(), master_key, key_len, salt, salt_len, NULL, 0, &derived_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set up cipher context
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, derived_key, NULL) != 1 ||
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Securely zero out sensitive data
    OPENSSL_cleanse(derived_key, sizeof(derived_key));

    return cipher;
}
```

