#include <stdio.h>

// Function to derive a key using HKDF-SHA256
int hkdf_derive_key(const unsigned char *ikm, size_t ikmlen,
                    const unsigned char *salt, size_t saltlen,
                    const unsigned char *info, size_t infolen,
                    unsigned char *okm, size_t okmlen) {
    EVP_HKDF_CTX *hkdf_ctx;
    int ret;

    hkdf_ctx = EVP_HKDF_CTX_new();
    if (hkdf_ctx == NULL) return 0;

    ret = EVP_HKDF_Init(hkdf_ctx, EVP_sha256(), salt, saltlen, ikm, ikmlen);
    if (ret != 1) goto end;

    ret = EVP_HKDF_derive(hkdf_ctx, okm, okmlen, info, infolen);
    if (ret != 1) goto end;

end:
    EVP_HKDF_CTX_free(hkdf_ctx);
    return ret;
}

// Function to securely allocate memory
void *secure_malloc(size_t size) {
    void *ptr = OPENSSL_secure_malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to securely zero out memory
void secure_free(void *ptr, size_t len) {
    OPENSSL_cleanse(ptr, len);
    OPENSSL_secure_free(ptr);
}

// Function to initialize the cryptographic library
EVP_CIPHER_CTX *initialize_cipher(const char *cipher_name,
                                   const unsigned char *key,
                                   int key_len,
                                   const unsigned char *iv,
                                   int iv_len,
                                   int encrypt_mode) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return NULL;

    if (encrypt_mode) {
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) goto err;
    } else {
        if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) goto err;
    }

    return ctx;

err:
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

// Function to encrypt data
int encrypt_data(EVP_CIPHER_CTX *ctx,
                 const unsigned char *plaintext,
                 size_t plaintext_len,
                 unsigned char *ciphertext) {
    int len, ciphertext_len = 0;

    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) return -1;
    ciphertext_len += len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) return -1;
    ciphertext_len += len;

    return ciphertext_len;
}

// Function to decrypt data
int decrypt_data(EVP_CIPHER_CTX *ctx,
                 const unsigned char *ciphertext,
                 size_t ciphertext_len,
                 unsigned char *plaintext) {
    int len, plaintext_len = 0;

    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) return -1;
    plaintext_len += len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) return -1;
    plaintext_len += len;

    return plaintext_len;
}

// Function to handle errors
void handle_error() {
    ERR_print_errors_fp(stderr);
    exit(EXIT_FAILURE);
}
