#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_CONTEXTS 100000
#define RRC_IDLE 0
#define RRC_CONNECTED 1
#define HISTORY_RETENTION_DAYS 30

typedef struct {
    int ue_id;
    int rrc_state;
    int active_bearers[MAX_BEARERS];
    time_t connection_history[HISTORY_RETENTION_DAYS];
    int qos_params;
} LTE_UE_Context;

LTE_UE_Context ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_ue_context(int ue_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == -1) {
            ue_contexts[i].ue_id = ue_id;
            ue_contexts[i].rrc_state = RRC_IDLE;
            for (int j = 0; j < MAX_BEARERS; j++) {
                ue_contexts[i].active_bearers[j] = -1;
            }
            time_t now = time(NULL);
            for (int k = 0; k < HISTORY_RETENTION_DAYS; k++) {
                ue_contexts[i].connection_history[k] = now - k * 86400;
            }
            ue_contexts[i].qos_params = 0;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void update_rrc_state(int ue_id, int new_state) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            ue_contexts[i].rrc_state = new_state;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void add_active_bearer(int ue_id, int bearer_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            for (int j = 0; j < MAX_BEARERS; j++) {
                if (ue_contexts[i].active_bearers[j] == -1) {
                    ue_contexts[i].active_bearers[j] = bearer_id;
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void update_qos_params(int ue_id, int new_params) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            ue_contexts[i].qos_params = new_params;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void update_connection_history(int ue_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            time_t now = time(NULL);
            memmove(ue_contexts[i].connection_history + 1, ue_contexts[i].connection_history, (HISTORY_RETENTION_DAYS - 2) * sizeof(time_t));
            ue_contexts[i].connection_history[HISTORY_RETENTION_DAYS - 1] = now;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
