        FILE* file = fopen(file_paths[i], "r");
        if (file == NULL) {
            perror("Failed to open file");
            continue;
        }

        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), file)) {
            // Perform text transformations here
            // ...

            Token* tokens = malloc(sizeof(Token));
            if (tokens == NULL) {
                perror("Memory allocation failed for tokens");
                fclose(file);
                continue;
            }
            memset(tokens, 0, sizeof(Token));
            strncpy(tokens->token, buffer, MAX_TOKEN_LENGTH - 1);
            tokens->length = strlen(tokens->token);

            // Handle memory allocation limit
            if (sizeof(Token) * num_tokens > MAX_MEMORY_ALLOCATION_SIZE) {
                free(tokens);
                break;
            }
        }

        fclose(file);
    }

    return NULL;
}

