        if (pthread_create(&threads[i], NULL, process_file_paths, (void*)&file_paths[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < MAX_FILE_PATHS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
