#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <thread>
#include <vector>

struct SessionContext {
    std::string sessionID;
    enum ConnectionState { DISCONNECTED, CONNECTING, CONNECTED } state;
    struct TrafficMetadata {
        // Define traffic metadata fields here
    };
    std::vector<std::pair<std::time_t, int>> bandwidthHistory; // Timestamp and bandwidth usage

    void updateBandwidth(int bytes) {
        bandwidthHistory.emplace_back(std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()), bytes);
        if (bandwidthHistory.size() > 31536000) { // One year in seconds
            bandwidthHistory.erase(bandwidthHistory.begin());
        }
    }

    int getBandwidthUsage(const std::tm& start, const std::tm& end) {
        auto startIt = std::lower_bound(bandwidthHistory.begin(), bandwidthHistory.end(), start,
                                       [](const std::pair<std::time_t, int>& a, const std::tm& b) {
                                           return a.first < mktime(&b);
                                       });
        auto endIt = std::upper_bound(startIt, bandwidthHistory.end(), end,
                                     [](const std::pair<std::time_t, int>& a, const std::tm& b) {
                                         return a.first < mktime(&b);
                                     });

        int totalBytes = 0;
        for (auto it = startIt; it != endIt; ++it) {
            totalBytes += it->second;
        }

        return totalBytes;
    }
};

class SessionManager {
private:
    std::unordered_map<std::string, SessionContext> sessions;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void addSession(const std::string& sessionID) {
        std::lock_guard<std::mutex> lock(mutex);
        sessions[sessionID] = {sessionID, SessionContext::DISCONNECTED};
        cv.notify_all();
    }

    void updateSessionState(const std::string& sessionID, SessionContext::ConnectionState newState) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sessions.find(sessionID) != sessions.end()) {
            sessions[sessionID].state = newState;
            cv.notify_all();
        }
    }

    void updateSessionBandwidth(const std::string& sessionID, int bytes) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sessions.find(sessionID) != sessions.end()) {
            sessions[sessionID].updateBandwidth(bytes);
            cv.notify_all();
        }
    }

    int getHistoricalBandwidthUsage(const std::string& sessionID, const std::tm& start, const std::tm& end) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sessions.find(sessionID) != sessions.end()) {
            return sessions[sessionID].getBandwidthUsage(start, end);
        }
        return 0;
    }

    void pruneInactiveSessions() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::hours(1));
            std::lock_guard<std::mutex> lock(mutex);
            auto now = std::time(nullptr);
            for (auto it = sessions.begin(); it != sessions.end(); ) {
                if ((now - it->second.bandwidthHistory.back().first) > 31536000) { // One year in seconds
                    it = sessions.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

    void runPruningThread() {
        std::thread([this]() {
            pruneInactiveSessions();
        }).detach();
    }
};
