#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_UE_CONTEXTS 1000
#define HISTORICAL_RECORD_DAYS 30

typedef struct {
    int ue_id;
    int rrc_state;
    int *active_bearers;
    int bearer_count;
    pthread_mutex_t mutex;
} UEContext;

typedef struct {
    UEContext contexts[MAX_UE_CONTEXTS];
    int next_index;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} LTEUEManager;

LTEUEManager* create_lte_ue_manager() {
    LTEUEManager *manager = (LTEUEManager*)malloc(sizeof(LTEUEManager));
    if (!manager) return NULL;

    manager->next_index = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);

    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        pthread_mutex_init(&manager->contexts[i].mutex, NULL);
    }

    return manager;
}

void destroy_lte_ue_manager(LTEUEManager *manager) {
    if (!manager) return;

    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        pthread_mutex_destroy(&manager->contexts[i].mutex);
    }
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond);

    free(manager);
}

void add_ue_context(LTEUEManager *manager, int ue_id, int rrc_state) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->next_index >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    UEContext *new_context = &manager->contexts[manager->next_index++];
    new_context->ue_id = ue_id;
    new_context->rrc_state = rrc_state;
    new_context->active_bearers = (int*)malloc(0); // Initial size 0
    new_context->bearer_count = 0;

    pthread_mutex_unlock(&manager->mutex);
}

void remove_ue_context(LTEUEManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->next_index; i++) {
        if (manager->contexts[i].ue_id == ue_id) {
            free(manager->contexts[i].active_bearers);
            manager->contexts[i] = manager->contexts[--manager->next_index];
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void update_rrc_state(LTEUEManager *manager, int ue_id, int new_state) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->next_index; i++) {
        if (manager->contexts[i].ue_id == ue_id) {
            pthread_mutex_lock(&manager->contexts[i].mutex);
            manager->contexts[i].rrc_state = new_state;
            pthread_mutex_unlock(&manager->contexts[i].mutex);
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void add_bearer(LTEUEManager *manager, int ue_id, int bearer_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->next_index; i++) {
        if (manager->contexts[i].ue_id == ue_id) {
            pthread_mutex_lock(&manager->contexts[i].mutex);
            manager->contexts[i].active_bearers = realloc(manager->contexts[i].active_bearers, 
                (manager->contexts[i].bearer_count + 1) * sizeof(int));
            if (manager->contexts[i].active_bearers) {
                manager->contexts[i].active_bearers[manager->contexts[i].bearer_count++] = bearer_id;
            }
            pthread_mutex_unlock(&manager->contexts[i].mutex);
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void remove_bearer(LTEUEManager *manager, int ue_id, int bearer_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->next_index; i++) {
        if (manager->contexts[i].ue_id == ue_id) {
            pthread_mutex_lock(&manager->contexts[i].mutex);
            for (int j = 0; j < manager->contexts[i].bearer_count; j++) {
                if (manager->contexts[i].active_bearers[j] == bearer_id) {
                    for (int k = j; k < manager->contexts[i].bearer_count - 1; k++) {
                        manager->contexts[i].active_bearers[k] = manager->contexts[i].active_bearers[k + 1];
                    }
                    manager->contexts[i].bearer_count--;
                    break;
                }
            }
            pthread_mutex_unlock(&manager->contexts[i].mutex);
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
