#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_MESSAGES 1000
#define HASH_SIZE 1024

typedef struct {
    int id;
    char *message;
    int priority;
} Message;

Message message_queue[MAX_MESSAGES];
int front = -1, rear = -1;
sem_t queue_lock;

typedef struct {
    pthread_t thread_id;
    // Additional worker-specific data
} Worker;

Worker workers[20]; // Adjust the size as needed

pthread_mutex_t lookup_mutex;
unsigned char processed_messages[HASH_SIZE];

void enqueue(Message msg) {
    sem_wait(&queue_lock);
    if ((rear + 1) % MAX_MESSAGES == front) {
        printf("Queue is full\n");
        return;
    }
    rear = (rear + 1) % MAX_MESSAGES;
    message_queue[rear] = msg;
    sem_post(&queue_lock);
}

Message dequeue() {
    Message msg;
    sem_wait(&queue_lock);
    if (front == -1) {
        printf("Queue is empty\n");
        msg.message = NULL;
        return msg;
    }
    msg = message_queue[front];
    front = (front + 1) % MAX_MESSAGES;
    sem_post(&queue_lock);
    return msg;
}

void* worker_thread(void *arg) {
    Worker *worker = (Worker *) arg;
    Message msg;
    while (1) {
        msg = dequeue();
        if (msg.message == NULL) break; // Exit thread when queue is empty
        // Process the message
        printf("Worker %d processing message %s\n", worker->id, msg.message);
        // Simulate processing time
        sleep(msg.priority); // Lower priority messages take longer to process
    }
    return NULL;
}

void start_worker_pool(int num_workers) {
    for (int i = 0; i < num_workers; ++i) {
        workers[i].id = i;
        pthread_create(&workers[i].thread_id, NULL, worker_thread, &workers[i]);
    }
}

void adjust_worker_count(int new_count) {
    int current_count = sizeof(workers) / sizeof(workers[0]);
    if (new_count > current_count) {
        // Add new workers
        for (int i = current_count; i < new_count; ++i) {
            pthread_create(&workers[i].thread_id, NULL, worker_thread, &workers[i]);
        }
    } else if (new_count < current_count) {
        // Terminate excess workers
        for (int i = new_count; i < current_count; ++i) {
            pthread_join(workers[i].thread_id, NULL);
        }
        // Resize the worker array if necessary
    }
}

void process_message_queue() {
    start_worker_pool(5); // Initial number of workers
    int current_load = 100; // Simulated system load
    while (1) {
        adjust_worker_count(current_load / 10); // Adjust workers based on load
        Message msg = dequeue();
        if (msg.message == NULL) break;
        // Check for duplicates using a hash-based lookup table
        unsigned int hash = msg.id % HASH_SIZE;
        pthread_mutex_lock(&lookup_mutex);
        if (!processed_messages[hash]) {
            processed_messages[hash] = 1;
            enqueue(msg); // Enqueue the message again to be processed by workers
        }
        pthread_mutex_unlock(&lookup_mutex);
    }
}

int main() {
    sem_init(&queue_lock, 0, 1);
    pthread_mutex_init(&lookup_mutex, NULL);

    process_message_queue();

    for (int i = 0; i < sizeof(workers) / sizeof(workers[0]); ++i) {
        pthread_join(workers[i].thread_id, NULL);
    }

    sem_destroy(&queue_lock);
    pthread_mutex_destroy(&lookup_mutex);

    return 0;
}
