        sscanf(entries[entry_count]->udp_count, "%d", &entries[entry_count]->udp_count);
        sscanf(entries[entry_count]->icmp_count, "%d", &entries[entry_count]->icmp_count);

        if (entries[entry_count]->tcp_count > 1000 || entries[entry_count]->udp_count > 1000) {
            printf("Alert: High traffic on interface %s\n", entries[entry_count]->interface_id);
        }

        entry_count++;
    }

    fclose(file);
