            if (!ec) {
                std::vector<char> buffer(4096);
                auto receivedBytes = socket.read_some(boost::asio::buffer(buffer), ec);
                // Process response
            } else {
                BOOST_LOG_TRIVIAL(error) << "Request failed: " << ec.message();
            }
        } catch (const boost::system::system_error& e) {
            BOOST_LOG_TRIVIAL(error) << "Exception occurred: " << e.what();
