#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structures
typedef struct {
    int ue_id;
    char rrc_state[50];
    int *bearers;
    // Add more fields as needed
} UEContext;

typedef struct {
    pthread_mutex_t lock;
    UEContext **contexts;
    int size;
    int max_size;
} LTEUEManager;

// Function to initialize the LTE UE context manager
LTEUEManager* init_lte_manager(int initial_size) {
    LTEUEManager *manager = (LTEUEManager*)malloc(sizeof(LTEUEManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->contexts = (UEContext**)calloc(initial_size, sizeof(UEContext*));
    manager->size = 0;
    manager->max_size = initial_size;

    return manager;
}

// Function to add a new UE context
int add_ue_context(LTEUEManager *manager, UEContext *ue) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->max_size) {
        manager->contexts = realloc(manager->contexts, 2 * manager->max_size * sizeof(UEContext*));
        if (!manager->contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->max_size *= 2;
    }
    manager->contexts[manager->size++] = ue;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to update an existing UE context
int update_ue_context(LTEUEManager *manager, int ue_id, char *new_rrc_state) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            strcpy(manager->contexts[i]->rrc_state, new_rrc_state);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

// Function to remove an UE context
int remove_ue_context(LTEUEManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            free(manager->contexts[i]);
            for (; i < manager->size - 1; ++i) {
                manager->contexts[i] = manager->contexts[i + 1];
            }
            manager->size--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

// Function to destroy the LTE UE context manager
void destroy_lte_manager(LTEUEManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; ++i) {
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
