log_event *create_log_events(int num_events, int max_message_length) {
    log_event *events = malloc(num_events * sizeof(log_event));
    if (!events) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_events; ++i) {
        events[i].tag = 'A' + rand() % 26; // Random tag
        events[i].timestamp = time(NULL);
        int message_length = rand() % max_message_length;
        events[i].message[0] = '\0';
        strncat(events[i].message, "Log message ", 13); // Prefix with fixed string
        strncat(events[i].message, &events[i].tag, 1);
        strncat(events[i].message, " at time ", 10);
        char timestamp_str[MAX_TIMESTAMP_LENGTH];
        snprintf(timestamp_str, MAX_TIMESTAMP_LENGTH, "%d", events[i].timestamp);
        strncat(events[i].message, timestamp_str, message_length - strlen(events[i].message));
    }

    return events;
}

void free_log_events(log_event *events, int num_events) {
    free(events);
}

int main() {
    int num_events = 10;
    int max_message_length = 256;

    log_event *log_events = create_log_events(num_events, max_message_length);
