        for (int i = 0; i < num_events; ++i) {
            printf("Event %d: Tag=%c, Timestamp=%d, Message='%s'\n", 
                   i, log_events[i].tag, log_events[i].timestamp, log_events[i].message);
        }
        free_log_events(log_events, num_events);
