#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_IPS 10
#define MAX_HOSTNAME_LENGTH 256

typedef struct {
    u_char ip[16]; // Can hold both IPv4 and IPv6 addresses
    int address_type; // 0 for IPv4, 1 for IPv6
} IPAddress;

int resolve_hostname(const char *hostname, IPAddress *ip_addresses, int max_ips) {
    if (strlen(hostname) >= MAX_HOSTNAME_LENGTH) {
        return -1; // Error: Hostname too long
    }

    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -2; // Error: DNS resolution failed
    }

    int count = 0;
    for (p = res; p != NULL && count < max_ips; p = p->ai_next) {
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            memcpy(ip_addresses[count].ip, &ipv4->sin_addr.s_addr, 4);
            ip_addresses[count].address_type = 0;
        } else if (p->ai_family == AF_INET6) { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            memcpy(ip_addresses[count].ip, ipv6->sin6_addr.s6_addr, 16);
            ip_addresses[count].address_type = 1;
        }
        count++;
    }

    freeaddrinfo(res);
    return count;
}

int main() {
    char hostname[MAX_HOSTNAME_LENGTH] = "example.com";
    IPAddress ips[MAX_IPS];

    int num_ips = resolve_hostname(hostname, ips, MAX_IPS);
    if (num_ips < 0) {
        printf("Error: %d\n", num_ips);
    } else {
        for (int i = 0; i < num_ips; i++) {
            char ip_str[INET6_ADDRSTRLEN];
            if (ips[i].address_type == 0) {
                inet_ntop(AF_INET, ips[i].ip, ip_str, INET_ADDRSTRLEN);
            } else {
                inet_ntop(AF_INET6, ips[i].ip, ip_str, INET6_ADDRSTRLEN);
            }
            printf("IP Address %d: %s\n", i + 1, ip_str);
        }
    }

    return 0;
}
