// Function to perform AES-256 encryption
int aes_256_encrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int temp;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &temp)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ciphertext_len += temp;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Function to perform AES-256 decryption
int aes_256_decrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int temp;
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &temp)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    plaintext_len += temp;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

