    unsigned char key[8];
    unsigned char iv[DES_BLOCK_SIZE];
} CipherContext;

void init_cipher_context(CipherContext *cc, EncryptionMode mode) {
    cc->ctx = EVP_CIPHER_CTX_new();
    switch (mode) {
        case NULL_ENCRYPTION:
            // Initialize for null encryption
            break;
        case DES_ECB:
            EVP_EncryptInit_ex(cc->ctx, EVP_des_ecb(), NULL, cc->key, cc->iv);
            break;
        case DES_EDE:
            EVP_EncryptInit_ex(cc->ctx, EVP_des_ede_cbc(), NULL, cc->key, cc->iv);
            break;
        case DES_EDE3:
            EVP_EncryptInit_ex(cc->ctx, EVP_des_ede3_cbc(), NULL, cc->key, cc->iv);
            break;
        case CFB_MODE:
            EVP_EncryptInit_ex(cc->ctx, EVP_des_cfb64(), NULL, cc->key, cc->iv);
            break;
    }
}

void encrypt_data(CipherContext *cc, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    EVP_EncryptUpdate(cc->ctx, ciphertext, &len, plaintext, plaintext_len);
    int ciphertext_len = len;
    EVP_EncryptFinal_ex(cc->ctx, ciphertext + len, &len);
    ciphertext_len += len;
}

void decrypt_data(CipherContext *cc, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len;
    EVP_DecryptUpdate(cc->ctx, plaintext, &len, ciphertext, ciphertext_len);
    int plaintext_len = len;
    EVP_DecryptFinal_ex(cc->ctx, plaintext + len, &len);
    plaintext_len += len;
}

void cleanup_cipher_context(CipherContext *cc) {
    EVP_CIPHER_CTX_free(cc->ctx);
}
