#define MAX_UE_CONTEXTS 1024
#define MAX_BEARERS_PER_UE 8
#define HISTORY_RETENTION_DAYS 30

typedef enum { IDLE, CONNECTED } RRCState;
typedef struct {
    int bearer_id;
    // Other bearer details
} Bearer;

typedef struct {
    int ue_id;
    RRCState rrc_state;
    Bearer active_bearers[MAX_BEARERS_PER_UE];
    time_t connection_history[HISTORY_RETENTION_DAYS];
    // QoS parameters and other details
} UEContext;

typedef struct {
    UEContext ues[MAX_UE_CONTEXTS];
    pthread_mutex_t mutex;
} UESet;

UESet* init_ueset() {
    UESet* set = malloc(sizeof(UESet));
    pthread_mutex_init(&set->mutex, NULL);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        set->ues[i].ue_id = -1;
    }
    return set;
}

void update_ue_context(UESet* set, int ue_id, RRCState state, Bearer* bearers) {
    pthread_mutex_lock(&set->mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (set->ues[i].ue_id == ue_id) {
            set->ues[i].rrc_state = state;
            for (int j = 0; j < MAX_BEARERS_PER_UE && bearers[j].bearer_id != -1; j++) {
                set->ues[i].active_bearers[j] = bearers[j];
            }
            time_t current_time = time(NULL);
            for (int j = 0; j < HISTORY_RETENTION_DAYS; j++) {
                set->ues[i].connection_history[j] = current_time - (j * 86400);
            }
            break;
        }
    }
    pthread_mutex_unlock(&set->mutex);
}

