#include <iostream>
#include <mutex>
#include <unordered_map>
#include <list>
#include <vector>
#include <chrono>

class AuthenticationSession {
public:
    using SessionID = int;
    enum class Status { ACTIVE, INACTIVE };
    struct AccessAttempt {
        bool success;
        std::chrono::system_clock::time_point timestamp;
    };

private:
    struct SessionData {
        Status status;
        std::list<AccessAttempt> history;
    };

    std::unordered_map<SessionID, SessionData> sessions;
    mutable std::mutex sessions_mutex;

public:
    void updateStatus(SessionID id, Status new_status) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        auto it = sessions.find(id);
        if (it != sessions.end()) {
            it->second.status = new_status;
        }
    }

    bool recordAccessAttempt(SessionID id, bool success) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        auto it = sessions.find(id);
        if (it == sessions.end()) {
            return false; // Session not found
        }
        AccessAttempt attempt{success, std::chrono::system_clock::now()};
        it->second.history.push_back(attempt);
        if (it->second.history.size() > 90) {
            it->second.history.pop_front();
        }
        return true;
    }

    bool getStatus(SessionID id, Status& status) const {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        auto it = sessions.find(id);
        if (it != sessions.end()) {
            status = it->second.status;
            return true;
        }
        return false;
    }

    std::vector<AccessAttempt> getRecentAttempts(SessionID id) const {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        auto it = sessions.find(id);
        if (it != sessions.end()) {
            return {it->second.history.begin(), it->second.history.end()};
        }
        return {};
    }
};
