#define LOG_RETENTION_DAYS 7

typedef struct {
    int request_id;
    time_t timestamp;
    int response_code;
} RequestLog;

typedef struct ServerInstance {
    int instance_id;
    RequestLog* log;
    size_t log_size;
    size_t log_capacity;
} ServerInstance;

ServerInstance* create_server_instance(int instance_id) {
    ServerInstance* instance = (ServerInstance*)malloc(sizeof(ServerInstance));
    if (instance == NULL) {
        fprintf(stderr, "Memory allocation failed for server instance.\n");
        exit(EXIT_FAILURE);
    }
    instance->instance_id = instance_id;
    instance->log = NULL;
    instance->log_size = 0;
    instance->log_capacity = 0;
    return instance;
}

void add_request_log(ServerInstance* instance, int request_id, int response_code) {
    if (instance->log_size >= instance->log_capacity) {
        size_t new_capacity = instance->log_capacity > 0 ? instance->log_capacity * 2 : 16;
        RequestLog* new_log = (RequestLog*)realloc(instance->log, new_capacity * sizeof(RequestLog));
        if (new_log == NULL) {
            fprintf(stderr, "Memory allocation failed for request log.\n");
            exit(EXIT_FAILURE);
        }
        instance->log = new_log;
        instance->log_capacity = new_capacity;
    }
    RequestLog entry = {request_id, time(NULL), response_code};
    instance->log[instance->log_size++] = entry;
}

void remove_server_instance(ServerInstance* instance) {
    free(instance->log);
