int next_ue_id = 0;
pthread_mutex_t context_lock;

void initialize_ue_context(int ue_id, int rrc_state) {
    pthread_mutex_lock(&context_lock);
    if (next_ue_id < MAX_UE_CONTEXTS) {
        ue_contexts[next_ue_id] = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
        ue_contexts[next_ue_id]->ue_id = ue_id;
        ue_contexts[next_ue_id]->rrc_state = rrc_state;
        pthread_mutex_init(&ue_contexts[next_ue_id]->bearer_lock, NULL);
        // Initialize radio bearers and QoS parameters
        next_ue_id++;
    }
    pthread_mutex_unlock(&context_lock);
}

void update_ue_context(int ue_id, int new_rrc_state) {
    pthread_mutex_lock(&context_lock);
    for (int i = 0; i < next_ue_id; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            pthread_mutex_lock(&ue_contexts[i]->bearer_lock);
            ue_contexts[i]->rrc_state = new_rrc_state;
            // Update radio bearers and QoS parameters
            pthread_mutex_unlock(&ue_contexts[i]->bearer_lock);
            break;
        }
    }
    pthread_mutex_unlock(&context_lock);
}

