void initialize_frame_pool(FRAME_POOL *pool) {
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

MAC_FRAME_PDU_T* allocate_frame(FRAME_POOL *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < MAX_FRAMES) {
        MAC_FRAME_PDU_T *frame = &pool->frames[pool->count++];
        pthread_mutex_unlock(&pool->mutex);
        return frame;
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL; // Frame pool exhausted
}

void deallocate_frame(FRAME_POOL *pool, MAC_FRAME_PDU_T *frame) {
    pthread_mutex_lock(&pool->mutex);
    size_t index = (size_t)(frame - pool->frames);
    if (index < pool->count) {
        frame = &pool->frames[--pool->count];
        pthread_mutex_unlock(&pool->mutex);
        // Optionally reset frame to a known state
        memset(frame, 0, sizeof(MAC_FRAME_PDU_T));
    } else {
        pthread_mutex_unlock(&pool->mutex);
    }
}

void populate_mac_frames(FRAME_POOL *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        MAC_FRAME_PDU_T *frame = &pool->frames[i];
        // Populate the PHY layer stats tag
        frame->phy_stats = ...;

        // Populate the MAC layer config tag
        frame->mac_config = ...;
    }
}

void destroy_frame_pool(FRAME_POOL *pool) {
