#define MAX_AP 100
#define MAX_STATION 50

typedef enum { INFRASTRUCTURE, AD_HOC } Mode;

typedef struct {
    int id;
    Mode mode;
    char ssid[32];
    int channel;
    int security_policy;
} Station;

typedef struct {
    int ap_id;
    Mode mode;
    Station stations[MAX_STATION];
    int station_count;
    pthread_mutex_t lock;
} APConfig;

APConfig ap_configs[MAX_AP];

void init_ap_config(int ap_id, Mode mode) {
    ap_configs[ap_id].ap_id = ap_id;
    ap_configs[ap_id].mode = mode;
    ap_configs[ap_id].station_count = 0;
    pthread_mutex_init(&ap_configs[ap_id].lock, NULL);
}

void add_station(int ap_id, Station station) {
    pthread_mutex_lock(&ap_configs[ap_id].lock);
    if (ap_configs[ap_id].station_count < MAX_STATION) {
        ap_configs[ap_id].stations[ap_configs[ap_id].station_count] = station;
        ap_configs[ap_id].station_count++;
    }
    pthread_mutex_unlock(&ap_configs[ap_id].lock);
}

void update_ap_mode(int ap_id, Mode new_mode) {
    pthread_mutex_lock(&ap_configs[ap_id].lock);
    ap_configs[ap_id].mode = new_mode;
    // Trigger notification mechanism here
    printf("AP %d mode updated to %s\n", ap_id, (new_mode == INFRASTRUCTURE) ? "INFRASTRUCTURE" : "AD_HOC");
    pthread_mutex_unlock(&ap_configs[ap_id].lock);
}

void log_operation(int ap_id, const char* operation, int success) {
    time_t now = time(NULL);
    printf("AP %d - %s: %s\n", ap_id, operation, (success) ? "Success" : "Failure");
}

// Example usage
int main() {
    init_ap_config(1, INFRASTRUCTURE);

    Station station1;
    station1.id = 101;
    strcpy(station1.ssid, "MyNetwork");
    station1.channel = 6;
    station1.security_policy = 2;

    add_station(1, station1);

    update_ap_mode(1, AD_HOC);

    log_operation(1, "Add Station", 1);
    log_operation(1, "Update Mode", 1);

    return 0;
}
