    private void executeSedCommands(Map<String, Object> parameters, String configFilePath) throws IOException {
        for (Map.Entry<String, Object> entry : parameters.entrySet()) {
            String command = "sed -i 's/" + entry.getKey() + "/" + entry.getValue() + "/' " + configFilePath;
            Process process = Runtime.getRuntime().exec(command);
