#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    time_t timestamp;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    node->data = data;
    node->next = NULL;
    node->timestamp = time(NULL);
    return node;
}

void append_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Handle memory allocation failure
    }
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
