#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head, *tail;
    size_t count;
    pthread_mutex_t mutex;
} RX_UE_INFORMATION_LIST;

RX_UE_INFORMATION_LIST* rx_ue_list_create() {
    RX_UE_INFORMATION_LIST* list = (RX_UE_INFORMATION_LIST*)malloc(sizeof(RX_UE_INFORMATION_LIST));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void rx_ue_list_destroy(RX_UE_INFORMATION_LIST* list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int rx_ue_list_add(RX_UE_INFORMATION_LIST* list, uint8_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU* new_entry = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_entry) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }
    new_entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->RNTI = RNTI;
    new_entry->CRC_INDICATION_REL8_TAG = (rand() % 2); // Randomly set CRCFLAG
    new_entry->timestamp = time(NULL);
    new_entry->prev = list->tail;
    new_entry->next = NULL;

    if (!list->head) {
        list->head = list->tail = new_entry;
    } else {
        list->tail->next = new_entry;
        list->tail = new_entry;
    }
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void rx_ue_list_traverse(RX_UE_INFORMATION_LIST* list, void (*callback)(NFAPI_CRC_INDICATION_PDU*)) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Example usage
void print_entry(NFAPI_CRC_INDICATION_PDU* entry) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d, Timestamp: %s", 
           entry->RX_UE_INFORMATION_TAG, entry->RNTI, entry->CRC_INDICATION_REL8_TAG, ctime(&entry->timestamp));
}

int main() {
    RX_UE_INFORMATION_LIST* list = rx_ue_list_create();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    // Add entries
    for (int i = 0; i < 5; i++) {
        if (rx_ue_list_add(list, i, 1234 + i)) {
            fprintf(stderr, "Failed to add entry %d\n", i);
        }
    }

    // Traverse and print list
    rx_ue_list_traverse(list, print_entry);

    // Clean up
    rx_ue_list_destroy(list);
    return 0;
}
```

