function copyBufferedData(chunks, byteOffset, numBytes, encoding = 'utf8', retries = 3, backoffFactor = 2) {
    // Validate input parameters
    if (byteOffset < 0 || numBytes <= 0) {
        throw new Error('Invalid byte offset or number of bytes');
    }

    let totalLength = 0;
    for (let chunk of chunks) {
        totalLength += chunk.length;
    }

    if (byteOffset + numBytes > totalLength) {
        throw new Error('Out-of-bounds access');
    }

    // Allocate a buffer to hold the copied data
    const outputBuffer = Buffer.allocUnsafe(numBytes);

    // Function to attempt copying data with retries and backoff
    function copyDataWithRetries(currentOffset, retryCount) {
        try {
            let bytesRead = 0;
            for (let chunk of chunks) {
                if (currentOffset < byteOffset + numBytes) {
                    const bytesToCopy = Math.min(chunk.length, byteOffset + numBytes - currentOffset);
                    outputBuffer.copy(chunk, 0, currentOffset - byteOffset, currentOffset - byteOffset + bytesToCopy);
                    bytesRead += bytesToCopy;
                    currentOffset += bytesToCopy;
                } else {
                    break;
                }
            }
            return bytesRead;
        } catch (error) {
            if (retryCount > 0) {
                const backoffTime = Math.pow(backoffFactor, retries - retryCount) * 100; // Exponential backoff
                setTimeout(() => copyDataWithRetries(currentOffset, retryCount - 1), backoffTime);
            } else {
                throw error;
            }
        }
    }

    // Start copying data
    copyDataWithRetries(byteOffset, retries);

    return outputBuffer.toString(encoding);
}
