            ue_contexts[i]->qos_params = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
}

void update_ue_context(int ue_id, int rrc_state, int *active_bearers, size_t bearer_count) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] != NULL && ue_contexts[i]->ue_id == ue_id) {
            ue_contexts[i]->rrc_state = rrc_state;
            free(ue_contexts[i]->active_bearers);
            ue_contexts[i]->active_bearers = (int *)malloc(bearer_count * sizeof(int));
            memcpy(ue_contexts[i]->active_bearers, active_bearers, bearer_count * sizeof(int));
            ue_contexts[i]->bearer_count = bearer_count;
            time(&ue_contexts[i]->connection_history[0]);
            memmove(&ue_contexts[i]->connection_history[1], &ue_contexts[i]->connection_history[2], (30 - 2) * sizeof(time_t));
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
}

void free_ue_context(int ue_id) {
