pthread_cond_t ue_cond = PTHREAD_COND_INITIALIZER;

void init_ue_context(int ue_id, int rrc_state) {
    pthread_mutex_lock(&ue_mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] == NULL) {
            ue_contexts[i] = malloc(sizeof(LTE_UE_Context));
            ue_contexts[i]->ue_id = ue_id;
            ue_contexts[i]->rrc_state = rrc_state;
            memset(ue_contexts[i]->active_bearers, 0, sizeof(int) * MAX_BEARERS_PER_UE);
            memset(ue_contexts[i]->connection_history, 0, sizeof(time_t) * MAX_CONNECTION_HISTORY);
            memset(ue_contexts[i]->qos_parameters, 0, sizeof(int) * 5);
            pthread_cond_signal(&ue_cond);
            pthread_mutex_unlock(&ue_mutex);
            return;
        }
    }
    pthread_mutex_unlock(&ue_mutex);
}

void update_ue_context(int ue_id, int new_rrc_state, int bearer_id) {
    pthread_mutex_lock(&ue_mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] != NULL && ue_contexts[i]->ue_id == ue_id) {
            ue_contexts[i]->rrc_state = new_rrc_state;
            for (int j = 0; j < MAX_BEARERS_PER_UE; j++) {
                if (ue_contexts[i]->active_bearers[j] == bearer_id) {
                    break;
                }
                if (j == 0) {
                    memmove(ue_contexts[i]->active_bearers + 1, ue_contexts[i]->active_bearers, sizeof(int) * MAX_BEARERS_PER_UE);
                }
                ue_contexts[i]->active_bearers[j] = bearer_id;
                break;
            }
            time(&ue_contexts[i]->connection_history[0]);
            memmove(ue_contexts[i]->connection_history + 1, ue_contexts[i]->connection_history, sizeof(time_t) * MAX_CONNECTION_HISTORY);
            pthread_cond_signal(&ue_cond);
            pthread_mutex_unlock(&ue_mutex);
            return;
        }
    }
    pthread_mutex_unlock(&ue_mutex);
}

void free_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] != NULL && ue_contexts[i]->ue_id == ue_id) {
            free(ue_contexts[i]);
            ue_contexts[i] = NULL;
            pthread_cond_signal(&ue_cond);
            pthread_mutex_unlock(&ue_mutex);
            return;
        }
    }
    pthread_mutex_unlock(&ue_mutex);
}

