#include <string.h>
#include <time.h>

#define MAX_UE_CONTEXTS 1000
#define RRC_MAX_BEARERS 5
#define HISTORY_RETENTION_DAYS 30

typedef struct {
    int ue_id;
    int rrc_state;
    int active_bearers[RRC_MAX_BEARERS];
    time_t connection_history[HISTORY_RETENTION_DAYS];
    float qos_params[HISTORY_RETENTION_DAYS][2]; // [latency, throughput]
} LTE_UE_Context;

LTE_UE_Context* ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t mutex;
int next_id = 0;

void init_ue_context() {
    pthread_mutex_init(&mutex, NULL);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        ue_contexts[i] = NULL;
    }
}

LTE_UE_Context* create_ue_context(int rrc_state) {
    pthread_mutex_lock(&mutex);
    LTE_UE_Context* context = malloc(sizeof(LTE_UE_Context));
    if (context == NULL) return NULL;
    memset(context, 0, sizeof(LTE_UE_Context));
    context->ue_id = next_id++;
    context->rrc_state = rrc_state;
    pthread_mutex_unlock(&mutex);
    return context;
}

void update_ue_context(int ue_id, int rrc_state, int* bearers, int bearer_count) {
    pthread_mutex_lock(&mutex);
    LTE_UE_Context* context = ue_contexts[ue_id];
    if (context == NULL) {
        context = create_ue_context(rrc_state);
        ue_contexts[ue_id] = context;
    } else {
        context->rrc_state = rrc_state;
        memcpy(context->active_bearers, bearers, bearer_count * sizeof(int));
    }
    pthread_mutex_unlock(&mutex);
}

void purge_old_entries() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] != NULL) {
            time_t now = time(NULL);
            int days_since_last_connection = difftime(now, ue_contexts[i]->connection_history[0]) / (24 * 3600);
            if (days_since_last_connection > HISTORY_RETENTION_DAYS) {
                free(ue_contexts[i]);
                ue_contexts[i] = NULL;
            }
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* lru_purger(void* arg) {
    while (1) {
        purge_old_entries();
        sleep(24 * 3600); // Purge every day
    }
}
