    struct ResourceInfo {
        std::string id;
        bool isAllocated;
        std::vector<std::string> profiles;
    };

    void addResource(const std::string& id, const std::vector<std::string>& profiles) {
        std::lock_guard<std::mutex> lock(mutex_);
        resources_[id] = {id, false, profiles};
    }

    bool allocateResource(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (resources_.find(id) == resources_.end()) return false;
        if (resources_[id].isAllocated) return false;

        // Simulate allocation logic
        resources_[id].isAllocated = true;
        return true;
    }

    void deallocateResource(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (resources_.find(id) == resources_.end()) return;
        if (!resources_[id].isAllocated) return;

        // Simulate deallocation logic
        resources_[id].isAllocated = false;
    }

private:
    std::map<std::string, ResourceInfo> resources_;
    std::mutex mutex_;
};
