// Function to calculate average of last two fields in a line
double calculate_average(char *line) {
    double field1 = 0, field2 = 0;
    char *token = strtok(line, " ");
    int count = 0;
    while (token != NULL) {
        if (count == 3 || count == 4) { // Assuming last two fields are the ones to average
            if (sscanf(token, "%lf", &field2) == 1) {
                if (count == 3)
                    field1 = field2;
            } else {
                field2 = 0; // Treat missing values as zero
            }
        }
        token = strtok(NULL, " ");
        count++;
    }
    return (field1 + field2) / 2;
}

// Function to process text file line by line
void *process_text_file(void *file_path) {
    FILE *file = fopen((char*)file_path, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        printf("%s,%f\n", line, calculate_average(line));
    }

    free(line);
    fclose(file);
    return NULL;
}

// Function to get EVP_CIPHER structure for chosen cipher
EVP_CIPHER *get_cipher(char *cipher_name) {
    if (strcmp(cipher_name, "ECB") == 0)
        return EVP_aes_128_ecb();
    else if (strcmp(cipher_name, "EDE") == 0)
        return EVP_aes_128_cbc();
    else if (strcmp(cipher_name, "EDE3") == 0)
        return EVP_aes_192_cbc();
    else if (strcmp(cipher_name, "CFB") == 0)
        return EVP_aes_256_cfb();
    else
        return NULL; // Null encryption for testing purposes
}

// Function to perform cryptographic operations in parallel
void *perform_crypto_operations(void *args) {
    struct crypto_args {
        char *file_path;
        char *cipher_name;
    } *crypto_args = (struct crypto_args *)args;

    EVP_CIPHER *cipher = get_cipher(crypto_args->cipher_name);
    if (cipher == NULL) {
        fprintf(stderr, "Invalid cipher name\n");
        return NULL;
    }

    // Perform cryptographic operations here
    // ...

    free(crypto_args);
    return NULL;
}

// Main function to demonstrate text processing and cryptographic operations
int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <text_file> <cipher_name> <crypto_file>\n", argv[0]);
        return 1;
    }

    pthread_t text_thread;
    if (pthread_create(&text_thread, NULL, process_text_file, argv[1]) != 0) {
        perror("Failed to create text processing thread");
        return 1;
    }

    struct crypto_args *crypto_args = malloc(sizeof(struct crypto_args));
    crypto_args->file_path = argv[3];
    crypto_args->cipher_name = argv[2];

    pthread_t crypto_thread;
    if (pthread_create(&crypto_thread, NULL, perform_crypto_operations, crypto_args) != 0) {
        perror("Failed to create cryptographic operations thread");
        free(crypto_args);
        return 1;
    }

    pthread_join(text_thread, NULL);
    pthread_join(crypto_thread, NULL);

    return 0;
}
