#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size = 0;
    da->capacity = INITIAL_CAPACITY;
    return da;
}

void freeDynamicArray(DynamicArray *da) {
    free(da->array);
    free(da);
}

int isRNTIUnique(DynamicArray *da, int RNTI) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == RNTI) return 0;
    }
    return 1;
}

void addElementToDynamicArray(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    if (da->size >= da->capacity) {
        da->capacity *= 2;
        da->array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    da->array[da->size++] = element;
}

void removeElementFromDynamicArray(DynamicArray *da, int RNTI) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == RNTI) {
            for (size_t j = i; j < da->size - 1; ++j) {
                da->array[j] = da->array[j + 1];
            }
            --da->size;
            return;
        }
    }
}

void iterateDynamicArray(DynamicArray *da, void (*operation)(NFAPI_CRC_INDICATION_PDU_T *)) {
    for (size_t i = 0; i < da->size; ++i) {
        operation(&da->array[i]);
    }
}

void printElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           element->RX_UE_INFORMATION_TAG, element->RNTI, element->CRC_INDICATION_REL8_TAG, element->CRCFLAG);
}

int main() {
    srand(time(NULL));
    DynamicArray *da = createDynamicArray();

    NFAPI_CRC_INDICATION_PDU_T newElement;
    for (size_t i = 0; i < 20; ++i) {
        do {
            newElement.RX_UE_INFORMATION_TAG = rand() % 1000;
            newElement.RNTI = rand() % 1000;
            newElement.CRC_INDICATION_REL8_TAG = rand() % 1000;
            newElement.CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        } while (!isRNTIUnique(da, newElement.RNTI));
        addElementToDynamicArray(da, newElement);
    }

    iterateDynamicArray(da, printElement);

    removeElementFromDynamicArray(da, 500); // Example removal

    iterateDynamicArray(da, printElement);

    freeDynamicArray(da);
    return 0;
}
