    size_t capacity;
    size_t size;
    size_t activeRetransmissions;
} CRCArray;

void initCRCArray(CRCArray *crcArray, size_t initialCapacity) {
    crcArray->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crcArray->capacity = initialCapacity;
    crcArray->size = 0;
    crcArray->activeRetransmissions = 0;
}

void addCRCIndication(CRCArray *crcArray) {
    if (crcArray->size >= crcArray->capacity) {
        crcArray->capacity *= 2;
        crcArray->array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crcArray->array, crcArray->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Generate unique RNTI and random CRCFLAG
    unsigned short rnti;
    do {
        rnti = rand() % 65536; // Assuming valid range for RNTI
    } while (isRNTIUsed(crcArray, rnti));

    NFAPI_CRC_INDICATION_PDU_T newIndication;
    newIndication.RX_UE_INFORMATION_TAG = generateRXUETag();
    newIndication.RNTI = rnti;
    newIndication.CRCFLAG = rand() % 256;

    crcArray->array[crcArray->size++] = newIndication;
    updateActiveRetransmissions(crcArray);
}

int removeCRCIndicationByRNTI(CRCArray *crcArray, unsigned short rnti) {
    for (size_t i = 0; i < crcArray->size; ++i) {
        if (crcArray->array[i].RNTI == rnti) {
            for (size_t j = i + 1; j < crcArray->size; ++j) {
                crcArray->array[j - 1] = crcArray->array[j];
            }
            --crcArray->size;
            updateActiveRetransmissions(crcArray);
            return 0; // Removed successfully
        }
    }
    return -1; // RNTI not found
}

void iterateCRCArray(CRCArray *crcArray, void (*operation)(NFAPI_CRC_INDICATION_PDU_T *)) {
