        ctx->active_bearers = NULL;
        ctx->bearer_count = 0;
        memset(ctx->connection_history, 0, sizeof(ctx->connection_history));
        memset(ctx->qos_parameters, 0, sizeof(ctx->qos_parameters));
    }
    pthread_mutex_unlock(&regions[region_id].mutex);
