Session sessions[MAX_SESSIONS];

pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;
int session_count = 0;

void* handle_session_update(void* arg) {
    char* session_id = (char*)arg;
    // Simulate session update logic
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i].session_id, session_id) == 0) {
            sessions[i].last_activity = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return NULL;
}

void update_session(const char* session_id) {
