#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define MAX_RESOURCES 100

typedef struct {
    int id;
} RX_UE_INFORMATION_TAG;

typedef struct {
    u_int16_t rnti;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    NFAPI_CRC_INDICATION_PDU_T crc_indication_pdu;
} CRC_DATA;

sem_t resource_sem;
pthread_mutex_t pool_mutex;
CRC_DATA *resource_pool[MAX_RESOURCES];
int pool_size = 0;

void init_resource_pool(int num_resources) {
    sem_init(&resource_sem, 0, num_resources);
    pthread_mutex_init(&pool_mutex, NULL);
}

void* allocate_resource(void* arg) {
    CRC_DATA *data = malloc(sizeof(CRC_DATA));
    data->ue_info_tag.id = rand();
    data->crc_indication_pdu.rnti = (u_int16_t)(rand() % 65536);
    sem_wait(&resource_sem);
    pthread_mutex_lock(&pool_mutex);
    resource_pool[pool_size++] = data;
    pthread_mutex_unlock(&pool_mutex);
    return data;
}

void deallocate_resource(void* data) {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < pool_size; i++) {
        if (resource_pool[i] == data) {
            resource_pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    sem_post(&resource_sem);
    free(data);
}

void* dns_resolution(char* hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    u_long ip = ipv4->sin_addr.s_addr;

    memcpy(ip_address, &ip, sizeof(u_char) * 4);

    freeaddrinfo(res);
    return ip_address;
}

void cleanup_resource_pool() {
    sem_destroy(&resource_sem);
    pthread_mutex_destroy(&pool_mutex);
    for (int i = 0; i < pool_size; i++) {
        if (resource_pool[i]) {
            free(resource_pool[i]);
        }
    }
}
