#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>

#define MAX_LOG_SIZE 1024

typedef struct {
    char message[MAX_LOG_SIZE];
} LogMessage;

typedef struct {
    LogMessage *buffer;
    int head, tail;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full, not_empty;
    bool running;
} LoggingSystem;

void init_logging(LoggingSystem *ls, int capacity) {
    ls->capacity = capacity;
    ls->buffer = (LogMessage *)malloc(capacity * sizeof(LogMessage));
    ls->head = 0;
    ls->tail = 0;
    pthread_mutex_init(&ls->mutex, NULL);
    pthread_cond_init(&ls->not_full, NULL);
    pthread_cond_init(&ls->not_empty, NULL);
    ls->running = true;
}

void enqueue_log(LoggingSystem *ls, const char *message) {
    pthread_mutex_lock(&ls->mutex);
    while ((ls->tail + 1) % ls->capacity == ls->head && ls->running) {
        pthread_cond_wait(&ls->not_full, &ls->mutex);
    }
    if (!ls->running) {
        pthread_mutex_unlock(&ls->mutex);
        return;
    }
    strncpy(ls->buffer[ls->tail].message, message, MAX_LOG_SIZE - 1);
    ls->buffer[ls->tail].message[MAX_LOG_SIZE - 1] = '\0';
    ls->tail = (ls->tail + 1) % ls->capacity;
    pthread_cond_signal(&ls->not_empty);
    pthread_mutex_unlock(&ls->mutex);
}

void dequeue_log(LoggingSystem *ls, char *output) {
    pthread_mutex_lock(&ls->mutex);
    while (ls->head == ls->tail && ls->running) {
        pthread_cond_wait(&ls->not_empty, &ls->mutex);
    }
    if (!ls->running) {
        pthread_mutex_unlock(&ls->mutex);
        return;
    }
    strncpy(output, ls->buffer[ls->head].message, MAX_LOG_SIZE - 1);
    output[MAX_LOG_SIZE - 1] = '\0';
    ls->head = (ls->head + 1) % ls->capacity;
    pthread_cond_signal(&ls->not_full);
    pthread_mutex_unlock(&ls->mutex);
}

void stop_logging(LoggingSystem *ls) {
    pthread_mutex_lock(&ls->mutex);
    ls->running = false;
    pthread_cond_broadcast(&ls->not_empty);
    pthread_cond_broadcast(&ls->not_full);
    pthread_mutex_unlock(&ls->mutex);
}

void destroy_logging(LoggingSystem *ls) {
    stop_logging(ls);
    free(ls->buffer);
    pthread_mutex_destroy(&ls->mutex);
    pthread_cond_destroy(&ls->not_full);
    pthread_cond_destroy(&ls->not_empty);
}
