class UeContext {
public:
    int ueId;
    std::string rrcState;
    std::list<int> radioBearers;
    // Add more fields as needed
};

class UeContextManager {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<UeContext> queue_;
    std::unordered_map<int, UeContext> contextMap_;

public:
    void addUeContext(const UeContext& context) {
        std::lock_guard<std::mutex> lock(mutex_);
        contextMap_[context.ueId] = context;
        cv_.notify_one();
    }

    UeContext getUeContext(int ueId) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this, ueId]{ return contextMap_.find(ueId) != contextMap_.end(); });
        return contextMap_[ueId];
    }
};

class SandeshClient : public boost::asio::io_service {
private:
    std::unordered_map<std::string, boost::function<void()>> requestHandlers_;
    std::mutex mutex_;

public:
    void registerRequestHandler(const std::string& protocol, const boost::function<void()>& handler) {
        std::lock_guard<std::mutex> lock(mutex_);
        requestHandlers_[protocol] = handler;
    }

    void handleRequest(const std::string& protocol) {
        if (requestHandlers_.find(protocol) != requestHandlers_.end()) {
            requestHandlers_[protocol]();
        }
    }
};

