    const size_t arraySize = 10;

    long* offsets;
    int* keys;
    Record* records;

    // Initialize random seed
    srand(time(0));

    // Initialize arrays
    initArrays(&offsets, &keys, &records, arraySize);

    for (size_t i = 0; i < arraySize; ++i) {
        startService();
        sleep(rand() % 5 + 1); // Random delay between 1 and 5 seconds

        stopServiceAndSendMessage(offsets[i], keys[i]);
        sendMessage("Service stopped.");

        sleep(rand() % 3 + 2); // Random delay between 2 and 4 seconds
    }

    // Clean up memory
    delete[] offsets;
    delete[] keys;
    delete[] records;

    return 0;
}
