double calculate_average(int *array, int size) {
    if (size == 0) {
        return 0.0;
    }
    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    return (double)sum / size;
}

int main() {
    int array[1000];
    int count = 0;
    char input[256];

    while (fgets(input, sizeof(input), stdin)) {
        if (sscanf(input, "%d", &array[count]) == 1) {
            count++;
            if (count >= 1000) break;
        } else {
            printf("Invalid input. Please enter an integer.\n");
        }
    }

    double average = calculate_average(array, count);
    printf("Average: %.2f\n", average);

    return 0;
}
