using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class MessageBrokerClient
{
    private HttpClient _httpClient;
    private ILogger _logger;
    private string _messageBrokerUrl;

    public MessageBrokerClient(string messageBrokerUrl, ILogger logger)
    {
        _messageBrokerUrl = messageBrokerUrl;
        _logger = logger;
        _httpClient = new HttpClient();
    }

    public async Task<string> SendMessageAsync(string jsonPayload)
    {
        try
        {
            _logger.Log("Serialization started", LogLevel.Debug);
            byte[] payloadBytes = Encoding.UTF8.GetBytes(jsonPayload);
            _logger.Log("Serialization completed", LogLevel.Debug);

            _logger.Log($"Sending message to {_messageBrokerUrl}", LogLevel.Information);
            HttpResponseMessage response = await _httpClient.PostAsync(_messageBrokerUrl, new ByteArrayContent(payloadBytes));
            string acknowledgmentToken = await response.Content.ReadAsStringAsync();
            _logger.Log("Message sent successfully", LogLevel.Information);

            return acknowledgmentToken;
        }
        catch (Exception ex)
        {
            _logger.Log($"Failed to send message: {ex.Message}", LogLevel.Error);
            throw;
        }
    }

    public async Task RetrySendMessageAsync(string jsonPayload, int maxRetries = 3)
    {
        for (int attempt = 1; attempt <= maxRetries; attempt++)
        {
            try
            {
                string acknowledgmentToken = await SendMessageAsync(jsonPayload);
                return acknowledgmentToken;
            }
            catch (Exception ex)
            {
                if (attempt == maxRetries)
                {
                    throw;
                }

                _logger.Log($"Retry {attempt} failed, retrying...", LogLevel.Warning);
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt))); // Exponential backoff
            }
        }
    }
}

public interface ILogger
{
    void Log(string message, LogLevel level);
}

public enum LogLevel
{
    Debug,
    Information,
    Warning,
    Error
}
