#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RESOURCES 10

typedef struct {
    int resource_count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ResourcePool;

void initialize_pool(ResourcePool *pool, int count) {
    pool->resource_count = count;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->not_full, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
}

void allocate_resource(ResourcePool *pool) {
    pthread_mutex_lock(&pool->lock);
    while (pool->resource_count <= 0) {
        pthread_cond_wait(&pool->not_full, &pool->lock);
    }
    pool->resource_count--;
    pthread_cond_signal(&pool->not_empty);
    pthread_mutex_unlock(&pool->lock);
}

void deallocate_resource(ResourcePool *pool) {
    pthread_mutex_lock(&pool->lock);
    while (pool->resource_count >= MAX_RESOURCES) {
        pthread_cond_wait(&pool->not_empty, &pool->lock);
    }
    pool->resource_count++;
    pthread_cond_signal(&pool->not_full);
    pthread_mutex_unlock(&pool->lock);
}

void *thread_function(void *arg) {
    ResourcePool *pool = (ResourcePool *)arg;
    allocate_resource(pool);
    // Perform resource-intensive task here
    deallocate_resource(pool);
    return NULL;
}

int main() {
    ResourcePool pool;
    initialize_pool(&pool, 5);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, &pool);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
