        std::lock_guard<std::mutex> lock(mutex_);
        if (services_.find(id) != services_.end()) return false;

        void* handle = dlopen(libraryPath.c_str(), RTLD_LAZY);
        if (!handle) {
            std::cerr << "Failed to load library: " << dlerror() << std::endl;
            return false;
        }

        ServiceFunction func = reinterpret_cast<ServiceFunction>(dlsym(handle, "service_function"));
        if (!func) {
            std::cerr << "Failed to find service function: " << dlerror() << std::endl;
            dlclose(handle);
            return false;
        }

        services_[id] = std::unique_ptr<ServiceFunction, ServiceDeleter>(new ServiceFunction(func), ServiceDeleter());
        return true;
    }

    void unloadService(const ServiceID& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        services_.erase(id);
    }

    void unloadAllServices() {
        std::lock_guard<std::mutex> lock(mutex_);
        services_.clear();
    }

    bool invokeService(const ServiceID& id) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = services_.find(id);
        if (it == services_.end()) return false;

        (*it->second)();
        return true;
    }

private:
    std::map<ServiceID, std::unique_ptr<ServiceFunction, ServiceDeleter>> services_;
    mutable std::mutex mutex_;
};
