#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_TASKS 1024
#define TASK_FILE "tasks.json"

typedef struct {
    char description[256];
} Task;

Task task_list[MAX_TASKS];
int task_count = 0;
pthread_mutex_t task_lock;

void load_tasks_from_file() {
    FILE *file = fopen(TASK_FILE, "r");
    if (file == NULL) {
        perror("Failed to open tasks file for reading");
        return;
    }
    // Deserialize JSON from file into task_list
    fclose(file);
}

void save_tasks_to_file() {
    FILE *file = fopen(TASK_FILE, "w");
    if (file == NULL) {
        perror("Failed to open tasks file for writing");
        return;
    }
    // Serialize task_list to JSON and write to file
    fclose(file);
}

void add_task(const char *description) {
    pthread_mutex_lock(&task_lock);
    if (task_count < MAX_TASKS) {
        strcpy(task_list[task_count].description, description);
        task_count++;
        save_tasks_to_file();
    } else {
        fprintf(stderr, "Task list is full\n");
    }
    pthread_mutex_unlock(&task_lock);
}

void remove_task(int index) {
    pthread_mutex_lock(&task_lock);
    if (index >= 0 && index < task_count) {
        for (int i = index; i < task_count - 1; i++) {
            strcpy(task_list[i].description, task_list[i + 1].description);
        }
        task_count--;
        save_tasks_to_file();
    } else {
        fprintf(stderr, "Invalid task index\n");
    }
    pthread_mutex_unlock(&task_lock);
}

void list_tasks() {
    pthread_mutex_lock(&task_lock);
    for (int i = 0; i < task_count; i++) {
        printf("%d: %s\n", i, task_list[i].description);
    }
    pthread_mutex_unlock(&task_lock);
}

void show_help() {
    printf("Usage: task_manager [options]\n");
    printf("Options:\n");
    printf("  -l --list\tList all tasks\n");
    printf("  -a --add <description>\tAdd a new task\n");
    printf("  -r --remove <index>\tRemove a task by index\n");
    printf("  -h --help\tShow this help message\n");
}

int main(int argc, char *argv[]) {
    pthread_mutex_init(&task_lock, NULL);
    load_tasks_from_file();

    if (argc == 1) {
        show_help();
        return 0;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--list") == 0 || strcmp(argv[i], "-l") == 0) {
            list_tasks();
        } else if (strcmp(argv[i], "--add") == 0 || strcmp(argv[i], "-a") == 0) {
            if (i + 1 < argc) {
                add_task(argv[i + 1]);
                i++;
            } else {
                fprintf(stderr, "Missing task description for --add option\n");
            }
        } else if (strcmp(argv[i], "--remove") == 0 || strcmp(argv[i], "-r") == 0) {
            if (i + 1 < argc && atoi(argv[i + 1]) >= 0) {
                remove_task(atoi(argv[i + 1]));
                i++;
            } else {
                fprintf(stderr, "Invalid index for --remove option\n");
            }
        } else if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            show_help();
            return 0;
        } else {
            fprintf(stderr, "Unknown option: %s\n", argv[i]);
        }
    }

    pthread_mutex_destroy(&task_lock);
    return 0;
}
