#define MAX_CONCURRENT_REQUESTS 100
#define CACHE_SIZE 1024

typedef struct {
    char hostname[NI_MAXHOST];
    struct in_addr ip;
    time_t last_accessed;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_index = 0;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cache_cv = PTHREAD_COND_INITIALIZER;

void init_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        memset(&cache[i], 0, sizeof(CacheEntry));
    }
}

void* resolve_hostname(void* arg) {
    char* hostname = (char*)arg;
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];
    u_char ip_addr[sizeof(struct in_addr)];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return (void*)-1;
    }

    for(p = res;p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        memcpy(ip_addr, addr, sizeof(struct in_addr));
        freeaddrinfo(res); // all done with this structure
        return (void*)ip_addr;
    }

    freeaddrinfo(res); // if we got here, something went wrong
    return (void*)-1;
}

int main() {
    init_cache();
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    char* hostnames[] = {"www.google.com", "nonexistentdomain.com", "example.com"};
    int num_hostnames = sizeof(hostnames) / sizeof(hostnames[0]);

    for (int i = 0; i < num_hostnames; i++) {
        pthread_create(&threads[i], NULL, resolve_hostname, hostnames[i]);
    }

    for (int i = 0; i < num_hostnames; i++) {
        void* result;
        pthread_join(threads[i], &result);
        if ((long)result != -1) {
            printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr*)result));
            free(result);
        } else {
            printf("Failed to resolve hostname.\n");
        }
    }

    return 0;
}
