#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define RRC_STATE_CONNECTED 0
#define RRC_STATE_DISCONNECTED 1
#define MAX_BEARERS 10

typedef struct LTE_UE_Context {
    int ue_id;
    int rrc_state;
    int bearer_ids[MAX_BEARERS];
    int num_bearers;
    time_t connection_history[30];
    int qos_parameters[30];
} LTE_UE_Context;

LTE_UE_Context** ue_contexts = NULL;
int max_ue_count = 1024;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_ue_contexts(int initial_size) {
    max_ue_count = initial_size;
    ue_contexts = (LTE_UE_Context**)malloc(max_ue_count * sizeof(LTE_UE_Context*));
    for (int i = 0; i < max_ue_count; i++) {
        ue_contexts[i] = NULL;
    }
}

LTE_UE_Context* get_or_create_ue_context(int ue_id) {
    pthread_mutex_lock(&mutex);
    if (ue_id >= max_ue_count || ue_contexts[ue_id] == NULL) {
        if (ue_id >= max_ue_count) {
            int new_size = max_ue_count * 2;
            init_ue_contexts(new_size);
        }
        ue_contexts[ue_id] = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
        ue_contexts[ue_id]->ue_id = ue_id;
        ue_contexts[ue_id]->rrc_state = RRC_STATE_DISCONNECTED;
        ue_contexts[ue_id]->num_bearers = 0;
        time_t current_time = time(NULL);
        for (int i = 0; i < 30; i++) {
            ue_contexts[ue_id]->connection_history[i] = current_time - (24 * 60 * 60) * (i + 1);
            ue_contexts[ue_id]->qos_parameters[i] = 0;
        }
    }
    LTE_UE_Context* context = ue_contexts[ue_id];
    pthread_mutex_unlock(&mutex);
    return context;
}

void update_ue_context(int ue_id, int rrc_state, int bearer_ids[], int num_bearers) {
    LTE_UE_Context* context = get_or_create_ue_context(ue_id);
    pthread_mutex_lock(&context->mutex);
    context->rrc_state = rrc_state;
    for (int i = 0; i < num_bearers && i < MAX_BEARERS; i++) {
        context->bearer_ids[i] = bearer_ids[i];
    }
    context->num_bearers = num_bearers;
    pthread_mutex_unlock(&context->mutex);
}

void delete_ue_context(int ue_id) {
    pthread_mutex_lock(&mutex);
    if (ue_id >= 0 && ue_id < max_ue_count && ue_contexts[ue_id] != NULL) {
        free(ue_contexts[ue_id]);
        ue_contexts[ue_id] = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

void handle_put_request(int ue_id, int rrc_state, int bearer_ids[], int num_bearers) {
    update_ue_context(ue_id, rrc_state, bearer_ids, num_bearers);
    printf("PUT request processed for UE ID: %d\n", ue_id);
}

void handle_delete_request(int ue_id) {
    delete_ue_context(ue_id);
    printf("DELETE request processed for UE ID: %d\n", ue_id);
}
```

This code provides a basic structure for managing LTE UE contexts in a multi-threaded environment. It includes functions to initialize, update, and delete UE contexts, as well as handle HTTP PUT and DELETE requests. The `get_or_create_ue_context` function ensures thread-safe creation of new UE contexts and handles dynamic resizing of the context array. The `update_ue_context` and `delete_ue_context` functions manage the state of individual UE contexts, ensuring thread safety using mutexes. The `handle_put_request` and `handle_delete_request` functions provide the interface for processing HTTP requests to update or delete UE contexts. This implementation provides a foundation that can be expanded with additional features such as object pooling, caching strategies, and error handling for external data sources.']

