std::string md5(const std::string& input) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, input.c_str(), input.size());
    MD5_Final(hash, &md5);
    char outputBuffer[33];
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(outputBuffer + (i * 2), "%02x", hash[i]);
    return std::string(outputBuffer);
}

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

void generate_crc_indications_from_binary_file(const char* inputFilePath, const char* outputFilePath, 
                                               time_t startTimestamp, int eventIdStart, int eventIdEnd,
                                               std::vector<int>& statusCodes) {
    std::ifstream inputFile(inputFilePath, std::ios::binary);
    if (!inputFile.is_open()) {
        std::cerr << "Failed to open input file" << std::endl;
        return;
    }

    inputFile.seekg(0, std::ios::end);
    size_t fileSize = inputFile.tellg();
    inputFile.seekg(0, std::ios::beg);

    std::vector<char> buffer(fileSize);
    inputFile.read(buffer.data(), fileSize);
    inputFile.close();

    size_t N = buffer.size() / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (N * sizeof(NFAPI_CRC_INDICATION_PDU_T) != fileSize) {
        std::cerr << "Input file size is not a multiple of the structure size" << std::endl;
        return;
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications(N);

    for (size_t i = 0; i < N; ++i) {
        crcIndications[i].ueInfoTag = generateRandomUeInfoTag();
        crcIndications[i].rnti = generateRandomRNTI(startTimestamp, eventIdStart, eventIdEnd);
        crcIndications[i].crcIndication.crcFlag = generateRandomCrcFlag(statusCodes);
    }

    std::ofstream outputFile(outputFilePath, std::ios::binary);
    if (!outputFile.is_open()) {
        std::cerr << "Failed to open output file" << std::endl;
        return;
    }
    outputFile.write(reinterpret_cast<char*>(crcIndications.data()), N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    outputFile.close();
}

int main() {
    // Example usage
    time_t startTimestamp = time(nullptr);
    int eventIdStart = 100, eventIdEnd = 200;
    std::vector<int> statusCodes = {0, 1, 2};

    generate_crc_indications_from_binary_file("input.bin", "output.bin", startTimestamp, eventIdStart, eventIdEnd, statusCodes);

    return 0;
}
