    if (log_index == 0) {
        // Write the oldest log entries to a file and clear memory
        FILE *file = fopen(LOG_FILE_PATH, "a");
        for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
            fprintf(file, "%s %d\n", log_entries[i].timestamp, log_entries[i].response_code);
        }
        fclose(file);
