import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class DistributedCacheManager {
    private Map<String, CacheService> cacheServices = new HashMap<>();
    private ReadWriteLock lock = new ReentrantReadWriteLock();

    public void registerCacheService(String serviceId, CacheService service) {
        lock.writeLock().lock();
        try {
            if (!cacheServices.containsKey(serviceId)) {
                cacheServices.put(serviceId, service);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public CacheService getCacheService(String serviceId) {
        lock.readLock().lock();
        try {
            return cacheServices.get(serviceId);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void evictCacheService(String serviceId) {
        lock.writeLock().lock();
        try {
            cacheServices.remove(serviceId);
        } finally {
            lock.writeLock().unlock();
        }
    }

    // Custom load balancing strategy implementation
    public CacheService getLoadBalancedService() {
        // Implement your custom load balancing logic here
        return null;
    }

    interface CacheService {
        void put(String key, Object value);
        Object get(String key);
        void remove(String key);
    }
}
