#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t lock;
} PooledArray;

PooledArray* create_pooled_array(size_t initial_capacity) {
    PooledArray* pool = (PooledArray*)malloc(sizeof(PooledArray));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_pooled_array(PooledArray* pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->data);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(PooledArray* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle allocation failure
        }
        pool->data = new_data;
        pool->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->data[pool->size++];
    pdu->RX_UE_INFORMATION_TAG = 0; // Initialize RX_UE_INFORMATION_TAG
    pdu->RNTI = rand() % 65536; // Random RNTI
    pdu->CRC_INDICATION_REL8_TAG = 0; // Initialize CRC_INDICATION_REL8_TAG
    pdu->CRCFLAG = (rand() & 1) ? 1 : 0; // Randomly set CRCFLAG

    pthread_mutex_unlock(&pool->lock);

    return pdu;
}
```

