#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pcap.h>

#define MAX_PACKETS 1000
#define BUFFER_SIZE 65536

typedef struct {
    struct tm timestamp;
    int packet_size;
    char protocol_type[20];
} packet_entry;

void capture_and_process_packets(char *interface, int duration, int *filter_criteria) {
    pcap_t *handle;
    char errbuf[PCAP_ERRBUF_SIZE];
    struct bpf_program fp;
    char filter_exp[] = "ip";
    bpf_u_int32 net;
    packet_entry packets[MAX_PACKETS];
    int packet_count = 0;

    handle = pcap_open_live(interface, BUFFER_SIZE, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", interface, errbuf);
        exit(EXIT_FAILURE);
    }

    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        exit(EXIT_FAILURE);
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        exit(EXIT_FAILURE);
    }

    struct timeval start_time;
    gettimeofday(&start_time, NULL);

    while (packet_count < MAX_PACKETS && difftime(time(NULL), start_time.tv_sec) < duration) {
        struct pcap_pkthdr header;
        const u_char *packet = pcap_next(handle, &header);
        if (packet == NULL) {
            continue;
        }

        struct tm current_time;
        time_t current_timestamp = time(NULL);
        localtime_r(&current_timestamp, &current_time);

        packets[packet_count].timestamp = current_time;
        packets[packet_count].packet_size = header.len;

        // Extract protocol type from packet header
        if (ntohs(*(u_short *)(packet + 12)) == IPPROTO_TCP) {
            strcpy(packets[packet_count].protocol_type, "TCP");
        } else if (ntohs(*(u_short *)(packet + 12)) == IPPROTO_UDP) {
            strcpy(packets[packet_count].protocol_type, "UDP");
        } else {
            strcpy(packets[packet_count].protocol_type, "Other");
        }

        packet_count++;
    }

    pcap_freecode(&fp);
    pcap_close(handle);

    // Process packets based on filter criteria
    for (int i = 0; i < packet_count; i++) {
        if (packets[i].packet_size >= filter_criteria[0] &&
            strcmp(packets[i].protocol_type, filter_criteria[1]) == 0) {
            // Process packet
            printf("Timestamp: %s, Packet Size: %d, Protocol Type: %s\n",
                   asctime(&packets[i].timestamp), packets[i].packet_size,
                   packets[i].protocol_type);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <interface> <duration> <filter_criteria>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *interface = argv[1];
    int duration = atoi(argv[2]);
    int filter_criteria[3] = {atoi(argv[3]), NULL};

    capture_and_process_packets(interface, duration, filter_criteria);

    return EXIT_SUCCESS;
}
```

This code snippet defines a `network_data_collector` program that captures and processes network packets based on specified criteria. It includes a main function to parse command-line arguments and call the `capture_and_process_packets` function. The latter reads packets from a given network interface, filters them according to size and protocol type, and prints relevant details about each packet.']

