    int *array = NULL;
    int count = 0;
    char buffer[256];

    while (fgets(buffer, sizeof(buffer), stdin) != NULL && count < 10000) {
        long num = strtol(buffer, NULL, 10);
        if (*buffer != '\n' && errno == 0) {
            array = realloc(array, (count + 1) * sizeof(int));
            if (array == NULL) {
                printf("Memory allocation failed.\n");
                break;
            }
            array[count++] = num;
        } else {
            fprintf(stderr, "Invalid input. Please enter integers only.\n");
        }
    }

    findAndPrintLargest(array, count);

    free(array);
    return 0;
}
