from Crypto.Cipher import DES, DES3, AES
from Crypto.Util.Padding import pad, unpad

class CipherMode:
    ECB = 'ECB'
    EDE = 'EDE'
    EDE3 = 'EDE3'
    CFB = 'CFB'

class NullCipher:
    def encrypt(self, data):
        return data

    def decrypt(self, data):
        return data

class EVP_CIPHER:
    pass

class CipherFactoryRegistry:
    _registry = {}

    @staticmethod
    def add_factory(id, factory_func):
        CipherFactoryRegistry._registry[id] = factory_func

    @staticmethod
    def create_cipher(id, key):
        if id in CipherFactoryRegistry._registry:
            return CipherFactoryRegistry._registry[id](key)
        else:
            raise ValueError("No cipher factory registered for ID: {}".format(id))

class DesCipher:
    def __init__(self, key):
        self.key = key

    def encrypt(self, data):
        cipher = DES.new(self.key, DES.MODE_ECB)
        return cipher.encrypt(pad(data, DES.block_size))

    def decrypt(self, data):
        cipher = DES.new(self.key, DES.MODE_ECB)
        return unpad(cipher.decrypt(data), DES.block_size)

class Des3Cipher:
    def __init__(self, key):
        self.key = key

    def encrypt(self, data):
        cipher = DES3.new(self.key, DES3.MODE_ECB)
        return cipher.encrypt(pad(data, DES3.block_size))

    def decrypt(self, data):
        cipher = DES3.new(self.key, DES3.MODE_ECB)
        return unpad(cipher.decrypt(data), DES3.block_size)

class AesCipher:
    def __init__(self, key):
        self.key = key

    def encrypt(self, data):
        cipher = AES.new(self.key, AES.MODE_CFB)
        return cipher.encrypt(pad(data, AES.block_size))

    def decrypt(self, data):
        cipher = AES.new(self.key, AES.MODE_CFB)
        return unpad(cipher.decrypt(data), AES.block_size)

# Register factory functions
CipherFactoryRegistry.add_factory(CipherMode.ECB, lambda key: DesCipher(key))
CipherFactoryRegistry.add_factory(CipherMode.EDE, lambda key: Des3Cipher(key))
CipherFactoryRegistry.add_factory(CipherMode.EDE3, lambda key: Des3Cipher(key))
CipherFactoryRegistry.add_factory(CipherMode.CFB, lambda key: AesCipher(key))
