LTEManager lte_manager = { .lock = PTHREAD_MUTEX_INITIALIZER };

void init_lte_manager() {
    pthread_mutex_lock(&lte_manager.lock);
    memset(lte_manager.ue_contexts, 0, sizeof(lte_manager.ue_contexts));
    lte_manager.context_count = 0;
    pthread_mutex_unlock(&lte_manager.lock);
}

int add_ue_context(int ue_id, const char *rrc_state) {
    pthread_mutex_lock(&lte_manager.lock);
    if (lte_manager.context_count >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&lte_manager.lock);
        return -1; // Overflow
    }
    UEContext *new_context = &lte_manager.ue_contexts[lte_manager.context_count++];
    new_context->ue_id = ue_id;
    strncpy(new_context->rrc_state, rrc_state, sizeof(new_context->rrc_state) - 1);
    pthread_mutex_unlock(&lte_manager.lock);
    return 0;
}

