#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_POOL_SIZE 10

typedef struct Connection {
    int id;
    char status[20];
} Connection;

typedef struct Pool {
    int id;
    int pool_size;
    Connection connections[MAX_POOL_SIZE];
    pthread_mutex_t lock;
} Pool;

Pool pools[MAX_POOL_SIZE];
int pool_count = 0;
pthread_mutex_t global_lock;

void init_pool(int id, int size) {
    pthread_mutex_init(&pools[id].lock, NULL);
    pools[id].id = id;
    pools[id].pool_size = size;
    for (int i = 0; i < size; i++) {
        pools[id].connections[i].id = i;
        strcpy(pools[id].connections[i].status, "Available");
    }
}

void *add_connection(void *arg) {
    int pool_id = *(int *)arg;
    pthread_mutex_lock(&pools[pool_id].lock);
    for (int i = 0; i < pools[pool_id].pool_size; i++) {
        if (strcmp(pools[pool_id].connections[i].status, "Available") == 0) {
            strcpy(pools[pool_id].connections[i].status, "In Use");
            printf("Connection %d added to pool %d\n", pools[pool_id].connections[i].id, pools[pool_id].id);
            pthread_mutex_unlock(&pools[pool_id].lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&pools[pool_id].lock);
    printf("Pool %d is full\n", pool_id);
    return NULL;
}

void *remove_connection(void *arg) {
    int pool_id = *(int *)arg;
    pthread_mutex_lock(&pools[pool_id].lock);
    for (int i = 0; i < pools[pool_id].pool_size; i++) {
        if (strcmp(pools[pool_id].connections[i].status, "In Use") == 0) {
            strcpy(pools[pool_id].connections[i].status, "Available");
            printf("Connection %d removed from pool %d\n", pools[pool_id].connections[i].id, pools[pool_id].id);
            pthread_mutex_unlock(&pools[pool_id].lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&pools[pool_id].lock);
    printf("No connection to remove from pool %d\n", pool_id);
    return NULL;
}

int main() {
    int pool_ids[] = {0, 1};
    for (int i = 0; i < sizeof(pool_ids) / sizeof(pool_ids[0]); i++) {
        init_pool(pool_ids[i], MAX_POOL_SIZE);
    }

    pthread_t add_threads[MAX_POOL_SIZE];
    pthread_t remove_threads[MAX_POOL_SIZE];

    for (int i = 0; i < sizeof(pool_ids) / sizeof(pool_ids[0]); i++) {
        pthread_create(&add_threads[i], NULL, add_connection, &pool_ids[i]);
        pthread_create(&remove_threads[i], NULL, remove_connection, &pool_ids[i]);
    }

    for (int i = 0; i < sizeof(pool_ids) / sizeof(pool_ids[0]); i++) {
        pthread_join(add_threads[i], NULL);
        pthread_join(remove_threads[i], NULL);
    }

    return 0;
}
