#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CONCURRENT_REQUESTS 100
#define DNS_SERVER "8.8.8.8"
#define DNS_PORT 53

typedef struct {
    char hostname[256];
    u_char ip_address[4];
} DNSCacheEntry;

DNSCacheEntry cache[MAX_CONCURRENT_REQUESTS];

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int cache_count = 0;

u_char* dns_resolve(const char* hostname) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memcpy(result, cache[i].ip_address, 4);
            pthread_mutex_unlock(&cache_lock);
            return result;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    int sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sockfd < 0) {
        perror("socket");
        return NULL;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, DNS_SERVER, &server_addr.sin_addr);
    server_addr.sin_port = htons(DNS_PORT);

    // Construct DNS query packet
    u_char dns_query[1024];
    memset(dns_query, 0, sizeof(dns_query));
    // Populate the DNS query packet with the hostname

    if (sendto(sockfd, dns_query, sizeof(dns_query), 0, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return NULL;
    }

    u_char response[1024];
    socklen_t server_len = sizeof(server_addr);
    if (recvfrom(sockfd, response, sizeof(response), 0, (struct sockaddr*)&server_addr, &server_len) < 0) {
        perror("recvfrom");
        close(sockfd);
        return NULL;
    }

    // Parse DNS response and extract IP address
    u_char* ip_address = parse_dns_response(response);

    if (ip_address != NULL) {
        pthread_mutex_lock(&cache_lock);
        if (cache_count < MAX_CONCURRENT_REQUESTS) {
            strcpy(cache[cache_count].hostname, hostname);
            memcpy(cache[cache_count].ip_address, ip_address, 4);
            cache_count++;
        }
        pthread_mutex_unlock(&cache_lock);
    }

    close(sockfd);
    return ip_address;
}

void* resolve_task(void* arg) {
    const char* hostname = (const char*)arg;
    u_char* ip_address = dns_resolve(hostname);
    if (ip_address != NULL) {
        printf("Resolved %s to %d.%d.%d.%d\n", hostname, ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    } else {
        printf("Failed to resolve %s\n", hostname);
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    const char* hostnames[] = {"example.com", "google.com", "nonexistentdomain"};

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS && i < sizeof(hostnames) / sizeof(hostnames[0]); i++) {
        if (pthread_create(&threads[i], NULL, resolve_task, (void*)hostnames[i]) != 0) {
            perror("pthread_create");
            break;
        }
    }

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS && i < sizeof(hostnames) / sizeof(hostnames[0]); i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
