    private static final int MAX_THREADS = Runtime.getRuntime().availableProcessors();

    public void parse_and_generate_output(String[] inputFiles, String outputFilePath, boolean verbose, boolean help) {
        if (help) {
            printHelp();
            return;
        }

        List<Future<PacketEntry>> futures = new ArrayList<>();
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

        for (String file : inputFiles) {
            Callable<PacketEntry> task = () -> parsePcapFile(file, 12345); // Example stream ID
            futures.add(executor.submit(task));
        }

        List<PacketEntry> packetEntries = new ArrayList<>();
        try {
            for (Future<PacketEntry> future : futures) {
                packetEntries.add(future.get());
            }
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }

        // Generate and output summary report
        generateReport(packetEntries, outputFilePath, verbose);
    }

