#define LOG_DEBUG 1
#define LOG_INFO 2
#define LOG_WARNING 3
#define LOG_ERROR 4
#define LOG_CRITICAL 5

typedef struct {
    int log_level;
    FILE *log_file;
} LoggerConfig;

LoggerConfig* create_logger(const char *filename, int initial_level) {
    LoggerConfig *config = (LoggerConfig *)malloc(sizeof(LoggerConfig));
    if (!config) {
        return NULL;
    }

    config->log_level = initial_level;
    config->log_file = fopen(filename, "w");
    if (!config->log_file) {
        free(config);
        return NULL;
    }

    return config;
}

void set_log_level(LoggerConfig *config, int level) {
    config->log_level = level;
}

void log_message(LoggerConfig *config, int level, const char *message, ...) {
    va_list args;
    va_start(args, message);

    if (level >= config->log_level) {
        vfprintf(config->log_file, message, args);
        fprintf(config->log_file, "\n");
    }

    va_end(args);
}

void rotate_log_file(LoggerConfig *config, size_t max_size) {
    fseek(config->log_file, 0, SEEK_END);
    long current_size = ftell(config->log_file);

    if (current_size > max_size) {
        fclose(config->log_file);
        char new_filename[256];
        snprintf(new_filename, sizeof(new_filename), "%s.old", "logfile.log");
        rename("logfile.log", new_filename);
        config->log_file = fopen("logfile.log", "w");
    }
}

void free_logger(LoggerConfig *config) {
    if (config->log_file) {
        fclose(config->log_file);
    }
    free(config);
}
