#include <stdlib.h>
#include <stdio.h>

typedef struct {
    // Define your structure members here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    size_t capacity;
    size_t max_size;
    FILE *file_handle;
} CRCList;

void initCRCList(CRCList *list, size_t initial_capacity, size_t max_size, const char *filename) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initial_capacity;
    list->max_size = max_size;
    list->file_handle = fopen(filename, "wb+");
    if (!list->file_handle) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }
}

void addElement(CRCList *list, const NFAPI_CRC_INDICATION_PDU_T *element) {
    if (list->count >= list->max_size) {
        fprintf(stderr, "Maximum size reached\n");
        return;
    }

    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->elements = realloc(list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->elements) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
    }

    list->elements[list->count++] = *element;

    // Serialize the new element to the file
    fwrite(&list->elements[list->count - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, list->file_handle);
}

void serializeList(CRCList *list) {
    // Ensure all elements are serialized before calling this function
    fflush(list->file_handle);
}

size_t getListCount(const CRCList *list) {
    return list->count;
}

void freeCRCList(CRCList *list) {
    free(list->elements);
    fclose(list->file_handle);
}
