    list->list = (UECAP_CQI_INDICATION*)calloc(initial_capacity, sizeof(UECAP_CQI_INDICATION));
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void destroy_cqi_list(UECAP_CQI_LIST *list) {
    free(list->list);
    free(list);
}

int add_cqi_element(UECAP_CQI_LIST *list, int UE_ID, int CQI_REPORT_ID, double CQI_VALUE, double QUALITY_METRIC) {
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        UECAP_CQI_INDICATION *new_list = (UECAP_CQI_INDICATION*)realloc(list->list, new_capacity * sizeof(UECAP_CQI_INDICATION));
        if (!new_list) return -1;
        list->list = new_list;
        list->capacity = new_capacity;
    }

    for (int i = 0; i < list->size; ++i) {
        if (list->list[i].UE_ID == UE_ID) {
            return -2; // Duplicate UE_ID
        }
    }

    list->list[list->size].UE_ID = UE_ID;
    list->list[list->size].CQI_REPORT_ID = CQI_REPORT_ID;
    list->list[list->size].CQI_VALUE = CQI_VALUE;
    list->list[list->size].QUALITY_METRIC = QUALITY_METRIC;
    ++list->size;

    return 0;
}

double compute_weighted_average(UECAP_CQI_LIST *list) {
    double total_value = 0.0, total_metric = 0.0;

    for (int i = 0; i < list->size; ++i) {
        total_value += list->list[i].CQI_VALUE * list->list[i].QUALITY_METRIC;
        total_metric += list->list[i].QUALITY_METRIC;
    }

    return total_metric > 0 ? total_value / total_metric : 0.0;
}

void scale_quality_metrics(UECAP_CQI_LIST *list, double load_factor) {
    for (int i = 0; i < list->size; ++i) {
        list->list[i].QUALITY_METRIC *= load_factor;
    }
