#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CACHE_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t lastAccessTime;
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

typedef struct {
    CacheNode* head;
    CacheNode* tail;
    int size;
    int hits;
    int misses;
} LRUCache;

LRUCache* createCache() {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    if (!cache) return NULL;
    cache->head = cache->tail = NULL;
    cache->size = 0;
    cache->hits = cache->misses = 0;
    return cache;
}

void insertCache(LRUCache* cache, NFAPI_CRC_INDICATION_PDU_T data) {
    CacheNode* newNode = (CacheNode*)malloc(sizeof(CacheNode));
    if (!newNode) return;

    newNode->data = data;
    newNode->lastAccessTime = time(NULL);
    newNode->next = NULL;
    newNode->prev = cache->tail;

    if (cache->size == MAX_CACHE_SIZE) {
        CacheNode* temp = cache->head;
        cache->head = cache->head->next;
        if (cache->head) cache->head->prev = NULL;
        else cache->tail = NULL;
        free(temp);
        cache->size--;
    }

    if (cache->tail) cache->tail->next = newNode;
    else cache->head = newNode;

    cache->tail = newNode;
    cache->size++;
}

void removeCache(LRUCache* cache, CacheNode* node) {
    if (!node || !cache) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (node == cache->head) cache->head = node->next;
    if (node == cache->tail) cache->tail = node->prev;

    free(node);
    cache->size--;
}

void updateCacheAccess(LRUCache* cache, CacheNode* node) {
    if (!node || !cache || node == cache->tail) return;
    removeCache(cache, node);
    insertCache(cache, node->data);
}

int getCacheSize(LRUCache* cache) {
    return cache->size;
}

void logLRUStatistics(LRUCache* cache, const char* filename) {
    FILE* logFile = fopen(filename, "a");
    if (!logFile) return;

    time_t now = time(NULL);
    fprintf(logFile, "Time: %s, Hits: %d, Misses: %d\n", ctime(&now), cache->hits, cache->misses);

    fclose(logFile);
}
