void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == nullptr) {
        std::cerr << "Memory allocation failed" << std::endl;
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, record** records, size_t size, int min_val, int max_val) {
    *offsets = static_cast<long*>(allocate_memory(size * sizeof(long)));
    *keys = static_cast<int*>(allocate_memory(size * sizeof(int)));
    *records = static_cast<record*>(allocate_memory(size * sizeof(record)));

    for (size_t i = 0; i < size; ++i) {
        (*keys)[i] = rand() % (max_val - min_val + 1) + min_val;
        (*records)[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void simulate_service(std::vector<record>& record_list, int offset_index, long* offsets, int* keys, size_t size, double average_delay) {
    while (true) {
        // Simulate service processing
        for (size_t i = 0; i < size; ++i) {
            record_list[i].value += (*keys)[i];
            offsets[offset_index] += record_list[i].value;
            offset_index = (offset_index + 1) % size;
        }

        // Update moving average delay
        average_delay = (average_delay * 9 + rand() % 10) / 10;

        std::cout << "Service running. Average Delay: " << average_delay << std::endl;
        sleep(static_cast<unsigned int>(average_delay));
    }
}

void send_message(int message_id, const std::string& message) {
    // Simulate sending a message
    std::cout << "Message ID: " << message_id << ", Message: " << message << std::endl;
}

int main() {
    srand(time(0)); // Seed for random number generation

    size_t array_size = 100;
    long* offsets = nullptr;
    int* keys = nullptr;
    record* records = nullptr;

    initialize_arrays(&offsets, &keys, &records, array_size, 0, 100);

    std::vector<record> record_list(records, records + array_size);
    double average_delay = 5.0; // Initial delay

    try {
        simulate_service(record_list, 0, offsets, keys, array_size, average_delay);
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
