#define MAX_CLIENTS 1024
#define MAX_CHANNELS 50

typedef enum {
    WIFI_CHANNEL_2_4G,
    WIFI_CHANNEL_5G,
    WIFI_CHANNEL_6G,
} wifi_channel_t;

