    uint32_t client_id;
    int connection_state;
    wifi_channel_t channels[MAX_CHANNELS];
} wifi_client_t;

wifi_client_t clients[MAX_CLIENTS];
pthread_mutex_t clients_mutex = PTHREAD_MUTEX_INITIALIZER;
int client_count = 0;

void initialize_client(uint32_t client_id, int state) {
    pthread_mutex_lock(&clients_mutex);
    if (client_count < MAX_CLIENTS) {
        clients[client_count].client_id = client_id;
        clients[client_count].connection_state = state;
        for (int i = 0; i < MAX_CHANNELS; i++) {
            clients[client_count].channels[i] = WIFI_CHANNEL_2_4G; // Default channel
        }
        client_count++;
    } else {
        // Handle error: Max clients reached
    }
    pthread_mutex_unlock(&clients_mutex);
}

void update_client_connection(uint32_t client_id, int new_state) {
    pthread_mutex_lock(&clients_mutex);
    for (int i = 0; i < client_count; i++) {
        if (clients[i].client_id == client_id) {
            clients[i].connection_state = new_state;
            break;
        }
    }
    pthread_mutex_unlock(&clients_mutex);
}

void add_client_channel(uint32_t client_id, wifi_channel_t channel) {
    pthread_mutex_lock(&clients_mutex);
    for (int i = 0; i < client_count; i++) {
        if (clients[i].client_id == client_id) {
            for (int j = 0; j < MAX_CHANNELS; j++) {
                if (clients[i].channels[j] == WIFI_CHANNEL_2_4G) {
                    clients[i].channels[j] = channel;
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&clients_mutex);
}

void remove_client_channel(uint32_t client_id, wifi_channel_t channel) {
    pthread_mutex_lock(&clients_mutex);
    for (int i = 0; i < client_count; i++) {
        if (clients[i].client_id == client_id) {
            for (int j = 0; j < MAX_CHANNELS; j++) {
                if (clients[i].channels[j] == channel) {
                    clients[i].channels[j] = WIFI_CHANNEL_2_4G;
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&clients_mutex);
}
