from Crypto.Cipher import DES, DES3, PKCS1_OAEP
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes
import logging
from datetime import datetime

# Set up logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CryptographicOperations:
    class Factory:
        def __init__(self):
            self.registry = {}

        def register(self, id, factory_func):
            self.registry[id] = factory_func

        def create(self, id, *args, **kwargs):
            if id not in self.registry:
                raise ValueError(f"Unsupported cipher mode: {id}")
            return self.registry[id](*args, **kwargs)

    class ECBMode(CryptographicOperations):
        def __init__(self, key):
            self.cipher = DES.new(key, DES.MODE_ECB)
            logging.info(f"ECB Mode created with key: {key}")

        def encrypt(self, data):
            padded_data = pad(data, DES.block_size)
            encrypted_data = self.cipher.encrypt(padded_data)
            return encrypted_data

        def decrypt(self, data):
            decrypted_data = self.cipher.decrypt(data)
            unpadded_data = unpad(decrypted_data, DES.block_size)
            return unpadded_data

    class EDEMode(CryptographicOperations):
        def __init__(self, key):
            if len(key) not in [24]:
                raise ValueError("Invalid key size for EDE mode")
            self.cipher = DES3.new(key, DES3.MODE_EDE)
            logging.info(f"EDE Mode created with key: {key}")

        def encrypt(self, data):
            padded_data = pad(data, DES.block_size)
            encrypted_data = self.cipher.encrypt(padded_data)
            return encrypted_data

        def decrypt(self, data):
            decrypted_data = self.cipher.decrypt(data)
            unpadded_data = unpad(decrypted_data, DES.block_size)
            return unpadded_data

    class EDE3Mode(CryptographicOperations):
        def __init__(self, key):
            if len(key) not in [24, 168]:
                raise ValueError("Invalid key size for EDE3 mode")
            self.cipher = DES3.new(key, DES3.MODE_EDE)
            logging.info(f"EDE3 Mode created with key: {key}")

        def encrypt(self, data):
            padded_data = pad(data, DES.block_size)
            encrypted_data = self.cipher.encrypt(padded_data)
            return encrypted_data

        def decrypt(self, data):
            decrypted_data = self.cipher.decrypt(data)
            unpadded_data = unpad(decrypted_data, DES.block_size)
            return unpadded_data

    class CFBMode(CryptographicOperations):
        def __init__(self, key):
            self.cipher = PKCS1_OAEP.new(DES.new(key, DES.MODE_ECB))
            logging.info(f"CFB Mode created with key: {key}")

        def encrypt(self, data):
            encrypted_data = self.cipher.encrypt(data)
            return encrypted_data

        def decrypt(self, data):
            decrypted_data = self.cipher.decrypt(data)
            return decrypted_data

    class NullEncryption(CryptographicOperations):
        @staticmethod
        def encrypt(data):
            logging.info("Null Encryption: No encryption performed")
            return data

        @staticmethod
        def decrypt(data):
            logging.info("Null Encryption: No decryption performed")
            return data

# Usage example:
factory = CryptographicOperations.Factory()
factory.register('ECB', lambda key: CryptographicOperations.ECBMode(key))
factory.register('EDE', lambda key: CryptographicOperations.EDEMode(key))
factory.register('EDE3', lambda key: CryptographicOperations.EDE3Mode(key))
factory.register('CFB', lambda key: CryptographicOperations.CFBMode(key))
factory.register('NULL', CryptographicOperations.NullEncryption)

cipher_mode = 'ECB'
key = get_random_bytes(8)
crypt = factory.create(cipher_mode, key)
encrypted_data = crypt.encrypt(b'Hello, World!')
decrypted_data = crypt.decrypt(encrypted_data)
print(decrypted_data.decode())
```']

