int manage_external_process(ProcessManager *manager, int max_retries) {
    int retries = 0;
    while (retries < max_retries) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            return 0;
        } else if (pid == 0) {
            // Child process
            setsid(); // Detach from the terminal
            signal(SIGCHLD, handle_signal);
            execvp(manager->command, NULL); // Execute the command
            perror("execvp"); // If execvp fails, it will return here
            exit(1);
        } else {
            // Parent process
            manager->pid = pid;
            // Monitor resource usage and terminate if necessary
            // Clean up temporary files or resources if needed
            int status;
            waitpid(pid, &status, 0); // Wait for the child to finish
            if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                return 1; // Success
            }
        }
        retries++;
    }
    return 0; // Max retries reached
}

