#include <string.h>

// Define the NFAPI_MESSAGE_T structure
typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG *crc_indication;
} NFAPI_MESSAGE_T;

// Define a thread-safe dynamic array with logging and memory management
typedef struct {
    NFAPI_MESSAGE_T **array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
    FILE *log_file;
} DynamicArray;

// Initialize the dynamic array
void init_dynamic_array(DynamicArray *arr, const char *log_filename) {
    arr->array = NULL;
    arr->used = 0;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    arr->log_file = fopen(log_filename, "a");
}

// Free the dynamic array and its elements
void free_dynamic_array(DynamicArray *arr) {
    for (size_t i = 0; i < arr->used; ++i) {
        if (arr->array[i]->crc_indication != NULL) {
            free(arr->array[i]->crc_indication);
        }
        free(arr->array[i]);
    }
    free(arr->array);
    pthread_mutex_destroy(&arr->lock);
    fclose(arr->log_file);
}

// Add a new entry to the dynamic array
int add_entry(DynamicArray *arr, RX_UE_INFORMATION_TAG ue_info, uint16_t RNTI) {
    pthread_mutex_lock(&arr->lock);
    if (arr->used == arr->size) {
        size_t new_size = arr->size > 0 ? arr->size * 2 : 4;
        NFAPI_MESSAGE_T **new_array = realloc(arr->array, new_size * sizeof(NFAPI_MESSAGE_T *));
        if (new_array == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Memory allocation failed
        }
        arr->array = new_array;
        arr->size = new_size;
    }
    NFAPI_MESSAGE_T *new_entry = malloc(sizeof(NFAPI_MESSAGE_T));
    if (new_entry == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Memory allocation failed
    }
    new_entry->ue_info = ue_info;
    new_entry->RNTI = RNTI;
    new_entry->crc_indication = malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (new_entry->crc_indication == NULL) {
        free(new_entry);
        pthread_mutex_unlock(&arr->lock);
        return -1; // Memory allocation failed
    }
    new_entry->crc_indication->CRCFLAG = rand() % 256; // Randomly set CRCFLAG

    arr->array[arr->used++] = new_entry;
    fprintf(arr->log_file, "Added entry at index %zu\n", arr->used - 1);
    pthread_mutex_unlock(&arr->lock);

    return arr->used - 1;
}

// Update an existing entry in the dynamic array
int update_entry(DynamicArray *arr, size_t index, RX_UE_INFORMATION_TAG ue_info) {
    if (index >= arr->used) {
        return -1; // Invalid index
    }

    pthread_mutex_lock(&arr->lock);
    NFAPI_MESSAGE_T *entry = arr->array[index];
    entry->ue_info = ue_info;
    free(entry->crc_indication); // Free the old CRC_INDICATION_REL8_TAG
    entry->crc_indication = malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (entry->crc_indication == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Memory allocation failed
    }
    entry->crc_indication->CRCFLAG = rand() % 256; // Randomly set CRCFLAG

    fprintf(arr->log_file, "Updated entry at index %zu\n", index);
    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Compact the dynamic array to minimize memory usage
void compact_dynamic_array(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);
    NFAPI_MESSAGE_T **new_array = realloc(arr->array, arr->used * sizeof(NFAPI_MESSAGE_T *));
    if (new_array != NULL) {
        arr->array = new_array;
        arr->size = arr->used;
        fprintf(arr->log_file, "Compacted dynamic array to size %zu\n", arr->size);
    }
    pthread_mutex_unlock(&arr->lock);
}

// Custom thread pool for handling incoming operations
typedef struct {
    DynamicArray *dynamic_arr;
    int (*operation)(DynamicArray *, ...);
    va_list args;
    pthread_t *threads;
    size_t num_threads;
    int queue_size;
} ThreadPool;

void *thread_func(void *pool) {
    ThreadPool *tp = (ThreadPool *)pool;
    while (1) {
        // Implement thread pool logic here
    }
}

// Initialize the thread pool
int init_thread_pool(ThreadPool *tp, DynamicArray *dynamic_arr, int (*operation)(DynamicArray *, ...), size_t num_threads, int queue_size) {
    tp->dynamic_arr = dynamic_arr;
    tp->operation = operation;
    tp->args = NULL;
    tp->threads = malloc(num_threads * sizeof(pthread_t));
    if (tp->threads == NULL) {
        return -1; // Memory allocation failed
    }
    tp->num_threads = num_threads;
    tp->queue_size = queue_size;

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&tp->threads[i], NULL, thread_func, tp);
    }

    return 0;
}

// Free the thread pool
void free_thread_pool(ThreadPool *tp) {
    // Implement thread pool cleanup logic here
    free(tp->threads);
}

// Example usage
int main() {
    DynamicArray dynamic_arr;
    init_dynamic_array(&dynamic_arr, "log.txt");

    ThreadPool tp;
    init_thread_pool(&tp, &dynamic_arr, add_entry, 4, 100);

    // Add entries using the thread pool
    for (size_t i = 0; i < 10000; ++i) {
        RX_UE_INFORMATION_TAG ue_info = { /* initialize fields */ };
        update_thread_pool(&tp, &ue_info);
    }

    free_thread_pool(&tp);
    free_dynamic_array(&dynamic_arr);

    return 0;
}
