typedef struct {
    int ue_id;
    char rrc_state[20];
    int *radio_bearers;
    int num_bearers;
} LTE_UE_Context;

typedef struct {
    pthread_mutex_t mutex;
    LTE_UE_Context **contexts;
    int count;
    int capacity;
} UE_Context_Manager;

void init_ue_context_manager(UE_Context_Manager *manager) {
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
    manager->contexts = NULL;
    manager->count = 0;
    manager->capacity = 0;
}

void free_ue_context_manager(UE_Context_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        free(manager->contexts[i]->radio_bearers);
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

LTE_UE_Context* create_ue_context(int ue_id, char *rrc_state, int *bearers, int num_bearers) {
    LTE_UE_Context *ctx = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    ctx->ue_id = ue_id;
    strcpy(ctx->rrc_state, rrc_state);
    ctx->radio_bearers = (int*)malloc(num_bearers * sizeof(int));
    memcpy(ctx->radio_bearers, bearers, num_bearers * sizeof(int));
    ctx->num_bearers = num_bearers;
    return ctx;
}

void add_ue_context(UE_Context_Manager *manager, LTE_UE_Context *ctx) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count == manager->capacity) {
        manager->capacity += 10;
        manager->contexts = (LTE_UE_Context**)realloc(manager->contexts, manager->capacity * sizeof(LTE_UE_Context*));
    }
    manager->contexts[manager->count++] = ctx;
    pthread_mutex_unlock(&manager->mutex);
}

void update_ue_context(UE_Context_Manager *manager, int ue_id, char *rrc_state, int *bearers, int num_bearers) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        if (manager->contexts[i]->ue_id == ue_id) {
            free(manager->contexts[i]->radio_bearers);
            manager->contexts[i]->ue_id = ue_id;
            strcpy(manager->contexts[i]->rrc_state, rrc_state);
            manager->contexts[i]->radio_bearers = (int*)realloc(manager->contexts[i]->radio_bearers, num_bearers * sizeof(int));
            memcpy(manager->contexts[i]->radio_bearers, bearers, num_bearers * sizeof(int));
            manager->contexts[i]->num_bearers = num_bearers;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void remove_ue_context(UE_Context_Manager *manager, int ue_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        if (manager->contexts[i]->ue_id == ue_id) {
            free(manager->contexts[i]->radio_bearers);
            free(manager->contexts[i]);
            for (int j = i; j < manager->count - 1; j++) {
                manager->contexts[j] = manager->contexts[j + 1];
            }
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}
