pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;
int successful_allocations = 0;
clock_t total_time = 0;

void* allocate_memory(size_t N) {
    if (N > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Warning: Requested size exceeds maximum allowed. Truncating request to %d.\n", MAX_ARRAY_SIZE);
        N = MAX_ARRAY_SIZE;
    }

    clock_t start_time = clock();
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < N; i++) {
        pdu_array[i].UE_INFO.RX_UE_INFORMATION_TAG = i + 1;
        pdu_array[i].UE_INFO.RNTI = (unsigned short)(i * 12345 % 65536);
        pdu_array[i].CRC_INDICATION.CRC_INDICATION_REL8_TAG = i + 2;
        pdu_array[i].CRC_INDICATION.CRCFLAG = rand() % 2;
    }

    clock_t end_time = clock();
    total_time += (end_time - start_time);

    pthread_mutex_lock(&allocation_mutex);
    successful_allocations++;
    pthread_mutex_unlock(&allocation_mutex);

    return pdu_array;
}

void log_performance(size_t frequency) {
    if (frequency <= 0) {
        frequency = 1; // Default to logging once per second
    }

    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Unable to open log file.\n");
        return;
    }

    clock_t average_time_per_allocation = total_time / successful_allocations;
    fprintf(log_file, "Average time per allocation: %ld ticks\n", average_time_per_allocation);

    fclose(log_file);
}

void* thread_function(void* arg) {
    size_t N = *(size_t*)arg;
    allocate_memory(N);
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        size_t N = rand() % 50 + 1;
        if (pthread_create(&threads[i], NULL, thread_function, &N) != 0) {
            fprintf(stderr, "Error: Unable to create thread.\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    log_performance(5); // Log performance every 5 seconds

    return EXIT_SUCCESS;
}
