    int guti[GUTI_LENGTH];
    unsigned int sequence_number;
} PathErrorReportingEntity;

typedef struct SignalingMessage {
    // Define signaling message structure
} SignalingMessage;

typedef struct SignalingSubsystem {
    PathErrorReportingEntity* path_error_entities;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    sem_t enqueue_sem;
    sem_t dequeue_sem;
} SignalingSubsystem;

void init_signaling_subsystem(SignalingSubsystem* subsystem, size_t capacity) {
    subsystem->path_error_entities = (PathErrorReportingEntity*)malloc(capacity * sizeof(PathErrorReportingEntity));
    subsystem->capacity = capacity;
    subsystem->size = 0;
    pthread_mutex_init(&subsystem->mutex, NULL);
    sem_init(&subsystem->enqueue_sem, 0, capacity);
    sem_init(&subsystem->dequeue_sem, 0, 0);
}

void enqueue_message(SignalingSubsystem* subsystem, SignalingMessage* message) {
    sem_wait(&subsystem->enqueue_sem);
    pthread_mutex_lock(&subsystem->mutex);
    // Add message to subsystem
    pthread_mutex_unlock(&subsystem->mutex);
    sem_post(&subsystem->dequeue_sem);
}

SignalingMessage* dequeue_message(SignalingSubsystem* subsystem) {
    SignalingMessage* message = NULL;
    sem_wait(&subsystem->dequeue_sem);
    pthread_mutex_lock(&subsystem->mutex);
    if (subsystem->size > 0) {
        // Retrieve message from subsystem
        subsystem->size--;
    }
    pthread_mutex_unlock(&subsystem->mutex);
    sem_post(&subsystem->enqueue_sem);
    return message;
}

void destroy_signaling_subsystem(SignalingSubsystem* subsystem) {
    free(subsystem->path_error_entities);
    pthread_mutex_destroy(&subsystem->mutex);
    sem_destroy(&subsystem->enqueue_sem);
    sem_destroy(&subsystem->dequeue_sem);
}
