#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UE_CONTEXTS 1000
#define RRC_STATE_SIZE 50
#define QOS_PARAMS_SIZE 20
#define HISTORY_BUFFER_SIZE (30 * 86400) // 30 days in seconds

typedef struct {
    uint32_t ue_id;
    char rrc_state[RRC_STATE_SIZE];
    uint8_t qos_params[QOS_PARAMS_SIZE];
} LTE_UE_Context;

typedef struct {
    pthread_mutex_t lock;
    LTE_UE_Context contexts[MAX_UE_CONTEXTS];
    int next_available_index;
} LTE_UE_Manager;

LTE_UE_Manager ue_manager;

void initialize_ue_manager() {
    pthread_mutex_init(&ue_manager.lock, NULL);
    memset(ue_manager.contexts, 0, sizeof(ue_manager.contexts));
    ue_manager.next_available_index = 0;
}

int add_or_update_ue_context(uint32_t ue_id, const char* rrc_state, const uint8_t* qos_params) {
    pthread_mutex_lock(&ue_manager.lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_manager.contexts[i].ue_id == ue_id) {
            strncpy(ue_manager.contexts[i].rrc_state, rrc_state, RRC_STATE_SIZE);
            memcpy(ue_manager.contexts[i].qos_params, qos_params, QOS_PARAMS_SIZE);
            pthread_mutex_unlock(&ue_manager.lock);
            return 0;
        }
    }
    if (ue_manager.next_available_index < MAX_UE_CONTEXTS) {
        ue_manager.contexts[ue_manager.next_available_index].ue_id = ue_id;
        strncpy(ue_manager.contexts[ue_manager.next_available_index].rrc_state, rrc_state, RRC_STATE_SIZE);
        memcpy(ue_manager.contexts[ue_manager.next_available_index].qos_params, qos_params, QOS_PARAMS_SIZE);
        ue_manager.next_available_index++;
        pthread_mutex_unlock(&ue_manager.lock);
        return 0;
    }
    pthread_mutex_unlock(&ue_manager.lock);
    return -1; // No available space
}

int get_ue_context(uint32_t ue_id, char* rrc_state, uint8_t* qos_params) {
    pthread_mutex_lock(&ue_manager.lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_manager.contexts[i].ue_id == ue_id) {
            strncpy(rrc_state, ue_manager.contexts[i].rrc_state, RRC_STATE_SIZE);
            memcpy(qos_params, ue_manager.contexts[i].qos_params, QOS_PARAMS_SIZE);
            pthread_mutex_unlock(&ue_manager.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ue_manager.lock);
    return -1; // UE context not found
}
