#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <dirent.h>
#include <string.h>
#include <sys/time.h>

#define MAX_THREADS 10

typedef struct {
    char *directory_path;
    FILE *output_file;
    char *filter_criteria;
    char *format_specifier;
    double cpu_threshold;
    double io_threshold;
} ThreadArgs;

void* process_directory(void* arg) {
    ThreadArgs *args = (ThreadArgs*)arg;
    DIR *dir;
    struct dirent *entry;
    struct timeval start_time, end_time;
    double total_time, cpu_usage, io_usage;

    gettimeofday(&start_time, NULL);

    dir = opendir(args->directory_path);
    if (dir == NULL) {
        perror("Error opening directory");
        pthread_exit(NULL);
    }

    while ((entry = readdir(dir)) != NULL) {
        // Simulate processing each file
        usleep(100); // Sleep for 100 microseconds to simulate work
    }

    closedir(dir);

    gettimeofday(&end_time, NULL);
    total_time = (end_time.tv_sec - start_time.tv_sec) + 
                 (end_time.tv_usec - start_time.tv_usec) / 1000000.0;

    // Simulate CPU and I/O usage
    cpu_usage = (double)rand() / RAND_MAX;
    io_usage = (double)rand() / RAND_MAX;

    if (cpu_usage > args->cpu_threshold || io_usage > args->io_threshold) {
        fprintf(args->output_file, "Warning: Resource constraints exceeded for %s\n", args->directory_path);
    }

    fprintf(args->output_file, "Processed directory: %s, Time: %.2f seconds, CPU Usage: %.2f%%, IO Usage: %.2f%%\n",
            args->directory_path, total_time, cpu_usage * 100, io_usage * 100);

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <input_directory> <output_file> <filter_criteria> <format_specifier> <cpu_threshold> <io_threshold>\n", argv[0]);
        return 1;
    }

    pthread_t threads[MAX_THREADS];
    ThreadArgs args[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS && i < argc - 7; i++) {
        args[i].directory_path = argv[i + 1];
        args[i].output_file = fopen(argv[2], "a");
        args[i].filter_criteria = argv[3];
        args[i].format_specifier = argv[4];
        args[i].cpu_threshold = atof(argv[5]);
        args[i].io_threshold = atof(argv[6]);

        pthread_create(&threads[i], NULL, process_directory, &args[i]);
    }

    for (int i = 0; i < MAX_THREADS && i < argc - 7; i++) {
        pthread_join(threads[i], NULL);
        fclose(args[i].output_file);
    }

    return 0;
}
