#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for a sensor reading
typedef struct {
    int id;
    float value;
    char unit[10];
} SensorReading;

// Define the structure for an IoT device connection
typedef struct {
    int deviceId;
    char status[20];
    SensorReading *readings;
    int numReadings;
    pthread_mutex_t lock;
} DeviceConnection;

// Function to initialize a device connection
void initDeviceConnection(DeviceConnection *device, int id) {
    device->deviceId = id;
    strcpy(device->status, "active");
    device->readings = NULL;
    device->numReadings = 0;
    pthread_mutex_init(&device->lock, NULL);
}

// Function to add a sensor reading to a device connection
void addSensorReading(DeviceConnection *device, SensorReading reading) {
    pthread_mutex_lock(&device->lock);
    device->readings = realloc(device->readings, (device->numReadings + 1) * sizeof(SensorReading));
    if (device->readings == NULL) {
        perror("Failed to allocate memory for sensor readings");
        exit(EXIT_FAILURE);
    }
    device->readings[device->numReadings++] = reading;
    pthread_mutex_unlock(&device->lock);
}

// Function to update the operational status of a device connection
void updateDeviceStatus(DeviceConnection *device, const char *status) {
    pthread_mutex_lock(&device->lock);
    strcpy(device->status, status);
    pthread_mutex_unlock(&device->lock);
}

// Function to clean up and free resources for a device connection
void cleanupDeviceConnection(DeviceConnection *device) {
    if (device->readings != NULL) {
        free(device->readings);
    }
    pthread_mutex_destroy(&device->lock);
}
