#define BUFFER_SIZE 4096

void process_file(const char* input_file_name, const char* output_file_name, const char* pattern, int verbosity) {
    FILE *input_file = fopen(input_file_name, "r");
    if (input_file == NULL) {
        fprintf(stderr, "Failed to open input file.\n");
        return;
    }

    FILE *output_file = fopen(output_file_name, "w");
    if (output_file == NULL) {
        fprintf(stderr, "Failed to open output file.\n");
        fclose(input_file);
        return;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, input_file)) {
        if (strstr(buffer, pattern)) {
            fprintf(output_file, "%s", buffer);
            if (verbosity > 0) {
                printf("Found match: %s", buffer);
            }
        }
    }

    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char* argv[]) {
    if (argc < 4 || argc > 5) {
        fprintf(stderr, "Usage: %s input_file output_file pattern [verbosity]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* input_file_name = argv[1];
    const char* output_file_name = argv[2];
    const char* pattern = argv[3];
    int verbosity = (argc == 5) ? atoi(argv[4]) : 0;

    process_file(input_file_name, output_file_name, pattern, verbosity);

    return EXIT_SUCCESS;
}
