#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000

typedef struct {
    int event_id;
    time_t timestamp;
    char type[50];
    char payload[256];
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    int head, tail, count;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} MessageQueue;

void mq_init(MessageQueue *mq) {
    mq->head = mq->tail = mq->count = 0;
    pthread_mutex_init(&mq->lock, NULL);
    pthread_cond_init(&mq->not_full, NULL);
    pthread_cond_init(&mq->not_empty, NULL);
}

int mq_enqueue(MessageQueue *mq, Event event) {
    pthread_mutex_lock(&mq->lock);
    while (mq->count == MAX_EVENTS)
        pthread_cond_wait(&mq->not_full, &mq->lock);
    mq->events[mq->tail] = event;
    mq->tail = (mq->tail + 1) % MAX_EVENTS;
    mq->count++;
    pthread_cond_signal(&mq->not_empty);
    pthread_mutex_unlock(&mq->lock);
    return 0;
}

int mq_dequeue(MessageQueue *mq, Event *event) {
    pthread_mutex_lock(&mq->lock);
    while (mq->count == 0)
        pthread_cond_wait(&mq->not_empty, &mq->lock);
    *event = mq->events[mq->head];
    mq->head = (mq->head + 1) % MAX_EVENTS;
    mq->count--;
    pthread_cond_signal(&mq->not_full);
    pthread_mutex_unlock(&mq->lock);
    return 0;
}

void* producer(void *arg) {
    MessageQueue *mq = (MessageQueue*) arg;
    Event event;
    for (int i = 0; i < MAX_EVENTS; i++) {
        // Simulate event generation
        event.event_id = i;
        time(&event.timestamp);
        sprintf(event.type, "Type%d", i % 5);
        sprintf(event.payload, "Payload%d", i);
        mq_enqueue(mq, event);
    }
    return NULL;
}

void* consumer(void *arg) {
    MessageQueue *mq = (MessageQueue*) arg;
    Event event;
    for (int i = 0; i < MAX_EVENTS; i++) {
        mq_dequeue(mq, &event);
        // Simulate event processing
        printf("Processed event %d\n", event.event_id);
    }
    return NULL;
}

int main() {
    MessageQueue mq;
    pthread_t producer_thread, consumer_thread;

    mq_init(&mq);

    pthread_create(&producer_thread, NULL, producer, &mq);
    pthread_create(&consumer_thread, NULL, consumer, &mq);

    pthread_join(producer_thread, NULL);
    pthread_join(consumer_thread, NULL);

    return 0;
}
```

This code provides a basic framework for implementing a message broker using a lock-free queue and demonstrates the use of threads for concurrent producer and consumer operations.']

