#define MAX_UE_CONTEXTS 1000
#define MAX_BEARERS_PER_UE 5
#define DNS_CACHE_SIZE 1024

typedef enum {
    RRC_IDLE,
    RRC_CONNECTED
} RrcState;

typedef struct {
    int ue_id;
    RrcState rrc_state;
    int bearer_count;
    int bearers[MAX_BEARERS_PER_UE];
} UeContext;

UeContext ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t ue_context_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (!ue_contexts[i].ue_id) {
            ue_contexts[i].ue_id = ue_id;
            ue_contexts[i].rrc_state = RRC_IDLE;
            ue_contexts[i].bearer_count = 0;
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
}

void update_ue_rrc_state(int ue_id, RrcState new_state) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            ue_contexts[i].rrc_state = new_state;
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
}

int add_bearer_to_ue(int ue_id, int bearer_id) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id && ue_contexts[i].bearer_count < MAX_BEARERS_PER_UE) {
            ue_contexts[i].bearers[ue_contexts[i].bearer_count++] = bearer_id;
            pthread_mutex_unlock(&ue_context_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
    return -1;
}

u_char* resolve_hostname(const char* hostname, int max_retries) {
    static u_char ip[4];
    struct hostent *host = NULL;
    for (int i = 0; i < max_retries; i++) {
        if ((host = gethostbyname(hostname)) != NULL) {
            memcpy(ip, host->h_addr_list[0], sizeof(u_char)*4);
            return ip;
        }
        sleep(1); // Wait before retrying
    }
    return NULL;
}

void* dns_resolution_thread(void* arg) {
    char* hostname = (char*)arg;
    int max_retries = atoi(getenv("DNS_MAX_RETRIES"));
    u_char* ip = resolve_hostname(hostname, max_retries);
    if (ip != NULL) {
        printf("Resolved %s to IP: %d.%d.%d.%d\n", hostname, ip[0], ip[1], ip[2], ip[3]);
    } else {
        printf("Failed to resolve %s\n", hostname);
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_UE_CONTEXTS];
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        initialize_ue_context(i + 1);
    }

    // Simulate concurrent DNS resolution
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        pthread_create(&threads[i], NULL, dns_resolution_thread, "example.com");
    }

    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
