#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

typedef struct {
    int id;
    time_t timestamp;
    char* type;
    char* payload;
} Event;

typedef struct node {
    Event event;
    struct node* next;
} Node;

Node* queue_head = NULL;
Node* queue_tail = NULL;
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_condition = PTHREAD_COND_INITIALIZER;
int queue_size = 0;

void enqueue(Event event) {
    pthread_mutex_lock(&queue_mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->event = event;
    new_node->next = NULL;

    if (queue_tail == NULL) {
        queue_head = new_node;
        queue_tail = new_node;
    } else {
        queue_tail->next = new_node;
        queue_tail = new_node;
    }
    queue_size++;
    pthread_cond_signal(&queue_condition);
    pthread_mutex_unlock(&queue_mutex);
}

Event dequeue() {
    pthread_mutex_lock(&queue_mutex);
    while (queue_head == NULL) {
        pthread_cond_wait(&queue_condition, &queue_mutex);
    }

    Event event = queue_head->event;
    Node* temp = queue_head;
    queue_head = queue_head->next;
    if (queue_head == NULL) {
        queue_tail = NULL;
    }
    free(temp);
    queue_size--;
    pthread_mutex_unlock(&queue_mutex);
    return event;
}

void* analytics_engine(void* arg) {
    while (1) {
        Event event = dequeue();
        // Process the event with the Analytics Engine
        printf("Event processed: ID=%d, Timestamp=%ld, Type=%s, Payload=%s\n", 
               event.id, event.timestamp, event.type, event.payload);
    }
    return NULL;
}

int main() {
    pthread_t analytics_thread;
    pthread_create(&analytics_thread, NULL, analytics_engine, NULL);

    // Simulate event generation and processing
    for (int i = 0; i < 10; i++) {
        Event event = {i, time(NULL), "TypeA", "PayloadData"};
        enqueue(event);
        usleep(100000); // Sleep to simulate varying event arrival rates
    }

    pthread_join(analytics_thread, NULL);
    return 0;
}
