typedef struct {
    int ue_id;
    int rrc_state;
    pthread_mutex_t mutex;
} LTE_UE_Context;

LTE_UE_Context* init_lte_ue_contexts(int N) {
    if (N > MAX_UE_CONTEXTS) {
        fprintf(stderr, "Error: Exceeding maximum number of UE contexts\n");
        return NULL;
    }

    LTE_UE_Context* contexts = (LTE_UE_Context*)malloc(N * sizeof(LTE_UE_Context));
    if (!contexts) {
        perror("Memory allocation failed for UE contexts");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        contexts[i].ue_id = i + 1;
        contexts[i].rrc_state = 0;
        pthread_mutex_init(&contexts[i].mutex, NULL);
    }

    return contexts;
}

void free_lte_ue_contexts(LTE_UE_Context* contexts, int N) {
    if (contexts) {
        for (int i = 0; i < N; ++i) {
            pthread_mutex_destroy(&contexts[i].mutex);
        }
        free(contexts);
    }
}
