        perror("Memory allocation failed for CRC indication PDU array");
        return NULL;
    }

    // Initialize the array with valid values or default values
    int valid_tags[] = {0x1234, 0x5678, 0xABCD}; // Example set of valid tags
    int num_valid_tags = sizeof(valid_tags) / sizeof(valid_tags[0]);

    for (int i = 0; i < N; ++i) {
        pdu_array[i].rx_ue_info_tag = rand() % (num_valid_tags * 10); // Simulate random tag values

        if (pdu_array[i].rx_ue_info_tag >= num_valid_tags * 10) {
            fprintf(stderr, "Error: Invalid RX UE information tag found\n");
