#define MAX_QOS_FLOWS 256
#define INITIAL_ARRAY_SIZE 100

typedef struct {
    NAS_MESSAGE *message;
    int UE_ID;
    uint8_t QFI;
    int sequence_number;
} LTE_Uplink_NAS_Transport_T;

typedef struct {
    LTE_Uplink_NAS_Transport_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_Message_Array_T;

LTE_Message_Array_T* lte_message_array_create() {
    LTE_Message_Array_T *array = (LTE_Message_Array_T*)malloc(sizeof(LTE_Message_Array_T));
    array->array = (LTE_Uplink_NAS_Transport_T*)malloc(INITIAL_ARRAY_SIZE * sizeof(LTE_Uplink_NAS_Transport_T));
    array->size = 0;
    array->capacity = INITIAL_ARRAY_SIZE;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void lte_message_array_free(LTE_Message_Array_T *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->array[i].message);
    }
    free(array->array);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int lte_message_array_insert(LTE_Message_Array_T *array, LTE_Uplink_NAS_Transport_T message) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_Uplink_NAS_Transport_T *new_array = (LTE_Uplink_NAS_Transport_T*)realloc(array->array, new_capacity * sizeof(LTE_Uplink_NAS_Transport_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Out of memory
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = message;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int lte_message_array_delete(LTE_Message_Array_T *array, size_t index) {
    pthread_mutex_lock(&array->lock);
    if (index >= array->size) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Invalid index
    }
    for (size_t i = index + 1; i < array->size; ++i) {
        array->array[i - 1] = array->array[i];
    }
    --array->size;
    pthread_mutex_unlock(&array->lock);
    return 0;
}
```
