#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct LTE_PHY_RX_FRAME_INFO {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int PHY_RX_FRAME_STATUS;
    int CRC_FLAG;
    struct LTE_PHY_RX_FRAME_INFO *prev, *next;
    pthread_mutex_t lock;
} LTE_PHY_RX_FRAME_INFO;

typedef struct DoublyLinkedList {
    LTE_PHY_RX_FRAME_INFO *head, *tail;
    pthread_mutex_t list_lock;
} DoublyLinkedList;

typedef struct RNTIIndexNode {
    int RNTI;
    LTE_PHY_RX_FRAME_INFO *node;
    struct RNTIIndexNode *next;
} RNTIIndexNode;

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

RNTIIndexNode** create_rnti_index(int size) {
    RNTIIndexNode **index = calloc(size, sizeof(RNTIIndexNode*));
    return index;
}

void insert_node(DoublyLinkedList *list, RNTIIndexNode **index, LTE_PHY_RX_FRAME_INFO *node, int rnti_hash_size) {
    pthread_mutex_lock(&list->list_lock);
    node->next = list->head;
    if (list->head != NULL) list->head->prev = node;
    list->head = node;
    if (list->tail == NULL) list->tail = node;

    int hash_index = rnti_hash(node->RNTI, rnti_hash_size);
    pthread_mutex_lock(&index[hash_index]->lock);
    node->next_in_index = index[hash_index];
    index[hash_index] = node;
    pthread_mutex_unlock(&index[hash_index]->lock);

    pthread_mutex_unlock(&list->list_lock);
}

void delete_node_by_tag(DoublyLinkedList *list, RNTIIndexNode **index, int tag) {
    pthread_mutex_lock(&list->list_lock);
    LTE_PHY_RX_FRAME_INFO *current = list->head;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == tag) {
            if (current->prev != NULL) current->prev->next = current->next;
            if (current->next != NULL) current->next->prev = current->prev;
            if (list->head == current) list->head = current->next;
            if (list->tail == current) list->tail = current->prev;

            int hash_index = rnti_hash(current->RNTI, rnti_hash_size);
            RNTIIndexNode **current_index = &index[hash_index];
            while (*current_index != NULL) {
                if ((*current_index)->node == current) {
                    *current_index = (*current_index)->next_in_index;
                    break;
                }
                current_index = &(*current_index)->next_in_index;
            }

            free(current);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->list_lock);
}

LTE_PHY_RX_FRAME_INFO* get_node_with_highest_status(DoublyLinkedList *list) {
    LTE_PHY_RX_FRAME_INFO *max_node = NULL;
    pthread_mutex_lock(&list->list_lock);
    for (LTE_PHY_RX_FRAME_INFO *current = list->head; current != NULL; current = current->next) {
        if (max_node == NULL || current->PHY_RX_FRAME_STATUS > max_node->PHY_RX_FRAME_STATUS) {
            max_node = current;
        }
    }
    pthread_mutex_unlock(&list->list_lock);
    return max_node;
}

void destroy_list(DoublyLinkedList *list, RNTIIndexNode **index, int rnti_hash_size) {
    for (int i = 0; i < rnti_hash_size; i++) {
        RNTIIndexNode *current = index[i];
        while (current != NULL) {
            RNTIIndexNode *temp = current;
            current = current->next_in_index;
            free(temp);
        }
    }
    pthread_mutex_destroy(&list->list_lock);
    for (int i = 0; i < rnti_hash_size; i++) {
        pthread_mutex_destroy(&index[i]->lock);
    }
    free(index);
    free(list);
}

int rnti_hash(int rnti, int size) {
    return (rnti * 31) % size;
}
