#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <openssl/evp.h>

#define MAX_IP_LENGTH 16

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return status;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), INET_ADDRSTRLEN);
    freeaddrinfo(res);

    return 0;
}

int main() {
    u_char ip[MAX_IP_LENGTH];
    const char *hostname = "example.com";

    int result = resolve_dns(hostname, ip);
    if (result == 0) {
        printf("IP address: %s\n", inet_ntoa(*(struct in_addr *)ip));
    } else {
        printf("Failed to resolve DNS for hostname: %s\n", hostname);
    }

    return 0;
}
```

