enum LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR,
    FATAL
};

struct LogEntry {
    LogLevel level;
    std::string module;
    std::string message;
    std::time_t timestamp;
    // Add more metadata fields as needed
};

class Logger {
private:
    static const size_t MAX_QUEUE_SIZE = 1024;
    std::queue<LogEntry> logQueue;
    std::mutex queueMutex;
    std::condition_variable notFull, notEmpty;
    bool stop;
    std::thread worker;

public:
    Logger() : stop(false) {
        worker = std::thread(&Logger::run, this);
    }

    ~Logger() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        notEmpty.notify_all();
        worker.join();
    }

    void log(LogLevel level, const std::string& module, const std::string& message) {
        LogEntry entry{level, module, message, std::time(nullptr)};
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            notFull.wait(lock, [this] { return !logQueue.full(); });
            logQueue.push(entry);
        }
        notEmpty.notify_one();
    }

private:
    void run() {
        while (true) {
            LogEntry entry;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                notEmpty.wait(lock, [this] { return !logQueue.empty() || stop; });
                if (stop && logQueue.empty()) {
                    break;
                }
                entry = logQueue.front();
                logQueue.pop();
            }
            dispatchLog(entry);
        }
    }

    void dispatchLog(const LogEntry& entry) {
        // Implement logic to dispatch log to different destinations
        std::cout << "Logging: [" << timestampToString(entry.timestamp) << "] " 
                  << getLevelString(entry.level) << " " << entry.module << ": " 
                  << entry.message << std::endl;
    }

    std::string getLevelString(LogLevel level) {
        switch (level) {
            case DEBUG: return "DEBUG";
            case INFO: return "INFO";
            case WARN: return "WARN";
            case ERROR: return "ERROR";
            case FATAL: return "FATAL";
            default: return "UNKNOWN";
        }
    }

    std::string timestampToString(std::time_t timestamp) {
        // Implement logic to convert timestamp to string
        return std::ctime(&timestamp);
    }
};

int main() {
    Logger logger;
    logger.log(INFO, "Main", "Application started");
    logger.log(ERROR, "Database", "Failed to connect");
    return 0;
}
```

