#include <time.h>

#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_WARNING 3
#define LOG_LEVEL_ERROR 4
#define LOG_LEVEL_CRITICAL 5

typedef struct {
    int level;
    FILE *console_output;
    FILE *file_output;
    size_t file_size_limit;
    time_t file_time_interval;
    // Add other configuration settings here
} LoggerConfig;

LoggerConfig* create_logger_config(int log_level, const char *log_file_path) {
    LoggerConfig *config = (LoggerConfig*)malloc(sizeof(LoggerConfig));
    config->level = log_level;
    config->console_output = stdout;
    config->file_output = fopen(log_file_path, "a");
    config->file_size_limit = 1024 * 1024; // 1MB
    config->file_time_interval = 3600; // 1 hour
    // Initialize other configuration settings here
    return config;
}

void log_message(LoggerConfig *config, int level, const char *tag, const char *format, ...) {
    if (level < config->level) {
        return;
    }

    va_list args;
    va_start(args, format);

    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);

    // Console output
    fprintf(config->console_output, "[%02d:%02d:%02d] [%s] [%s] ", 
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
            (level == LOG_LEVEL_DEBUG ? "DEBUG" : level == LOG_LEVEL_INFO ? "INFO" :
             level == LOG_LEVEL_WARNING ? "WARNING" : level == LOG_LEVEL_ERROR ? "ERROR" :
             level == LOG_LEVEL_CRITICAL ? "CRITICAL" : "UNKNOWN"),
            tag);
    vfprintf(config->console_output, format, args);
    fprintf(config->console_output, "\n");
    fflush(config->console_output);

    // File output
    if (config->file_output) {
        fprintf(config->file_output, "[%02d:%02d:%02d] [%s] [%s] ", 
                time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
                (level == LOG_LEVEL_DEBUG ? "DEBUG" : level == LOG_LEVEL_INFO ? "INFO" :
                 level == LOG_LEVEL_WARNING ? "WARNING" : level == LOG_LEVEL_ERROR ? "ERROR" :
                 level == LOG_LEVEL_CRITICAL ? "CRITICAL" : "UNKNOWN"),
                tag);
        vfprintf(config->file_output, format, args);
        fprintf(config->file_output, "\n");
        fflush(config->file_output);

        // File size and time interval checks
        fseek(config->file_output, 0L, SEEK_END);
        size_t file_size = ftell(config->file_output);
        if (file_size >= config->file_size_limit || difftime(time(NULL), current_time) > config->file_time_interval) {
            fclose(config->file_output);
            rename(log_file_path, log_file_path".old");
            config->file_output = fopen(log_file_path, "w");
        }
    }

    va_end(args);
}

void *log_thread_function(void *arg) {
    LoggerConfig *config = (LoggerConfig*)arg;
    // Implement asynchronous logging logic here
    return NULL;
}

int main() {
    LoggerConfig *config = create_logger_config(LOG_LEVEL_INFO, "app.log");

    pthread_t log_thread;
    pthread_create(&log_thread, NULL, log_thread_function, config);

    // Example usage of the logger
    log_message(config, LOG_LEVEL_INFO, "Main", "Application started");
    sleep(1);
    log_message(config, LOG_LEVEL_WARNING, "Main", "Memory usage is high");

    pthread_join(log_thread, NULL);
    free(config->file_output);
    fclose(config->console_output);
    free(config);

    return 0;
