// Function prototypes
void* process_log(void* arg);
int log_filter(const char* line, const char* filter_criteria);

// Structure to hold thread data
typedef struct {
    FILE* log_file;
    FILE* report_file;
    pthread_mutex_t* mutex;
} ThreadData;

int main(int argc, char* argv[]) {
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <input_log_file> <output_report_file> <filter_criteria> <format_specifier> <memory_threshold> <max_threads>\n", argv[0]);
        return 1;
    }

    FILE* input_log = fopen(argv[1], "r");
    if (!input_log) {
        perror("Failed to open input log file");
        return 1;
    }

    FILE* output_report = fopen(argv[2], "w");
    if (!output_report) {
        perror("Failed to open output report file");
        fclose(input_log);
        return 1;
    }

    pthread_t threads[atoi(argv[6])];
    ThreadData thread_data[atoi(argv[6])];
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < atoi(argv[6]); ++i) {
        thread_data[i].log_file = input_log;
        thread_data[i].report_file = output_report;
        thread_data[i].mutex = &mutex;
        pthread_create(&threads[i], NULL, process_log, &thread_data[i]);
    }

    for (int i = 0; i < atoi(argv[6]); ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(input_log);
    fclose(output_report);

    return 0;
}

void* process_log(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    FILE* log_file = data->log_file;
    FILE* report_file = data->report_file;
    pthread_mutex_t* mutex = data->mutex;

    char line[1024];
    while (fgets(line, sizeof(line), log_file)) {
        if (log_filter(line, argv[3])) {
            pthread_mutex_lock(mutex);
            fprintf(report_file, argv[4], line); // Use the format specifier from command-line
            pthread_mutex_unlock(mutex);
        }
    }

    return NULL;
}

int log_filter(const char* line, const char* filter_criteria) {
    if (strstr(line, filter_criteria)) {
        return 1;
    }
    return 0;
}
