    int rrc_state;
    int active_bearers[MAX_RADIO_BEARERS];
} LTE_UE_Context;

typedef struct {
    pthread_mutex_t mutex;
    LTE_UE_Context contexts[MAX_UE_CONTEXTS];
    int context_count;
} LTE_UE_Manager;

LTE_UE_Manager* lte_init() {
    LTE_UE_Manager* manager = (LTE_UE_Manager*)malloc(sizeof(LTE_UE_Manager));
    if (!manager) return NULL;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->context_count = 0;
    return manager;
}

void lte_add_context(LTE_UE_Manager* manager, LTE_UE_Context context) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->context_count < MAX_UE_CONTEXTS) {
        manager->contexts[manager->context_count] = context;
        manager->context_count++;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void lte_update_context(LTE_UE_Manager* manager, int ue_id, LTE_UE_Context new_context) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->context_count; i++) {
        if (manager->contexts[i].ue_id == ue_id) {
            manager->contexts[i] = new_context;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

EVP_CIPHER_CTX* lte_cipher_setup(const char* command_line_option, const char* key, const char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    int ret;
    if (strcmp(command_line_option, "aes-128-cbc") == 0) {
        ret = EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
    } else if (strcmp(command_line_option, "aes-256-gcm") == 0) {
        ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!ret) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void lte_cleanup(LTE_UE_Manager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

