#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* log_message;
    int severity_level;
} LogEntry;

typedef struct {
    LogEntry** logs;
    int capacity;
    int front;
    int rear;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} Logger;

Logger* create_logger(int initial_capacity) {
    Logger* logger = (Logger*)malloc(sizeof(Logger));
    logger->logs = (LogEntry**)malloc(initial_capacity * sizeof(LogEntry*));
    for (int i = 0; i < initial_capacity; ++i) {
        logger->logs[i] = NULL;
    }
    logger->capacity = initial_capacity;
    logger->front = 0;
    logger->rear = -1;
    logger->size = 0;
    pthread_mutex_init(&logger->mutex, NULL);
    pthread_cond_init(&logger->not_full, NULL);
    pthread_cond_init(&logger->not_empty, NULL);
    return logger;
}

void enqueue_log(Logger* logger, char* log_message, int severity_level) {
    pthread_mutex_lock(&logger->mutex);
    while (logger->size == logger->capacity) {
        pthread_cond_wait(&logger->not_full, &logger->mutex);
    }
    logger->rear = (logger->rear + 1) % logger->capacity;
    logger->logs[logger->rear] = (LogEntry*)malloc(sizeof(LogEntry));
    logger->logs[logger->rear]->log_message = strdup(log_message);
    logger->logs[logger->rear]->severity_level = severity_level;
    ++logger->size;
    pthread_cond_signal(&logger->not_empty);
    pthread_mutex_unlock(&logger->mutex);
}

void dequeue_log(Logger* logger, char** log_message, int* severity_level) {
    pthread_mutex_lock(&logger->mutex);
    while (logger->size == 0) {
        pthread_cond_wait(&logger->not_empty, &logger->mutex);
    }
    *log_message = strdup(logger->logs[logger->front]->log_message);
    *severity_level = logger->logs[logger->front]->severity_level;
    free(logger->logs[logger->front]);
    logger->logs[logger->front] = NULL;
    logger->front = (logger->front + 1) % logger->capacity;
    --logger->size;
    pthread_cond_signal(&logger->not_full);
    pthread_mutex_unlock(&logger->mutex);
}

void destroy_logger(Logger* logger) {
    for (int i = 0; i < logger->capacity; ++i) {
        if (logger->logs[i] != NULL) {
            free(logger->logs[i]->log_message);
            free(logger->logs[i]);
        }
    }
    free(logger->logs);
    pthread_mutex_destroy(&logger->mutex);
    pthread_cond_destroy(&logger->not_full);
    pthread_cond_destroy(&logger->not_empty);
    free(logger);
}
