#define MAX_LOG_SIZE 1024

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct LogMessage {
    LogLevel level;
    char message[MAX_LOG_SIZE];
} LogMessage;

typedef struct LogQueue {
    LogMessage *messages;
    int front, rear;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full, cond_not_empty;
} LogQueue;

LogQueue* create_log_queue(int capacity) {
    LogQueue *queue = (LogQueue*)malloc(sizeof(LogQueue));
    queue->capacity = capacity;
    queue->messages = (LogMessage*)malloc(capacity * sizeof(LogMessage));
    queue->front = 0;
    queue->rear = -1;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond_not_full, NULL);
    pthread_cond_init(&queue->cond_not_empty, NULL);
    return queue;
}

void enqueue_log(LogQueue *queue, LogMessage message) {
    pthread_mutex_lock(&queue->mutex);
    while ((queue->rear + 1) % queue->capacity == queue->front) {
        pthread_cond_wait(&queue->cond_not_full, &queue->mutex);
    }
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->messages[queue->rear] = message;
    pthread_cond_signal(&queue->cond_not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

LogMessage dequeue_log(LogQueue *queue) {
    LogMessage message;
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == queue->rear) {
        pthread_cond_wait(&queue->cond_not_empty, &queue->mutex);
    }
    queue->front = (queue->front + 1) % queue->capacity;
    message = queue->messages[queue->front];
    pthread_cond_signal(&queue->cond_not_full);
    pthread_mutex_unlock(&queue->mutex);
    return message;
}

void destroy_log_queue(LogQueue *queue) {
    free(queue->messages);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond_not_full);
    pthread_cond_destroy(&queue->cond_not_empty);
    free(queue);
}
