CipherObject* create_cipher_object(const char* command_line_option) {
    CipherObject* cipher_obj = (CipherObject*)malloc(sizeof(CipherObject));
    if (!cipher_obj) return NULL;

    // Initialize OpenSSL library
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Create and initialize cipher context based on the command line option
    EVP_CIPHER_CTX_init(cipher_obj->cipher_ctx);
    int cipher_type;
    if (strcmp(command_line_option, "AES-128-CBC") == 0) {
        cipher_type = EVP_aes_128_cbc();
    } else if (strcmp(command_line_option, "AES-256-CBC") == 0) {
        cipher_type = EVP_aes_256_cbc();
    } else {
        // Handle invalid command line option
        free(cipher_obj);
        return NULL;
    }

    EVP_EncryptInit_ex(cipher_obj->cipher_ctx, cipher_type, NULL, NULL, NULL);

    pthread_mutex_init(&cipher_obj->lock, NULL);
    return cipher_obj;
}

void destroy_cipher_object(CipherObject* cipher_obj) {
    if (!cipher_obj) return;

    // Clean up OpenSSL library
    EVP_CIPHER_CTX_cleanup(cipher_obj->cipher_ctx);
    EVP_cleanup();
    ERR_free_strings();

    pthread_mutex_destroy(&cipher_obj->lock);
    free(cipher_obj);
}
