#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_RESOURCES 100

typedef struct {
    sem_t pool_lock;
    sem_t resource_count;
    int resources[MAX_RESOURCES];
    time_t last_usage[MAX_RESOURCES];
    int is_available[MAX_RESOURCES];
} ResourcePool;

void initialize_pool(ResourcePool *pool, int initial_size) {
    sem_init(&pool->pool_lock, 0, 1);
    sem_init(&pool->resource_count, 0, initial_size);
    for (int i = 0; i < MAX_RESOURCES; i++) {
        pool->resources[i] = i;
        pool->last_usage[i] = 0;
        pool->is_available[i] = 1;
    }
}

void* allocate_resource(void *pool_ptr) {
    ResourcePool *pool = (ResourcePool*)pool_ptr;
    sem_wait(&pool->resource_count);
    sem_wait(&pool->pool_lock);

    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (pool->is_available[i]) {
            pool->is_available[i] = 0;
            time_t now = time(NULL);
            pool->last_usage[i] = now;
            sem_post(&pool->pool_lock);
            return (void*)&pool->resources[i];
        }
    }

    sem_post(&pool->pool_lock);
    return NULL; // No available resource
}

void deallocate_resource(void *pool_ptr, void *resource) {
    ResourcePool *pool = (ResourcePool*)pool_ptr;
    int res_id = *(int*)resource;
    sem_wait(&pool->pool_lock);

    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (pool->resources[i] == res_id) {
            pool->is_available[i] = 1;
            break;
        }
    }

    sem_post(&pool->pool_lock);
    sem_post(&pool->resource_count);
}

void clean_up_pool(ResourcePool *pool) {
    sem_destroy(&pool->pool_lock);
    sem_destroy(&pool->resource_count);
}
