#define MAX_FD_POOL_SIZE 100

typedef struct {
    int fd_pool[MAX_FD_POOL_SIZE];
    int pool_size;
    pthread_mutex_t mutex;
} FD_Pool;

FD_Pool *fd_pool_init(int initial_size) {
    FD_Pool *pool = (FD_Pool *)malloc(sizeof(FD_Pool));
    if (!pool) return NULL;
    pool->pool_size = initial_size;
    for (int i = 0; i < initial_size; i++) {
        pool->fd_pool[i] = -1; // -1 indicates the slot is empty
    }
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

int fd_pool_get_fd(FD_Pool *pool) {
    int fd;
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->pool_size; i++) {
        if (pool->fd_pool[i] == -1) {
            pool->fd_pool[i] = i; // Simulate opening a file descriptor
            fd = i;
            pthread_mutex_unlock(&pool->mutex);
            return fd;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return -1; // No available FDs
}

void fd_pool_release_fd(FD_Pool *pool, int fd) {
    if (fd < 0 || fd >= pool->pool_size) return;
    pthread_mutex_lock(&pool->mutex);
    pool->fd_pool[fd] = -1; // Simulate closing a file descriptor
    pthread_mutex_unlock(&pool->mutex);
}

void fd_pool_cleanup(FD_Pool *pool) {
    if (!pool) return;
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}
