#include <iostream>
#include <memory>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include "lte_library.hpp"
#include "key_management_service.hpp"
#include "sandesh_client.hpp"

class LTEUEContext {
public:
    LTEUEContext(const std::string& ue_id) : ue_id(ue_id), rrc_state(RRC_IDLE), active_bearers() {}

    void setRRCState(RRCState state) { rrc_state = state; }
    RRCState getRRCState() const { return rrc_state; }

    void addBearer(const RadioBearer& bearer) { active_bearers.push_back(bearer); }
    void removeBearer(int bearer_id) {
        active_bearers.erase(std::remove_if(active_bearers.begin(), active_bearers.end(),
                                           [bearer_id](const RadioBearer& bearer) { return bearer.id == bearer_id; }),
                             active_bearers.end());
    }

private:
    std::string ue_id;
    RRCState rrc_state;
    std::vector<RadioBearer> active_bearers;
};

class LTEUEContextManager {
public:
    void addContext(const LTEUEContext& context) {
        std::unique_lock<std::mutex> lock(mutex_);
        contexts_[context.ue_id] = context;
    }

    void removeContext(const std::string& ue_id) {
        std::unique_lock<std::mutex> lock(mutex_);
        contexts_.erase(ue_id);
    }

    LTEUEContext getContext(const std::string& ue_id) const {
        std::shared_lock<std::mutex> lock(mutex_);
        return contexts_.at(ue_id);
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<std::string, LTEUEContext> contexts_;
};

class LTETelemetry {
public:
    void logActiveUECount(int count) const { active_ue_count_ = count; }
    int getActiveUECount() const { return active_ue_count_; }

private:
    mutable std::mutex mutex_;
    int active_ue_count_ = 0;
};

class LTEEncryption {
public:
    // Encryption and decryption methods using OpenSSL
    void encrypt(const std::string& data, std::string& encrypted_data) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_, iv_);
        EVP_EncryptUpdate(ctx, (unsigned char*)encrypted_data.data(), &len, (const unsigned char*)data.c_str(), data.size());
        encrypted_data.resize(len);
        EVP_EncryptFinal_ex(ctx, (unsigned char*)(encrypted_data.data() + len), &len);
        encrypted_data.resize(len);
        EVP_CIPHER_CTX_free(ctx);
    }

    void decrypt(const std::string& encrypted_data, std::string& decrypted_data) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_, iv_);
        EVP_DecryptUpdate(ctx, (unsigned char*)decrypted_data.data(), &len, (const unsigned char*)encrypted_data.c_str(), encrypted_data.size());
        decrypted_data.resize(len);
        EVP_DecryptFinal_ex(ctx, (unsigned char*)(decrypted_data.data() + len), &len);
        decrypted_data.resize(len);
        EVP_CIPHER_CTX_free(ctx);
    }

private:
    unsigned char key_[32];
    unsigned char iv_[16];
};

class LTEHashing {
public:
    std::string hash(const std::string& data) const {
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, data.c_str(), data.size());
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_Final(hash, &sha256);
        std::ostringstream oss;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            oss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
        }
        return oss.str();
    }

private:
};

