#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <errno.h>

typedef struct {
    sem_t *sem;
    pthread_mutex_t lock;
} Semaphore;

struct SemaphoreCollection {
    Semaphore *semaphores;
    size_t count;
    size_t capacity;
    pthread_mutex_t collection_lock;
};

int create_semaphore_collection(struct SemaphoreCollection *collection, size_t initial_capacity) {
    collection->semaphores = malloc(initial_capacity * sizeof(Semaphore));
    if (!collection->semaphores) {
        perror("Failed to allocate memory for semaphore collection");
        return -1;
    }
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->collection_lock, NULL);
    return 0;
}

int add_semaphore(struct SemaphoreCollection *collection, unsigned int initial_value) {
    if (collection->count >= collection->capacity) {
        // Resize the collection
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 16;
        Semaphore *new_semaphores = realloc(collection->semaphores, new_capacity * sizeof(Semaphore));
        if (!new_semaphores) {
            perror("Failed to resize semaphore collection");
            return -1;
        }
        collection->semaphores = new_semaphores;
        collection->capacity = new_capacity;
    }

    pthread_mutex_lock(&collection->collection_lock);
    Semaphore *new_semaphore = &collection->semaphores[collection->count++];
    pthread_mutex_init(&new_semaphore->lock, NULL);
    sem_init(new_semaphore->sem, 0, initial_value);
    pthread_mutex_unlock(&collection->collection_lock);

    return 0;
}

int increment_semaphore(struct SemaphoreCollection *collection, size_t semaphore_id) {
    if (semaphore_id >= collection->count) {
        fprintf(stderr, "Invalid semaphore identifier\n");
        return -1;
    }

    pthread_mutex_lock(&collection->semaphores[semaphore_id].lock);
    sem_post(collection->semaphores[semaphore_id].sem);
    pthread_mutex_unlock(&collection->semaphores[semaphore_id].lock);

    return 0;
}

int decrement_semaphore(struct SemaphoreCollection *collection, size_t semaphore_id) {
    if (semaphore_id >= collection->count) {
        fprintf(stderr, "Invalid semaphore identifier\n");
        return -1;
    }

    struct timespec timeout;
    clock_gettime(CLOCK_REALTIME, &timeout);
    timeout.tv_sec += 5;

    pthread_mutex_lock(&collection->semaphores[semaphore_id].lock);
    int result = sem_timedwait(collection->semaphores[semaphore_id].sem, &timeout);
    pthread_mutex_unlock(&collection->semaphores[semaphore_id].lock);

    if (result == -1) {
        perror("Semaphore wait timed out");
        return -1;
    }

    return 0;
}

int delete_semaphore(struct SemaphoreCollection *collection, size_t semaphore_id) {
    if (semaphore_id >= collection->count) {
        fprintf(stderr, "Invalid semaphore identifier\n");
        return -1;
    }

    pthread_mutex_lock(&collection->semaphores[semaphore_id].lock);
    sem_destroy(collection->semaphores[semaphore_id].sem);
    pthread_mutex_unlock(&collection->semaphores[semaphore_id].lock);

    // Remove the semaphore from the collection
    for (size_t i = semaphore_id; i < collection->count - 1; ++i) {
        collection->semaphores[i] = collection->semaphores[i + 1];
    }
    collection->count--;

    return 0;
}

void destroy_semaphore_collection(struct SemaphoreCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        delete_semaphore(collection, i);
    }
    free(collection->semaphores);
    pthread_mutex_destroy(&collection->collection_lock);
}
