#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_RESOURCES 100

typedef struct {
    int id;
    time_t last_usage_time;
    int available;
    // Add type-specific attributes here
} Resource;

typedef struct {
    Resource resources[MAX_RESOURCES];
    sem_t pool_mutex;
    sem_t resource_sems[MAX_RESOURCES];
    int num_resources;
} ResourcePool;

void init_resource_pool(ResourcePool *pool, int num_resources) {
    pool->num_resources = num_resources;
    sem_init(&pool->pool_mutex, 0, 1);
    for (int i = 0; i < num_resources; i++) {
        sem_init(&pool->resource_sems[i], 0, 0);
        pool->resources[i].id = i;
        pool->resources[i].last_usage_time = time(NULL);
        pool->resources[i].available = 1;
    }
}

int allocate_resource(ResourcePool *pool) {
    int resource_id = -1;
    sem_wait(&pool->pool_mutex);
    for (int i = 0; i < pool->num_resources; i++) {
        if (pool->resources[i].available) {
            resource_id = i;
            break;
        }
    }
    if (resource_id != -1) {
        pool->resources[resource_id].available = 0;
        sem_post(&pool->resource_sems[resource_id]);
    }
    sem_post(&pool->pool_mutex);
    return resource_id;
}

int reserve_resource(ResourcePool *pool, int timeout_ms) {
    for (int i = 0; i < pool->num_resources; i++) {
        if (sem_wait(&pool->resource_sems[i]) == 0) {
            sem_wait(&pool->pool_mutex);
            if (!pool->resources[i].available) {
                sem_post(&pool->resource_sems[i]);
                continue;
            }
            pool->resources[i].available = 0;
            sem_post(&pool->pool_mutex);
            return i;
        }
    }
    return -1; // Timeout
}

void cancel_reservation(ResourcePool *pool, int resource_id) {
    sem_wait(&pool->resource_sems[resource_id]);
    sem_wait(&pool->pool_mutex);
    pool->resources[resource_id].available = 1;
    sem_post(&pool->pool_mutex);
}

void deallocate_resource(ResourcePool *pool, int resource_id) {
    sem_wait(&pool->resource_sems[resource_id]);
    sem_wait(&pool->pool_mutex);
    pool->resources[resource_id].last_usage_time = time(NULL);
    pool->resources[resource_id].available = 1;
    sem_post(&pool->pool_mutex);
}

void clean_up_resource_pool(ResourcePool *pool) {
    for (int i = 0; i < pool->num_resources; i++) {
        sem_destroy(&pool->resource_sems[i]);
    }
    sem_destroy(&pool->pool_mutex);
}
