#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FD_POOL_SIZE 1024

typedef struct {
    int fd_pool[MAX_FD_POOL_SIZE];
    int pool_size;
    int current_count;
} FD_Pool;

FD_Pool* init_fd_pool(int initial_size) {
    FD_Pool* pool = (FD_Pool*)malloc(sizeof(FD_Pool));
    if (!pool) return NULL;

    pool->pool_size = initial_size;
    pool->current_count = 0;

    for (int i = 0; i < initial_size; i++) {
        pool->fd_pool[i] = -1; // Initialize to an invalid value
    }

    return pool;
}

int get_fd_from_pool(FD_Pool* pool) {
    if (pool == NULL || pool->current_count >= pool->pool_size) return -1;

    for (int i = 0; i < pool->pool_size; i++) {
        if (pool->fd_pool[i] == -1) {
            pool->fd_pool[i] = open("data.txt", "r");
            if (pool->fd_pool[i] != -1) {
                pool->current_count++;
                return pool->fd_pool[i];
            }
        }
    }

    return -1;
}

void release_fd_to_pool(FD_Pool* pool, int fd) {
    if (pool == NULL || fd < 0) return;

    for (int i = 0; i < pool->pool_size; i++) {
        if (pool->fd_pool[i] == fd) {
            close(fd);
            pool->fd_pool[i] = -1;
            pool->current_count--;
            break;
        }
    }
}

void cleanup_fd_pool(FD_Pool* pool) {
    if (pool == NULL) return;

    for (int i = 0; i < pool->pool_size; i++) {
        if (pool->fd_pool[i] != -1) {
            close(pool->fd_pool[i]);
        }
    }

    free(pool);
}
