            nodes.erase(std::remove(nodes.begin(), nodes.end(), it->second), nodes.end());
            nodeMap.erase(it);
        }
    }

    void start() {
        isRunning = true;
        for (auto& node : nodes) {
            std::thread([node]() {
                while (true) {
                    node->collectData();
                    node->sendData(node->getCollectedData());
                    std::this_thread::sleep_for(std::chrono::seconds(1));
                }
            }).detach();
        }
    }

    void stop() {
        isRunning = false;
    }

private:
    std::string nodeId;
    std::string collectedData;

public:
    SensorNode* getNode(const std::string& nodeId) {
        return nodeMap[nodeId];
    }

    const std::string& getCollectedData() const {
        return collectedData;
    }

    void setNodeId(const std::string& id) {
        nodeId = id;
    }

    // Other methods and members as per the requirements
};

int main() {
    SensorManager manager;
    SensorNode node1, node2;
    node1.setNodeId("node1");
    node2.setNodeId("node2");

    manager.addSensorNode(&node1);
    manager.addSensorNode(&node2);

    manager.start();

    // Simulate adding and removing nodes dynamically
    std::this_thread::sleep_for(std::chrono::seconds(5));
    manager.removeSensorNode("node1");
    manager.addSensorNode(new SensorNode());

    manager.stop();

    return 0;
}
```

