} packet_entry;

packet_entry cache[CACHE_SIZE];
int cache_index = 0;

NFAPI_CRC_INDICATION_PDU_T *create_crc_pdu(RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->ue_information_tag = ue_info_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void capture_and_process_packets(char *interface, int duration, char **filters, int filter_count) {
    pcap_t *handle;
    struct pcap_pkthdr header;
    const u_char *packet;
    time_t start_time = time(NULL);
    time_t current_time;

    handle = pcap_open_live(interface, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", interface, errbuf);
        return;
    }

    while ((packet = pcap_next(handle, &header)) != NULL && difftime(time(NULL), start_time) < duration) {
        current_time = time(NULL);
        packet_entry *entry = (packet_entry *)malloc(sizeof(packet_entry));
        entry->timestamp = current_time;
        entry->size = header.len;

        // Determine protocol type based on packet header
        memcpy(entry->protocol_type, "TCP", 4); // Simplified example

        // Apply filtering rules
        int discard_packet = 0;
        for (int i = 0; i < filter_count && !discard_packet; i++) {
            if (strcmp(filters[i], entry->protocol_type) != 0) {
                discard_packet = 1;
            }
        }

        if (!discard_packet) {
            // Check cache for duplicates
            int is_duplicate = 0;
            for (int i = 0; i < cache_index && !is_duplicate; i++) {
                if (cache[i].timestamp == entry->timestamp && strcmp(cache[i].protocol_type, entry->protocol_type) == 0) {
                    is_duplicate = 1;
                }
            }

            if (!is_duplicate) {
                // Store in cache
                if (cache_index >= CACHE_SIZE) {
                    cache_index = 0; // Simple round-robin replacement
                }
                memcpy(&cache[cache_index], entry, sizeof(packet_entry));
                cache_index++;
            }

            free(entry);
        } else {
            free(entry);
        }

        // Update progress indicator
        if (difftime(current_time, start_time) >= duration - 10) {
            printf("Processing: %.2f%%\n", ((float)difftime(time(NULL), start_time) / duration) * 100);
        }
    }

    pcap_close(handle);
}

int main(int argc, char **argv) {
    int opt;
    char *interface = NULL;
    int duration = 60; // Default duration
    char *filters[MAX_FILTERS];
    int filter_count = 0;

    while ((opt = getopt(argc, argv, "i:d:f:o:t:h")) != -1) {
        switch (opt) {
            case 'i':
                interface = optarg;
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 'f':
                filters[filter_count++] = optarg;
                break;
            case 'o':
                // Handle output file
                break;
            case 't':
                // Handle threshold option
                break;
            case 'h':
                printf("Usage: %s -i <interface> -d <duration> [-f <protocol>] [-o <output_file>] [-t <threshold>]\n", argv[0]);
                exit(0);
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                exit(1);
        }
    }

    if (interface == NULL) {
        printf("Interface not specified.\n");
        return 1;
    }

    capture_and_process_packets(interface, duration, filters, filter_count);

    return 0;
}
