#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <chrono>
#include <functional>
#include <string>

class DistributedLogger {
public:
    enum LogLevel { INFO, WARNING, ERROR };

    DistributedLogger(std::size_t numThreads = 4) : stop(false), threadCount(numThreads) {
        for (std::size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this]{ return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) {
                            return;
                        }
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~DistributedLogger() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void log(const std::string& ip, LogLevel level, const std::string& message) {
        LogEntry entry = { generateId(), std::chrono::system_clock::now(), ip, level, message };
        queue.push(entry);
        condition.notify_one();
    }

private:
    struct LogEntry {
        std::size_t id;
        std::chrono::time_point<std::chrono::system_clock> timestamp;
        std::string ip;
        LogLevel level;
        std::string message;
    };

    std::atomic<bool> stop;
    std::vector<std::thread> workers;
    std::queue<LogEntry> queue;
    std::mutex queueMutex;
    std::condition_variable condition;

    std::size_t generateId() {
        static std::atomic<std::size_t> idCounter(0);
        return ++idCounter;
    }
};

int main() {
    DistributedLogger logger(4);

    // Example usage
    logger.log("192.168.1.1", DistributedLogger::INFO, "User logged in");
    logger.log("192.168.1.2", DistributedLogger::WARNING, "Low disk space");

    return 0;
}
