    const char *crypto_suite = "AES";
    const char *output_file = "output.txt";

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printf("Man page content here...\n");
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0 && i + 1 < argc) {
            crypto_suite = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (!input_file) {
            input_file = argv[i];
        }
    }

    if (!input_file) {
        print_usage(argv[0]);
        return 1;
    }

    FILE *in = fopen(input_file, "r");
    if (!in) {
        perror("Error opening file");
        return 1;
    }

    char buffer[256];
    int line_count = 0;
    while (fgets(buffer, sizeof(buffer), in)) {
        line_count++;
    }
