#include <unistd.h>

void process_directory(const char *path, const char *output_file);
int count_lines_in_file(const char *file_path);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s --help\n", argv[0]);
        return EXIT_FAILURE;
    }

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s directory_path [--help] [-d] [-o output_file]\n", argv[0]);
            return EXIT_SUCCESS;
        } else if (strcmp(argv[i], "-d") == 0) {
            // Handle -d option, which is not required for this task
            continue;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            process_directory(argv[1], argv[i + 1]);
            return EXIT_SUCCESS;
        }
    }

    process_directory(argv[1], NULL);
    return EXIT_SUCCESS;
}

void process_directory(const char *path, const char *output_file) {
    DIR *dir = opendir(path);
    if (!dir) {
        perror("Error opening directory");
        return;
    }

    int total_lines = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_name[0] == '.') continue; // Ignore hidden files
        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        struct stat file_stat;
        if (lstat(full_path, &file_stat) != 0) {
            perror("Error getting file status");
            continue;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            process_directory(full_path, output_file);
        } else if (S_ISREG(file_stat.st_mode) && strcmp(entry->d_name + strlen(entry->d_name) - 4, ".txt") == 0) {
            total_lines += count_lines_in_file(full_path);
        }
    }

    closedir(dir);

    if (output_file != NULL) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            perror("Error opening output file");
            return;
        }
        fprintf(out, "Total lines: %d\n", total_lines);
        fclose(out);
    } else {
        printf("Total lines: %d\n", total_lines);
    }
}

int count_lines_in_file(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Error opening file for counting lines");
        return 0;
    }

    int lines = 0;
    while (fgets(NULL, 0, file)) ++lines;
    fclose(file);
    return lines;
}
