#include <memory>

class LibraryManager {
public:
    struct Config {
        // Define configuration parameters for library loading here
        bool enableLogging;
        int maxVersion;
    };

    static std::shared_ptr<LibraryManager> getInstance() {
        static std::shared_ptr<LibraryManager> instance = std::make_shared<LibraryManager>();
        return instance;
    }

    void loadLibrary(const std::string& name, const Config& config = {}) {
        // Implement logic to load the library with given configuration
        if (loadedLibraries.find(name) != loadedLibraries.end()) {
            // Handle multiple concurrent loads of the same library version
            return;
        }
        // Load the library and store it in the map
        loadedLibraries[name] = std::make_shared<Library>(name, config);
    }

    void unloadLibrary(const std::string& name) {
        // Implement logic to unload the library
        if (loadedLibraries.find(name) != loadedLibraries.end()) {
            loadedLibraries.erase(name);
        }
    }

private:
    LibraryManager() {}

    ~LibraryManager() {
        // Ensure all libraries are unloaded upon application exit
        for (auto& pair : loadedLibraries) {
            unloadLibrary(pair.first);
        }
    }

    std::unordered_map<std::string, std::shared_ptr<Library>> loadedLibraries;
};

class Library {
public:
    Library(const std::string& name, const LibraryManager::Config& config)
        : name(name), config(config) {
        // Implement logic to load the library
    }

    ~Library() {
        // Implement logic to unload the library
    }

private:
    std::string name;
    LibraryManager::Config config;
};

int main() {
    auto manager = LibraryManager::getInstance();
    manager->loadLibrary("library1");
    manager->loadLibrary("library2", {true, 5});
    return 0;
}
```

