#define MAX_UE_CONTEXTS 10000

typedef struct {
    int id;
    int rrc_state;
    EVP_CIPHER_CTX *cipher_ctx;
} LTE_UE_Context;

LTE_UE_Context ue_contexts[MAX_UE_CONTEXTS];
int num_active_ues = 0;

void initialize_cipher(LTE_UE_Context *ue, const char *cipher_name) {
    const EVP_CIPHER *cipher = EVP_get_cipherbyname(cipher_name);
    if (cipher == NULL) {
        fprintf(stderr, "Cipher not supported\n");
        return;
    }
    ue->cipher_ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ue->cipher_ctx, cipher, NULL, NULL, NULL) != 1) {
        fprintf(stderr, "Error initializing cipher\n");
        EVP_CIPHER_CTX_free(ue->cipher_ctx);
        ue->cipher_ctx = NULL;
    }
}

void update_ue_context(int id, int new_rrc_state, const char *cipher_name) {
    for (int i = 0; i < num_active_ues; i++) {
        if (ue_contexts[i].id == id) {
            if (new_rrc_state != -1) {
                ue_contexts[i].rrc_state = new_rrc_state;
            }
            if (cipher_name != NULL) {
                initialize_cipher(&ue_contexts[i], cipher_name);
            }
            return;
        }
    }
    fprintf(stderr, "UE context not found\n");
}

void log_ue_context_changes(int id, int rrc_state, const char *cipher_name) {
    printf("Updated UE Context: ID=%d, RRC State=%d", id, rrc_state);
    if (cipher_name != NULL) {
        printf(", Cipher=%s", cipher_name);
    }
    printf("\n");
}

int main() {
    // Example usage
    update_ue_context(12345, 1, "AES-128-CBC");
    log_ue_context_changes(12345, 1, "AES-128-CBC");

    return 0;
}
