    if (network != NULL) {
        network->num_contexts = 0;
        pthread_mutex_init(&network->context_scaling_mutex, NULL);
    }
    return network;
}

void add_ue_context(NRNetwork *network, int ue_id) {
    pthread_mutex_lock(&network->context_scaling_mutex);
    if (network->num_contexts < MAX_UE_CONTEXTS) {
        initialize_ue_context(&network->contexts[network->num_contexts], ue_id);
        configure_radio_bearers(&network->contexts[network->num_contexts]);
        network->num_contexts++;
    }
    pthread_mutex_unlock(&network->context_scaling_mutex);
}

void scale_network(NRNetwork *network, int target_num_contexts) {
    pthread_mutex_lock(&network->context_scaling_mutex);
    if (target_num_contexts > MAX_UE_CONTEXTS) {
        target_num_contexts = MAX_UE_CONTEXTS;
    }
    while (network->num_contexts < target_num_contexts) {
        add_ue_context(network, network->num_contexts + 1);
    }
    pthread_mutex_unlock(&network->context_scaling_mutex);
}

void free_network(NRNetwork *network) {
    for (int i = 0; i < network->num_contexts; i++) {
        pthread_mutex_destroy(&network->contexts[i].mutex);
    }
    pthread_mutex_destroy(&network->context_scaling_mutex);
    free(network);
}
