#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>

// Function to encrypt data using AES
int aes_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key,
                const unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return 0;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        return 0;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        return 0;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        return 0;
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to decrypt data using AES
int aes_decrypt(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *key,
                const unsigned char *iv, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return 0;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        return 0;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        return 0;
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        return 0;
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}

// Function to generate MD5 hash
void md5_hash(const unsigned char *data, int length, unsigned char *md5_result) {
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, data, length);
    MD5_Final(md5_result, &md5_ctx);
}

// Function to generate SHA1 hash
void sha1_hash(const unsigned char *data, int length, unsigned char *sha1_result) {
    SHA_CTX sha1_ctx;
    SHA1_Init(&sha1_ctx);
    SHA1_Update(&sha1_ctx, data, length);
    SHA1_Final(sha1_result, &sha1_ctx);
}

// Function to encrypt RSA with SHA1
int rsa_encrypt_with_sha1(const unsigned char *data, int data_len, const RSA *rsa,
                           unsigned char *ciphertext) {
    EVP_PKEY_CTX *ctx;
    int ciphertext_len;

    if (!(ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, NULL)))
        return 0;

    if (1 != EVP_PKEY_encrypt_init_ex(ctx))
        return 0;

    if (1 != EVP_PKEY_CTX_set_rsa_padding(ctx, RSA_PKCS1_PADDING))
        return 0;

    if (1 != EVP_PKEY_CTX_set_signature_md(ctx, EVP_sha1()))
        return 0;

    if (1 != EVP_PKEY_encrypt_update(ctx, NULL, &ciphertext_len, data, data_len))
        return 0;

    ciphertext = realloc(ciphertext, ciphertext_len);
    if (!ciphertext)
        return 0;

    if (1 != EVP_PKEY_encrypt_final_ex(ctx, ciphertext, &ciphertext_len))
        return 0;

    EVP_PKEY_CTX_free(ctx);

    return ciphertext_len;
}

// Function to decrypt RSA with SHA1
int rsa_decrypt_with_sha1(const unsigned char *ciphertext, int ciphertext_len, const RSA *rsa,
                           unsigned char *plaintext) {
    EVP_PKEY_CTX *ctx;
    int plaintext_len;

    if (!(ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, NULL)))
        return 0;

    if (1 != EVP_PKEY_decrypt_init_ex(ctx))
        return 0;

    if (1 != EVP_PKEY_ctx_set_rsa_padding(ctx, RSA_PKCS1_PADDING))
        return 0;

    if (1 != EVP_PKEY_decrypt_update(ctx, NULL, &plaintext_len, ciphertext, ciphertext_len))
        return 0;

    plaintext = realloc(plaintext, plaintext_len);
    if (!plaintext)
        return 0;

    if (1 != EVP_PKEY_decrypt_final_ex(ctx, plaintext, &plaintext_len))
        return 0;

    EVP_PKEY_CTX_free(ctx);

    return plaintext_len;
}
