    int n = 10; // Number of elements per thread
    NFCRCIndicationPdu* pdu_list = (NFCRCIndicationPdu*)malloc(n * sizeof(NFCRCIndicationPdu));

    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed for thread %d\n", thread_id);
        return NULL;
