        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rand() % 65536;
        pdu_list[i].CRCFLAG = rand() % 2;
    }

    // Simulate passing data to another function
    processNFCrcIndications(pdu_list, n);

    free(pdu_list);
    return NULL;
}

