    pthread_mutex_lock(&manager->lock);
    if (manager->next_free_index >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&manager->lock);
        return NULL; // No more space
    }
    lte_ue_context* ctx = (lte_ue_context*)malloc(sizeof(lte_ue_context));
    memset(ctx, 0, sizeof(lte_ue_context));
    manager->contexts[manager->next_free_index++] = ctx;
    pthread_mutex_unlock(&manager->lock);
    return ctx;
