#include <pthread.h>

// Define encryption modes
typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB,
    NULL_MODE
} EncryptionMode;

// Define key management parameters
typedef struct {
    unsigned char *key;
    int key_length;
    pthread_mutex_t lock; // Mutex for thread-safe access
} KeyManagementParameters;

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize key management parameters
void init_key_management_params(KeyManagementParameters *params, const unsigned char *key, int key_length) {
    params->key = (unsigned char *)malloc(key_length);
    memcpy(params->key, key, key_length);
    params->key_length = key_length;
    pthread_mutex_init(&params->lock, NULL);
}

// Function to set a new key
void update_key(KeyManagementParameters *params, const unsigned char *new_key, int new_key_length) {
    pthread_mutex_lock(&params->lock);
    free(params->key);
    params->key = (unsigned char *)malloc(new_key_length);
    memcpy(params->key, new_key, new_key_length);
    params->key_length = new_key_length;
    pthread_mutex_unlock(&params->lock);
}

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T *list, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        // Populate each entry with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        list[i].ue_info_tag.value = rand() % 1000;
        list[i].rnti.value = rand() % 65536;
        list[i].crc_indication.crcflag = (rand() % 2 == 0) ? true : false;
    }
}

// Function to clean up key management parameters
void cleanup_key_management_params(KeyManagementParameters *params) {
    pthread_mutex_destroy(&params->lock);
    free(params->key);
}
