['```go
package main

import (
	"log"
	"sync"
)

const (
	initialFDs = 1024
	maxFDs     = 65536
)

type FileDescriptorManager struct {
	fds         []int
	nextFD      int
	mutex       sync.Mutex
	shutdown    bool
	shutdownCh  chan struct{}
	logPrefix   string
}

func NewFileDescriptorManager(logPrefix string) *FileDescriptorManager {
	return &FileDescriptorManager{
		fds:        make([]int, initialFDs),
		nextFD:     0,
		mutex:      sync.Mutex{},
		shutdown:   false,
		shutdownCh: make(chan struct{}),
		logPrefix:  logPrefix,
	}
}

func (f *FileDescriptorManager) Allocate() (int, error) {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	if f.shutdown {
		return -1, ErrServerShuttingDown
	}

	if f.nextFD >= len(f.fds) {
		if f.nextFD >= maxFDs {
			return -1, ErrMaxFDReached
		}
		newFds := make([]int, len(f.fds)*2)
		copy(newFds, f.fds)
		f.fds = newFds
	}

	fd := f.nextFD
	f.nextFD++
	log.Printf("%s Allocated FD: %d", f.logPrefix, fd)
	return fd, nil
}

func (f *FileDescriptorManager) Release(fd int) {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	if fd < 0 || fd >= len(f.fds) {
		log.Printf("%s Invalid FD released: %d", f.logPrefix, fd)
		return
	}

	f.fds[fd] = -1 // Mark as free
	log.Printf("%s Released FD: %d", f.logPrefix, fd)
}

func (f *FileDescriptorManager) Shutdown() {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	if f.shutdown {
		return
	}
	f.shutdown = true

	close(f.shutdownCh)

	for i := 0; i < len(f.fds); i++ {
		f.Release(i)
	}
	log.Println(f.logPrefix + "Server has shut down gracefully.")
}

func (f *FileDescriptorManager) GetFDs() []int {
	f.mutex.Lock()
	defer f.mutex.Unlock()

	return append([]int(nil), f.fds...)
}

type ErrCode int

const (
	ErrMaxFDReached ErrCode = iota
	ErrServerShuttingDown
)

var (
	errMsg = map[ErrCode]string{
		ErrMaxFDReached:     "Maximum file descriptors reached",
		ErrServerShuttingDown: "Server is shutting down",
	}
)

func (e ErrCode) Error() string {
	return errMsg[e]
}

func main() {
	fdm := NewFileDescriptorManager("FDM: ")

	// Simulate client connections
	for i := 0; i < initialFDs*2; i++ {
		fd, err := fdm.Allocate()
		if err != nil {
			log.Printf("%s Error allocating FD: %v", fdm.logPrefix, err)
			break
		}
	}

	// Release some FDs
	for i := 0; i < initialFDs/2; i++ {
		fdm.Release(i)
	}

	// Simulate server shutdown
	fdm.Shutdown()
}
```']

