} record;

typedef struct node {
    record data;
    struct node* next;
} Node;

Node* create_node(record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_record(Node** head, record data) {
    Node* new_node = create_node(data);
    new_node->next = *head;
    *head = new_node;
}

record create_random_record() {
    record r;
    srand(time(NULL));
    r.offset = rand();
    r.key = rand() % 100; // Random key between 0 and 99
    r.value = (double)rand() / RAND_MAX; // Random value between 0.0 and 1.0
    r.timestamp = time(NULL);
    r.status = true;
    return r;
}

void initialize_records(Node** head) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        insert_record(head, create_random_record());
    }
}

// Function to calculate and validate checksums
bool validate_checksum(record data) {
    // Implement checksum validation logic here
    return true;
}

void free_records(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    Node* records_head = NULL;
    initialize_records(&records_head);

    // Example of how to use the records
    Node* current = records_head;
    while (current != NULL) {
        if (!validate_checksum(current->data)) {
            printf("Checksum validation failed for record with key %d\n", current->data.key);
        }
        current = current->next;
    }

    free_records(records_head);
    return 0;
}
