#include <iostream>
#include <string>
#include <map>
#include <mutex>
#include <dlfcn.h>

class DynamicLibraryManager {
private:
    std::map<std::string, void*> loadedLibraries;
    std::mutex libraryMutex;

public:
    ~DynamicLibraryManager() {
        unloadAllLibraries();
    }

    void* loadLibrary(const std::string& libraryPath, const char* options = nullptr) {
        std::lock_guard<std::mutex> lock(libraryMutex);
        if (loadedLibraries.find(libraryPath) != loadedLibraries.end()) {
            return loadedLibraries[libraryPath];
        }

        void* handle = dlopen(libraryPath.c_str(), RTLD_LAZY | RTLD_GLOBAL);
        if (!handle) {
            std::cerr << "Failed to load library: " << dlerror() << std::endl;
            return nullptr;
        }

        if (options) {
            // Apply configurable options here
            // Example:
            // int result = callFunction(handle, "configure", options);
            // if (result != 0) {
            //     dlclose(handle);
            //     return nullptr;
            // }
        }

        loadedLibraries[libraryPath] = handle;
        return handle;
    }

    void unloadLibrary(const std::string& libraryPath) {
        std::lock_guard<std::mutex> lock(libraryMutex);
        auto it = loadedLibraries.find(libraryPath);
        if (it != loadedLibraries.end()) {
            dlclose(it->second);
            loadedLibraries.erase(it);
        }
    }

    void unloadAllLibraries() {
        std::lock_guard<std::mutex> lock(libraryMutex);
        for (auto& pair : loadedLibraries) {
            dlclose(pair.second);
        }
        loadedLibraries.clear();
    }

    // Example usage
    int callFunction(void* handle, const char* functionName, ...) {
        typedef int (*FunctionType)(...);
        FunctionType func = reinterpret_cast<FunctionType>(dlsym(handle, functionName));
        if (!func) {
            std::cerr << "Failed to find function: " << dlerror() << std::endl;
            return -1;
        }

        va_list args;
        va_start(args, functionName);
        int result = func(args);
        va_end(args);

        return result;
    }
};
```

This code snippet provides a basic structure for a `DynamicLibraryManager` class in C++ that can dynamically load and unload shared libraries. It includes thread safety with a mutex, error handling for library loading failures, and a mechanism to call functions within loaded libraries. The example usage demonstrates how to call a function from a loaded library. You would need to expand on this to support configurable options, handle missing dependencies, and manage memory more efficiently as per your specific requirements.']

