#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    sem_t *sem;
    pthread_t *threads;
    int num_threads;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int initial_value, int num_threads) {
    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    manager->sem = sem_open("/my_semaphore", O_CREAT, 0644, initial_value);
    if (manager->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }

    manager->threads = malloc(num_threads * sizeof(pthread_t));
    manager->num_threads = num_threads;
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&manager->threads[i], NULL, thread_function, manager);
    }
    return manager;
}

void* thread_function(void* arg) {
    SemaphoreManager *manager = (SemaphoreManager*)arg;
    while (1) {
        sem_wait(manager->sem);
        // Critical section
        sem_post(manager->sem);
    }
    pthread_exit(NULL);
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->num_threads; i++) {
        pthread_join(manager->threads[i], NULL);
    }
    sem_close(manager->sem);
    sem_unlink("/my_semaphore");
    free(manager->threads);
    free(manager);
}
