#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>

// Function to initialize and manage a semaphore
void manage_semaphore(int initial_value) {
    sem_t *sem;
    int result;

    // Create the semaphore
    if ((sem = sem_open("/my_semaphore", O_CREAT, 0644, initial_value)) == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(EXIT_FAILURE);
    }

    // Use the semaphore for synchronization (example: decrement and increment)
    printf("Attempting to acquire semaphore...\n");
    if ((result = sem_wait(sem)) != 0) {
        perror("Failed to wait on semaphore");
        sem_close(sem);
        sem_unlink("/my_semaphore");
        exit(EXIT_FAILURE);
    }

    printf("Semaphore acquired. Critical section begins.\n");

    // Simulate work in critical section
    sleep(2);

    printf("Critical section ends. Releasing semaphore...\n");
    if ((result = sem_post(sem)) != 0) {
        perror("Failed to post on semaphore");
    }

    // Delete the semaphore after use
    if (sem_close(sem) != 0) {
        perror("Failed to close semaphore");
    }
    if (sem_unlink("/my_semaphore") != 0) {
        perror("Failed to unlink semaphore");
    }

    printf("Semaphore deleted successfully.\n");
}

int main() {
    int initial_value = 1; // Initial value of the semaphore
    manage_semaphore(initial_value);
    return 0;
}
```

