void print_usage() {
    printf("Usage: program_name [options] input_file\n");
    printf("Options:\n");
    printf("  --manpage     Display this manual page and exit.\n");
    printf("  -cs           Enable concurrent updates support.\n");
    printf("  -o output_file Write the result to output_file instead of stdout.\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    const char *input_file = NULL;
    int concurrent_updates = 0;
    const char *output_file = "stdout";

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            return EXIT_SUCCESS;
        } else if (strcmp(argv[i], "-cs") == 0) {
            concurrent_updates = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else {
            input_file = argv[i];
        }
    }

    if (!input_file) {
        print_usage();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp)) {
        line_count++;
    }

    fclose(fp);

    FILE *out_fp = output_file[0] != 's' ? fopen(output_file, "w") : stdout;
    if (!out_fp) {
        perror("Error opening output file");
        return EXIT_FAILURE;
    }

    fprintf(out_fp, "Number of lines: %d\n", line_count);

    if (output_file[0] != 's') {
        fclose(out_fp);
    }

    return EXIT_SUCCESS;
}
