typedef struct {
    int ue_id;
    RRC_State rrc_state;
    // Other fields as needed for UE context
} UE_Context;

typedef struct {
    UE_Context ues[MAX_UE_CONTEXTS];
    pthread_mutex_t lock;
    int count;
} UE_Manager;

void init_ue_manager(UE_Manager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_ue(UE_Manager *manager, UE_Context new_ue) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_UE_CONTEXTS) {
        manager->ues[manager->count++] = new_ue;
        pthread_mutex_unlock(&manager->lock);
        return 0; // Success
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Failure: Manager full
}

