#include <atomic>
#include <condition_variable>

struct DeviceContext {
    std::string deviceID;
    bool connectionState;
    std::vector<std::string> communicationChannels;

    void configureCommunicationChannel(const std::string& channel, const std::string& securityProtocol, int qos) {
        // Simulate channel configuration
        communicationChannels.push_back(channel);
    }
};

class DeviceManager {
private:
    std::unordered_map<std::string, DeviceContext> deviceMap;
    std::mutex mapMutex;
    std::atomic<int> activeDeviceCount{0};
    std::condition_variable updateCondition;

public:
    void addDevice(const std::string& deviceID) {
        std::lock_guard<std::mutex> lock(mapMutex);
        if (deviceMap.find(deviceID) == deviceMap.end()) {
            DeviceContext newDevice;
            newDevice.deviceID = deviceID;
            newDevice.connectionState = false;
            deviceMap[deviceID] = newDevice;
            activeDeviceCount.fetch_add(1, std::memory_order_relaxed);
        }
    }

    void updateConnectionState(const std::string& deviceID, bool newState) {
        std::lock_guard<std::mutex> lock(mapMutex);
        if (deviceMap.find(deviceID) != deviceMap.end()) {
            deviceMap[deviceID].connectionState = newState;
        }
    }

    void addCommunicationChannel(const std::string& deviceID, const std::string& channel, const std::string& securityProtocol, int qos) {
        std::lock_guard<std::mutex> lock(mapMutex);
        if (deviceMap.find(deviceID) != deviceMap.end()) {
            deviceMap[deviceID].configureCommunicationChannel(channel, securityProtocol, qos);
        }
    }

    void logActiveDeviceCount() const {
        std::cout << "Active Device Count: " << activeDeviceCount.load(std::memory_order_relaxed) << std::endl;
    }

    void updatePeriodicly(const std::string& deviceID) {
        // Simulate periodic update
        std::lock_guard<std::mutex> lock(mapMutex);
        if (deviceMap.find(deviceID) != deviceMap.end()) {
            deviceMap[deviceID].connectionState = !deviceMap[deviceID].connectionState;
            for (auto& channel : deviceMap[deviceID].communicationChannels) {
                // Reconfigure channels based on some logic
                deviceMap[deviceID].configureCommunicationChannel(channel, "TLS", 1);
            }
        }
        updateCondition.notify_one();
    }

    void waitForUpdate() {
        std::unique_lock<std::mutex> lock(mapMutex);
        updateCondition.wait(lock);
    }
};

int main() {
    DeviceManager manager;
    manager.addDevice("device001");
    manager.updateConnectionState("device001", true);
    manager.addCommunicationChannel("device001", "channel001", "TLS", 1);
    manager.logActiveDeviceCount();
    manager.updatePeriodicly("device001");
    manager.waitForUpdate();

    return 0;
}
