#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <pthread.h>
#include <sys/stat.h>

#define MAX_DEPTH 15
#define THREAD_POOL_SIZE 10

typedef struct {
    char* path;
    int depth;
} DirectoryInfo;

void* process_directory(void* arg) {
    DirectoryInfo* info = (DirectoryInfo*)arg;
    // Implement directory processing logic here
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory> [output_file]\n", argv[0]);
        return EXIT_FAILURE;
    }

    char* root_directory = argv[1];
    FILE* output_file = argc > 2 ? fopen(argv[2], "w") : stdout;

    pthread_t threads[THREAD_POOL_SIZE];
    DirectoryInfo info[MAX_DEPTH];

    int thread_count = 0;
    int current_depth = 0;
    stack_init(&stack);

    // Initialize root directory information
    stack_push(&stack, (void*)root_directory);
    info[current_depth].path = root_directory;
    info[current_depth].depth = 0;

    while (!stack_is_empty(&stack)) {
        char* current_path = (char*)stack_pop(&stack);
        DIR* dir = opendir(current_path);

        if (dir == NULL) {
            fprintf(stderr, "Error opening directory: %s\n", current_path);
            continue;
        }

        struct dirent* entry;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_name[0] == '.' || S_ISLNK(entry->d_type)) {
                continue; // Skip hidden files and symbolic links
            }

            char path[MAX_PATH_LENGTH];
            snprintf(path, sizeof(path), "%s/%s", current_path, entry->d_name);

            struct stat file_stat;
            if (stat(path, &file_stat) == -1) {
                fprintf(stderr, "Error getting file info: %s\n", path);
                continue;
            }

            if (S_ISDIR(file_stat.st_mode)) {
                if (current_depth < MAX_DEPTH - 1) {
                    stack_push(&stack, (void*)path);
                    info[++current_depth].path = path;
                    info[current_depth].depth = current_depth;
                }
            } else if (S_ISREG(file_stat.st_mode)) {
                // Process file logic here
            }
        }

        closedir(dir);

        // Launch threads for processing directories
        while (current_depth > 0 && thread_count < THREAD_POOL_SIZE) {
            pthread_create(&threads[thread_count++], NULL, process_directory, &info[current_depth--]);
        }

        // Wait for all active threads to finish
        for (int i = 0; i < thread_count; ++i) {
            pthread_join(threads[i], NULL);
        }
    }

    if (output_file != stdout) {
        fclose(output_file);
    }

    return EXIT_SUCCESS;
}
