int fork_and_manage_process(const char *command, int resource_limits[]) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        return 0;
    } else if (pid == 0) {
        // Execute the command as a child process
        execl(command, command, NULL);
        perror("Exec failed");
        exit(1);
    } else {
        int status;
        waitpid(pid, &status, 0);
        // Handle child process cleanup and errors
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    }
}

