    bool connected;
    std::vector<CommunicationChannel> channels;
};

// Define the SessionManager class
class SessionManager {
private:
    std::unordered_map<std::string, Session> sessions;
    std::mutex sessionsMutex;

public:
    // Add or update a session
    void updateSession(const Session& session) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        sessions[session.sessionId] = session;
    }

    // Get a session by ID
    Session getSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        auto it = sessions.find(sessionId);
        if (it != sessions.end()) {
            return it->second;
        }
        return Session{};
    }

    // Get the number of active sessions
    size_t getActiveSessionsCount() const {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        return sessions.size();
    }
};

int main() {
    SessionManager manager;

    // Example usage
    Session session = {"session123", true, {"admin"}, "device456", true, {{"TCP", 1}, {"UDP", 2}}};
    manager.updateSession(session);

    Session retrievedSession = manager.getSession("session123");
    std::cout << "Active Sessions: " << manager.getActiveSessionsCount() << std::endl;

    return 0;
}
