    if (len <= size_limit && !(flags & STRING_TRUNCATE_FLAG)) {
        return strdup(input);
    }

    char *output = (char *)malloc(size_limit + 2); // Space for '\0' and optional '/'
    if (!output) {
        log_message(LOG_ERROR, "Memory allocation failed");
        return NULL;
    }

    strncpy(output, input, size_limit);
    output[size_limit] = '\0';
    if (!(flags & STRING_TRUNCATE_FLAG)) {
        strncat(output, "/", size_limit - strlen(output));
    }

    return output;
}

// Global counter for monitoring total allocations
int allocation_counter = 0;

// Function to limit the number of allocations
void *safe_malloc(size_t size) {
    if (allocation_counter >= MAX_ALLOCATIONS) {
        log_message(LOG_WARNING, "Memory usage limit exceeded");
        return NULL;
    }

    void *ptr = malloc(size);
    if (ptr) {
        allocation_counter++;
    }
    return ptr;
}

// Function to safely free memory and decrement the counter
void safe_free(void *ptr) {
    if (ptr) {
        free(ptr);
        allocation_counter--;
    }
}

