#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_DEPTH 20
#define MAX_FILES 1000

typedef struct {
    int lineCount;
    size_t fileSize;
} FileStats;

typedef struct {
    char path[1024];
    FileStats stats;
} DirectoryEntry;

DirectoryEntry directoryEntries[MAX_FILES];

int process_directory(const char *path, int depth, FileStats *parentStats) {
    if (depth > MAX_DEPTH)
        return -1;

    DIR *dir = opendir(path);
    if (!dir) {
        perror("opendir");
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char fullPath[1024];
        snprintf(fullPath, sizeof(fullPath), "%s/%s", path, entry->d_name);

        if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            process_directory(fullPath, depth + 1, parentStats);
        } else if ((entry->d_type == DT_REG || entry->d_type == DT_LNK) && entry->d_name[0] != '.') {
            struct stat fileStat;
            if (stat(fullPath, &fileStat) == -1) {
                perror("stat");
                continue;
            }

            parentStats->fileSize += fileStat.st_size;

            FILE *file = fopen(fullPath, "r");
            if (!file) {
                perror("fopen");
                continue;
            }

            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), file)) {
                parentStats->lineCount++;
            }

            fclose(file);
        }
    }

    closedir(dir);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <directory> <output_file>\n", argv[0]);
        return -1;
    }

    const char *dirPath = argv[1];
    const char *outputFile = argv[2];

    FileStats rootStats = {0};
    if (process_directory(dirPath, 0, &rootStats) != 0)
        return -1;

    FILE *out = fopen(outputFile, "w");
    if (!out) {
        perror("fopen");
        return -1;
    }

    fprintf(out, "Total line count: %d\n", rootStats.lineCount);
    fprintf(out, "Total file size: %zu bytes\n", rootStats.fileSize);

    fclose(out);

    return 0;
}
```

