// Define the resource structure
typedef struct Resource {
    int id;
    int type;
    time_t last_used;
    int available;
    // Add any type-specific attributes here
} Resource;

// Define the resource pool structure
typedef struct ResourcePool {
    int num_resources;
    Resource* resources;
    sem_t* semaphores;
    pthread_mutex_t lock;
} ResourcePool;

// Initialize the resource pool
int init_resource_pool(ResourcePool** pool, int num_resources) {
    *pool = (ResourcePool*)malloc(sizeof(ResourcePool));
    if (*pool == NULL) return 0;

    (*pool)->num_resources = num_resources;
    (*pool)->resources = (Resource*)malloc(num_resources * sizeof(Resource));
    if ((*pool)->resources == NULL) return 0;

    (*pool)->semaphores = (sem_t*)malloc(num_resources * sizeof(sem_t));
    if ((*pool)->semaphores == NULL) return 0;

    for (int i = 0; i < num_resources; i++) {
        sem_init(&(*pool)->semaphores[i], 0, 1);
        (*pool)->resources[i].id = i;
        (*pool)->resources[i].type = rand() % 5; // Example type
        (*pool)->resources[i].last_used = time(NULL);
        (*pool)->resources[i].available = 1;
    }

    pthread_mutex_init(&(*pool)->lock, NULL);

    return 1;
}

// Allocate a resource
int allocate_resource(ResourcePool* pool) {
    for (int i = 0; i < pool->num_resources; i++) {
        if (sem_wait(&pool->semaphores[i]) == -1) continue;

        pthread_mutex_lock(&pool->lock);
        if (pool->resources[i].available) {
            pool->resources[i].available = 0;
            time(&pool->resources[i].last_used);
            pthread_mutex_unlock(&pool->lock);

            sem_post(&pool->semaphores[i]);
            return pool->resources[i].id;
        }
        pthread_mutex_unlock(&pool->lock);
        sem_post(&pool->semaphores[i]);
    }

    return -1; // No available resource
}

// Deallocate a resource
void deallocate_resource(ResourcePool* pool, int id) {
    for (int i = 0; i < pool->num_resources; i++) {
        if (pool->resources[i].id == id) {
            pthread_mutex_lock(&pool->lock);
            pool->resources[i].available = 1;
            pthread_mutex_unlock(&pool->lock);

            sem_post(&pool->semaphores[i]);
            break;
        }
    }
}

