class DistributedCache {
private:
    std::unordered_map<std::string, std::string> cache;
    std::mutex cache_mutex;
    std::condition_variable data_available;
    bool running;

public:
    DistributedCache() : running(true) {}

    void startFeed(const std::string& feedName, const std::function<void(std::string)>& updateCallback) {
        std::thread([this, feedName, updateCallback]() {
            while (running) {
                // Simulate data update from external source
                std::string newData = fetchNewData(feedName);
                updateCache(feedName, newData);
                updateCallback(newData);

                // Notify waiting threads about new data
                std::unique_lock<std::mutex> lock(cache_mutex);
                data_available.notify_all();
            }
        }).detach();
    }

    void waitForUpdate(const std::string& feedName) {
        std::unique_lock<std::mutex> lock(cache_mutex);
        data_available.wait(lock, [this, &feedName]() {
            return cache.find(feedName) != cache.end();
        });
    }

    std::string getFeedData(const std::string& feedName) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        if (cache.find(feedName) == cache.end()) {
            throw std::runtime_error("Feed not found");
        }
        return cache[feedName];
    }

private:
    void updateCache(const std::string& feedName, const std::string& newData) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        cache[feedName] = newData;
    }

    std::string fetchNewData(const std::string& feedName) {
        // Simulate fetching new data from external source
        return "Updated data for " + feedName;
    }
};

void logFeedChange(const std::string& feedName, const std::string& newData) {
    std::ofstream logFile("feed_changes.log", std::ios::app);
    logFile << "Feed: " << feedName << ", New Data: " << newData << std::endl;
}

int main() {
    DistributedCache cache;

    // Start data feeds
    cache.startFeed("stockQuotes", [](const std::string& data) {
        logFeedChange("stockQuotes", data);
    });
    cache.startFeed("marketNews", [](const std::string& data) {
        logFeedChange("marketNews", data);
    });

    // Simulate client access
    for (int i = 0; i < 5; ++i) {
        std::thread([&, i]() {
            cache.waitForUpdate("stockQuotes");
            std::cout << "Client " << i << " got stock quotes: " << cache.getFeedData("stockQuotes") << std::endl;
        }).detach();
    }

    for (int i = 0; i < 5; ++i) {
        std::thread([&, i]() {
            cache.waitForUpdate("marketNews");
            std::cout << "Client " << i << " got market news: " << cache.getFeedData("marketNews") << std::endl;
        }).detach();
    }

    // Keep the main thread alive
    std::this_thread::sleep_for(std::chrono::seconds(10));

    return 0;
}
