public class EventProcessingPipeline {

    private final KafkaConsumer<String, String> consumer;
    private final KafkaProducer<String, String> producer;
    private final Gauge latencyGauge;
    private final Gauge throughputGauge;

    public EventProcessingPipeline(String bootstrapServers, String topic) {
        // Initialize Kafka consumer and producer
        consumer = new KafkaConsumer<>(Map.of(
            "bootstrap.servers", bootstrapServers,
            "key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer",
            "value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer"
        ));
        consumer.subscribe(List.of(topic));

        producer = new KafkaProducer<>(Map.of(
            "bootstrap.servers", bootstrapServers,
            "key.serializer", "org.apache.kafka.common.serialization.StringSerializer",
            "value.serializer", "org.apache.kafka.common.serialization.StringSerializer"
        ));

        // Initialize Prometheus metrics
        DefaultExports.initialize();
        latencyGauge = Gauge.build()
            .name("event_processing_latency_ms")
            .help("Latency of event processing in milliseconds")
            .register();

        throughputGauge = Gauge.build()
            .name("events_processed_per_second")
            .help("Throughput of events processed per second")
            .register();
    }

    public void processEvents() {
        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                // Perform complex transformations and aggregations
                String processedEvent = transformAndAggregate(record.value());

                // Deliver processed results to downstream consumers
                producer.send(new ProducerRecord<>("processed-events-topic", processedEvent));

                // Update metrics
                latencyGauge.set(System.currentTimeMillis() - record.timestamp());
            }
        }
    }

    private String transformAndAggregate(String event) {
        // Implement complex transformations and aggregations logic here
        return "Processed: " + event;
    }

    public void shutdown() {
        consumer.close();
        producer.close();
    }

    public static void main(String[] args) {
        EventProcessingPipeline pipeline = new EventProcessingPipeline("localhost:9092", "raw-events-topic");
        Runtime.getRuntime().addShutdownHook(new Thread(pipeline::shutdown));
        pipeline.processEvents();
    }
