#define MAX_NODES 5000
#define TOTAL_MEMORY 2 * 1024 * 1024 // 2MB

typedef struct node {
    long id;
    char name[256];
    struct node* next;
    time_t timestamp;
    bool status;
    unsigned int checksum;
} Node;

Node* root = NULL;
int current_id = 0;
size_t allocated_memory = 0;

unsigned int calculate_checksum(Node* node) {
    // Implement a simple checksum calculation
    return (unsigned int)(node->id + strlen(node->name) + node->status);
}

void validate_checksum(Node* node) {
    unsigned int expected_checksum = calculate_checksum(node);
    if (node->checksum != expected_checksum) {
        fprintf(stderr, "Checksum validation failed for node ID: %ld\n", node->id);
    }
}

Node* create_node(const char* name, bool status) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    new_node->id = current_id++;
    strcpy(new_node->name, name);
    new_node->next = root;
    new_node->timestamp = time(NULL);
    new_node->status = status;
    new_node->checksum = calculate_checksum(new_node);

    validate_checksum(new_node);
    allocated_memory += sizeof(Node);

    if (allocated_memory > TOTAL_MEMORY) {
        fprintf(stderr, "Memory limit exceeded\n");
        free(new_node);
        return NULL;
    }

    root = new_node;
    return new_node;
}

