    OctreeNode* children[8];
    OctreeNode() : data(""), children{nullptr} {}
};

void initializeOctree(int featureSize, int numLeafNodes, size_t dataCapacity) {
    OctreeNode* root = new OctreeNode();
    root->children[0] = new OctreeNode();
    root->children[1] = new OctreeNode();
    // Initialize other children similarly...

    std::ifstream file("data.txt");
    if (!file.is_open()) {
        std::cerr << "Failed to open file!" << std::endl;
        return;
    }

    std::string line;
    while (std::getline(file, line)) {
        size_t length = line.length();
        char* buffer = new char[length + 1];
        strcpy(buffer, line.c_str());

        // Process the line and compute the average of the last two fields
        std::istringstream iss(buffer);
        std::vector<std::string> fields;
        std::string field;
        while (std::getline(iss, field, ',')) {
            fields.push_back(field);
        }

        if (fields.size() < 3) {
            delete[] buffer;
            continue;
        }

        double lastField = std::stod(fields[fields.size() - 1]);
        double secondLastField = std::stod(fields[fields.size() - 2]);
        double average = (lastField + secondLastField) / 2;

        // Append the average to the line
        std::ostringstream oss;
        for (size_t i = 0; i < fields.size(); ++i) {
            if (i > 0) oss << ",";
            oss << fields[i];
        }
        oss << "," << average;
        root->data += oss.str() + "\n";

        delete[] buffer;
    }

    file.close();
}

int main() {
    initializeOctree(3, 8, 1024);
    // Additional code to use the octree can be added here
    return 0;
}
