} SIGNALLING_QUEUE;

SIGNALLING_QUEUE* init_signaling_queue(int capacity) {
    SIGNALLING_QUEUE *queue = (SIGNALLING_QUEUE*)malloc(sizeof(SIGNALLING_QUEUE));
    queue->messages = (SIGNALING_MESSAGE*)calloc(capacity, sizeof(SIGNALING_MESSAGE));
    queue->capacity = capacity;
    queue->size = 0;
    sem_init(&queue->semaphore, 0, capacity);
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}

void enqueue_signaling_message(SIGNALLING_QUEUE *queue, SIGNALING_MESSAGE message) {
    sem_wait(&queue->semaphore);
    pthread_mutex_lock(&queue->mutex);
    if (queue->size < queue->capacity) {
        queue->messages[queue->size++] = message;
    }
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->semaphore);
}

SIGNALING_MESSAGE dequeue_signaling_message(SIGNALLING_QUEUE *queue) {
    SIGNALING_MESSAGE message;
    memset(&message, 0, sizeof(message));
    sem_wait(&queue->semaphore);
    pthread_mutex_lock(&queue->mutex);
    if (queue->size > 0) {
        memcpy(&message, &queue->messages[--queue->size], sizeof(SIGNALING_MESSAGE));
    }
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->semaphore);
    return message;
}

void free_signaling_queue(SIGNALLING_QUEUE *queue) {
    free(queue->messages);
    sem_destroy(&queue->semaphore);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}
