#include <sys/stat.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

#define MAX_DEPTH 20
#define MAX_THREADS 10

typedef struct {
    char* path;
    int depth;
    pthread_mutex_t mutex;
} DirectoryData;

typedef struct {
    sqlite3* db;
    pthread_mutex_t db_mutex;
} GlobalState;

GlobalState global_state = {NULL, PTHREAD_MUTEX_INITIALIZER};

void* process_directory(void* arg) {
    DirectoryData* data = (DirectoryData*)arg;
    DIR* dir = opendir(data->path);
    if (!dir) {
        perror("opendir");
        return NULL;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_name[0] == '.' || S_ISLNK(entry->st_mode)) continue;

        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", data->path, entry->d_name);

        struct stat file_stat;
        if (stat(full_path, &file_stat) != 0) {
            perror("stat");
            continue;
        }

        pthread_mutex_lock(&data->mutex);
        // Aggregate line counts and total size
        // ...
        pthread_mutex_unlock(&data->mutex);

        if (S_ISDIR(file_stat.st_mode) && data->depth < MAX_DEPTH - 1) {
            DirectoryData sub_dir = {full_path, data->depth + 1};
            process_directory((void*)&sub_dir);
        }
    }

    closedir(dir);
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory> [output_file]\n", argv[0]);
        return 1;
    }

    sqlite3* db;
    int rc = sqlite3_open("metadata.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return 1;
    }

    pthread_mutex_lock(&global_state.db_mutex);
    global_state.db = db;

    pthread_t threads[MAX_THREADS];
    DirectoryData dirs[MAX_THREADS];
    int num_threads = 0;

    for (int i = 1; i < argc && num_threads < MAX_THREADS; ++i) {
        if (i == argc - 1) {
            // Handle output file separately
            continue;
        }

        dirs[num_threads].path = argv[i];
        dirs[num_threads].depth = 0;
        pthread_mutex_init(&dirs[num_threads].mutex, NULL);
        num_threads++;
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, process_directory, &dirs[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    sqlite3_close(global_state.db);

    return 0;
}
