    if (!da) return NULL;
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    da->retransmission_count = 0;
    da->next_rnti = 1; // Start from 1 to avoid zero
    return da;
}

void free_dynamic_array(DynamicArray* da) {
    if (da->array) free(da->array);
    free(da);
}

int add_to_dynamic_array(DynamicArray* da, uint16_t RNTI) {
    if (RNTI == 0 || RNTI > MAX_RNTI) return -1;
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 4;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return -1;
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size].RX_UE_INFORMATION_TAG = 0; // Simulate valid tag
    da->array[da->size].RNTI = RNTI;
    da->array[da->size].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    da->retransmission_count++;
    da->size++;
    return 0;
}

int remove_from_dynamic_array(DynamicArray* da, uint16_t RNTI) {
    for (size_t i = 0; i < da->size; i++) {
        if (da->array[i].RNTI == RNTI) {
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            da->retransmission_count--;
            da->size--;
            return 0;
        }
    }
    return -1; // RNTI not found
}

void iterate_dynamic_array(DynamicArray* da, void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (size_t i = 0; i < da->size; i++) {
        operation(da->array[i]);
    }
}

