    FILE* file = fopen(filename, "rb");
    if (!file) {
        return -1; // Error opening file
    }

    // Read the version and size of the serialized data
    uint32_t version;
    size_t size;
    fread(&version, sizeof(version), 1, file);
    fread(&size, sizeof(size), 1, file);

    // Allocate memory for the state object
    *state = (MoSTState*)malloc(size);
    if (!*state) {
        fclose(file);
        return -2; // Error allocating memory
    }

    // Read the serialized data into the state object
    size_t bytes_read = fread(*state, 1, size, file);
    if (bytes_read != size) {
        free(*state);
        fclose(file);
        return -3; // Error reading file
    }

    fclose(file);

    // Validate the version of the serialized data
    if (version != CURRENT_VERSION) {
        free(*state);
        return -4; // Version mismatch
    }

    return 0; // Success
}

