void optimizeStringHandler(char *str, size_t limit, bool optimized) {
    if (str == NULL || limit <= 0) {
        return;
    }

    if (!optimized) {
        if (strlen(str) < limit) {
            str = realloc(str, limit + 1);
            str[strlen(str)] = '/';
            str[strlen(str)] = '\0';
        }
    } else {
        size_t len = strlen(str);
        if (len < limit) {
            char *newStr = malloc(limit + 1);
            if (newStr != NULL) {
                strcpy(newStr, str);
                newStr[len] = '/';
                newStr[len + 1] = '\0';
                free(str);
                str = newStr;
            }
        }
    }
