#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct ResourcePool {
    sem_t *available;
    int initial_size;
    int max_size;
    int current_size;
    pthread_mutex_t lock;
} ResourcePool;

ResourcePool* create_resource_pool(int initial_size, int max_size) {
    ResourcePool *pool = (ResourcePool*) malloc(sizeof(ResourcePool));
    pool->initial_size = initial_size;
    pool->max_size = max_size;
    pool->current_size = initial_size;
    sem_init(&pool->available, 0, initial_size);
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_resource_pool(ResourcePool *pool) {
    sem_destroy(&pool->available);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int allocate_resource(ResourcePool *pool) {
    if (pool->current_size < pool->max_size) {
        sem_wait(&pool->available);
        pthread_mutex_lock(&pool->lock);
        pool->current_size++;
        pthread_mutex_unlock(&pool->lock);
        return 1;
    }
    return 0; // No more resources available
}

void deallocate_resource(ResourcePool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current_size > pool->initial_size) {
        pool->current_size--;
        sem_post(&pool->available);
    }
    pthread_mutex_unlock(&pool->lock);
}
```

This code snippet provides a basic implementation of a resource pool in C using threads and semaphores for synchronization. The `ResourcePool` structure contains a semaphore to manage available resources, mutexes for thread-safe operations, and variables to track the initial size, maximum size, and current size of the pool. The functions include initialization (`create_resource_pool`), destruction (`destroy_resource_pool`), allocation (`allocate_resource`), and deallocation (`deallocate_resource`).']

