    private JobExecutionState state;
    private List<ProcessingNode> activeNodes;
    private Map<String, ProcessingStage> stages;

    public DataProcessingPipeline(String clusterId) {
        this.clusterId = clusterId;
        this.state = JobExecutionState.IDLE;
        this.activeNodes = new ArrayList<>();
        this.stages = Collections.synchronizedMap(new HashMap<>());
    }

    public void addProcessingStage(String taskId, Map<String, Object> metadata, List<String> inputStreams, List<String> outputStreams) {
        ProcessingStage stage = new ProcessingStage(taskId, metadata, inputStreams, outputStreams);
        stages.put(taskId, stage);
    }

    public void updatePipelineState(JobExecutionState newState) {
        this.state = newState;
    }

    public void addActiveNode(ProcessingNode node) {
        activeNodes.add(node);
    }

    public void removeActiveNode(ProcessingNode node) {
        activeNodes.remove(node);
    }

    public List<ProcessingStage> getStages() {
        return new ArrayList<>(stages.values());
    }

    public JobExecutionState getState() {
        return state;
    }

    public List<ProcessingNode> getActiveNodes() {
        return Collections.unmodifiableList(activeNodes);
    }

    public static void main(String[] args) {
        DataProcessingPipeline pipeline = new DataProcessingPipeline("cluster-1");

        // Example usage
        pipeline.addProcessingStage("stage1", new HashMap<>(), Arrays.asList("input1"), Arrays.asList("output1"));
        pipeline.updatePipelineState(JobExecutionState.RUNNING);
        pipeline.addActiveNode(new ProcessingNode("node1"));
    }
}

class ProcessingStage {
    private final String taskId;
    private final Map<String, Object> metadata;
    private final List<String> inputStreams;
    private final List<String> outputStreams;

    public ProcessingStage(String taskId, Map<String, Object> metadata, List<String> inputStreams, List<String> outputStreams) {
        this.taskId = taskId;
        this.metadata = metadata;
        this.inputStreams = inputStreams;
        this.outputStreams = outputStreams;
    }

    // Getters and other methods
}

class ProcessingNode {
    private final String nodeId;

    public ProcessingNode(String nodeId) {
        this.nodeId = nodeId;
    }

    // Getters and other methods
}

enum JobExecutionState {
    IDLE, RUNNING, PAUSED, STOPPED
}
```

