public class MetricManager {
    private static final MetricManager INSTANCE = new MetricManager();
    private ConcurrentHashMap<String, AtomicInteger> counters;
    private ConcurrentHashMap<String, Integer> gauges;
    private ConcurrentHashMap<String, int[]> histograms;

    private MetricManager() {
        this.counters = new ConcurrentHashMap<>();
        this.gauges = new ConcurrentHashMap<>();
        this.histograms = new ConcurrentHashMap<>();
    }

    public static MetricManager getInstance() {
        return INSTANCE;
    }

    public void incrementCounter(String key) {
        counters.computeIfAbsent(key, k -> new AtomicInteger()).incrementAndGet();
    }

    public void setGauge(String key, int value) {
        gauges.put(key, value);
    }

    public void recordHistogramValue(String key, int value) {
        histograms.computeIfAbsent(key, k -> new int[100]).[value]++;
    }

    // Additional methods for real-time visualization, historical data analysis,
    // CSV/JSON export, and concurrent data collection handling.
}
