#include <iostream>
#include <map>
#include <mutex>
#include <dlfcn.h>

class LibraryManager {
private:
    std::map<std::string, void*> libraries;
    std::mutex mutex;

public:
    ~LibraryManager() {
        unloadAllLibraries();
    }

    bool loadLibrary(const std::string& name) {
        std::lock_guard<std::mutex> lock(mutex);
        if (libraries.find(name) != libraries.end()) {
            return true; // Library already loaded
        }
        void* handle = dlopen(name.c_str(), RTLD_LAZY | RTLD_GLOBAL);
        if (!handle) {
            std::cerr << "Failed to load library: " << dlerror() << std::endl;
            return false;
        }
        libraries[name] = handle;
        return true;
    }

    void* getSymbol(const std::string& name, const std::string& libName) {
        std::lock_guard<std::mutex> lock(mutex);
        if (libraries.find(libName) == libraries.end()) {
            loadLibrary(libName); // Attempt to load library
        }
        void* handle = libraries[libName];
        return dlsym(handle, name.c_str());
    }

    void unloadLibrary(const std::string& name) {
        std::lock_guard<std::mutex> lock(mutex);
        if (libraries.find(name) != libraries.end()) {
            dlclose(libraries[name]);
            libraries.erase(name);
        }
    }

    void unloadAllLibraries() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& pair : libraries) {
            dlclose(pair.second);
        }
        libraries.clear();
    }
};
