#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONCURRENT_QUERIES 10
#define TIMEOUT_SECONDS 5

typedef struct {
    char hostname[256];
    u_char ip[16]; // 16 bytes for IPv4 and IPv6
} DNSQuery;

sem_t query_semaphore;
pthread_mutex_t log_mutex;
int current_queries = 0;

void* dns_query_worker(void* arg) {
    DNSQuery* query = (DNSQuery*)arg;

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    sem_wait(&query_semaphore);
    current_queries++;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    status = getaddrinfo(query->hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        sem_post(&query_semaphore);
        current_queries--;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        memcpy(query->ip, addr, 16); // Copy the IP to the query structure

        printf("Resolved %s (%s): %s\n", query->hostname, ipver, ipstr);
        break;
    }

    freeaddrinfo(res);
    sem_post(&query_semaphore);
    current_queries--;

    return NULL;
}

int dns_query(char* hostname, u_char* ip) {
    DNSQuery query;
    memcpy(query.hostname, hostname, strlen(hostname));

    if (sem_trywait(&query_semaphore) == -1 && errno == EAGAIN) {
        printf("DNS resolution queue is full. Please try again later.\n");
        return -1; // Queue is full
    }

    pthread_t thread;
    int status = pthread_create(&thread, NULL, dns_query_worker, &query);
    if (status != 0) {
        fprintf(stderr, "Failed to create thread for DNS query: %d\n", status);
        sem_post(&query_semaphore);
        return -1; // Thread creation failed
    }

    if (pthread_detach(thread) != 0) {
        fprintf(stderr, "Failed to detach thread for DNS query.\n");
    }

    while (current_queries >= MAX_CONCURRENT_QUERIES) {
        sleep(1); // Wait until a slot becomes available
    }

    return 0; // Query started successfully
}

int main() {
    sem_init(&query_semaphore, 0, MAX_CONCURRENT_QUERIES);
    pthread_mutex_init(&log_mutex, NULL);

    u_char ip[16];
    if (dns_query("www.example.com", ip) == 0) {
        printf("DNS query started successfully.\n");
    }

    // Additional DNS queries can be made here

    sem_destroy(&query_semaphore);
    pthread_mutex_destroy(&log_mutex);

    return 0;
}
