#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RX_UE_INFORMATION_TAG 0x12345678
#define RNTI 0xABCD
#define CRC_INDICATION_REL8_TAG 0x9ABCDEF0

typedef struct {
    unsigned int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->count = 0;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->mutex);
        free(da);
    }
}

int resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    da->array = new_array;
    da->capacity = new_capacity;

    return 0;
}

int add_structure(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);

    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity == 0 ? 1 : da->capacity * 2;
        if (resize_dynamic_array(da, new_capacity) < 0) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *new_struct = &da->array[da->count];
    new_struct->crcflag = rand();

    da->count++;

    pthread_mutex_unlock(&da->mutex);

    return 0;
}

int get_memory_usage(DynamicArray *da, size_t *memory_used, size_t *total_capacity) {
    if (da) {
        pthread_mutex_lock(&da->mutex);

        *memory_used = da->count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        *total_capacity = da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        pthread_mutex_unlock(&da->mutex);

        return 0;
    }

    return -1;
}

// Example usage
int main() {
    DynamicArray *array = create_dynamic_array(1024);
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return 1;
    }

    for (size_t i = 0; i < 50000; i++) {
        if (add_structure(array) < 0) {
            fprintf(stderr, "Failed to add structure at index %zu\n", i);
            break;
        }
    }

    size_t memory_used, total_capacity;
    if (get_memory_usage(array, &memory_used, &total_capacity) == 0) {
        printf("Memory used: %zu bytes\n", memory_used);
        printf("Total capacity: %zu bytes\n", total_capacity);
    } else {
        fprintf(stderr, "Failed to get memory usage\n");
    }

    destroy_dynamic_array(array);

    return 0;
}
