typedef struct UeContext {
    int ue_id;
    char rrc_state[20];
    // List of active radio bearers with correct QoS parameters and security contexts
    struct UeContext *parent;
    struct UeContext *child;
    time_t timestamp;
    bool status_flag;
    long unique_id;
} UeContext;

typedef struct Node {
    struct UeContext *ue_context;
    long id;
    char name[50];
    struct Node *next;
    time_t timestamp;
    bool status_flag;
    unsigned int checksum;
} Node;

Node* create_node(UeContext *ue_context, long id, const char *name) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        return NULL;
    }
    new_node->ue_context = ue_context;
    new_node->id = id;
    strncpy(new_node->name, name, sizeof(new_node->name) - 1);
    new_node->next = NULL;
    new_node->timestamp = time(NULL);
    new_node->status_flag = true;
    // Calculate checksum (simplified for example)
    new_node->checksum = (unsigned int)new_node->id ^ (unsigned int)new_node->timestamp;
    return new_node;
}

void free_tree(Node *root) {
    if (!root) return;
    free_tree(root->next);
    free(root);
}

Node* insert_node(Node *root, Node *new_node) {
    if (!root) return new_node;
    Node *current = root;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
    return root;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

Node* export_tree_as_json(Node *root, bool include_attributes) {
    // Implementation to export tree as JSON
    return NULL;
}

int main() {
    UeContext ue_context = {12345, "RRC_CONNECTED"};
    Node *node = create_node(&ue_context, 1, "UE_001");
    if (node) {
        node = insert_node(NULL, node);
        free_tree(node);
    }
    return 0;
}
