function aggregateDataStream(records, options = {}) {
  const { batchSize = 1000, incrementalMode = false } = options;
  let buffer = Buffer.allocUnsafe(0);
  let totalRecords = 0;

  function processBuffer() {
    // Implement logic to parse and aggregate records from the buffer
    // Handle edge cases such as malformed records
    // Log errors using a robust error handling library like winston or pino
  }

  function handleRecord(record) {
    if (record.length > bufferSize || record.offset < 0) {
      throw new Error('Invalid record size or offset');
    }
    buffer = Buffer.concat([buffer, record]);
    totalRecords++;

    if (incrementalMode && totalRecords % batchSize === 0) {
      processBuffer();
