#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

void display_usage() {
    printf("Usage: program [options] [file]\n");
    printf("Options:\n");
    printf("  -h, --help          Display this help message\n");
    printf("  -c, --count         Output only the line count\n");
    printf("  -s, --summary       Provide a summary of the file content without line numbers\n");
    printf("  -o <file>, --output=<file> Redirect the output to a specified file\n");
}

int main(int argc, char *argv[]) {
    FILE *input_file = stdin;
    FILE *output_file = stdout;
    int line_count = 0;
    int count_only = 0;
    int summary_mode = 0;
    const char *output_filename = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            display_usage();
            return 0;
        } else if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count") == 0) {
            count_only = 1;
        } else if (strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--summary") == 0) {
            summary_mode = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0 || strncmp(argv[i], "--output=", 9) == 0) {
            output_filename = argv[i + 1];
            i++;
        } else if (i == argc - 1) {
            input_file = fopen(argv[i], "r");
            if (!input_file) {
                perror("Error opening file");
                return 1;
            }
        } else {
            fprintf(stderr, "Invalid argument: %s\n", argv[i]);
            display_usage();
            return 1;
        }
    }

    if (output_filename) {
        output_file = fopen(output_filename, "w");
        if (!output_file) {
            perror("Error opening output file");
            fclose(input_file);
            return 1;
        }
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, input_file)) {
        line_count++;
        if (!summary_mode) {
            fprintf(output_file, "%s", line);
        }
    }

    if (!count_only) {
        fprintf(output_file, "Total lines: %d\n", line_count);
    }

    fclose(input_file);
    if (output_filename) {
        fclose(output_file);
    }

    return 0;
}
```

