using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using Newtonsoft.Json;

public class GameConfigManager
{
    private Dictionary<string, object> _configurations;

    public GameConfigManager()
    {
        _configurations = new Dictionary<string, object>();
        LoadConfigurations();
    }

    private void LoadConfigurations()
    {
        var assembly = Assembly.GetExecutingAssembly();
        foreach (var file in Directory.GetFiles(assembly.Location, "*.json"))
        {
            try
            {
                var json = File.ReadAllText(file);
                var config = JsonConvert.DeserializeObject(json);
                _configurations[file] = config;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to load configuration from {file}: {ex.Message}");
            }
        }
    }

    public T GetConfiguration<T>(string configName) where T : class
    {
        if (_configurations.ContainsKey(configName))
        {
            return _configurations[configName] as T;
        }
        throw new KeyNotFoundException($"Configuration '{configName}' not found.");
    }

    public void UpdateConfiguration(string configName, object newConfig)
    {
        if (_configurations.ContainsKey(configName))
        {
            _configurations[configName] = newConfig;
        }
        else
        {
            throw new KeyNotFoundException($"Configuration '{configName}' not found.");
        }
    }
}

public class PlayerConfig
{
    public int HealthPoints { get; set; }
    // Other player settings...
}

public class WeaponConfig
{
    public Dictionary<string, int> DamageThresholds { get; set; }
    public Dictionary<string, float> CooldownTimes { get; set; }
    // Other weapon settings...
}

class Program
{
    static void Main(string[] args)
    {
        var configManager = new GameConfigManager();

        try
        {
            var playerConfig = configManager.GetConfiguration<PlayerConfig>("playerConfig.json");
            var weaponConfig = configManager.GetConfiguration<WeaponConfig>("weaponConfig.json");

            Console.WriteLine($"Player Health: {playerConfig.HealthPoints}");
            // Use weaponConfig to set up weapons...
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error accessing configuration: {ex.Message}");
        }

        // Example of updating a configuration at runtime
        var newWeaponConfig = new WeaponConfig
        {
            DamageThresholds = new Dictionary<string, int> { { "Sword", 10 } },
            CooldownTimes = new Dictionary<string, float> { { "Sword", 2.5f } }
        };
        configManager.UpdateConfiguration("weaponConfig.json", newWeaponConfig);

        // Retrieve and use updated weapon configuration...
    }
}
```

