void insertUeContext(UeContext** root, UeContext* newContext) {
    if (*root == NULL) {
        *root = newContext;
    } else {
        UeContext* temp = *root;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newContext;
    }
}

void deleteUeContext(UeContext** root, long id) {
    UeContext* current = *root;
    UeContext* previous = NULL;

    if (current == NULL) return; // Empty list

    if (current->id == id) {
        *root = current->next;
        free(current);
        return;
    }

    while (current != NULL && current->id != id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // ID not found

    previous->next = current->next;
    free(current);
}

UeContext* findUeContext(UeContext* root, long id) {
    UeContext* temp = root;
    while (temp != NULL) {
        if (temp->id == id) {
