typedef struct TreeNode {
    UEContext data;
    struct TreeNode* children[MAX_CHILDREN];
    int num_children;
    pthread_mutex_t lock;
} TreeNode;

TreeNode* createTreeNode(UEContext data) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    node->data = data;
    for (int i = 0; i < MAX_CHILDREN; i++) {
        node->children[i] = NULL;
    }
    node->num_children = 0;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void insertChild(TreeNode* parent, TreeNode* child) {
    if (parent == NULL || child == NULL) {
        // Handle error
        return;
    }
    pthread_mutex_lock(&parent->lock);
    if (parent->num_children < MAX_CHILDREN) {
        parent->children[parent->num_children++] = child;
    } else {
        // Handle maximum children reached
    }
    pthread_mutex_unlock(&parent->lock);
}

TreeNode* findNode(TreeNode* root, int ue_id) {
    if (root == NULL) {
        return NULL;
    }
    pthread_mutex_lock(&root->lock);
    for (int i = 0; i < root->num_children; i++) {
        if (root->children[i]->data.ue_id == ue_id) {
            pthread_mutex_unlock(&root->lock);
            return root->children[i];
        }
    }
    pthread_mutex_unlock(&root->lock);
    for (int i = 0; i < root->num_children; i++) {
        TreeNode* result = findNode(root->children[i], ue_id);
        if (result != NULL) {
            return result;
        }
    }
    return NULL;
}

void deleteNode(TreeNode** node) {
    if (*node == NULL) {
        return;
    }
    pthread_mutex_lock(&(*node)->lock);
    for (int i = 0; i < (*node)->num_children; i++) {
        deleteNode(&(*node)->children[i]);
    }
    pthread_mutex_unlock(&(*node)->lock);
    free(*node);
    *node = NULL;
}

void exportTreeAsJSON(TreeNode* root, FILE* file, int depth, int include_attributes) {
    // Implement JSON export logic here
