        perror("Failed to create thread");
        free(arg);
        return EXIT_FAILURE;
    }

    pthread_join(*((pthread_t*)arg), NULL);

    // Clean up and report total connections
    printf("Total connections initialized: %d\n", conn_count);

    // Additional cleanup code can be added here

    return EXIT_SUCCESS;
}
