        RX_UE_INFORMATION rxueinfo = { .RX_UE_INFORMATION_TAG = i, .RNTI = rand() % 65536 };
        CRC_INDICATION crcindication = { .CRC_INDICATION_REL8_TAG = i, .CRCFLAG = (rand() & 1) };

        strcpy(result[i].rxueinfo.RX_UE_INFORMATION_TAG, rxueinfo.RX_UE_INFORMATION_TAG);
        result[i].rxueinfo.RNTI = rxueinfo.RNTI;
        result[i].crcindication.CRC_INDICATION_REL8_TAG = crcindication.CRC_INDICATION_REL8_TAG;
        result[i].crcindication.CRCFLAG = crcindication.CRCFLAG;

        compute_md5(strings[i], result[i].md5_hash);

        ++successful_allocations;
    }

    printf("Total successful allocations: %d\n", successful_allocations);
    return result;
}
