// Assume media processing library headers are included here

typedef struct {
    int statusCode;
    char* message;
} CloudResponse;

typedef struct {
    char* filePath;
    void* metadata;
    char* cloudUrl;
    int resolutionWidth;
    int resolutionHeight;
} MediaUploadRequest;

CloudResponse processAndUploadMediaToCloud(MediaUploadRequest request) {
    // Initialize the CloudResponse object
    CloudResponse response;
    response.statusCode = 0;
    response.message = "Success";

    // Read binary content of the file
    FILE* file = fopen(request.filePath, "rb");
    if (file == NULL) {
        response.statusCode = -1;
        response.message = "Failed to open file";
        return response;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    void* mediaContent = malloc(fileSize);
    if (mediaContent == NULL) {
        fclose(file);
        response.statusCode = -1;
        response.message = "Memory allocation failed";
        return response;
    }

    fread(mediaContent, 1, fileSize, file);
    fclose(file);

    // Apply transformations based on metadata specifications
    if (!transformMedia(mediaContent, request.metadata)) {
        free(mediaContent);
        response.statusCode = -2;
        response.message = "Transformation failed";
        return response;
    }

    // Prepare the media upload request
    void* transformedMedia = prepareForUpload(mediaContent);

    // Upload the processed media to the cloud storage service
    if (!uploadToCloud(transformedMedia, request.cloudUrl, request.resolutionWidth, request.resolutionHeight)) {
        free(mediaContent);
        free(transformedMedia);
        response.statusCode = -3;
        response.message = "Upload failed";
        return response;
    }

    // Clean up resources
    free(mediaContent);
    free(transformedMedia);

    return response;
}

// Assume the following functions are defined elsewhere
bool transformMedia(void* media, void* metadata);
void* prepareForUpload(void* media);
bool uploadToCloud(void* media, char* url, int width, int height);
