#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CONNECTIONS 100
#define DEFAULT_TIMEOUT 5

typedef struct {
    int socket_id;
    int timeout;
    pthread_mutex_t lock;
} Connection;

Connection connection_pool[MAX_CONNECTIONS];
int pool_size = 0;
int current_connections = 0;
pthread_mutex_t pool_lock;

void initialize_connection_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_pool[i].socket_id = -1;
        connection_pool[i].timeout = DEFAULT_TIMEOUT;
        pthread_mutex_init(&connection_pool[i].lock, NULL);
    }
    pthread_mutex_init(&pool_lock, NULL);
}

int create_connection(int server_address, int timeout) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (connection_pool[i].socket_id == -1) {
            // Create and configure socket
            connection_pool[i].socket_id = socket(AF_INET, SOCK_STREAM, 0);
            connect(connection_pool[i].socket_id, (struct sockaddr*)&server_address, sizeof(server_address));
            connection_pool[i].timeout = timeout;
            current_connections++;
            pthread_mutex_unlock(&pool_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return -1; // No available connections
}

void destroy_connection(int index) {
    if (index >= 0 && index < pool_size && connection_pool[index].socket_id != -1) {
        pthread_mutex_lock(&connection_pool[index].lock);
        close(connection_pool[index].socket_id);
        connection_pool[index].socket_id = -1;
        current_connections--;
        pthread_mutex_unlock(&connection_pool[index].lock);
    }
}

void* manage_connection(void* arg) {
    int* session_index = (int*)arg;
    while (1) {
        // Simulate connection use
        sleep(1);
        destroy_connection(*session_index);
        *session_index = create_connection(get_server_address(), get_dynamic_timeout());
    }
}

int main() {
    initialize_connection_pool();

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, manage_connection, &i);
    }

    // Simulate system load and network conditions
    sleep(100);

    return 0;
}
```

