        connection_states[id].id = id;
        connection_states[id].state = state;
        connection_states[id].socket_descriptors = NULL;
        connection_states[id].socket_count = 0;
    }
}

void add_socket_descriptor(int id, int descriptor) {
    if (id >= 0 && id < MAX_CONNECTIONS) {
        int *new_descriptors = realloc(connection_states[id].socket_descriptors,
                                       (connection_states[id].socket_count + 1) * sizeof(int));
        if (new_descriptors != NULL) {
            connection_states[id].socket_descriptors = new_descriptors;
            connection_states[id].socket_descriptors[connection_states[id].socket_count] = descriptor;
            connection_states[id].socket_count++;
        }
    }
}

