void addCryptographicPrimitives() {
    // Initialize OpenSSL
    OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS, NULL);
    ENGINE_load_builtin_engines();
    ENGINE_register_all_complete();

    // Load configuration file
    CONF *conf = NCONF_new(NULL);
    if (!NCONF_load(conf, "crypto_config.conf", NULL)) {
        fprintf(stderr, "Error loading configuration file\n");
        return;
    }

    // Add AES primitive
    EVP_CIPHER *aes_cipher = EVP_aes_256_cbc();
    EVP_add_cipher(aes_cipher);

    // Add Camellia primitive
    EVP_CIPHER *camellia_cipher = EVP_camellia_256_cbc();
    EVP_add_cipher(camellia_cipher);

    // Add MD5 digest primitive
    EVP_MD *md5_digest = EVP_md5();
    EVP_add_digest(md5_digest);

    // Add SHA-1 digest primitive
    EVP_MD *sha1_digest = EVP_sha1();
    EVP_add_digest(sha1_digest);

    // Add RSA with SHA-1 primitive
    EVP_PKEY_CTX *rsa_ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, NULL);
    if (rsa_ctx == NULL) {
        fprintf(stderr, "Error creating RSA context\n");
        return;
    }
    EVP_PKEY_set_rsa_param(rsa_ctx, NCONF_get_string(conf, NULL, "RSA_KEY_SIZE"));
    EVP_PKEY_keygen_init(rsa_ctx);
    EVP_PKEY *rsa_key = EVP_PKEY_new();
    EVP_PKEY_generate_key_ex(rsa_ctx, rsa_key);

    // Clean up
    EVP_PKEY_free(rsa_key);
    EVP_PKEY_CTX_free(rsa_ctx);
    NCONF_free(conf);
}
