// Define encryption modes
enum EncryptionMode {
    ECB,
    EDE,
    EDE3,
    CFB
};

// Define key rotation interval (in seconds)
#define KEY_ROTATION_INTERVAL 3600

// Function to initialize the encryption library
void init_encryption_library() {
    // Initialize OpenSSL for AES encryption
    if (!OpenSSL_add_all_algorithms()) {
        fprintf(stderr, "Failed to load all algorithms\n");
        exit(EXIT_FAILURE);
    }
}

// Function to encrypt data using specified mode and key
int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                  const unsigned char *key, int key_len,
                  const unsigned char *iv, enum EncryptionMode mode,
                  unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len, ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    switch (mode) {
        case ECB:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, iv)) {
                break;
            }
            break;
        case EDE:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_ebc(), NULL, key, iv)) {
                break;
            }
            break;
        case EDE3:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, iv)) {
                break;
            }
            break;
        case CFB:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cfb128(), NULL, key, iv)) {
                break;
            }
            break;
    }

    // Encrypt the plaintext
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    // Finalize the encryption
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Encryption finalize failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using specified mode and key
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                  const unsigned char *key, int key_len,
                  const unsigned char *iv, enum EncryptionMode mode,
                  unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len, plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    switch (mode) {
        case ECB:
            if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, iv)) {
                break;
            }
            break;
        case EDE:
            if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_ebc(), NULL, key, iv)) {
                break;
            }
            break;
        case EDE3:
            if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, iv)) {
                break;
            }
            break;
        case CFB:
            if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cfb128(), NULL, key, iv)) {
                break;
            }
            break;
    }

    // Decrypt the ciphertext
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Decryption failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len = len;

    // Finalize the decryption
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        fprintf(stderr, "Decryption finalize failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Function to handle key rotation
void rotate_key(unsigned char *key) {
    if (!RAND_bytes(key, 32)) {
        fprintf(stderr, "Failed to generate random bytes for key\n");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char **argv) {
    // Example usage of the encryption library

    unsigned char key[32];
    unsigned char iv[16];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[100];
    unsigned char decryptedtext[100];

    init_encryption_library();

    if (!RAND_bytes(key, sizeof(key))) {
        fprintf(stderr, "Failed to generate random bytes for key\n");
        return EXIT_FAILURE;
    }

    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate random bytes for IV\n");
        return EXIT_FAILURE;
    }

    enum EncryptionMode mode = ECB;

    // Encrypt data
    int ciphertext_len = encrypt_data(plaintext, strlen((char *)plaintext),
                                     key, sizeof(key), iv, mode, ciphertext);
    if (ciphertext_len < 0) {
        return EXIT_FAILURE;
    }
    ciphertext[ciphertext_len] = '\0';

    // Decrypt data
    int decryptedtext_len = decrypt_data(ciphertext, ciphertext_len,
                                        key, sizeof(key), iv, mode, decryptedtext);
    if (decryptedtext_len < 0) {
        return EXIT_FAILURE;
    }
    decryptedtext[decryptedtext_len] = '\0';

    printf("Decrypted text: %s\n", decryptedtext);

    rotate_key(key);

    return EXIT_SUCCESS;
}
