#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define MAX_FD_POOL_SIZE 1024

typedef struct {
    int *fd_pool;
    size_t pool_size;
    size_t available_fds;
} FD_Pool;

FD_Pool* fd_pool_init(size_t initial_size) {
    FD_Pool *pool = (FD_Pool*)malloc(sizeof(FD_Pool));
    if (!pool) return NULL;

    pool->fd_pool = (int*)calloc(initial_size, sizeof(int));
    if (!pool->fd_pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->available_fds = initial_size;

    for(size_t i = 0; i < initial_size; ++i) {
        pool->fd_pool[i] = -1; // Assuming -1 indicates an available FD
    }

    return pool;
}

int fd_pool_open(FD_Pool *pool) {
    if (pool->available_fds == 0) return -1; // No available FDs

    for(size_t i = 0; i < pool->pool_size; ++i) {
        if (pool->fd_pool[i] == -1) {
            pool->fd_pool[i] = open("data.txt", "r");
            if (pool->fd_pool[i] == -1) return -1; // File opening failed
            --pool->available_fds;
            return i;
        }
    }

    return -1; // Should never reach here due to available_fds check
}

void fd_pool_close(FD_Pool *pool, int fd_index) {
    if (fd_index >= pool->pool_size || fd_index < 0 || pool->fd_pool[fd_index] == -1) return;

    close(pool->fd_pool[fd_index]);
    pool->fd_pool[fd_index] = -1; // Mark as available
    ++pool->available_fds;
}

void fd_pool_cleanup(FD_Pool *pool) {
    for(size_t i = 0; i < pool->pool_size; ++i) {
        if (pool->fd_pool[i] != -1) close(pool->fd_pool[i]);
    }

    free(pool->fd_pool);
    free(pool);
}
