#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>

// Function prototypes
void encrypt_data(const unsigned char *data, size_t data_len, const unsigned char *key, int key_len, const unsigned char *iv, unsigned char **encrypted_data, size_t *encrypted_data_len);
void decrypt_data(const unsigned char *encrypted_data, size_t encrypted_data_len, const unsigned char *key, int key_len, const unsigned char *iv, unsigned char **decrypted_data, size_t *decrypted_data_len);
void generate_mac(const unsigned char *data, size_t data_len, const unsigned char *key, unsigned char **mac, unsigned int *mac_len);
int verify_mac(const unsigned char *data, size_t data_len, const unsigned char *received_mac, size_t mac_len, const unsigned char *key);

int main(int argc, char *argv[]) {
    // Command-line argument processing and configuration
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <mode> <data> <key>\n", argv[0]);
        return 1;
    }

    const char *mode = argv[1];
    const unsigned char *data = (const unsigned char *)argv[2];
    int data_len = strlen((char *)data);
    const unsigned char *key = (const unsigned char *)argv[3];

    // Variable declarations
    unsigned char encrypted_data[data_len + EVP_MAX_BLOCK_LENGTH];
    size_t encrypted_data_len;
    unsigned char decrypted_data[data_len];
    size_t decrypted_data_len;
    unsigned char mac[HMAC_SIZE];
    unsigned int mac_len;

    // Encryption
    encrypt_data(data, data_len, key, strlen((char *)key), NULL, &encrypted_data, &encrypted_data_len);

    // MAC generation
    generate_mac(encrypted_data, encrypted_data_len, key, &mac, &mac_len);

    // Decryption and MAC verification
    decrypt_data(encrypted_data, encrypted_data_len, key, strlen((char *)key), NULL, &decrypted_data, &decrypted_data_len);
    if (!verify_mac(data, data_len, mac, mac_len, key)) {
        fprintf(stderr, "MAC verification failed!\n");
        return 1;
    }

    // Output results
    printf("Original Data: %s\n", data);
    printf("Decrypted Data: %s\n", decrypted_data);

    return 0;
}

// Encrypt data using the specified mode and key
void encrypt_data(const unsigned char *data, size_t data_len, const unsigned char *key, int key_len, const unsigned char *iv, unsigned char **encrypted_data, size_t *encrypted_data_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context!\n");
        return;
    }

    int len;
    int ciphertext_len;

    // Initialize encryption
    if (strcmp(mode, "ECB") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL);
    } else if (strcmp(mode, "EDE") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
    } else if (strcmp(mode, "EDE3") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_192_ecb(), NULL, key, NULL);
    } else if (strcmp(mode, "CFB") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cfb128(), NULL, key, iv);
    } else {
        fprintf(stderr, "Unsupported encryption mode!\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Encrypt data
    EVP_EncryptUpdate(ctx, *encrypted_data, &len, data, data_len);
    ciphertext_len = len;

    // Finalize encryption
    EVP_EncryptFinal_ex(ctx, (*encrypted_data + len), &len);
    ciphertext_len += len;

    *encrypted_data_len = ciphertext_len;
    EVP_CIPHER_CTX_free(ctx);
}

// Decrypt data using the specified mode and key
void decrypt_data(const unsigned char *encrypted_data, size_t encrypted_data_len, const unsigned char *key, int key_len, const unsigned char *iv, unsigned char **decrypted_data, size_t *decrypted_data_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context!\n");
        return;
    }

    int len;
    int decrypted_text_len;

    // Initialize decryption
    if (strcmp(mode, "ECB") == 0) {
        EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL);
    } else if (strcmp(mode, "EDE") == 0) {
        EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
    } else if (strcmp(mode, "EDE3") == 0) {
        EVP_DecryptInit_ex(ctx, EVP_aes_192_ecb(), NULL, key, NULL);
    } else if (strcmp(mode, "CFB") == 0) {
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cfb128(), NULL, key, iv);
    } else {
        fprintf(stderr, "Unsupported encryption mode!\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Decrypt data
    EVP_DecryptUpdate(ctx, *decrypted_data, &len, encrypted_data, encrypted_data_len);
    decrypted_text_len = len;

    // Finalize decryption
    EVP_DecryptFinal_ex(ctx, (*decrypted_data + len), &len);
    decrypted_text_len += len;

    *decrypted_data_len = decrypted_text_len;
    EVP_CIPHER_CTX_free(ctx);
}

// Generate HMAC-SHA256 for the given data and key
void generate_mac(const unsigned char *data, size_t data_len, const unsigned char *key, unsigned char **mac, unsigned int *mac_len) {
    *mac_len = SHA256_DIGEST_LENGTH;
    *mac = (unsigned char *)malloc(*mac_len);
    HMAC(EVP_sha256(), key, strlen((char *)key), data, data_len, *mac, mac_len);
}

// Verify HMAC-SHA256 for the given data and received MAC
int verify_mac(const unsigned char *data, size_t data_len, const unsigned char *received_mac, size_t mac_len, const unsigned char *key) {
    if (mac_len != SHA256_DIGEST_LENGTH) {
        return 0;
    }

    unsigned char calculated_mac[SHA256_DIGEST_LENGTH];
    HMAC(EVP_sha256(), key, strlen((char *)key), data, data_len, calculated_mac, &mac_len);

    return memcmp(received_mac, calculated_mac, mac_len) == 0;
}
