#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void print_usage() {
    printf("Usage: program [options] [file]\n");
    printf("Options:\n");
    printf("  -h, --help          Display usage information\n");
    printf("  -c, --count         Output only the line count\n");
    printf("  -s, --summary       Provide a summary of the file content without line numbers\n");
    printf("  -o <file>, --output=<file> Redirect the output to a specified file\n");
}

int main(int argc, char *argv[]) {
    // Parse command line arguments
    int count = 0;
    int summary = 0;
    const char *output_file = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count") == 0) {
            count = 1;
        } else if (strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--summary") == 0) {
            summary = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0 || strncmp(argv[i], "--output=", 9) == 0) {
            output_file = argv[i][0] == '-' ? &argv[i][3] : &argv[i][9];
        }
    }

    // Check for file argument
    if (argc < 2) {
        print_usage();
        return 1;
    }

    const char *filename = argc > 2 ? argv[2] : NULL;

    // Open input file
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    // Process file
    long line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
        if (!summary) {
            printf("%s", buffer);
        }
    }

    // Output results
    if (count || summary) {
        if (output_file) {
            FILE *out = fopen(output_file, "w");
            if (!out) {
                perror("Error opening output file");
                fclose(file);
                return 1;
            }
            fprintf(out, "%ld\n", line_count);
            fclose(out);
        } else {
            printf("%ld\n", line_count);
        }
    }

    // Close file
    fclose(file);

    return 0;
}
