int current_index = 0;

int init_ue_context(int id) {
    if (current_index >= MAX_UE_CONTEXTS) {
        return -1; // Error: Maximum number of UE contexts reached
    }

    UeContext* new_context = (UeContext*)malloc(sizeof(UeContext));
    if (!new_context) {
        return -2; // Error: Memory allocation failed
    }

    new_context->id = id;
    new_context->rrc_state = RRC_IDLE;

    ue_contexts[current_index++] = new_context;
    return 0; // Success
}

void free_ue_context(int id) {
    for (int i = 0; i < current_index; i++) {
        if (ue_contexts[i]->id == id) {
            free(ue_contexts[i]);
            ue_contexts[i] = NULL;
            for (; i < current_index - 1; i++) {
                ue_contexts[i] = ue_contexts[i + 1];
            }
            current_index--;
            break;
        }
    }
}

void update_ue_context(int id, RrcState new_state) {
    for (int i = 0; i < current_index; i++) {
        if (ue_contexts[i]->id == id) {
            ue_contexts[i]->rrc_state = new_state;
            break;
        }
    }
}

