#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Entry* next;
} Entry;

typedef struct {
    pthread_mutex_t lock;
    Entry* head;
    size_t count;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        Entry* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(DynamicList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (list->count >= MAX_ENTRIES) return -1;

    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) return -2;

    new_entry->pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->pdu.RNTI = RNTI;
    new_entry->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (RNTI % 2 == 0) ? 1 : 0;

    pthread_mutex_lock(&list->lock);
    new_entry->next = list->head;
    list->head = new_entry;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void clear_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        Entry* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}
