// Initialize the dynamic list with a given maximum capacity
void initDynamicList(DynamicList *list, size_t maxCapacity) {
    list->nodes = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = maxCapacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add an item to the dynamic list
int addToList(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    list->nodes[list->size++] = item;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Clear the dynamic list
void clearList(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    memset(list->nodes, 0, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
}

