from flask import Flask, request, jsonify
import logging

app = Flask(__name__)

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger()

user_profiles = {}
user_locks = {}

@app.route('/profile', methods=['PUT'])
def update_profile():
    user_id = request.args.get('id')
    if user_id not in user_profiles:
        return jsonify({"error": "User profile not found"}), 404
    data = request.json
    with user_locks[user_id]:
        user_profiles[user_id].update(data)
    logger.info(f"Updated user profile: {user_id}")
    return jsonify(user_profiles[user_id])

@app.route('/profiles', methods=['DELETE'])
def delete_profiles():
    user_ids = request.args.getlist('id')
    deleted_count = 0
    for user_id in user_ids:
        if user_id in user_profiles:
            with user_locks[user_id]:
                del user_profiles[user_id]
                deleted_count += 1
                logger.info(f"Deleted user profile: {user_id}")
    return jsonify({"deleted": deleted_count})

@app.route('/find_max', methods=['POST'])
def find_max():
    numbers = request.json.get('numbers')
    if not numbers:
        return jsonify({"error": "No numbers provided"}), 400
    max_value = find_largest_integer(numbers)
    return jsonify({"max_value": max_value})

def find_largest_integer(numbers):
    max_value = max(numbers)
    logger.info(f"Found largest integer: {max_value}")
    return max_value

if __name__ == '__main__':
    for user_id in range(1, 101):  # Initialize with some profiles
        user_profiles[user_id] = {"name": f"User{user_id}", "age": 25}
        user_locks[user_id] = threading.Lock()
    app.run(debug=True)
