#include <iostream>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <condition_variable>

struct ContentObject {
    int id;
    time_t expirationTime;
    std::vector<std::string> regions;
};

class DistributedCacheManager {
public:
    void addContent(const ContentObject& content) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[content.id] = content;
        cv_.notify_all();
    }

    bool getContent(int id, ContentObject& content) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (cache_.find(id) == cache_.end()) {
            cv_.wait(lock);
        }
        if (cache_[id].expirationTime <= time(nullptr)) {
            return false; // Cache expired
        }
        content = cache_[id];
        return true;
    }

    void updateContent(int id, const ContentObject& newContent) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(id);
        if (it != cache_.end()) {
            it->second = newContent;
            cv_.notify_all();
        }
    }

private:
    std::unordered_map<int, ContentObject> cache_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    DistributedCacheManager manager;

    // Example usage
    ContentObject content1 = {1, time(nullptr) + 3600, {"US", "Canada"}};
    manager.addContent(content1);

    ContentObject retrievedContent;
    if (manager.getContent(1, retrievedContent)) {
        std::cout << "Content retrieved successfully!" << std::endl;
    } else {
        std::cout << "Content retrieval failed or expired." << std::endl;
    }

    return 0;
}
```

