#include <dlfcn.h>

class DynamicModuleManager {
public:
    struct ModuleConfig {
        std::string path;
        std::map<std::string, std::string> parameters;
    };

    struct ModuleInfo {
        void* handle;
        std::map<std::string, std::string> attributes;
    };

    DynamicModuleManager() {}

    ~DynamicModuleManager() {
        for (auto& module : loadedModules) {
            dlclose(module.second.handle);
        }
    }

    bool loadModule(const std::string& moduleName, const ModuleConfig& config) {
        auto handle = dlopen(config.path.c_str(), RTLD_LAZY);
        if (!handle) {
            std::cerr << "Failed to load module: " << dlerror() << std::endl;
            return false;
        }

        void* initFunc = dlsym(handle, "initializeModule");
        if (!initFunc) {
            dlclose(handle);
            std::cerr << "Failed to find initialization function for module: " << config.path << std::endl;
            return false;
        }

        ModuleInfo info{handle, {}};
        // Call the initialization function with configuration parameters
        auto init = reinterpret_cast<void (*)(const std::map<std::string, std::string>&)>(initFunc);
        init(config.parameters);

        loadedModules[moduleName] = info;
        return true;
    }

    void unloadModule(const std::string& moduleName) {
        if (loadedModules.find(moduleName) != loadedModules.end()) {
            dlclose(loadedModules[moduleName].handle);
            loadedModules.erase(moduleName);
        }
    }

    ModuleInfo* getModuleInfo(const std::string& moduleName) {
        auto it = loadedModules.find(moduleName);
        if (it != loadedModules.end()) {
            return &it->second;
        }
        return nullptr;
    }

private:
    std::map<std::string, ModuleInfo> loadedModules;
};
