struct Resource {
    std::time_t lastUsageTime;
    bool isAvailable;
    // Add type-specific attributes here
};

class ResourcePool {
public:
    ResourcePool(int size) : pool(size), availableSemaphore(size) {}

    void allocateResource() {
        availableSemaphore.acquire();
        auto& resource = pool[allocatedCount++];
        resource.lastUsageTime = std::time(nullptr);
        resource.isAvailable = false;
        // Initialize type-specific attributes
    }

    bool reserveResource() {
        if (availableSemaphore.try_acquire()) {
            auto& resource = pool[allocatedCount++];
            resource.lastUsageTime = std::time(nullptr);
            resource.isAvailable = false;
            // Initialize type-specific attributes
            return true;
        }
        return false;
    }

    void cancelReservation(int index) {
        if (index < allocatedCount && !pool[index].isAvailable) {
            availableSemaphore.release();
            pool[index].isAvailable = true;
        }
    }

    void deallocateResource(int index) {
        if (index >= 0 && index < allocatedCount && !pool[index].isAvailable) {
            availableSemaphore.release();
            pool[index].isAvailable = true;
        }
    }

    // Add methods for monitoring usage and availability statistics

private:
    std::vector<Resource> pool;
    std::counting_semaphore<> availableSemaphore;
    int allocatedCount = 0;

    // Helper method to initialize resource pool based on configuration settings
    void loadConfiguration(const pugi::xml_document& doc) {
        auto tileNode = doc.child("tile");
        tileSize = {tileNode.attribute("width").as_int(), tileNode.attribute("height").as_int()};

        auto worldNode = doc.child("world");
        worldSize = {worldNode.attribute("width").as_int(), worldNode.attribute("height").as_int()};
    }
};

int main() {
    pugi::xml_document configDoc;
    configDoc.load_file("config.xml");

    ResourcePool resourcePool(10);
    resourcePool.loadConfiguration(configDoc);

    std::thread t1([&resourcePool]() {
        for (int i = 0; i < 5; ++i) {
            resourcePool.allocateResource();
            std::this_thread::sleep_for(std::chrono::seconds(1));
            resourcePool.deallocateResource(i);
        }
    });

    std::thread t2([&resourcePool]() {
        if (resourcePool.reserveResource()) {
            std::this_thread::sleep_for(std::chrono::seconds(3));
            resourcePool.cancelReservation(0);
        }
    });

    t1.join();
    t2.join();

    return 0;
}
```

