#include <vector>
#include <memory>
#include <mutex>
#include <unordered_map>

class Module {
public:
    virtual ~Module() {}
    virtual void init() = 0;
    virtual void cleanup() = 0;
};

class ModuleLoader {
private:
    std::unordered_map<std::string, std::shared_ptr<Module>> modules;
    std::mutex mutex;

public:
    void loadModule(const std::string& name, std::shared_ptr<Module> module) {
        std::lock_guard<std::mutex> lock(mutex);
        if (modules.find(name) != modules.end()) {
            throw std::runtime_error("Module already loaded");
        }
        modules[name] = module;
    }

    void unloadModule(const std::string& name) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = modules.find(name);
        if (it == modules.end()) {
            throw std::runtime_error("Module not found");
        }
        it->second->cleanup();
        modules.erase(it);
    }

    Module* getModule(const std::string& name) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = modules.find(name);
        if (it == modules.end()) {
            throw std::runtime_error("Module not found");
        }
        return it->second.get();
    }

    void initAllModules() {
        for (auto& [name, module] : modules) {
            try {
                module->init();
            } catch (...) {
                unloadModule(name);
                throw;
            }
        }
    }

    void cleanupAllModules() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& [name, module] : modules) {
            module->cleanup();
        }
        modules.clear();
    }
};

class ThirdPartyLibrary : public Module {
public:
    ThirdPartyLibrary(const std::string& config) {
        // Initialize third-party library with config
    }

    void init() override {
        // Initialize the library
    }

    void cleanup() override {
        // Cleanup the library
    }
};

int main() {
    ModuleLoader loader;
    auto module = std::make_shared<ThirdPartyLibrary>("config_file.txt");
    loader.loadModule("third_party_lib", module);
    loader.initAllModules();
    // Use the loaded modules...
    loader.cleanupAllModules();
    return 0;
}
```

