DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (da == NULL) {
        return NULL; // Allocation failure
    }
    da->capacity = initial_capacity;
    da->count = 0;
    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (da->array == NULL) {
        free(da);
        return NULL; // Allocation failure
    }
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    free(da);
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

int add_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity == 0 ? 1 : da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Allocation failure
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->count++] = item;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

