#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_CONCURRENT_INSTANCES 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CRC_Indication_Queue;

CRC_Indication_Queue* create_queue(size_t initial_capacity) {
    CRC_Indication_Queue *queue = (CRC_Indication_Queue*)malloc(sizeof(CRC_Indication_Queue));
    if (!queue) return NULL;

    queue->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->array) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);

    return queue;
}

void destroy_queue(CRC_Indication_Queue *queue) {
    free(queue->array);
    free(queue);
}

int enqueue(CRC_Indication_Queue *queue, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }

    if (queue->size >= MAX_CONCURRENT_INSTANCES) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Queue limit reached
    }

    queue->array[queue->size++] = *item;
    pthread_cond_signal(&queue->not_empty);

    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int dequeue(CRC_Indication_Queue *queue, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }

    *item = queue->array[--queue->size];
    pthread_cond_signal(&queue->not_full);

    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int serialize_queue(CRC_Indication_Queue *queue, FILE *file) {
    pthread_mutex_lock(&queue->mutex);

    // Serialize queue size
    if (fwrite(&queue->size, sizeof(size_t), 1, file) != 1) {
        pthread_mutex_unlock(&queue->mutex);
        return -1;
    }

    // Serialize each item in the queue
    for (size_t i = 0; i < queue->size; i++) {
        if (fwrite(&queue->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            pthread_mutex_unlock(&queue->mutex);
            return -1;
        }
    }

    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int deserialize_queue(CRC_Indication_Queue *queue, FILE *file) {
    size_t size;
    if (fread(&size, sizeof(size_t), 1, file) != 1 || size > MAX_CONCURRENT_INSTANCES) {
        return -1; // Invalid data
    }

    pthread_mutex_lock(&queue->mutex);

    if (size > queue->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(queue->array, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&queue->mutex);
            return -1;
        }
        queue->array = new_array;
        queue->capacity = size;
    }

    // Deserialize each item into the queue
    for (size_t i = 0; i < size; i++) {
        if (fread(&queue->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            pthread_mutex_unlock(&queue->mutex);
            return -1;
        }
    }

    queue->size = size;

    pthread_mutex_unlock(&queue->mutex);
    return 0;
}
