#include <map>
#include <dlfcn.h>
#include <vector>
#include <string>
#include <fstream>

class LibraryManager {
public:
    LibraryManager() {}
    ~LibraryManager();

    void setVerbosityLevel(int level);
    void addSearchPath(const std::string& path);
    void setDefaultFallbackLibs(const std::vector<std::string>& libs);

    bool loadLibrary(const std::string& name, const std::string& version);
    bool unloadLibrary(const std::string& name, const std::string& version);

private:
    std::mutex mtx;
    std::map<std::pair<std::string, std::string>, void*> libraries;
    int verbosityLevel = 0;
    std::vector<std::string> searchPaths;
    std::vector<std::string> defaultFallbackLibs;

    void log(const std::string& message);
    void* findLibraryInPath(const std::string& name, const std::string& version);
};

LibraryManager::~LibraryManager() {
    unloadAllLibraries();
}

void LibraryManager::setVerbosityLevel(int level) {
    verbosityLevel = level;
}

void LibraryManager::addSearchPath(const std::string& path) {
    searchPaths.push_back(path);
}

void LibraryManager::setDefaultFallbackLibs(const std::vector<std::string>& libs) {
    defaultFallbackLibs = libs;
}

bool LibraryManager::loadLibrary(const std::string& name, const std::string& version) {
    std::lock_guard<std::mutex> lock(mtx);

    auto it = libraries.find(std::make_pair(name, version));
    if (it != libraries.end()) {
        log("Library " + name + "@" + version + " is already loaded.");
        return true;
    }

    void* handle = findLibraryInPath(name, version);
    if (!handle) {
        for (const auto& fallback : defaultFallbackLibs) {
            handle = findLibraryInPath(fallback, version);
            if (handle) break;
        }
    }

    if (handle) {
        libraries[std::make_pair(name, version)] = handle;
        log("Successfully loaded library " + name + "@" + version);
        return true;
    } else {
        log("Failed to load library " + name + "@" + version);
        return false;
    }
}

bool LibraryManager::unloadLibrary(const std::string& name, const std::string& version) {
    std::lock_guard<std::mutex> lock(mtx);

    auto it = libraries.find(std::make_pair(name, version));
    if (it == libraries.end()) {
        log("Library " + name + "@" + version + " is not loaded.");
        return false;
    }

    dlclose(it->second);
    libraries.erase(it);
    log("Successfully unloaded library " + name + "@" + version);
    return true;
}

void LibraryManager::log(const std::string& message) {
    if (verbosityLevel > 0) {
        std::cout << message << std::endl;
    }
}

void* LibraryManager::findLibraryInPath(const std::string& name, const std::string& version) {
    for (const auto& path : searchPaths) {
        std::string fullPath = path + "/" + name + "@" + version + ".so";
        void* handle = dlopen(fullPath.c_str(), RTLD_LAZY);
        if (handle) return handle;
    }
    return nullptr;
}

void LibraryManager::unloadAllLibraries() {
    std::lock_guard<std::mutex> lock(mtx);

    for (const auto& lib : libraries) {
        dlclose(lib.second);
    }

    libraries.clear();
}
