#include <mutex>
#include <unordered_map>
#include <list>
#include <thread>
#include <chrono>
#include <atomic>

class UserActivityLog {
public:
    int userID;
    std::chrono::system_clock::time_point lastActivity;
    std::vector<std::string> interactions;
    bool isActive;

    UserActivityLog(int id, const std::chrono::system_clock::time_point& time, const std::vector<std::string>& interactions, bool active)
        : userID(id), lastActivity(time), interactions(interactions), isActive(active) {}
};

class UserActivityManager {
private:
    std::unordered_map<int, std::list<UserActivityLog>::iterator> activityMap;
    std::list<UserActivityLog> activities;
    std::mutex mtx;
    std::atomic<bool> running;
    std::thread cleanupThread;

    void cleanupInactiveUsers() {
        auto now = std::chrono::system_clock::now();
        while (running) {
            {
                std::lock_guard<std::mutex> lock(mtx);
                activities.remove_if([&now](const UserActivityLog& log) {
                    return now - log.lastActivity > std::chrono::days(7) && !log.isActive;
                });
                activityMap.erase(std::remove_if(activityMap.begin(), activityMap.end(),
                                                [&activities](const std::pair<int, std::list<UserActivityLog>::iterator>& p) {
                                                    return activities.empty();
                                                }),
                                 activityMap.end());
            }
            std::this_thread::sleep_for(std::chrono::hours(1));
        }
    }

public:
    UserActivityManager() : running(true) {
        cleanupThread = std::thread(&UserActivityManager::cleanupInactiveUsers, this);
    }

    ~UserActivityManager() {
        running = false;
        if (cleanupThread.joinable()) {
            cleanupThread.join();
        }
    }

    void addOrUpdateUserActivity(const UserActivityLog& log) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = activityMap.find(log.userID);
        if (it != activityMap.end()) {
            activities.erase(it->second);
        }
        activities.push_front(log);
        activityMap[log.userID] = activities.begin();
    }

    UserActivityLog getUserActivity(int userID) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = activityMap.find(userID);
        if (it != activityMap.end()) {
            return *it->second;
        }
        throw std::runtime_error("User not found");
    }

    std::list<UserActivityLog> getActivitiesOlderThan(const std::chrono::system_clock::time_point& time) {
        std::lock_guard<std::mutex> lock(mtx);
        std::list<UserActivityLog> result;
        for (const auto& log : activities) {
            if (log.lastActivity < time) {
                result.push_back(log);
            }
        }
        return result;
    }

    void updateActivityStatus(int userID, bool isActive) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = activityMap.find(userID);
        if (it != activityMap.end()) {
            it->second->isActive = isActive;
        }
    }
};
