UEContext *ueContexts[MAX_UE_CONTEXTS];
pthread_mutex_t ueContextMutex;

void initUEContexts() {
    pthread_mutex_init(&ueContextMutex, NULL);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        ueContexts[i] = NULL;
    }
}

int createUEContext(int ueId) {
    pthread_mutex_lock(&ueContextMutex);
    int contextIndex = -1;
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ueContexts[i] == NULL) {
            contextIndex = i;
            break;
        }
    }
    if (contextIndex != -1) {
        ueContexts[contextIndex] = (UEContext *)malloc(sizeof(UEContext));
        ueContexts[contextIndex]->ueId = ueId;
        ueContexts[contextIndex]->rrcState = RRC_IDLE;
        ueContexts[contextIndex]->bearerCount = 0;
    }
    pthread_mutex_unlock(&ueContextMutex);
    return contextIndex;
}

int addRadioBearer(int contextIndex, int bearerId, int QoSParameters) {
    if (contextIndex >= 0 && contextIndex < MAX_UE_CONTEXTS && ueContexts[contextIndex] != NULL) {
        pthread_mutex_lock(&ueContextMutex);
        if (ueContexts[contextIndex]->bearerCount < MAX_RADIO_BEARERS) {
            RadioBearer *newBearer = &ueContexts[contextIndex]->activeBearers[ueContexts[contextIndex]->bearerCount];
            newBearer->bearerId = bearerId;
            newBearer->QoSParameters = QoSParameters;
            ueContexts[contextIndex]->bearerCount++;
        }
        pthread_mutex_unlock(&ueContextMutex);
        return 1;
    }
    return 0;
}

void updateRRCState(int contextIndex, RRCState newState) {
    if (contextIndex >= 0 && contextIndex < MAX_UE_CONTEXTS && ueContexts[contextIndex] != NULL) {
        pthread_mutex_lock(&ueContextMutex);
        ueContexts[contextIndex]->rrcState = newState;
        pthread_mutex_unlock(&ueContextMutex);
    }
}

void offloadInactiveUEContexts() {
