#define MAX_BUFFER_POOL_SIZE 1024

typedef struct {
    void* buffer;
    int is_available;
} Buffer;

Buffer buffer_pool[MAX_BUFFER_POOL_SIZE];
int pool_capacity = 0;
int total_allocations = 0;

void init_buffer_manager(int capacity, size_t block_size) {
    if (capacity > MAX_BUFFER_POOL_SIZE || capacity <= 0) return;
    for (int i = 0; i < capacity; ++i) {
        buffer_pool[i].buffer = malloc(block_size);
        if (!buffer_pool[i].buffer) return;
        buffer_pool[i].is_available = 1;
    }
    pool_capacity = capacity;
}

void* get_buffer() {
    for (int i = 0; i < pool_capacity; ++i) {
        if (buffer_pool[i].is_available) {
            buffer_pool[i].is_available = 0;
            return buffer_pool[i].buffer;
        }
    }
    return NULL; // No available buffers
}

void recycle_buffer(void* buffer) {
    for (int i = 0; i < pool_capacity; ++i) {
        if (buffer_pool[i].buffer == buffer) {
            buffer_pool[i].is_available = 1;
            break;
        }
    }
}

void reset_buffer_manager() {
    for (int i = 0; i < pool_capacity; ++i) {
        if (!buffer_pool[i].is_available) {
            free(buffer_pool[i].buffer);
            buffer_pool[i].buffer = malloc(pool_capacity); // Assuming block_size is constant
            if (buffer_pool[i].buffer) buffer_pool[i].is_available = 1;
        }
    }
}

int get_total_allocations() {
    return total_allocations;
}

void clean_up_buffer_manager() {
    for (int i = 0; i < pool_capacity; ++i) {
        free(buffer_pool[i].buffer);
    }
}
