#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 256 * 1024 * 1024 // 256 MB

typedef struct {
    char* user_id;
    double amount;
    time_t timestamp;
} Transaction;

int parse_csv(const char* filename, void (*process_transaction)(Transaction*, int)) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open CSV file");
        return -1;
    }

    size_t line_size = 256;
    char* line = malloc(line_size);
    if (!line) {
        perror("Failed to allocate memory for line buffer");
        fclose(file);
        return -2;
    }

    int transaction_count = 0;

    while (getline(&line, &line_size, file) != -1) {
        // Parse the CSV line into a Transaction structure
        // For simplicity, assume the format: user_id,amount,timestamp
        char* token = strtok(line, ",");
        if (!token) continue; // Skip empty lines

        Transaction transaction;
        transaction.user_id = strdup(token);
        token = strtok(NULL, ",");
        if (token) {
            transaction.amount = atof(token);
            token = strtok(NULL, ",");
            if (token) {
                transaction.timestamp = atol(token);

                if ((size_t)transaction_count * sizeof(Transaction) > MAX_MEMORY_LIMIT) {
                    fprintf(stderr, "Memory limit exceeded\n");
                    break;
                }

                process_transaction(&transaction, transaction_count++);
            }
        }
    }

    free(line);
    fclose(file);

    return transaction_count;
}

void print_transaction(const Transaction* t, int index) {
    printf("Transaction %d: UserID=%s, Amount=%.2f, Timestamp=%ld\n", 
           index, t->user_id, t->amount, t->timestamp);
}

int main() {
    const char* csv_filename = "transactions.csv";
    int result = parse_csv(csv_filename, print_transaction);

    if (result < 0) {
        fprintf(stderr, "Error processing CSV file\n");
    } else {
        printf("Processed %d transactions successfully\n", result);
    }

    return result;
}
```

