#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_ADDRESS_LENGTH 16

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    unsigned char ip[MAX_IP_ADDRESS_LENGTH];
    time_t last_accessed;
} DNSEntry;

typedef struct {
    DNSEntry *entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache *create_cache(size_t capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->entries = calloc(capacity, sizeof(DNSEntry));
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(LRUCache *cache) {
    free(cache->entries);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void insert_cache(LRUCache *cache, const char *hostname, unsigned char *ip) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; i++) {
        if (strcmp(cache->entries[i].hostname, hostname) == 0) {
            memcpy(cache->entries[i].ip, ip, MAX_IP_ADDRESS_LENGTH);
            cache->entries[i].last_accessed = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }
    for (size_t i = 0; i < cache->capacity; i++) {
        if (time(NULL) - cache->entries[i].last_accessed > time(NULL) - cache->entries[0].last_accessed) {
            memcpy(cache->entries[i].hostname, hostname, MAX_HOSTNAME_LENGTH);
            memcpy(cache->entries[i].ip, ip, MAX_IP_ADDRESS_LENGTH);
            cache->entries[i].last_accessed = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

unsigned char* get_ip_from_cache(LRUCache *cache, const char *hostname) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; i++) {
        if (strcmp(cache->entries[i].hostname, hostname) == 0) {
            cache->entries[i].last_accessed = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return cache->entries[i].ip;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

int resolve_hostname(const char *hostname, unsigned char *ip) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // Use IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &(ipv4->sin_addr), sizeof(struct in_addr));
        freeaddrinfo(res);
        return 0;
    }

    freeaddrinfo(res);
    return -1;
}

int dns_resolve(const char *hostname, unsigned char *ip) {
    static LRUCache *cache = create_cache(1024); // Example capacity
    unsigned char *cached_ip = get_ip_from_cache(cache, hostname);

    if (cached_ip != NULL) {
        memcpy(ip, cached_ip, MAX_IP_ADDRESS_LENGTH);
        return 0; // Success from cache
    }

    int status = resolve_hostname(hostname, ip);
    if (status == 0) {
        insert_cache(cache, hostname, ip);
    }
    return status;
}

int main() {
    unsigned char ip[MAX_IP_ADDRESS_LENGTH];
    const char *hostname = "www.example.com";

    if (dns_resolve(hostname, ip) == 0) {
        printf("IP address for %s: ", hostname);
        for (int i = 0; i < MAX_IP_ADDRESS_LENGTH; i++) {
            printf("%02x:", ip[i]);
        }
        printf("\n");
    } else {
        printf("Failed to resolve IP address for %s\n", hostname);
    }

    return 0;
}
```

