#define MAX_UE_CONTEXTS 1024

typedef struct {
    int ue_id;
    int rrc_state;
    int *radio_bearers;
    int bearer_count;
} LTE_UE_Context;

LTE_UE_Context *ue_contexts[MAX_UE_CONTEXTS];
sem_t mutex;
int context_count = 0;

void initialize_ue_context(int ue_id, int rrc_state) {
    if (context_count >= MAX_UE_CONTEXTS) {
        printf("Error: Maximum number of UE contexts reached.\n");
        return;
    }

    LTE_UE_Context *new_context = (LTE_UE_Context *)malloc(sizeof(LTE_UE_Context));
    new_context->ue_id = ue_id;
    new_context->rrc_state = rrc_state;
    new_context->radio_bearers = NULL;
    new_context->bearer_count = 0;

    sem_wait(&mutex);
    ue_contexts[context_count++] = new_context;
    sem_post(&mutex);

    printf("UE Context initialized for UE ID: %d\n", ue_id);
}

void update_ue_context(int ue_id, int rrc_state) {
    sem_wait(&mutex);
    for (int i = 0; i < context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            ue_contexts[i]->rrc_state = rrc_state;
            printf("UE Context updated for UE ID: %d\n", ue_id);
            break;
        }
    }
    sem_post(&mutex);
}

void add_radio_bearer(int ue_id, int bearer_id, int qos_params) {
    sem_wait(&mutex);
    for (int i = 0; i < context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            ue_contexts[i]->radio_bearers = realloc(ue_contexts[i]->radio_bearers, (ue_contexts[i]->bearer_count + 1) * sizeof(int));
            ue_contexts[i]->radio_bearers[ue_contexts[i]->bearer_count] = bearer_id;
            ue_contexts[i]->radio_bearers[ue_contexts[i]->bearer_count++] = qos_params;
            printf("Radio Bearer added for UE ID: %d\n", ue_id);
            break;
        }
    }
    sem_post(&mutex);
}

