#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pcap.h>

#define MAX_PACKET_SIZE 1500

typedef struct {
    time_t timestamp;
    int size;
    char protocol[20];
} packet_entry;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure based on actual NFAPI specification
} NFAPI_CRC_INDICATION_PDU_T;

void capture_and_process_packets(const char *interface, int duration, ...) {
    pcap_t *handle;
    char errbuf[PCAP_ERRBUF_SIZE];
    struct bpf_program fp;
    packet_entry *packet_list = NULL;
    int packet_count = 0;

    handle = pcap_open_live(interface, MAX_PACKET_SIZE, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", interface, errbuf);
        return;
    }

    if (pcap_compile(handle, &fp, "ip", 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", "ip", pcap_geterr(handle));
        return;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", "ip", pcap_geterr(handle));
        return;
    }

    while (duration > 0) {
        struct pcap_pkthdr header;
        const u_char *packet = pcap_next(handle, &header);

        if (packet == NULL) continue;

        // Process packet and populate packet_entry
        packet_entry new_packet;
        new_packet.timestamp = time(NULL);
        new_packet.size = header.len;
        strcpy(new_packet.protocol, "IP"); // Simplified for example

        // Add packet to packet_list if not duplicate
        int is_duplicate = 0;
        for (int i = 0; i < packet_count; i++) {
            if (packet_list[i].timestamp == new_packet.timestamp &&
                packet_list[i].size == new_packet.size) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            packet_list = realloc(packet_list, (packet_count + 1) * sizeof(packet_entry));
            memcpy(&packet_list[packet_count], &new_packet, sizeof(packet_entry));
            packet_count++;
        }

        duration--;
    }

    // Process collected packets based on filtering criteria
    for (int i = 0; i < packet_count; i++) {
        printf("Timestamp: %ld, Size: %d, Protocol: %s\n", 
               packet_list[i].timestamp, packet_list[i].size, packet_list[i].protocol);
    }

    free(packet_list);
    pcap_freecode(&fp);
    pcap_close(handle);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <interface> <duration>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *interface = argv[1];
    int duration = atoi(argv[2]);

    capture_and_process_packets(interface, duration);

    return EXIT_SUCCESS;
}
