        if (i >= initial_capacity) {
            NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_array) {
                free(array);
                return NULL;
            }
            array = new_array;
        }

        // Initialize RX_UE_INFORMATION_TAG and RNTI within the valid range
        array[i].RX_UE_INFORMATION_TAG = i % 10; // Example initialization
        int rnti = MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1);
        if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
            free(array);
            return NULL;
        }
        array[i].RNTI = rnti;

        // Set CRC_INDICATION_REL8_TAG
        array[i].CRC_INDICATION_REL8_TAG = crcflag;
    }

    return array;
