} LTE_PHY_RX_FRAME_PDU_T;

typedef struct LTE_PHY_RX_BUFFER_T {
    LTE_PHY_RX_FRAME_PDU_T* frames;
    size_t capacity;
    size_t size;
} LTE_PHY_RX_BUFFER_T;

LTE_PHY_RX_BUFFER_T* create_buffer(size_t initial_capacity) {
    LTE_PHY_RX_BUFFER_T* buffer = (LTE_PHY_RX_BUFFER_T*)malloc(sizeof(LTE_PHY_RX_BUFFER_T));
    if (!buffer) return NULL;

    buffer->frames = (LTE_PHY_RX_FRAME_PDU_T*)malloc(initial_capacity * sizeof(LTE_PHY_RX_FRAME_PDU_T));
    if (!buffer->frames) {
        free(buffer);
        return NULL;
    }

    buffer->capacity = initial_capacity;
    buffer->size = 0;

    return buffer;
}

void destroy_buffer(LTE_PHY_RX_BUFFER_T* buffer) {
    if (buffer) {
        free(buffer->frames);
        free(buffer);
    }
}

int add_frame(LTE_PHY_RX_BUFFER_T* buffer, int UE_ID, int RSSI) {
    if (UE_ID < 0 || UE_ID > MAX_UE_ID) return -1;
    if (RSSI < MIN_RSSI) return -1;

    if (buffer->size >= buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        LTE_PHY_RX_FRAME_PDU_T* new_frames = (LTE_PHY_RX_FRAME_PDU_T*)realloc(buffer->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_PDU_T));
        if (!new_frames) return -1;

        buffer->frames = new_frames;
        buffer->capacity = new_capacity;
    }

    buffer->frames[buffer->size].UE_ID = UE_ID;
    buffer->frames[buffer->size].RSSI = RSSI;
    buffer->size++;

    return 0;
}

void correct_synchronization(LTE_PHY_RX_BUFFER_T* buffer) {
    for (size_t i = 1; i < buffer->size; i++) {
        if (buffer->frames[i].UE_ID != buffer->frames[i-1].UE_ID ||
            abs(buffer->frames[i].RSSI - buffer->frames[i-1].RSSI) > 5) {
            // Correct synchronization error
            printf("Synchronization error detected and corrected at index %zu\n", i);
            buffer->frames[i].UE_ID = buffer->frames[i-1].UE_ID;
            buffer->frames[i].RSSI = buffer->frames[i-1].RSSI;
        }
    }
}

// Example usage
