    LTE_PHY_RX_BUFFER_T* buffer = create_buffer(10);
    if (!buffer) return 1;

    add_frame(buffer, 123, -95);
    add_frame(buffer, 456, -98);
    // Add more frames as needed

    correct_synchronization(buffer);

    destroy_buffer(buffer);
    return 0;
