#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N, pthread_mutex_t *mutex) {
    if (N > 10000 || N <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    pthread_mutex_lock(mutex);

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            pthread_mutex_unlock(mutex);
            return head;
        }

        new_node->RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        new_node->RNTI = (i == 0) ? rand() % 1000 : ((current->RNTI + 1) % 1000); // Ensure no two consecutive RNTIs are the same
        new_node->CRCFLAG = (rand() % 2) != 0; // Randomly set CRCFLAG
        new_node->next = NULL;

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    pthread_mutex_unlock(mutex);
    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head, pthread_mutex_t *mutex) {
    pthread_mutex_lock(mutex);

    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(mutex);
}

