#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_DATASET_SIZE 1024 * 1024 * 1024 // 1 GB

typedef struct {
    int id;
    char data[MAX_DATASET_SIZE];
} DataItem;

typedef struct {
    DataItem items[MAX_DATASET_SIZE];
    int count;
    pthread_mutex_t lock;
} DataSet;

DataSet ds;

void initialize_dataset() {
    memset(&ds, 0, sizeof(ds));
    pthread_mutex_init(&ds.lock, NULL);
}

int add_data_item(int id, const char* data) {
    pthread_mutex_lock(&ds.lock);
    if (ds.count >= MAX_DATASET_SIZE) {
        pthread_mutex_unlock(&ds.lock);
        return -1; // Dataset is full
    }
    ds.items[ds.count].id = id;
    strncpy(ds.items[ds.count].data, data, sizeof(ds.items[ds.count].data));
    ds.count++;
    pthread_mutex_unlock(&ds.lock);
    return 0;
}

int get_data_item(int id, char* buffer, size_t buffer_size) {
    pthread_mutex_lock(&ds.lock);
    for (int i = 0; i < ds.count; i++) {
        if (ds.items[i].id == id) {
            strncpy(buffer, ds.items[i].data, buffer_size);
            pthread_mutex_unlock(&ds.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ds.lock);
    return -1; // Item not found
}

void update_data_item(int id, const char* data) {
    pthread_mutex_lock(&ds.lock);
    for (int i = 0; i < ds.count; i++) {
        if (ds.items[i].id == id) {
            strncpy(ds.items[i].data, data, sizeof(ds.items[i].data));
            break;
        }
    }
    pthread_mutex_unlock(&ds.lock);
}

void delete_data_item(int id) {
    pthread_mutex_lock(&ds.lock);
    for (int i = 0; i < ds.count; i++) {
        if (ds.items[i].id == id) {
            memmove(&ds.items[i], &ds.items[i + 1], sizeof(DataItem) * (ds.count - i - 1));
            ds.count--;
            break;
        }
    }
    pthread_mutex_unlock(&ds.lock);
}

void backup_dataset(const char* filename) {
    pthread_mutex_lock(&ds.lock);
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Failed to open file for backup");
        pthread_mutex_unlock(&ds.lock);
        return;
    }
    write(fd, &ds, sizeof(DataSet));
    close(fd);
    pthread_mutex_unlock(&ds.lock);
}

void recover_dataset(const char* filename) {
    pthread_mutex_lock(&ds.lock);
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open backup file");
        pthread_mutex_unlock(&ds.lock);
        return;
    }
    read(fd, &ds, sizeof(DataSet));
    close(fd);
    pthread_mutex_unlock(&ds.lock);
}

int main() {
    initialize_dataset();
    add_data_item(1, "Sample data 1");
    char buffer[MAX_DATASET_SIZE];
    get_data_item(1, buffer, sizeof(buffer));
    printf("Retrieved data: %s\n", buffer);
    update_data_item(1, "Updated data 1");
    delete_data_item(1);
    backup_dataset("dataset_backup.bin");
    recover_dataset("dataset_backup.bin");
    return 0;
}
