public class MessageBrokerClient
{
    private readonly ConnectionMultiplexer _redis;
    private readonly string _messageQueueKey;
    private readonly int _maxBatchSize = 100;
    private readonly TimeSpan _batchTimeout = TimeSpan.FromSeconds(5);
    private readonly int _retryAttempts = 3;
    private readonly TimeSpan _backoffFactor = TimeSpan.FromSeconds(2);

    public MessageBrokerClient(string redisConnectionString, string messageQueueKey)
    {
        _redis = ConnectionMultiplexer.Connect(redisConnectionString);
        _messageQueueKey = messageQueueKey;
    }

    public async Task<string> SendMessageAsync<T>(T payload)
    {
        var logContext = new LogContext { Event = "Send", Timestamp = DateTime.UtcNow };

        try
        {
            byte[] jsonBytes = JsonSerializer.SerializeToUtf8Bytes(payload);
            string messageId = Guid.NewGuid().ToString();

            logContext.Event = "Serialize";
            // Log structured message with custom metrics and events

            var batch = new List<byte[]>();
            batch.Add(jsonBytes);

            while (true)
            {
                logContext.Event = "BatchSend";
                // Log structured message with custom metrics and events

                await _redis.GetDatabase().ListRightPushAsync(_messageQueueKey, messageId);

                if (batch.Count == _maxBatchSize || DateTime.UtcNow - logContext.Timestamp > _batchTimeout)
                {
                    break;
                }

                await Task.Delay(100); // Throttle batch processing
            }

            logContext.Event = "Acknowledge";
            // Log structured message with custom metrics and events

            return messageId;
        }
        catch (Exception ex)
        {
            logContext.Event = "Error";
            logContext.Message = ex.Message;
            // Log structured error with custom metrics and events

            throw new Exception("Failed to send message", ex);
        }
    }

    private class LogContext
    {
        public string Event { get; set; }
        public DateTime Timestamp { get; set; }
        public string Message { get; set; }
    }
}
