} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

void init_nfaapi_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool add_nfaapi_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    list->list[list->count++] = item;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void clear_nfaapi_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i]->is_valid) {
            free(list->list[i]);
        }
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_nfaapi_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *item = list->list[index];
    pthread_mutex_unlock(&list->mutex);
    return item;
}
