using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;

public class RandomValueGenerator
{
    private Dictionary<string, RangeConfig> ranges = new Dictionary<string, RangeConfig>();

    public void AddRange(string name, float min, float max, bool includeMax)
    {
        if (ranges.ContainsKey(name))
        {
            throw new ArgumentException("Range already exists.");
        }
        ranges[name] = new RangeConfig(min, max, includeMax);
    }

    public void AddRange(string name, int min, int max, bool includeMax)
    {
        if (ranges.ContainsKey(name))
        {
            throw new ArgumentException("Range already exists.");
        }
        ranges[name] = new RangeConfig(min, max, includeMax);
    }

    public float GetRandomFloat(string rangeName)
    {
        if (!ranges.ContainsKey(rangeName))
        {
            throw new ArgumentException("Range does not exist.");
        }
        return ranges[rangeName].GetRandomFloat();
    }

    public int GetRandomInt(string rangeName)
    {
        if (!ranges.ContainsKey(rangeName))
        {
            throw new ArgumentException("Range does not exist.");
        }
        return ranges[rangeName].GetRandomInt();
    }

    public void ResetRange(string rangeName, float min = 0.0f, float max = 1.0f, bool includeMax = true)
    {
        if (!ranges.ContainsKey(rangeName))
        {
            throw new ArgumentException("Range does not exist.");
        }
        ranges[rangeName].Reset(min, max, includeMax);
    }

    public void ResetAllRanges()
    {
        foreach (var range in ranges.Values)
        {
            range.Reset(0.0f, 1.0f, true); // Default float range
        }
    }

    public void LoadRangesFromJson(string filePath)
    {
        try
        {
            string json = File.ReadAllText(filePath);
            var configs = JsonConvert.DeserializeObject<Dictionary<string, RangeConfig>>(json);

            foreach (var config in configs)
            {
                ranges[config.Key] = new RangeConfig(config.Value.Min, config.Value.Max, config.Value.IncludeMax);
            }
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to load range configurations.", ex);
        }
    }

    public override string ToString()
    {
        var sb = new System.Text.StringBuilder();
        foreach (var range in ranges)
        {
            sb.AppendLine($"{range.Key}: {range.Value}");
        }
        return sb.ToString();
    }
}

public class RangeConfig
{
    public float Min { get; set; }
    public float Max { get; set; }
    public bool IncludeMax { get; set; }

    public RangeConfig(float min, float max, bool includeMax)
    {
        Min = min;
        Max = max;
        IncludeMax = includeMax;
    }

    public float GetRandomFloat()
    {
        Random rnd = new Random();
        if (IncludeMax)
        {
            return rnd.NextFloat(Min, Max + 1);
        }
        else
        {
            return rnd.NextFloat(Min, Max);
        }
    }

    public int GetRandomInt()
    {
        Random rnd = new Random();
        if (IncludeMax)
        {
            return rnd.Next((int)Min, (int)(Max + 1));
        }
        else
        {
            return rnd.Next((int)Min, (int)Max);
        }
    }

    public void Reset(float min, float max, bool includeMax)
    {
        Min = min;
        Max = max;
        IncludeMax = includeMax;
    }

    public override string ToString()
    {
        return $"Range: {Min}-{(IncludeMax ? (Max + 1) : Max)}";
    }
}
