UeContext ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t ue_context_mutex;

void initialize_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_context_mutex);
    if (ue_id >= 0 && ue_id < MAX_UE_CONTEXTS) {
        ue_contexts[ue_id].ue_id = ue_id;
        ue_contexts[ue_id].rrc_state = RRC_IDLE;
        ue_contexts[ue_id].bearer_count = 0;
    }
    pthread_mutex_unlock(&ue_context_mutex);
}

void add_bearer_to_ue(int ue_id, int bearer_id) {
    pthread_mutex_lock(&ue_context_mutex);
    if (ue_id >= 0 && ue_id < MAX_UE_CONTEXTS && 
        bearer_id >= 0 && bearer_id < MAX_BEARERS_PER_UE &&
        ue_contexts[ue_id].bearer_count < MAX_BEARERS_PER_UE) {
        ue_contexts[ue_id].bearers[ue_contexts[ue_id].bearer_count].bearer_id = bearer_id;
        // Initialize QoS parameters and security context
        ue_contexts[ue_id].bearer_count++;
    }
    pthread_mutex_unlock(&ue_context_mutex);
}

void update_rrc_state(int ue_id, RrcState new_state) {
    pthread_mutex_lock(&ue_context_mutex);
    if (ue_id >= 0 && ue_id < MAX_UE_CONTEXTS) {
        ue_contexts[ue_id].rrc_state = new_state;
    }
    pthread_mutex_unlock(&ue_context_mutex);
}

UeContext* get_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_context_mutex);
    UeContext* context = NULL;
    if (ue_id >= 0 && ue_id < MAX_UE_CONTEXTS) {
        context = &ue_contexts[ue_id];
    }
    pthread_mutex_unlock(&ue_context_mutex);
    return context;
}

