#define MAX_CONNECTIONS 1024

typedef struct {
    int fd;
    char ip[16];
    int port;
} ConnectionContext;

void initialize_network_interface(ConnectionContext *contexts, int count) {
    for (int i = 0; i < count; ++i) {
        contexts[i].fd = -1;
        memset(contexts[i].ip, 0, sizeof(contexts[i].ip));
        contexts[i].port = 0;

        struct sockaddr_in addr;
        int server_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd == -1) {
            perror("socket creation failed");
            continue;
        }

        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(8080 + i);

        if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("bind failed");
            close(server_fd);
            continue;
        }

        if (listen(server_fd, 3) < 0) {
            perror("listen failed");
            close(server_fd);
            continue;
        }

        contexts[i].fd = server_fd;
        strcpy(contexts[i].ip, "127.0.0.1");
        contexts[i].port = ntohs(addr.sin_port);

        printf("Connection context %d initialized with IP: %s, Port: %d\n", i, contexts[i].ip, contexts[i].port);
    }
}

int main() {
    ConnectionContext *connections = (ConnectionContext *)malloc(MAX_CONNECTIONS * sizeof(ConnectionContext));
    if (!connections) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    initialize_network_interface(connections, MAX_CONNECTIONS);

    // Simulate handling connections
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (connections[i].fd != -1) {
            printf("Handling connection %d on IP: %s, Port: %d\n", i, connections[i].ip, connections[i].port);
            close(connections[i].fd);
        }
    }

    free(connections);
    return EXIT_SUCCESS;
}
