    redis_client.setex(user_id, 3600, str(data))  # Cache for 1 hour

    return jsonify(data), 200

@app.route('/delete_profiles', methods=['DELETE'])
def delete_profiles():
    user_ids = request.get_json()

    deleted_count = 0
    for user_id in user_ids:
        if redis_client.exists(user_id):
            redis_client.delete(user_id)
            deleted_count += 1

    # Log deletions for auditing purposes
    with open('deletions.log', 'a') as f:
        f.write(f'Deleted {deleted_count} profiles: {user_ids}\n')

