LTE_User_Mgmt_System* lte_init_user_mgmt_system(int max_users) {
    LTE_User_Mgmt_System *system = (LTE_User_Mgmt_System*)malloc(sizeof(LTE_User_Mgmt_System));
    system->ue_contexts = (LTE_UE_Context**)malloc(max_users * sizeof(LTE_UE_Context*));
    system->max_users = max_users;
    pthread_mutex_init(&system->mutex, NULL);
    return system;
}

void lte_free_user_mgmt_system(LTE_User_Mgmt_System *system) {
    for (int i = 0; i < system->max_users; i++) {
        if (system->ue_contexts[i] != NULL) {
            free(system->ue_contexts[i]->bearer_ids);
            free(system->ue_contexts[i]);
        }
    }
    free(system->ue_contexts);
    pthread_mutex_destroy(&system->mutex);
    free(system);
}

LTE_UE_Context* lte_create_ue_context(int ue_id, int rrc_state, int *bearer_ids, int num_bearers) {
