    pthread_mutex_lock(&system->mutex);
    for (int i = 0; i < system->max_users; i++) {
        if (system->ue_contexts[i] != NULL && system->ue_contexts[i]->ue_id == ue_id) {
            system->ue_contexts[i]->rrc_state = new_state;
            break;
        }
    }
    pthread_mutex_unlock(&system->mutex);
}

void lte_add_bearer(LTE_User_Mgmt_System *system, int ue_id, int bearer_id) {
    pthread_mutex_lock(&system->mutex);
    for (int i = 0; i < system->max_users; i++) {
        if (system->ue_contexts[i] != NULL && system->ue_contexts[i]->ue_id == ue_id) {
            system->ue_contexts[i]->bearer_ids = realloc(system->ue_contexts[i]->bearer_ids, (system->ue_contexts[i]->num_bearers + 1) * sizeof(int));
            system->ue_contexts[i]->bearer_ids[system->ue_contexts[i]->num_bearers] = bearer_id;
            system->ue_contexts[i]->num_bearers++;
            break;
        }
    }
    pthread_mutex_unlock(&system->mutex);
}

void lte_remove_bearer(LTE_User_Mgmt_System *system, int ue_id, int bearer_id) {
    pthread_mutex_lock(&system->mutex);
    for (int i = 0; i < system->max_users; i++) {
        if (system->ue_contexts[i] != NULL && system->ue_contexts[i]->ue_id == ue_id) {
            for (int j = 0; j < system->ue_contexts[i]->num_bearers; j++) {
                if (system->ue_contexts[i]->bearer_ids[j] == bearer_id) {
                    for (int k = j; k < system->ue_contexts[i]->num_bearers - 1; k++) {
                        system->ue_contexts[i]->bearer_ids[k] = system->ue_contexts[i]->bearer_ids[k + 1];
                    }
                    system->ue_contexts[i]->num_bearers--;
                    system->ue_contexts[i]->bearer_ids = realloc(system->ue_contexts[i]->bearer_ids, system->ue_contexts[i]->num_bearers * sizeof(int));
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&system->mutex);
}
