EVP_CIPHER_CTX* init_cipher(const char* cipher_name) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const EVP_CIPHER *cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

LTE_UE_Context* init_ue_context(int rrc_state, int num_bearers) {
    if (num_bearers <= 0 || num_bearers > MAX_UE_CONTEXTS) return NULL;

    LTE_UE_Context *ue_context = malloc(sizeof(LTE_UE_Context));
    if (!ue_context) return NULL;

    ue_context->rrc_context.rrc_state = rrc_state;
    ue_context->num_bearers = num_bearers;
    ue_context->bearers = malloc(num_bearers * sizeof(LTE_Bearer));
    if (!ue_context->bearers) {
        free(ue_context);
        return NULL;
