        EVP_CIPHER_CTX_cleanup(ctx->cipher_ctx);
        free(ctx);
        pthread_mutex_unlock(&mutex);
        return NULL; // Initialization failure
    }

    ue_contexts[ue_id] = ctx;

    pthread_mutex_unlock(&mutex);

    return ctx->cipher_ctx;
}

void clear_lte_ue_context(int ue_id) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) {
        return; // Invalid UE ID
    }

    pthread_mutex_lock(&mutex);

    if (ue_contexts[ue_id] != NULL) {
        EVP_CIPHER_CTX_cleanup(ue_contexts[ue_id]->cipher_ctx);
        free(ue_contexts[ue_id]);
        ue_contexts[ue_id] = NULL;
    }

    pthread_mutex_unlock(&mutex);
}
