#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef enum {
    ENCRYPT_MODE_ECB,
    ENCRYPT_MODE_EDE,
    ENCRYPT_MODE_EDE3,
    ENCRYPT_MODE_CFB,
    ENCRYPT_MODE_NULL
} EncryptionMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    EncryptionMode mode;
} CipherContext;

void init_cipher_context(CipherContext *ctx, EncryptionMode mode) {
    ctx->mode = mode;
    switch (mode) {
        case ENCRYPT_MODE_ECB:
            ctx->ctx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_ecb(), NULL, NULL, NULL);
            break;
        case ENCRYPT_MODE_EDE:
            // Initialize for triple DES EDE
            ctx->ctx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(ctx->ctx, EVP_des_ede3_cbc(), NULL, NULL, NULL);
            break;
        case ENCRYPT_MODE_EDE3:
            // Initialize for triple DES EDE3
            ctx->ctx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(ctx->ctx, EVP_des_ede3_cbc(), NULL, NULL, NULL);
            break;
        case ENCRYPT_MODE_CFB:
            ctx->ctx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cfb(), NULL, NULL, NULL);
            break;
        case ENCRYPT_MODE_NULL:
            // Initialize for null encryption
            ctx->ctx = NULL;
            break;
    }
}

void encrypt_data(CipherContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    switch (ctx->mode) {
        case ENCRYPT_MODE_ECB:
            EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
            break;
        case ENCRYPT_MODE_EDE:
            EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
            break;
        case ENCRYPT_MODE_EDE3:
            EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
            break;
        case ENCRYPT_MODE_CFB:
            EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
            break;
        case ENCRYPT_MODE_NULL:
            memcpy(ciphertext, plaintext, plaintext_len);
            ciphertext_len = plaintext_len;
            break;
    }
    EVP_EncryptFinal_ex(ctx->ctx, ciphertext + ciphertext_len, &ciphertext_len);
}

void free_cipher_context(CipherContext *ctx) {
    if (ctx->ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
    }
}

EncryptionMode parse_encryption_mode(const char *mode_str) {
    if (strcmp(mode_str, "ecb") == 0) return ENCRYPT_MODE_ECB;
    else if (strcmp(mode_str, "ede") == 0) return ENCRYPT_MODE_EDE;
    else if (strcmp(mode_str, "ede3") == 0) return ENCRYPT_MODE_EDE3;
    else if (strcmp(mode_str, "cfb") == 0) return ENCRYPT_MODE_CFB;
    else if (strcmp(mode_str, "null") == 0) return ENCRYPT_MODE_NULL;
    else return -1; // Invalid mode
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <mode> <data>\n", argv[0]);
        return 1;
    }

    EncryptionMode mode = parse_encryption_mode(argv[1]);
    if (mode == -1) {
        fprintf(stderr, "Invalid encryption mode\n");
        return 1;
    }

    CipherContext ctx;
    init_cipher_context(&ctx, mode);

    unsigned char key[32]; // Example key size
    unsigned char iv[16];  // Example IV size
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate random bytes\n");
        free_cipher_context(&ctx);
        return 1;
    }

    EVP_EncryptInit_ex(ctx.ctx, NULL, NULL, key, iv);

    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[sizeof(plaintext)];
    int ciphertext_len;

    encrypt_data(&ctx, plaintext, sizeof(plaintext), ciphertext);

    printf("Encrypted: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    free_cipher_context(&ctx);
    return 0;
}
```

This code snippet includes the core functionality of an encryption library in C, supporting ECB, EDE, EDE3, and CFB modes. It also demonstrates how to parse command-line arguments for selecting the encryption mode and performing basic encryption operations. The example uses OpenSSL for cryptographic functions, and it handles initialization, encryption, and cleanup of cipher contexts.']

