    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, thread->stack_size);
    pthread_setschedparam(thread->id, SCHED_FIFO, &(struct sched_param){.sched_priority = thread->priority});
    pthread_setaffinity_np(thread->id, sizeof(cpu_set_t), &thread->affinity_mask);

    // Main processing loop
    while (1) {
        // Process task
        sleep(1); // Placeholder for actual task processing logic

        // Check for failover conditions and resource constraints
        if (check_failover_conditions() || check_resource_constraints()) {
            // Request failover to backup pool or shut down gracefully
            break;
        }
    }

    pthread_exit(NULL);
}

void add_worker_thread(int index) {
    if (thread_count >= MAX_THREADS) {
        printf("Thread pool is full\n");
        return;
    }

    initialize_thread(&worker_threads[index], index);
    pthread_create(&worker_threads[index].id, NULL, worker_thread_function, &index);
    thread_count++;
}

void remove_worker_thread(int index) {
    if (index < 0 || index >= thread_count) {
        printf("Invalid thread index\n");
        return;
    }

    pthread_cancel(worker_threads[index].id);
    pthread_join(worker_threads[index].id, NULL);
    thread_count--;
}

