record* create_records(int num_records, int range) {
    if (num_records * sizeof(record) > MAX_MEMORY_LIMIT) {
        return NULL; // Exceeds memory limit
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % range;
    }
    return records;
}

void free_records(record* records) {
    if (records != NULL) {
        free(records);
    }
}

const char* get_algorithm_from_env() {
