#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Event {
    int id;
    time_t timestamp;
    char type[50];
    char payload[1024];
} Event;

typedef struct MessageQueueNode {
    Event event;
    struct MessageQueueNode* next;
} MessageQueueNode;

typedef struct MessageQueue {
    MessageQueueNode* head;
    MessageQueueNode* tail;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    int size;
    int capacity;
} MessageQueue;

void init_message_queue(MessageQueue* queue, int capacity) {
    queue->head = NULL;
    queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    queue->size = 0;
    queue->capacity = capacity;
}

void enqueue_event(MessageQueue* queue, Event event) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size >= queue->capacity) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    MessageQueueNode* new_node = (MessageQueueNode*)malloc(sizeof(MessageQueueNode));
    new_node->event = event;
    new_node->next = NULL;
    if (queue->tail == NULL) {
        queue->head = queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }
    queue->size++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

Event dequeue_event(MessageQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    Event event = queue->head->event;
    MessageQueueNode* old_head = queue->head;
    queue->head = old_head->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    free(old_head);
    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    return event;
}

void destroy_message_queue(MessageQueue* queue) {
    while (queue->head != NULL) {
        MessageQueueNode* temp = queue->head;
        queue->head = queue->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_empty);
}
```

