#include <functional>

class TimeSeriesDataProcessor {
public:
    struct DataStream {
        int id;
        std::function<void(const std::string&)> processData;
        int latencyTolerance;
    };

    TimeSeriesDataProcessor(int maxStreams) : maxStreams(maxStreams), running(true) {}

    ~TimeSeriesDataProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addDataStream(const DataStream& stream) {
        std::unique_lock<std::mutex> lock(mutex);
        dataStreams.push_back(stream);
        condition.notify_one();
    }

    void removeDataStream(int id) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = std::remove_if(dataStreams.begin(), dataStreams.end(), [id](const DataStream& stream) {
            return stream.id == id;
        });
        if (it != dataStreams.end()) {
            dataStreams.erase(it, dataStreams.end());
        }
        condition.notify_one();
    }

private:
    std::vector<std::thread> threads;
    std::queue<DataStream> workQueue;
    std::vector<DataStream> dataStreams;
    std::mutex mutex;
    std::condition_variable condition;
    bool running;
    int maxStreams;

    void workerThread() {
        while (true) {
            DataStream stream;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !workQueue.empty() || !running; });
                if (!running && workQueue.empty()) {
                    return;
                }
                stream = workQueue.front();
                workQueue.pop();
            }

            // Process data stream
            stream.processData("Sample Data");
        }
    }
};

int main() {
    TimeSeriesDataProcessor processor(10);

    processor.addDataStream({1, [](const std::string& data) { std::cout << "Processing data for stream 1: " << data << std::endl; }, 10});
    processor.addDataStream({2, [](const std::string& data) { std::cout << "Processing data for stream 2: " << data << std::endl; }, 5});

    for (int i = 3; i <= 10; ++i) {
        processor.addDataStream({i, [i](const std::string& data) { std::cout << "Processing data for stream " << i << ": " << data << std::endl; }, 20});
    }

    // Simulate adding and removing streams dynamically
    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.removeDataStream(3);
    processor.addDataStream({11, [](const std::string& data) { std::cout << "Processing data for stream 11: " << data << std::endl; }, 15});

    return 0;
}
