    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

TCPConnectionContext* add_tcp_context(TCPContextManager *manager, int connection_id, char *remote_ip, int port, time_t last_active, float latency, float packet_loss_rate, double throughput, void *metadata) {
    pthread_mutex_lock(&manager->lock);

    if (manager->current_size >= manager->max_size) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    TCPConnectionContext *context = (TCPConnectionContext*)malloc(sizeof(TCPConnectionContext));
    if (!context) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    context->connection_id = connection_id;
    context->remote_ip = strdup(remote_ip);
    context->port = port;
    context->last_active = last_active;
    context->latency = latency;
    context->packet_loss_rate = packet_loss_rate;
    context->throughput = throughput;
    context->metadata = metadata;

    // Insert into hash table or red-black tree here

    manager->contexts[manager->current_size++] = context;

    pthread_mutex_unlock(&manager->lock);
    return context;
}

void remove_tcp_context(TCPContextManager *manager, TCPConnectionContext *context) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->max_size; ++i) {
        if (manager->contexts[i] == context) {
            free(context->remote_ip);
            free(context);
            manager->contexts[i] = NULL;

            // Rehash or reorganize red-black tree here

            --manager->current_size;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

