// Define Network Interface Control Block structure
typedef struct {
    MAC_FRAME frame;
    L2_ADDRESS address;
    TX_STATS stats;
} NICB;

// Define MAC Statistics structure
typedef struct {
    // Statistics fields here
} MAC_STATS;

// Function to initialize NICB and MAC_STATS arrays dynamically
void init_network_interfaces(int num_interfaces, NICB **nicbs, MAC_STATS **mac_stats) {
    *nicbs = (NICB *)malloc(num_interfaces * sizeof(NICB));
    *mac_stats = (MAC_STATS *)malloc(num_interfaces * sizeof(MAC_STATS));

    for (int i = 0; i < num_interfaces; i++) {
        // Initialize each NICB structure
        init_mac_frame(&(*nicbs)[i].frame, &(*nicbs)[i].address);
        reset_tx_stats(&(*nicbs)[i].stats);

        // Initialize corresponding MAC_STATS structure
        init_mac_stats(&(*mac_stats)[i]);
    }
}

// Function to add a new interface at runtime
void add_interface(NICB **nicbs, MAC_STATS **mac_stats, int *num_interfaces) {
    NICB *new_nicbs = (NICB *)realloc(*nicbs, (*num_interfaces + 1) * sizeof(NICB));
    MAC_STATS *new_mac_stats = (MAC_STATS *)realloc(*mac_stats, (*num_interfaces + 1) * sizeof(MAC_STATS));

    if (new_nicbs == NULL || new_mac_stats == NULL) {
        // Handle memory allocation failure
        return;
    }

    *nicbs = new_nicbs;
    *mac_stats = new_mac_stats;

    // Initialize the new NICB and MAC_STATS structures
    init_mac_frame(&(*nicbs)[*num_interfaces].frame, &(*nicbs)[*num_interfaces].address);
    reset_tx_stats(&(*nicbs)[*num_interfaces].stats);
    init_mac_stats(&(*mac_stats)[*num_interfaces]);

    (*num_interfaces)++;
}

// Function to remove an interface at runtime
void remove_interface(NICB **nicbs, MAC_STATS **mac_stats, int *num_interfaces, int index) {
    if (index < 0 || index >= *num_interfaces) {
        // Handle invalid index
        return;
    }

    NICB *new_nicbs = (NICB *)realloc(*nicbs, (*num_interfaces - 1) * sizeof(NICB));
    MAC_STATS *new_mac_stats = (MAC_STATS *)realloc(*mac_stats, (*num_interfaces - 1) * sizeof(MAC_STATS));

    if (new_nicbs == NULL || new_mac_stats == NULL) {
        // Handle memory allocation failure
        return;
    }

    *nicbs = new_nicbs;
    *mac_stats = new_mac_stats;

    // Move remaining elements to fill the gap
    for (int i = index; i < *num_interfaces - 1; i++) {
        (*nicbs)[i] = (*nicbs)[i + 1];
        (*mac_stats)[i] = (*mac_stats)[i + 1];
    }

    (*num_interfaces)--;
}

// Function to handle concurrent access safely
pthread_mutex_t nicb_mutex = PTHREAD_MUTEX_INITIALIZER;
void safe_init_network_interfaces(int num_interfaces, NICB **nicbs, MAC_STATS **mac_stats) {
    pthread_mutex_lock(&nicb_mutex);
    init_network_interfaces(num_interfaces, nicbs, mac_stats);
    pthread_mutex_unlock(&nicb_mutex);
}

// Unit tests
