#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>

class ModuleLoader {
public:
    ModuleLoader() : _logLevel(LogLevel::INFO), _stopLoading(false) {}

    void setLogLevel(const std::string& level) {
        if (level == "DEBUG") _logLevel = LogLevel::DEBUG;
        else if (level == "INFO") _logLevel = LogLevel::INFO;
        else if (level == "WARNING") _logLevel = LogLevel::WARNING;
        else if (level == "ERROR") _logLevel = LogLevel::ERROR;
    }

    void loadModule(const std::string& moduleName, const std::vector<std::string>& dependencies) {
        std::lock_guard<std::mutex> lock(_mutex);
        _modules[moduleName] = std::make_shared<Module>(moduleName, dependencies);
        _moduleQueue.push(moduleName);
        _cond.notify_one();
    }

    void unloadModule(const std::string& moduleName) {
        std::lock_guard<std::mutex> lock(_mutex);
        auto it = _modules.find(moduleName);
        if (it != _modules.end()) {
            _modules.erase(it);
        }
        _cond.notify_one();
    }

    void startLoading() {
        _stopLoading = false;
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            _threads.emplace_back(&ModuleLoader::loadModules, this);
        }
    }

    void stopLoading() {
        std::lock_guard<std::mutex> lock(_mutex);
        _stopLoading = true;
        _cond.notify_all();
        for (auto& t : _threads) {
            if (t.joinable()) t.join();
        }
    }

private:
    enum class LogLevel { DEBUG, INFO, WARNING, ERROR };

    struct Module {
        Module(const std::string& name, const std::vector<std::string>& deps)
            : moduleName(name), dependencies(deps), loaded(false) {}

        std::string moduleName;
        std::vector<std::string> dependencies;
        bool loaded;
    };

    void loadModules() {
        while (true) {
            std::unique_lock<std::mutex> lock(_mutex);
            _cond.wait(lock, [this] { return !_moduleQueue.empty() || _stopLoading; });
            if (_stopLoading && _moduleQueue.empty()) break;
            auto moduleName = _moduleQueue.front();
            _moduleQueue.pop();
            lock.unlock();

            auto moduleIt = _modules.find(moduleName);
            if (moduleIt == _modules.end()) continue;

            if (!checkDependencies(moduleIt->second)) {
                log(LogLevel::ERROR, "Failed to load module due to dependency issues: " + moduleName);
                continue;
            }

            if (loadModuleImpl(moduleIt->second)) {
                log(LogLevel::INFO, "Module loaded successfully: " + moduleName);
            } else {
                log(LogLevel::WARNING, "Module loading failed, unloading: " + moduleName);
                unloadModule(moduleName);
            }
        }
    }

    bool checkDependencies(const std::shared_ptr<Module>& module) {
        for (const auto& dep : module->dependencies) {
            if (_modules.find(dep) == _modules.end()) {
                return false;
            }
        }
        return true;
    }

    bool loadModuleImpl(std::shared_ptr<Module>& module) {
        // Simulate module loading
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        module->loaded = true;
        return true;
    }

    void log(LogLevel level, const std::string& message) {
        if (level >= _logLevel) {
            std::cout << "[" << getLogLevelString(level) << "] " << message << std::endl;
        }
    }

    std::string getLogLevelString(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO:  return "INFO";
            case LogLevel::WARNING: return "WARNING";
            case LogLevel::ERROR:   return "ERROR";
        }
        return "";
    }

    std::mutex _mutex;
    std::condition_variable _cond;
    std::map<std::string, std::shared_ptr<Module>> _modules;
    std::queue<std::string> _moduleQueue;
    std::vector<std::thread> _threads;
    LogLevel _logLevel;
    std::atomic<bool> _stopLoading;
};
