public class CryptoHelper
{
    public static async Task<byte[]> EncryptAsync(string data, string algorithm, string key, string iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = Encoding.UTF8.GetBytes(key);
            aes.IV = Encoding.UTF8.GetBytes(iv);

            ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            byte[] encrypted;
            using (var msEncrypt = new System.IO.MemoryStream())
            {
                using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    using (var swEncrypt = new System.IO.StreamWriter(csEncrypt))
                    {
                        await swEncrypt.WriteAsync(data);
                    }
                    encrypted = msEncrypt.ToArray();
                }
            }

            return encrypted;
        }
    }

    public static byte[] HashData(string data, string algorithm)
    {
        byte[] hashBytes;

        using (var provider = GetHashAlgorithm(algorithm))
        {
            if (provider == null)
                throw new ArgumentException("Invalid hash algorithm.");

            hashBytes = provider.ComputeHash(Encoding.UTF8.GetBytes(data));
        }

        return hashBytes;
    }

    private static HashAlgorithm GetHashAlgorithm(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "md5":
                return MD5.Create();
            case "sha1":
                return SHA1.Create();
            case "sha256":
                return SHA256.Create();
            case "sha3":
                // Note: There is no built-in SHA-3 in .NET, you may need to use a third-party library.
                throw new NotSupportedException("SHA-3 is not supported.");
            default:
                return null;
        }
    }

    public static string GetEnvironmentSetting(string key, string defaultValue)
