{
    private const int MaxConcurrentRequests = 100;
    private readonly LruCache<string, byte[]> _cache = new LruCache<string, byte[]>(MaxConcurrentRequests);

    public async Task<byte[]> ResolveAsync(string hostname)
    {
        if (_cache.TryGetValue(hostname, out var ip))
            return ip;

        try
        {
            IPHostEntry hostEntry = await Dns.GetHostEntryAsync(hostname);
            byte[] ipAddressBytes = hostEntry.AddressList.FirstOrDefault()?.GetAddressBytes();
            _cache[hostname] = ipAddressBytes;
            Log($"Resolved {hostname} to {ipAddressBytes}");
            return ipAddressBytes;
        }
        catch (Exception ex)
        {
            Log($"Failed to resolve {hostname}: {ex.Message}");
            throw;
        }
    }

    private void Log(string message)
    {
        // Implement logging logic here.
        Console.WriteLine(message);
    }
}

public class LruCache<TKey, TValue>
{
    private readonly int _maxSize;
    private readonly Dictionary<TKey, TValue> _cache = new Dictionary<TKey, TValue>();

    public LruCache(int maxSize)
    {
        if (maxSize <= 0)
            throw new ArgumentException("Max size must be greater than zero.");

        _maxSize = maxSize;
    }

    public bool TryGetValue(TKey key, out TValue value)
    {
        if (_cache.TryGetValue(key, out value))
        {
            MoveToHead(key);
            return true;
        }
        return false;
    }

    public void AddOrUpdate(TKey key, TValue value)
    {
        if (_cache.ContainsKey(key))
        {
            _cache[key] = value;
            MoveToHead(key);
        }
        else
        {
            _cache.Add(key, value);

            if (_cache.Count > _maxSize)
            {
                var leastRecentlyUsedKey = _cache.Keys.First();
                _cache.Remove(leastRecentlyUsedKey);
            }
        }
    }

    private void MoveToHead(TKey key)
