#define MAX_RNTI 65535

typedef struct {
    int rx_ue_information_tag;
    unsigned short rnti;
    int crc_indication_rel8_tag;
} CustomStruct;

typedef struct {
    size_t max_memory_usage;
    int log_errors;
} ConfigStruct;

CustomStruct* allocateAndHashStringsAdvanced(int N, char** strings, ConfigStruct* config) {
    CustomStruct* result = NULL;
    size_t total_size = sizeof(CustomStruct) * N + N * MD5_DIGEST_LENGTH * sizeof(char);

    if (total_size > config->max_memory_usage) {
        if (config->log_errors) {
            fprintf(stderr, "Memory limit exceeded. Scaling down.\n");
        }
        N = config->max_memory_usage / (sizeof(CustomStruct) + MD5_DIGEST_LENGTH * sizeof(char));
        total_size = N * (sizeof(CustomStruct) + MD5_DIGEST_LENGTH * sizeof(char));
    }

    result = malloc(total_size);
    if (!result) {
        if (config->log_errors) {
            fprintf(stderr, "Memory allocation failed.\n");
        }
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        CustomStruct* current_struct = &result[i];
        unsigned char digest[MD5_DIGEST_LENGTH];

        MD5((unsigned char*)strings[i], strlen(strings[i]), digest);

        current_struct->rx_ue_information_tag = 1;
        current_struct->rnti = rand() % (MAX_RNTI + 1);
        current_struct->crc_indication_rel8_tag = rand() % 2;
    }

    return result;
}
