#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void addNode(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void freeList(Node** head) {
    Node* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

NFAPI_CRC_INDICATION_PDU_T generateRandomPDU() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
    return pdu;
}

void generatePDUList(int N, Node** head) {
    for (int i = 0; i < N; i++) {
        addNode(head, generateRandomPDU());
    }
}

// Example usage
int main() {
    srand(time(0));
    int N = 10; // Number of PDUs to generate
    Node* head = NULL;
    generatePDUList(N, &head);

    // Output for demonstration purposes
    Node* temp = head;
    while (temp != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", 
               temp->data.RX_UE_INFORMATION_TAG, 
               temp->data.RNTI, 
               temp->data.CRC_INDICATION_REL8_TAG);
        temp = temp->next;
    }

    freeList(&head);
    return 0;
}
