#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <unordered_map>

class TCPConnection {
public:
    std::string clientIP;
    bool status;
    std::vector<std::string> dataChannels;

    TCPConnection(const std::string& ip, bool connStatus)
        : clientIP(ip), status(connStatus) {}
};

class ConnectionPool {
private:
    std::mutex poolMutex;
    std::unordered_map<int, std::shared_ptr<TCPConnection>> connectionPool;
    int nextID = 0;

public:
    int allocate(const std::string& ip, bool connStatus) {
        std::lock_guard<std::mutex> lock(poolMutex);
        auto id = nextID++;
        connectionPool[id] = std::make_shared<TCPConnection>(ip, connStatus);
        return id;
    }

    void deallocate(int id) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (connectionPool.find(id) != connectionPool.end()) {
            connectionPool.erase(id);
        }
    }

    void updateStatus(int id, bool newStatus) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (auto conn = connectionPool.find(id)) {
            conn->second->status = newStatus;
        }
    }

    void addDataChannel(int id, const std::string& channel) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (auto conn = connectionPool.find(id)) {
            conn->second->dataChannels.push_back(channel);
        }
    }

    bool recoverFailedConnection(int id) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (auto conn = connectionPool.find(id)) {
            if (!conn->second->status) {
                conn->second->status = true;
                return true;
            }
        }
        return false;
    }

    TCPConnection* getConnection(int id) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (auto conn = connectionPool.find(id)) {
            return conn->second.get();
        }
        return nullptr;
    }
};

int main() {
    ConnectionPool pool;

    int id1 = pool.allocate("192.168.1.1", true);
    pool.addDataChannel(id1, "channel1");

    pool.updateStatus(id1, false);

    if (pool.recoverFailedConnection(id1)) {
        std::cout << "Connection recovered successfully." << std::endl;
    }

    TCPConnection* conn = pool.getConnection(id1);
    if (conn) {
        std::cout << "Client IP: " << conn->clientIP << ", Status: " << (conn->status ? "Connected" : "Disconnected") << std::endl;
    }

    pool.deallocate(id1);

    return 0;
}
