#define MAX_MESSAGE_SIZE 1024
#define NAS_MESSAGE_TYPE_COUNT 5

typedef struct {
    int type;
    char content[MAX_MESSAGE_SIZE];
} LTE_UPLINK_NAS_TRANSPORT;

typedef enum {
    MESSAGE_TYPE_1,
    MESSAGE_TYPE_2,
    MESSAGE_TYPE_3,
    MESSAGE_TYPE_4,
    MESSAGE_TYPE_5
} NAS_MESSAGE_TYPE;

void initializeAndValidateMessages(LTE_UPLINK_NAS_TRANSPORT** messages, int* count) {
    LTE_UPLINK_NAS_TRANSPORT* tempArray = (LTE_UPLINK_NAS_TRANSPORT*)malloc(NAS_MESSAGE_TYPE_COUNT * sizeof(LTE_UPLINK_NAS_TRANSPORT));
    if (!tempArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    NAS_MESSAGE_TYPE types[5] = {MESSAGE_TYPE_1, MESSAGE_TYPE_2, MESSAGE_TYPE_3, MESSAGE_TYPE_4, MESSAGE_TYPE_5};
    char payloads[][MAX_MESSAGE_SIZE] = {
        "Old Testament: Exodus 1",
        "Old Testament: Joshua 10",
        "Old Testament: Judges 12",
        "Old Testament: Ruth 1",
        "Old Testament: Samuel 1"
    };

    int uniqueCount = 0;
    for (int i = 0; i < NAS_MESSAGE_TYPE_COUNT; ++i) {
        int isUnique = 1;
        for (int j = 0; j < uniqueCount; ++j) {
            if (types[i] == tempArray[j].type) {
                isUnique = 0;
                break;
            }
        }

        if (isUnique && strlen(payloads[i]) <= MAX_MESSAGE_SIZE) {
            tempArray[uniqueCount].type = types[i];
            strcpy(tempArray[uniqueCount].content, payloads[i]);
            ++uniqueCount;
        }
    }

    *messages = realloc(tempArray, uniqueCount * sizeof(LTE_UPLINK_NAS_TRANSPORT));
    if (!*messages) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(tempArray);
        return;
    }

    *count = uniqueCount;
}

int main() {
    LTE_UPLINK_NAS_TRANSPORT* messages = NULL;
    int count;

    initializeAndValidateMessages(&messages, &count);

    for (int i = 0; i < count; ++i) {
        printf("Message Type: %d, Content: %s\n", messages[i].type, messages[i].content);
    }

    free(messages);

    return 0;
}
