#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_RESOURCES 10

typedef struct {
    int resources[MAX_RESOURCES];
    sem_t available;
    pthread_mutex_t mutex;
} ResourcePool;

void init_pool(ResourcePool *pool, int num_resources) {
    for (int i = 0; i < num_resources; i++) {
        pool->resources[i] = i + 1;
    }
    sem_init(&pool->available, 0, num_resources);
    pthread_mutex_init(&pool->mutex, NULL);
}

void request_resource(ResourcePool *pool) {
    sem_wait(&pool->available);
    pthread_mutex_lock(&pool->mutex);
    printf("Resource %d requested\n", pool->resources[sem_getvalue(&pool->available, NULL)]);
    // Remove the resource from the pool
    int index = sem_getvalue(&pool->available, NULL) + 1;
    pool->resources[index] = -1; // Mark as taken
    pthread_mutex_unlock(&pool->mutex);
}

void release_resource(ResourcePool *pool) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (pool->resources[i] == -1) {
            pool->resources[i] = i + 1;
            printf("Resource %d released\n", i + 1);
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    sem_post(&pool->available);
}

int main() {
    ResourcePool pool;
    init_pool(&pool, 5);

    // Example usage
    request_resource(&pool);
    release_resource(&pool);

    return 0;
}
