class FileSystemMonitor {
public:
    FileSystemMonitor(const std::vector<std::string>& directories, int pollingInterval)
        : directories(directories), pollingInterval(pollingInterval) {}

    void startMonitoring() {
        for (const auto& dir : directories) {
            threads.emplace_back(&FileSystemMonitor::monitorDirectory, this, dir);
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    std::vector<std::thread> threads;
    std::vector<Directory> directories;
    int pollingInterval;

    void monitorDirectory(const std::string& path) {
        while (true) {
            updateDirectoryInfo(path);
            generateAlerts(path);
            generateReport(path);
            std::this_thread::sleep_for(std::chrono::seconds(pollingInterval));
        }
    }

    void updateDirectoryInfo(const std::string& path) {
        Directory dir;
        dir.path = path;
        dir.lastModifiedTime = fs::last_write_time(path);
        dir.fileCount = 0;
        dir.totalSize = 0;

        for (const auto& entry : fs::directory_iterator(path)) {
            if (!entry.is_symlink()) {
                ++dir.fileCount;
                dir.totalSize += entry.status().file_size();
            }
        }

        directories.push_back(dir);
    }

    void generateAlerts(const std::string& path) {
        // Implement alert generation logic here
    }

    void generateReport(const std::string& path) {
        // Implement report generation logic here
    }
};

int main() {
    std::vector<std::string> directories = {"path/to/directory1", "path/to/directory2"};
