const int MAX_CONNECTIONS = 1024;
const int RNTI_RANGE_START = 1;
const int RNTI_RANGE_END = 4095;
const int MIN_CRCFLAG = 0;
const int MAX_CRCFLAG = 1;

struct ConnectionContext {
    std::string clientIP;
    bool isConnected;
    std::vector<int> dataChannels;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
};

class TCPConnectionManager {
public:
    TCPConnectionManager() : connectionPool(MAX_CONNECTIONS), crcIndicationPDUArray(MAX_CONNECTIONS) {}

    ConnectionContext* allocateConnection(const std::string& clientIP) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& context : connectionPool) {
            if (!context.isConnected) {
                context.clientIP = clientIP;
                context.isConnected = true;
                return &context;
            }
        }
        resizeConnectionPool();
        return allocateConnection(clientIP); // Retry after resizing
    }

    void deallocateConnection(ConnectionContext* context) {
        std::lock_guard<std::mutex> lock(mutex);
        context->clientIP.clear();
        context->isConnected = false;
    }

    NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateCRCIndicationPDU() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& pdu : crcIndicationPDUArray) {
            if (pdu.RX_UE_INFORMATION_TAG == 0 && pdu.CRC_INDICATION_REL8_TAG == MIN_CRCFLAG) {
                populateCRCIndicationPDU(&pdu);
                return &pdu;
            }
        }
        resizeCRCIndicationPDUArray();
