#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MESSAGE_SIZE 1024

typedef struct MESSAGE {
    int id;
    int priority;
    char payload[MAX_MESSAGE_SIZE];
    int status;
} MESSAGE;

typedef struct QUEUE_NODE {
    MESSAGE msg;
    struct QUEUE_NODE* next;
} QUEUE_NODE;

QUEUE_NODE* queue_head = NULL;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void enqueueAndProcessMessages(MESSAGE* messages, int count) {
    for (int i = 0; i < count; i++) {
        pthread_mutex_lock(&queue_lock);
        if (strlen(messages[i].payload) > MAX_MESSAGE_SIZE) {
            printf("Message %d exceeds maximum size. Skipping...\n", messages[i].id);
            pthread_mutex_unlock(&queue_lock);
            continue;
        }

        // Check message ID uniqueness
        QUEUE_NODE* current = queue_head;
        while (current != NULL) {
            if (current->msg.id == messages[i].id) {
                printf("Message %d is a duplicate. Skipping...\n", messages[i].id);
                pthread_mutex_unlock(&queue_lock);
                continue;
            }
            current = current->next;
        }

        // Enqueue message
        QUEUE_NODE* new_node = (QUEUE_NODE*)malloc(sizeof(QUEUE_NODE));
        if (new_node == NULL) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&queue_lock);
            return;
        }
        new_node->msg = messages[i];
        new_node->next = NULL;

        if (queue_head == NULL) {
            queue_head = new_node;
        } else {
            QUEUE_NODE* temp = queue_head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }

        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&queue_lock);

        // Process message (pseudo-code)
        printf("Processing message %d with priority %d\n", messages[i].id, messages[i].priority);
        // Simulate processing time
        sleep(1);
    }
}

int main() {
    MESSAGE messages[] = {
        {1, 5, "Hello, World!", 0},
        {2, 3, "Data integrity is crucial.", 0}
    };
    int count = sizeof(messages) / sizeof(messages[0]);

    enqueueAndProcessMessages(messages, count);

    return 0;
}
```

This code snippet demonstrates a basic implementation of enqueuing and processing messages in a C-based message queue system. It includes error handling for memory allocation, uniqueness checking of message IDs, and conditional locking to ensure thread safety. The main function demonstrates how to use the `enqueueAndProcessMessages` function with an array of MESSAGE structures.']

