using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using NServiceBus;

public class MessageBrokerClient : IDispatchMessages
{
    private readonly IBus _bus;
    private readonly ILogger<MessageBrokerClient> _logger;
    private int _workerThreads = 4; // Initial number of worker threads

    public MessageBrokerClient(IBus bus, ILoggerFactory loggerFactory)
    {
        _bus = bus;
        _logger = loggerFactory.CreateLogger<MessageBrokerClient>();
    }

    public async Task<string> SendMessageAsync(string jsonPayload, string messageQueue)
    {
        byte[] payloadBytes = Encoding.UTF8.GetBytes(jsonPayload);

        try
        {
            _logger.LogInformation("Serialization successful. Payload size: {Size}", payloadBytes.Length);

            await SendMessagesInBatch(new List<byte[]> { payloadBytes }, messageQueue);

            return "Message acknowledged";
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to send message");
            throw;
        }
    }

    private async Task SendMessagesInBatch(List<byte[]> messages, string messageQueue)
    {
        foreach (var batch in messages.Chunk(10))
        {
            await Task.WhenAll(batch.Select(msg => SendMessageAsyncInternal(msg, messageQueue)));
        }
    }

    private async Task SendMessageAsyncInternal(byte[] payloadBytes, string messageQueue)
    {
        try
        {
            var message = new Message { Payload = payloadBytes };
            _logger.LogInformation("Message sent to queue: {Queue}", messageQueue);

            await _bus.SendLocal(message);

            _logger.LogInformation("Acknowledgment received for message");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to send message to queue: {Queue}", messageQueue);
            throw;
        }
    }

    public async Task<int> SendMessagesAsync(List<string> jsonPayloads, string messageQueue)
    {
        var tasks = jsonPayloads.Select(json => SendMessageAsync(json, messageQueue));
        await Task.WhenAll(tasks);

        return tasks.Count;
    }
}

public class Message
{
    public byte[] Payload { get; set; }
}
