// Define a linked list node for the list of NFAPI structures
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create and populate the list
Node* createAndPopulateList(int numStructures) {
    Node* head = NULL;
    Node** currentPtr = &head;
    int rntiValues[10000];
    srand(time(NULL));

    for (int i = 0; i < numStructures; ++i) {
        // Generate a unique RNTI value
        int newRNTI;
        do {
            newRNTI = rand() % 10000;
        } while (isRNTIUsed(newRNTI, rntiValues, i));

        NFAPI_CRC_INDICATION_PDU_T newStruct;
        newStruct.RX_UE_INFORMATION_TAG = i + 1; // Example value
        newStruct.RNTI = newRNTI;
        newStruct.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = newStruct;
        newNode->next = NULL;

        *currentPtr = newNode;
        currentPtr = &(*currentPtr)->next;

        rntiValues[i] = newRNTI;
    }

    return head;
}

// Helper function to check if a RNTI value is already used
int isRNTIUsed(int rnti, int* rntiValues, int count) {
    for (int i = 0; i < count; ++i) {
        if (rntiValues[i] == rnti) {
            return 1;
        }
    }
    return 0;
}
