    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest_alias(EVP_sha1(), "rsa-md5");
    EVP_add_digest_alias(EVP_sha256(), "rsa-sha1");

