            Node* newNode = createCRCIndication(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
            if (newNode) {
                newNode->next = head;
                head = newNode;
                RNTI++;
                RX_UE_INFORMATION_TAG++;
            }
