    int referenceCRCValue = 1; // Placeholder for actual reference value
    Node* current = head;
    while (current) {
        if (current->data.CRC_INDICATION_REL8_TAG != referenceCRCValue) {
            fprintf(stderr, "Invalid CRC indication detected.\n");
        }
        current = current->next;
    }

    freeList(head);
}

Node* findNodeByRNTI(Node* head, unsigned short RNTI) {
    Node* current = head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void freeList(Node* head) {
