    // Lock the plugin management mutex to ensure thread-safe operations
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_plugins; i++) {
        Plugin* plugin = &plugins[i];

        // Handle potential thread starvation scenarios and ensure fair plugin distribution among threads
        if (plugin->state == 3) {
            pthread_cond_wait(&cond, &lock);
        }

        // Lock the plugin's mutex to ensure thread-safe operations
        pthread_mutex_lock(&plugin->lock);

        switch (plugin->state) {
            case 0:
                plugin->activate();
                plugin->state = 1;
                break;
            case 2:
                plugin->deactivate();
                plugin->state = 3;
                pthread_cond_signal(&cond);
                break;
        }

        // Unlock the plugin's mutex
        pthread_mutex_unlock(&plugin->lock);
    }

    // Unlock the plugin management mutex
    pthread_mutex_unlock(&lock);
}

