    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", timeinfo);

    int random_number = rand();
    char* new_filename = (char*)malloc(strlen(filename) + strlen(timestamp) + 10);
    if (new_filename == NULL) {
        return NULL; // Memory allocation failed
    }

    sprintf(new_filename, "%s_%s_%d", filename, timestamp, random_number);

    return new_filename;
