    for (int i = 0; i < initial_size; i++) {
        resource_pool[i].id = i;
        resource_pool[i].last_usage_time = -1;
        resource_pool[i].availability_status = 1;
        for (int j = 0; j < MAX_RESOURCES; j++) {
            resource_pool[i].reservation_history[j] = -1;
        }
    }
    current_size = initial_size;
}

int allocate_resource() {
    sem_wait(&pool_lock);
    for (int i = 0; i < current_size; i++) {
        if (resource_pool[i].availability_status == 1) {
            resource_pool[i].availability_status = 0;
            sem_post(&pool_lock);
            return resource_pool[i].id;
        }
    }
    sem_post(&pool_lock);
    return -1;
