    public String startSession(String metadata) {
        long sessionId = nextSessionId.getAndIncrement();
        UserSession session = new UserSession(sessionId, metadata);
        userSessions.put(String.valueOf(sessionId), session);
        return String.valueOf(sessionId);
    }

    public void updateActivity(String sessionId, String interactionLog) {
        userSessions.computeIfPresent(sessionId, (id, session) -> {
            session.updateLastActiveTimestamp();
            session.addInteractionLog(interactionLog);
            return session;
        });
    }

    public UserSession getSession(String sessionId) {
        return userSessions.getOrDefault(sessionId, null);
    }

