#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <mutex>
#include <json/json.h>
#include "third_party_logger.hpp"
#include "octree.hpp"

// Define custom 'event' structure
struct Event {
    std::chrono::system_clock::time_point timestamp;
    std::string type;
    double magnitude;
};

class DataAggregator {
public:
    void parse_and_aggregate(const std::vector<std::string>& log_files, const Json::Value& config) {
        // Initialize octree with configuration
        Octree octree(config);

        // Vector to hold events from all files
        std::vector<Event> all_events;

        // Mutex for thread-safe access
        std::mutex mtx;

        // Function to process a single log file
        auto process_file = [&](const std::string& file) {
            std::ifstream in(file);
            if (!in.is_open()) {
                logger.error("Failed to open file: " + file);
                return;
            }
            Event event;
            while (in >> event.timestamp >> event.type >> event.magnitude) {
                std::lock_guard<std::mutex> lock(mtx);
                all_events.push_back(event);
            }
        };

        // Create threads for batch processing
        std::vector<std::thread> threads;
        int num_files = log_files.size();
        int chunk_size = (num_files + 49) / 50; // Maximum of 5000 files in parallel

        for (int i = 0; i < num_files; i += chunk_size) {
            std::vector<std::string> batch(log_files.begin() + i, log_files.begin() + std::min(i + chunk_size, num_files));
            threads.emplace_back(process_file, batch);
        }

        // Join all threads
        for (auto& t : threads) {
            t.join();
        }

        // Aggregate data and generate JSON report
        Json::Value report;
        report["events"] = Json::Value(Json::arrayValue);
        for (const auto& event : all_events) {
            Json::Value ev;
            ev["timestamp"] = std::chrono::duration_cast<std::chrono::milliseconds>(event.timestamp.time_since_epoch()).count();
            ev["type"] = event.type;
            ev["magnitude"] = event.magnitude;
            report["events"].append(ev);
        }

        // Write JSON report
        Json::StreamWriterBuilder builder;
        builder["commentStyle"] = "None";
        builder["indentation"] = "   ";
        std::unique_ptr<Json::StreamWriter> writer(builder.newStreamWriter());
        std::ofstream out("report.json");
        writer->write(report, &out);
    }
};

int main(int argc, char* argv[]) {
    DataAggregator aggregator;
    Json::Value config; // Load configuration from command-line or file
    std::vector<std::string> log_files = {"log1.txt", "log2.txt"}; // Populate with actual log files

    aggregator.parse_and_aggregate(log_files, config);

    return 0;
}
