#include <stdio.h>
#include <stdlib.h>

#define MAX_UE_CONTEXTS 1024

typedef struct {
    int ue_id;
    int rrc_state;
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *digest_ctx;
} LTE_UE_Context;

LTE_UE_Context ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t ue_context_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_ue_context(int ue_id, int rrc_state) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (!ue_contexts[i].cipher_ctx && !ue_contexts[i].digest_ctx) {
            ue_contexts[i].ue_id = ue_id;
            ue_contexts[i].rrc_state = rrc_state;
            EVP_CIPHER *cipher = EVP_aes_256_cbc();
            EVP_MD *digest = EVP_sha256();
            if (!(ue_contexts[i].cipher_ctx = EVP_CIPHER_CTX_new()) ||
                !(ue_contexts[i].digest_ctx = EVP_MD_CTX_new())) {
                perror("Failed to create EVP contexts");
                exit(EXIT_FAILURE);
            }
            EVP_EncryptInit_ex(ue_contexts[i].cipher_ctx, cipher, NULL, NULL, NULL);
            EVP_DigestInit_ex(ue_contexts[i].digest_ctx, digest, NULL);
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    perror("No available UE context slots");
    exit(EXIT_FAILURE);
}

void update_ue_context(int ue_id, int rrc_state) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            ue_contexts[i].rrc_state = rrc_state;
            EVP_CIPHER *cipher = EVP_aes_256_cbc();
            EVP_MD *digest = EVP_sha256();
            EVP_EncryptInit_ex(ue_contexts[i].cipher_ctx, cipher, NULL, NULL, NULL);
            EVP_DigestInit_ex(ue_contexts[i].digest_ctx, digest, NULL);
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    perror("UE context not found");
    exit(EXIT_FAILURE);
}

void cleanup_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].ue_id == ue_id) {
            EVP_CIPHER_CTX_free(ue_contexts[i].cipher_ctx);
            EVP_MD_CTX_free(ue_contexts[i].digest_ctx);
            ue_contexts[i].cipher_ctx = NULL;
            ue_contexts[i].digest_ctx = NULL;
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    perror("UE context not found");
    exit(EXIT_FAILURE);
}

int main() {
    // Initialize and update UE contexts
    initialize_ue_context(1, 0);
    update_ue_context(1, 1);

    // Cleanup after use
    cleanup_ue_context(1);

    return 0;
}
```

