#include <string.h>

#define MAX_UE_CONTEXTS 1024

typedef struct {
    int ue_id;
    int rrc_state;
    // List of active radio bearers
} LTE_UE_Context;

LTE_UE_Context *ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t ue_context_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_cryptographic_library() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());
}

void initialize_UE_context(int ue_id) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] == NULL) {
            ue_contexts[i] = (LTE_UE_Context *)malloc(sizeof(LTE_UE_Context));
            ue_contexts[i]->ue_id = ue_id;
            ue_contexts[i]->rrc_state = 0; // Initial RRC state
            // Initialize radio bearers list
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
    fprintf(stderr, "Maximum UE contexts reached\n");
}

void update_UE_context(int ue_id, int new_rrc_state) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] != NULL && ue_contexts[i]->ue_id == ue_id) {
            ue_contexts[i]->rrc_state = new_rrc_state;
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
    fprintf(stderr, "UE context not found\n");
}

void free_UE_context(int ue_id) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] != NULL && ue_contexts[i]->ue_id == ue_id) {
            free(ue_contexts[i]);
            ue_contexts[i] = NULL;
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
    fprintf(stderr, "UE context not found\n");
}
