void create_and_log_structs(int logging_level, const char* compression_algorithm, const char* log_destination) {
    static NFAPI_CRC_INDICATION_PDU_T* local_cache[MAX_STRUCTS];
    static int cache_index = 0;
    static int initialized = 0;

    if (!initialized) {
        srand(time(NULL) + getpid() + (logging_level << 16));
        initialized = 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_struct->RX_UE_INFORMATION_TAG = rand();
    new_struct->RNTI = (unsigned short)rand();
    new_struct->CRC_INDICATION_REL8_TAG = rand() % 256;
    new_struct->CRCFLAG = (char)(rand() % 3);

    local_cache[cache_index++] = new_struct;
    if (cache_index >= MAX_STRUCTS) {
        cache_index = 0; // Overwrite old data if full
    }

    if (logging_level >= 2) { // Debug or higher
        char compressed_data[1024];
        int compressed_size = compress(compression_algorithm, compressed_data, new_struct, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (compressed_size < 0) {
            fprintf(stderr, "Compression failed\n");
        } else {
            log_to_destination(log_destination, compressed_data, compressed_size);
        }
    }
}

