    private LoadBalancer loadBalancer;

    public UserInterfaceIntegration(LoadBalancer loadBalancer) {
        this.loadBalancer = loadBalancer;
    }

    public void distributeRequest(Request request) {
        Server server = loadBalancer.getAvailableServer();
        server.handle(request);
    }

    // Session Management
    private SessionManager sessionManager;

    public UserInterfaceIntegration(SessionManager sessionManager) {
        this.sessionManager = sessionManager;
    }

    public void createSession(User user) {
        sessionManager.createSession(user);
