#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

typedef struct {
    char hostname[256];
    in_addr_t ip;
    time_t last_accessed;
} CacheEntry;

#define MAX_CACHE_SIZE 100
CacheEntry cache[MAX_CACHE_SIZE];
int cache_size = 0;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* dns_resolution(void* arg) {
    char* hostname = (char*)arg;
    struct addrinfo hints, *res, *p;
    int status;
    in_addr_t ip = 0;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return (void*)-1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if ((status = getnameinfo(p->ai_addr, p->ai_addrlen, (char*)&ip, sizeof(ip), NULL, 0, NI_NUMERICHOST)) != 0) {
            fprintf(stderr, "getnameinfo error: %s\n", gai_strerror(status));
            continue;
        }
        break;
    }

    freeaddrinfo(res);

    if (p == NULL) {
        return (void*)-1;
    }

    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            cache[i].ip = ip;
            cache[i].last_accessed = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return (void*)ip;
        }
    }

    if (cache_size < MAX_CACHE_SIZE) {
        strcpy(cache[cache_size].hostname, hostname);
        cache[cache_size].ip = ip;
        cache[cache_size].last_accessed = time(NULL);
        cache_size++;
    } else {
        // Handle cache full scenario
        printf("Cache is full. Evicting least recently used entry.\n");
        int lru_index = 0;
        time_t oldest_time = time(NULL);
        for (int i = 1; i < cache_size; i++) {
            if (cache[i].last_accessed < oldest_time) {
                oldest_time = cache[i].last_accessed;
                lru_index = i;
            }
        }
        strcpy(cache[lru_index].hostname, hostname);
        cache[lru_index].ip = ip;
        cache[lru_index].last_accessed = time(NULL);
    }
    pthread_mutex_unlock(&cache_lock);

    return (void*)ip;
}

int main() {
    char hostname[] = "www.example.com";
    void* result = dns_resolution(hostname);
    if ((long)result == -1) {
        printf("DNS resolution failed for %s\n", hostname);
    } else {
        struct in_addr addr;
        addr.s_addr = (in_addr_t)result;
        printf("IP address for %s is %s\n", hostname, inet_ntoa(addr));
    }
    return 0;
}
```

This code provides a basic implementation of the DNS resolution function with a simple LRU cache and thread safety using mutexes. It uses standard library functions like `getaddrinfo` to perform the resolution and stores resolved IP addresses in an array. The cache is synchronized using a mutex to ensure that concurrent access does not corrupt the data.']

