#define MAX_NODES 1000
#define BUFFER_SIZE 4096

typedef struct {
    time_t timestamp;
    int node_id;
    double read_iops, write_iops;
    double avg_latency;
    double peak_throughput;
} NodeStatus;

NodeStatus *parse_and_generate_alerts(const char *log_file_path, int sample_rate, double read_threshold, double write_threshold, double latency_threshold, double throughput_threshold) {
    FILE *file = fopen(log_file_path, "r");
    if (!file) {
        perror("Failed to open log file");
        return NULL;
    }

    NodeStatus *node_statuses = (NodeStatus *)malloc(MAX_NODES * sizeof(NodeStatus));
    int count = 0;

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        if (buffer[0] == 'R' && buffer[1] == 'E' && buffer[2] == 'A') {
            // Parse read IOPS
            node_statuses[count].read_iops = atof(strtok(NULL, ","));
            node_statuses[count].write_iops = atof(strtok(NULL, ","));
            node_statuses[count].avg_latency = atof(strtok(NULL, ","));
            node_statuses[count].peak_throughput = atof(strtok(NULL, "\n"));
            node_statuses[count].timestamp = time(NULL);
            node_statuses[count].node_id = count + 1;
            if (node_statuses[count].read_iops > read_threshold || node_statuses[count].write_iops > write_threshold) {
                // Generate alert for degraded performance or failures
                printf("Alert: Node %d - Read IOPS: %.2f, Write IOPS: %.2f\n", node_statuses[count].node_id, node_statuses[count].read_iops, node_statuses[count].write_iops);
            }
        } else if (buffer[0] == 'W' && buffer[1] == 'R' && buffer[2] == 'I') {
            // Parse write IOPS
            node_statuses[count].read_iops = atof(strtok(NULL, ","));
            node_statuses[count].write_iops = atof(strtok(NULL, ","));
            node_statuses[count].avg_latency = atof(strtok(NULL, ","));
            node_statuses[count].peak_throughput = atof(strtok(NULL, "\n"));
            node_statuses[count].timestamp = time(NULL);
            node_statuses[count].node_id = count + 1;
            if (node_statuses[count].read_iops > read_threshold || node_statuses[count].write_iops > write_threshold) {
                // Generate alert for degraded performance or failures
                printf("Alert: Node %d - Read IOPS: %.2f, Write IOPS: %.2f\n", node_statuses[count].node_id, node_statuses[count].read_iops, node_statuses[count].write_iops);
            }
        } else if (buffer[0] == 'L' && buffer[1] == 'A' && buffer[2] == 'T') {
            // Parse average latency
            node_statuses[count].avg_latency = atof(strtok(NULL, ","));
            node_statuses[count].peak_throughput = atof(strtok(NULL, "\n"));
            if (node_statuses[count].avg_latency > latency_threshold) {
                // Generate alert for degraded performance or failures
                printf("Alert: Node %d - Avg Latency: %.2f\n", node_statuses[count].node_id, node_statuses[count].avg_latency);
            }
        } else if (buffer[0] == 'T' && buffer[1] == 'H' && buffer[2] == 'R') {
            // Parse peak throughput
            node_statuses[count].peak_throughput = atof(strtok(NULL, "\n"));
            if (node_statuses[count].peak_throughput > throughput_threshold) {
                // Generate alert for degraded performance or failures
                printf("Alert: Node %d - Peak Throughput: %.2f\n", node_statuses[count].node_id, node_statuses[count].peak_throughput);
            }
        }
        count++;
    }

    fclose(file);
    return node_statuses;
}

int main(int argc, char *argv[]) {
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <log_file_path> <sample_rate> <read_threshold> <write_threshold> <latency_threshold> <throughput_threshold>\n", argv[0]);
        return 1;
    }

    const char *log_file_path = argv[1];
    int sample_rate = atoi(argv[2]);
    double read_threshold = atof(argv[3]);
    double write_threshold = atof(argv[4]);
    double latency_threshold = atof(argv[5]);
    double throughput_threshold = atof(argv[6]);

    NodeStatus *node_statuses = parse_and_generate_alerts(log_file_path, sample_rate, read_threshold, write_threshold, latency_threshold, throughput_threshold);
    if (node_statuses) {
        free(node_statuses);
    }

    return 0;
}
