import threading
from collections import defaultdict

class MicroservicesManager:
    def __init__(self):
        self.documents = defaultdict(lambda: {
            'version': 0,
            'last_edited': None,
            'editors': set(),
            'history': []
        })
        self.locks = {}

    def get_document(self, doc_id):
        if doc_id not in self.documents:
            self.initialize_document(doc_id)
        return self.documents[doc_id]

    def initialize_document(self, doc_id):
        self.documents[doc_id] = {
            'version': 0,
            'last_edited': None,
            'editors': set(),
            'history': []
        }
        self.locks[doc_id] = threading.Lock()

    def edit_document(self, doc_id, editor):
        with self.locks[doc_id]:
            document = self.get_document(doc_id)
            if editor not in document['editors']:
                document['editors'].add(editor)
                document['version'] += 1
                document['last_edited'] = threading.current_thread().name
                document['history'].append((document['version'], editor, 'Edit'))
                self.notify_changes(doc_id)

    def leave_document(self, doc_id, editor):
        with self.locks[doc_id]:
            document = self.get_document(doc_id)
            if editor in document['editors']:
                document['editors'].remove(editor)
                document['history'].append((document['version'], editor, 'Leave'))
                if not document['editors']:
                    del self.documents[doc_id]
                    del self.locks[doc_id]

    def notify_changes(self, doc_id):
        # Simulate notifying MAS about changes
        print(f"Document {doc_id} updated. Version: {self.documents[doc_id]['version']}")

# Example usage
manager = MicroservicesManager()
manager.edit_document('doc1', 'userA')
manager.edit_document('doc1', 'userB')
manager.leave_document('doc1', 'userA')
