#define MAX_SENSORS 10

typedef struct {
    int vehicle_id;
    bool sensor_status[MAX_SENSORS];
    pthread_mutex_t sensor_locks[MAX_SENSORS];
} AV_Sensor_Fusion_System;

typedef struct {
    AV_Sensor_Fusion_System *systems;
    int system_count;
    pthread_mutex_t fleet_lock;
} Fleet_Manager;

AV_Sensor_Fusion_System* create_av_sensor_fusion_system(int vehicle_id) {
    AV_Sensor_Fusion_System *system = (AV_Sensor_Fusion_System *)malloc(sizeof(AV_Sensor_Fusion_System));
    if (!system) return NULL;

    system->vehicle_id = vehicle_id;
    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_mutex_init(&system->sensor_locks[i], NULL);
        system->sensor_status[i] = false;
    }

    return system;
}

Fleet_Manager* create_fleet_manager(int system_count) {
    Fleet_Manager *manager = (Fleet_Manager *)malloc(sizeof(Fleet_Manager));
    if (!manager) return NULL;

    manager->systems = (AV_Sensor_Fusion_System **)malloc(system_count * sizeof(AV_Sensor_Fusion_System *));
    if (!manager->systems) {
        free(manager);
        return NULL;
    }

    manager->system_count = system_count;
    pthread_mutex_init(&manager->fleet_lock, NULL);

    for (int i = 0; i < system_count; i++) {
        manager->systems[i] = create_av_sensor_fusion_system(i);
        if (!manager->systems[i]) {
            for (int j = 0; j < i; j++) {
                free(manager->systems[j]);
            }
            free(manager->systems);
            pthread_mutex_destroy(&manager->fleet_lock);
            free(manager);
            return NULL;
        }
    }

    return manager;
}

void update_sensor_status(Fleet_Manager *manager, int vehicle_id, int sensor_id, bool status) {
    pthread_mutex_lock(&manager->fleet_lock);
    for (int i = 0; i < manager->system_count; i++) {
        if (manager->systems[i]->vehicle_id == vehicle_id) {
            pthread_mutex_lock(&manager->systems[i]->sensor_locks[sensor_id]);
            manager->systems[i]->sensor_status[sensor_id] = status;
            pthread_mutex_unlock(&manager->systems[i]->sensor_locks[sensor_id]);
            break;
        }
    }
    pthread_mutex_unlock(&manager->fleet_lock);
}

void destroy_fleet_manager(Fleet_Manager *manager) {
    for (int i = 0; i < manager->system_count; i++) {
        free(manager->systems[i]);
    }
    free(manager->systems);
    pthread_mutex_destroy(&manager->fleet_lock);
    free(manager);
}
