#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SENSORS 100

typedef struct {
    int vehicle_id;
    char sensor_status[20];
    char *active_sensors[MAX_SENSORS];
    int sensor_count;
} AV_Sensor_Fusion;

AV_Sensor_Fusion *sensor_fusions;
int num_vehicles;
pthread_mutex_t mutex;

void initialize_sensor_fusions(int num) {
    sensor_fusions = malloc(num * sizeof(AV_Sensor_Fusion));
    num_vehicles = num;
    pthread_mutex_init(&mutex, NULL);
}

void update_sensor_configuration(int vehicle_id, char *new_status, char **sensors, int count) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_vehicles; i++) {
        if (sensor_fusions[i].vehicle_id == vehicle_id) {
            strcpy(sensor_fusions[i].sensor_status, new_status);
            sensor_fusions[i].sensor_count = count;
            for (int j = 0; j < count; j++) {
                strcpy(sensor_fusions[i].active_sensors[j], sensors[j]);
            }
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void *read_sort_and_extract_file(void *file_path) {
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    char *lines[MAX_SENSORS];
    int line_count = 0;

    while (!feof(file)) {
        lines[line_count] = malloc(256);
        fgets(lines[line_count], 256, file);
        line_count++;
    }
    fclose(file);

    qsort(lines, line_count, sizeof(char *), (int (*)(const void *, const void *))strcmp);

    char *last_line = strdup(lines[line_count - 1]);
    for (int i = 0; i < line_count; i++) {
        free(lines[i]);
    }

    return last_line;
}

int main() {
    initialize_sensor_fusions(5);
    update_sensor_configuration(1, "active", (char *[]){"sensor1", "sensor2"}, 2);

    void *file_path = "path_to_file.txt";
    char *last_line = read_sort_and_extract_file(file_path);
    if (last_line != NULL) {
        printf("Last line: %s\n", last_line);
        free(last_line);
    }

    pthread_mutex_destroy(&mutex);
    free(sensor_fusions);

    return 0;
}
```

