    if (num_active_contexts >= MAX_UE_CONTEXTS) {
        printf("Error: Maximum number of UE contexts reached\n");
        return;
    }
    ue_contexts[num_active_contexts].id = id;
    ue_contexts[num_active_contexts].rrc_state = rrc_state;
    num_active_contexts++;
}

void update_ue_context(int id, int new_rrc_state) {
    for (int i = 0; i < num_active_contexts; i++) {
        if (ue_contexts[i].id == id) {
            ue_contexts[i].rrc_state = new_rrc_state;
            return;
        }
    }
    printf("Error: UE context with ID %d not found\n", id);
}

void display_ue_contexts() {
    for (int i = 0; i < num_active_contexts; i++) {
        printf("UE Context %d: ID = %d, RRC State = %d\n",
               i, ue_contexts[i].id, ue_contexts[i].rrc_state);
    }
}

int main() {
    initialize_ue_context(1, 0);
    update_ue_context(1, 1);
    display_ue_contexts();
    return 0;
}
