        contexts[i].rrc_state = 0;
        contexts[i].buffer_size = config_message_length;
        contexts[i].nas_buffer = (char*)malloc(config_message_length);
        if (!contexts[i].nas_buffer) {
            // Handle buffer allocation failure gracefully
            for (int j = 0; j < i; ++j) free(contexts[j].nas_buffer);
            free(contexts);
            return NULL;
        }
    }

    return contexts;
}

void destroy_lte_ue_contexts(LTE_UE_Context *contexts, size_t num_contexts) {
    if (!contexts) return;

    for (int i = 0; i < num_contexts; ++i) {
