void initialize_ue_contexts(size_t nas_buffer_size) {
    pthread_mutex_init(&ue_mutex, NULL);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        LTE_UE_Context *ctx = malloc(sizeof(LTE_UE_Context));
        ctx->UE_ID = -1;
        ctx->rrc_state = RRC_IDLE;
        ctx->nas_buffer = malloc(nas_buffer_size);
        ctx->buffer_size = nas_buffer_size;
        ctx->current_size = 0;
        ue_contexts[i] = ctx;
    }
}

void destroy_ue_contexts() {
    pthread_mutex_lock(&ue_mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        free(ue_contexts[i]->nas_buffer);
        free(ue_contexts[i]);
    }
    pthread_mutex_unlock(&ue_mutex);
    pthread_mutex_destroy(&ue_mutex);
}

void update_ue_context(int UE_ID, LTE_RRC_State state, const char *nas_message, size_t message_size) {
    pthread_mutex_lock(&ue_mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i]->UE_ID == UE_ID) {
            if (message_size > ue_contexts[i]->buffer_size) {
                // Handle buffer overflow gracefully
                printf("Buffer overflow detected. Dropping message.\n");
            } else {
                // Update NAS buffer safely
                memcpy(ue_contexts[i]->nas_buffer, nas_message, message_size);
                ue_contexts[i]->current_size = message_size;
                ue_contexts[i]->rrc_state = state;
            }
            break;
        }
    }
    pthread_mutex_unlock(&ue_mutex);
}

