    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *digest_ctx;
    // Other fields...
} LTE_UE_Context;

LTE_UE_Context* init_lte_ue_context(int ue_id, int rrc_state) {
    LTE_UE_Context* ctx = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!ctx) return NULL;

    ctx->ue_id = ue_id;
    ctx->rrc_state = rrc_state;

    // Initialize cipher and digest contexts
    if (!(ctx->cipher_ctx = EVP_CIPHER_CTX_new()) ||
        !(ctx->digest_ctx = EVP_MD_CTX_new())) {
        free(ctx);
        return NULL;
    }

    // Set up AES cipher context
    EVP_CIPHER* aes_cipher = EVP_aes_256_cbc();
    if (EVP_EncryptInit_ex(ctx->cipher_ctx, aes_cipher, NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        EVP_MD_CTX_free(ctx->digest_ctx);
        free(ctx);
        return NULL;
    }

    // Set up MD5 digest context
    if (EVP_DigestInit_ex(ctx->digest_ctx, EVP_md5(), NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        EVP_MD_CTX_free(ctx->digest_ctx);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void destroy_lte_ue_context(LTE_UE_Context* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        EVP_MD_CTX_free(ctx->digest_ctx);
        free(ctx);
    }
}

