    size_t file_size = ftell(infile);
    fseek(infile, 0, SEEK_SET);

    crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(file_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indications == NULL) {
        perror("Memory allocation failed");
        fclose(infile);
