    }

    // Populate CRC indications based on parameters
    for (size_t i = 0; i < file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = start_timestamp + i * event_id_range[1];
        crc_indications[i].RNTI = i % 256;
        crc_indications[i].CRC_INDICATION_REL8_TAG = (status_codes[rand() % num_status_codes] & 0x0F) | 0x80;
        crc_indications[i].CRCFLAG = rand() % 2;
    }

    // Apply transformation rules and write to output file
    FILE* outfile = fopen(output_file, "wb");
    if (outfile == NULL) {
        perror("Failed to open output file");
        free(crc_indications);
        fclose(infile);
        return;
