#include <iostream>
#include <map>
#include <string>
#include <vector>
#include <functional>

class ConfigManager {
private:
    struct ComponentInfo {
        std::string version;
        int priority;
        // Other component-specific data
    };

    std::map<std::string, ComponentInfo> components;

public:
    void loadComponent(const std::string& componentName, const std::string& version, int priority = 0) {
        if (components.find(componentName) != components.end()) {
            if (priority > components[componentName].priority) {
                unloadComponent(componentName);
                components[componentName] = {version, priority};
            } else if (priority == components[componentName].priority && version < components[componentName].version) {
                unloadComponent(componentName);
                components[componentName] = {version, priority};
            }
        } else {
            components[componentName] = {version, priority};
        }
    }

    void unloadComponent(const std::string& componentName) {
        // Logic to unload the component
        components.erase(componentName);
    }

    void applyConfig() {
        // Logic to apply configuration based on priorities
        for (const auto& pair : components) {
            if (pair.second.priority == 0) {
                loadComponent(pair.first, pair.second.version);
            }
        }
    }

    ~ConfigManager() {
        for (const auto& component : components) {
            unloadComponent(component.first);
        }
    }
};

int main() {
    ConfigManager manager;
    manager.loadComponent("ComponentA", "1.0", 5);
    manager.loadComponent("ComponentB", "2.0", 3);
    manager.applyConfig();
    return 0;
}
```

