    clients[index].auth_status = status;
    pthread_mutex_unlock(&clients[index].lock);
}

void connect_client(int index, const char *ssid) {
    pthread_mutex_lock(&clients[index].lock);
    strncpy(clients[index].ssid, ssid, sizeof(clients[index].ssid));
    pthread_mutex_unlock(&clients[index].lock);
}

void disconnect_client(int index) {
    pthread_mutex_lock(&clients[index].lock);
    memset(clients[index].ssid, 0, sizeof(clients[index].ssid));
    pthread_mutex_unlock(&clients[index].lock);
}

