typedef struct {
    ConnectionContext connections[MAX_CONNECTIONS];
    int currentConnections;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} TCPServerManager;

TCPServerManager* initTCPServer() {
    TCPServerManager *manager = (TCPServerManager*)malloc(sizeof(TCPServerManager));
    manager->currentConnections = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    return manager;
}

void addConnection(TCPServerManager* manager, int clientID) {
    pthread_mutex_lock(&manager->lock);
    if (manager->currentConnections < MAX_CONNECTIONS) {
        manager->connections[manager->currentConnections].clientID = clientID;
        manager->connections[manager->currentConnections].state = STATE_CONNECTED;
        // Initialize session history log and audit trail
        manager->currentConnections++;
    } else {
        printf("Max connections reached\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

void removeConnection(TCPServerManager* manager, int clientID) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->currentConnections; i++) {
        if (manager->connections[i].clientID == clientID) {
            // Log disconnection and audit trail
            manager->connections[i] = manager->connections[manager->currentConnections - 1];
            manager->currentConnections--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void* manageConnections(void* arg) {
    TCPServerManager *manager = (TCPServerManager*)arg;
    while (1) {
        pthread_mutex_lock(&manager->lock);
        if (manager->currentConnections > 0 && time(NULL) - manager->connections[0].lastActivity > IDLE_TIMEOUT) {
            removeConnection(manager, manager->connections[0].clientID);
        }
        pthread_cond_wait(&manager->cond, &manager->lock);
        pthread_mutex_unlock(&manager->lock);
    }
}

