LTE_UE_Context *ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_ue_context(int ue_id, int rrc_state) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (!ue_contexts[i]) {
            LTE_UE_Context *new_context = malloc(sizeof(LTE_UE_Context));
            new_context->ue_id = ue_id;
            new_context->rrc_state = rrc_state;
            new_context->active_bearers = NULL;
            new_context->bearer_count = 0;
            ue_contexts[i] = new_context;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);
    fprintf(stderr, "Maximum number of UE contexts reached\n");
}

void update_ue_context(int ue_id, int rrc_state) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] && ue_contexts[i]->ue_id == ue_id) {
            ue_contexts[i]->rrc_state = rrc_state;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);
    fprintf(stderr, "UE context not found\n");
}

void free_ue_context(int ue_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] && ue_contexts[i]->ue_id == ue_id) {
            free(ue_contexts[i]);
            ue_contexts[i] = NULL;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);
    fprintf(stderr, "UE context not found\n");
}

void *md5_hash(const char *input, size_t length) {
    unsigned char digest[16];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, input, length);
    MD5_Final(digest, &ctx);

    char *output = malloc(33);
    for (int i = 0; i < 16; ++i) {
        sprintf(output + (i * 2), "%02x", digest[i]);
    }
    return output;
}
