DataPacket* allocate_data_packets(int N) {
    if (N < 0 || N > INT_MAX / sizeof(DataPacket)) {
        log_error("Invalid number of data packets.");
        return NULL;
    }

    DataPacket *data_packets = (DataPacket*)malloc(N * sizeof(DataPacket));
    if (data_packets == NULL) {
        log_error("Failed to allocate memory for data packets.");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        data_packets[i].SourceID = rand() % 1000;
        data_packets[i].DestinationID = rand() % 1000;
        int payload_size = rand() % MAX_PAYLOAD_SIZE;
        data_packets[i].Payload[payload_size] = '\0'; // Null-terminate the payload
    }

    return data_packets;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(int N) {
    if (N < 0 || N > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_error("Invalid number of CRC indications.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indications == NULL) {
        log_error("Failed to allocate memory for CRC indications.");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crc_indications[i].RNTI = rand() % 1024;
        crc_indications[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG
    }

    return crc_indications;
}

void free_data_packets(DataPacket *data_packets, int N) {
    free(data_packets);
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *crc_indications, int N) {
    free(crc_indications);
}

