    UE_Manager *manager = (UE_Manager *)malloc(sizeof(UE_Manager));
    if (!manager) return NULL;
    memset(manager, 0, sizeof(UE_Manager));
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void ue_manager_add_context(UE_Manager *manager, LTE_UE_Context *context) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (!manager->contexts[i]) {
            manager->contexts[i] = context;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void ue_manager_remove_context(UE_Manager *manager, LTE_UE_Context *context) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->contexts[i] == context) {
            manager->contexts[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

