#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int socket_id;
    int status_flags;
    time_t last_active_timestamp;
    char buffer[1024];
} TCP_SOCKET_T;

typedef struct {
    TCP_SOCKET_T* sockets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SocketManager;

SocketManager* create_socket_manager(size_t initial_capacity) {
    SocketManager* manager = (SocketManager*)malloc(sizeof(SocketManager));
    if (!manager) return NULL;

    manager->sockets = (TCP_SOCKET_T*)calloc(initial_capacity, sizeof(TCP_SOCKET_T));
    if (!manager->sockets) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_socket_manager(SocketManager* manager) {
    if (manager->sockets) {
        free(manager->sockets);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_socket(SocketManager* manager, TCP_SOCKET_T new_socket) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TCP_SOCKET_T* new_sockets = realloc(manager->sockets, new_capacity * sizeof(TCP_SOCKET_T));
        if (!new_sockets) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->sockets = new_sockets;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sockets[i].socket_id == new_socket.socket_id) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate socket ID
        }
    }

    manager->sockets[manager->size++] = new_socket;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Add other functions as needed, such as updating the last active timestamp, handling errors, etc.
```

