#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the LTE UE context structure
typedef struct {
    int ue_id;
    char rrc_state[50];
    // Add other necessary fields
} LTE_UE_Context;

// Define a hash table to store UE contexts with thread-safe operations
typedef struct {
    pthread_mutex_t lock;
    int size;
    LTE_UE_Context **buckets;
} LTE_UE_Registry;

// Initialize the UE registry
LTE_UE_Registry* lte_ue_registry_init(int initial_size) {
    LTE_UE_Registry *registry = (LTE_UE_Registry*) malloc(sizeof(LTE_UE_Registry));
    pthread_mutex_init(&registry->lock, NULL);
    registry->size = initial_size;
    registry->buckets = (LTE_UE_Context**) calloc(initial_size, sizeof(LTE_UE_Context*));
    return registry;
}

// Insert or update an UE context in the registry
void lte_ue_registry_update(LTE_UE_Registry *registry, LTE_UE_Context *ue_context) {
    pthread_mutex_lock(&registry->lock);
    int index = ue_context->ue_id % registry->size;
    if (registry->buckets[index] != NULL) {
        // Update existing UE context
        free(registry->buckets[index]);
    }
    registry->buckets[index] = ue_context;
    pthread_mutex_unlock(&registry->lock);
}

// Retrieve an UE context from the registry
LTE_UE_Context* lte_ue_registry_get(LTE_UE_Registry *registry, int ue_id) {
    pthread_mutex_lock(&registry->lock);
    LTE_UE_Context *ue_context = NULL;
    int index = ue_id % registry->size;
    if (registry->buckets[index] != NULL && registry->buckets[index]->ue_id == ue_id) {
        ue_context = registry->buckets[index];
    }
    pthread_mutex_unlock(&registry->lock);
    return ue_context;
}

// Free the memory used by the UE registry
void lte_ue_registry_free(LTE_UE_Registry *registry) {
    for (int i = 0; i < registry->size; i++) {
        if (registry->buckets[i] != NULL) {
            free(registry->buckets[i]);
        }
    }
    pthread_mutex_destroy(&registry->lock);
    free(registry->buckets);
    free(registry);
}

// Example usage
int main() {
    LTE_UE_Registry *ue_registry = lte_ue_registry_init(1024);

    // Create a new UE context
    LTE_UE_Context *new_context = (LTE_UE_Context*) malloc(sizeof(LTE_UE_Context));
    new_context->ue_id = 123;
    strcpy(new_context->rrc_state, "RRC_CONNECTED");
    lte_ue_registry_update(ue_registry, new_context);

    // Retrieve the UE context
    LTE_UE_Context *retrieved_context = lte_ue_registry_get(ue_registry, 123);
    if (retrieved_context != NULL) {
        printf("UE ID: %d, RRC State: %s\n", retrieved_context->ue_id, retrieved_context->rrc_state);
    }

    // Free the memory used by the registry
    lte_ue_registry_free(ue_registry);

    return 0;
}
