    size_t size;
    pthread_mutex_t lock;
} LTE_UE_Context_Manager;

LTE_UE_Context_Manager* create_lte_ue_context_manager(size_t initial_capacity) {
    LTE_UE_Context_Manager *manager = (LTE_UE_Context_Manager*)malloc(sizeof(LTE_UE_Context_Manager));
    manager->contexts = (LTE_UE_Context*)calloc(initial_capacity, sizeof(LTE_UE_Context));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_lte_ue_context_manager(LTE_UE_Context_Manager *manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_lte_ue_context(LTE_UE_Context_Manager *manager, LTE_UE_Context context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->contexts = (LTE_UE_Context*)realloc(manager->contexts, manager->capacity * sizeof(LTE_UE_Context));
    }
    manager->contexts[manager->size++] = context;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Return success
}

int remove_lte_ue_context(LTE_UE_Context_Manager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            while (i < manager->size - 1) {
                manager->contexts[i] = manager->contexts[i + 1];
                ++i;
            }
            --manager->size;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Return success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Return error if UE ID not found
}

// Add more functions as needed for updating and querying LTE_UE_Contexts

int main() {
    LTE_UE_Context_Manager *manager = create_lte_ue_context_manager(1024);

    LTE_UE_Context context;
    context.ue_id = 1;
    context.rrc_state = 0; // Example RRC state
    // Initialize other fields as needed

    add_lte_ue_context(manager, context);

    destroy_lte_ue_context_manager(manager);
    return 0;
}
