#include <pthread.h>

#define MAX_UE_CONTEXTS 10000

typedef enum {
    RRC_IDLE,
    RRC_CONNECTED,
    RRC_ESTABLISHING
} RRC_State;

typedef struct QoS_Params {
    int priority;
    int bandwidth;
} QoS_Params;

typedef struct Radio_Bearer {
    int bearer_id;
    QoS_Params qos_params;
} Radio_Bearer;

typedef struct UE_Context {
    int ue_id;
    RRC_State rrc_state;
    Radio_Bearer *bearers;
    int bearer_count;
} UE_Context;

UE_Context *ue_contexts[MAX_UE_CONTEXTS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_ue_context(int ue_id) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return -1;
    pthread_mutex_lock(&lock);
    if (ue_contexts[ue_id] != NULL) {
        pthread_mutex_unlock(&lock);
        return -2; // UE context already exists
    }
    ue_contexts[ue_id] = malloc(sizeof(UE_Context));
    if (ue_contexts[ue_id] == NULL) {
        pthread_mutex_unlock(&lock);
        return -3; // Memory allocation failed
    }
    ue_contexts[ue_id]->ue_id = ue_id;
    ue_contexts[ue_id]->rrc_state = RRC_IDLE;
    ue_contexts[ue_id]->bearers = NULL;
    ue_contexts[ue_id]->bearer_count = 0;
    pthread_mutex_unlock(&lock);
    return 0; // Success
}

void destroy_ue_context(int ue_id) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return;
    pthread_mutex_lock(&lock);
    if (ue_contexts[ue_id] != NULL) {
        free(ue_contexts[ue_id]);
        ue_contexts[ue_id] = NULL;
    }
    pthread_mutex_unlock(&lock);
}

int add_radio_bearer(int ue_id, int bearer_id, QoS_Params *qos_params) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return -1;
    pthread_mutex_lock(&lock);
    UE_Context *ctx = ue_contexts[ue_id];
    if (ctx == NULL) {
        pthread_mutex_unlock(&lock);
        return -2; // UE context does not exist
    }
    Radio_Bearer *new_bearer = realloc(ctx->bearers, (ctx->bearer_count + 1) * sizeof(Radio_Bearer));
    if (new_bearer == NULL) {
        pthread_mutex_unlock(&lock);
        return -3; // Memory allocation failed
    }
    ctx->bearers = new_bearer;
    new_bearer[ctx->bearer_count].bearer_id = bearer_id;
    new_bearer[ctx->bearer_count].qos_params = *qos_params;
    ctx->bearer_count++;
    pthread_mutex_unlock(&lock);
    return 0; // Success
}

int remove_radio_bearer(int ue_id, int bearer_id) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return -1;
    pthread_mutex_lock(&lock);
    UE_Context *ctx = ue_contexts[ue_id];
    if (ctx == NULL) {
        pthread_mutex_unlock(&lock);
        return -2; // UE context does not exist
    }
    for (int i = 0; i < ctx->bearer_count; i++) {
        if (ctx->bearers[i].bearer_id == bearer_id) {
            memmove(ctx->bearers + i, ctx->bearers + i + 1, (ctx->bearer_count - i - 1) * sizeof(Radio_Bearer));
            ctx->bearer_count--;
            pthread_mutex_unlock(&lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&lock);
    return -3; // Radio bearer not found
}

void update_rrc_state(int ue_id, RRC_State new_state) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return;
    pthread_mutex_lock(&lock);
    UE_Context *ctx = ue_contexts[ue_id];
    if (ctx != NULL) {
        ctx->rrc_state = new_state;
    }
    pthread_mutex_unlock(&lock);
}

void log_event(const char *message) {
    printf("%s\n", message);
}
