        if (!interfaces[i]->stats) {
            for (int j = 0; j < i; j++) {
                free(interfaces[j]->frame);
                free(interfaces[j]);
            }
            free(interfaces);
            free(mutexes);
            perror("Memory allocation failed for TX_STATS");
            return NULL;
        }

        pthread_mutex_init(&mutexes[i], NULL);
    }

    // Initialize interfaces based on type and parameters
