    if (current_index >= MAX_UE_CONTEXTS) {
        fprintf(stderr, "Maximum number of UE contexts reached\n");
        return NULL;
    }

    UEContext* new_context = &ue_contexts[current_index];
    new_context->ue_id = ue_id;
    strncpy(new_context->rrc_state, rrc_state, sizeof(new_context->rrc_state) - 1);
    current_index++;

    // Initialize other fields as needed for LTE and 5G NR

    return new_context;
}

void delete_ue_context(UEContext* context) {
    int index = context - ue_contexts;
    if (index < 0 || index >= current_index) {
        fprintf(stderr, "Invalid UE context\n");
        return;
    }

    // Clean up other resources associated with the context

    memset(&ue_contexts[index], 0, sizeof(UEContext));
    while (index < current_index - 1) {
        ue_contexts[index] = ue_contexts[index + 1];
        index++;
    }
    current_index--;
}

