#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define logging levels
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
    LOG_CRITICAL
} LogLevel;

// Define log sinks
typedef enum {
    SINK_FILE,
    SINK_CONSOLE,
    SINK_NETWORK
} LogSink;

// Define log entry structure
typedef struct {
    char* message;
    LogLevel level;
    time_t timestamp;
} LogEntry;

// Define logger structure
typedef struct {
    LogLevel min_level;
    LogSink sink;
    FILE* file;
    int buffer_size;
    LogEntry** buffer;
    int front, rear;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int shutdown_flag;
} Logger;

// Initialize logger
Logger* logger_init(LogLevel min_level, LogSink sink, const char* filename, int buffer_size) {
    // Allocate memory for logger and log entries
    Logger* logger = (Logger*)malloc(sizeof(Logger));
    logger->min_level = min_level;
    logger->sink = sink;
    if (logger->sink == SINK_FILE) {
        logger->file = fopen(filename, "a");
        if (!logger->file) {
            perror("Failed to open log file");
            free(logger);
            return NULL;
        }
    } else {
        logger->file = NULL;
    }
    logger->buffer_size = buffer_size;
    logger->buffer = (LogEntry**)malloc(buffer_size * sizeof(LogEntry*));
    for (int i = 0; i < buffer_size; i++) {
        logger->buffer[i] = (LogEntry*)malloc(sizeof(LogEntry));
    }
    logger->front = logger->rear = -1;
    pthread_mutex_init(&logger->mutex, NULL);
    pthread_cond_init(&logger->cond, NULL);
    logger->shutdown_flag = 0;

    // Start a thread for asynchronous logging
    pthread_t tid;
    pthread_create(&tid, NULL, logger_thread, (void*)logger);

    return logger;
}

// Log message asynchronously
void log_message(Logger* logger, LogLevel level, const char* format, ...) {
    if (level < logger->min_level) {
        return;
    }

    va_list args;
    va_start(args, format);
    char buffer[1024];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    pthread_mutex_lock(&logger->mutex);
    while ((logger->rear + 1) % logger->buffer_size == logger->front && !logger->shutdown_flag) {
        pthread_cond_wait(&logger->cond, &logger->mutex);
    }
    if (logger->shutdown_flag) {
        pthread_mutex_unlock(&logger->mutex);
        return;
    }

    int next = (logger->rear + 1) % logger->buffer_size;
    logger->rear = next;
    logger->buffer[next]->message = strdup(buffer);
    logger->buffer[next]->level = level;
    logger->buffer[next]->timestamp = time(NULL);

    pthread_cond_signal(&logger->cond);
    pthread_mutex_unlock(&logger->mutex);
}

// Asynchronous logging thread
void* logger_thread(void* arg) {
    Logger* logger = (Logger*)arg;
    while (1) {
        LogEntry* entry;
        pthread_mutex_lock(&logger->mutex);
        while (logger->front == -1 && !logger->shutdown_flag) {
            pthread_cond_wait(&logger->cond, &logger->mutex);
        }
        if (logger->shutdown_flag) {
            break;
        }

        int next = (logger->front + 1) % logger->buffer_size;
        entry = logger->buffer[next];
        logger->front = next;

        // Log to the selected sink
        if (logger->sink == SINK_FILE && logger->file) {
            fprintf(logger->file, "[%s] [%s] %s\n", log_level_to_string(entry->level), ctime(&entry->timestamp), entry->message);
            fflush(logger->file);
        } else if (logger->sink == SINK_CONSOLE) {
            printf("[%s] [%s] %s\n", log_level_to_string(entry->level), ctime(&entry->timestamp), entry->message);
        }

        // Free the log entry
        free(entry->message);
        free(entry);

        pthread_cond_signal(&logger->cond);
        pthread_mutex_unlock(&logger->mutex);
    }
    return NULL;
}

// Convert log level to string
const char* log_level_to_string(LogLevel level) {
    switch (level) {
        case LOG_DEBUG: return "DEBUG";
        case LOG_INFO: return "INFO";
        case LOG_WARNING: return "WARNING";
        case LOG_ERROR: return "ERROR";
        case LOG_CRITICAL: return "CRITICAL";
        default: return "UNKNOWN";
    }
}

// Shutdown logger
void logger_shutdown(Logger* logger) {
    pthread_mutex_lock(&logger->mutex);
    logger->shutdown_flag = 1;
    pthread_cond_broadcast(&logger->cond);
    pthread_mutex_unlock(&logger->mutex);

    // Wait for the logging thread to finish
    pthread_join(logger_thread_id, NULL);

    // Free resources
    for (int i = 0; i <= logger->rear; i++) {
        free(logger->buffer[i]->message);
        free(logger->buffer[i]);
    }
    free(logger->buffer);
    pthread_mutex_destroy(&logger->mutex);
    pthread_cond_destroy(&logger->cond);

    if (logger->sink == SINK_FILE) {
        fclose(logger->file);
    }

    free(logger);
}
```

This code provides a basic implementation of a scalable logging framework in C. It includes features such as multiple logging levels, configurable log sinks, dynamic log level setting at runtime, and asynchronous logging to minimize latency during high-throughput scenarios. The logger is designed to be flexible and efficient, with mechanisms for log rotation and archiving to prevent disk overflow. This implementation serves as a starting point and can be extended with additional features such as support for custom log formats, structured logging, and integration with distributed tracing systems.']

