#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define MAX_IP_LEN 16

typedef struct {
    char hostname[MAX_IP_LEN];
    char ip[MAX_IP_LEN];
    time_t last_resolved;
} CacheEntry;

CacheEntry cache[1024];
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* dns_resolution_thread(void* arg) {
    char* hostname = (char*)arg;
    struct hostent* host_info = gethostbyname(hostname);
    if (!host_info) {
        fprintf(stderr, "Failed to resolve %s\n", hostname);
        return NULL;
    }

    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            strcpy(cache[i].ip, inet_ntoa(*(struct in_addr*)host_info->h_addr_list[0]));
            cache[i].last_resolved = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return NULL;
        }
    }

    if (cache_size < 1024) {
        cache[cache_size].hostname[0] = '\0';
        strcpy(cache[cache_size].hostname, hostname);
        strcpy(cache[cache_size].ip, inet_ntoa(*(struct in_addr*)host_info->h_addr_list[0]));
        cache[cache_size].last_resolved = time(NULL);
        cache_size++;
    }
    pthread_mutex_unlock(&cache_lock);

    return NULL;
}

int dns_resolve(const char* hostname, u_char ip[MAX_IP_LEN]) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, dns_resolution_thread, (void*)hostname) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return -1;
    }

    if (pthread_join(thread_id, NULL) != 0) {
        fprintf(stderr, "Failed to join thread\n");
        return -1;
    }

    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            strcpy((char*)ip, cache[i].ip);
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    return -1;
}
