class DataProcessor {
  constructor(options) {
    this.options = options || {};
    this.outputBuffer = Buffer.alloc(0);
    this.processingQueue = [];
    this.isProcessing = false;
    this.logLevel = this.options.logLevel || 'info';
    this.retryCount = 0;
    this.maxRetries = this.options.maxRetries || 5;
    this.exponentialBackoffFactor = this.options.exponentialBackoffFactor || 2;
    this.requestTimeout = this.options.requestTimeout || 10000;
    this.backpressureThreshold = this.options.backpressureThreshold || 1024 * 1024; // 1MB
  }

  async processData(dataChunk) {
    if (typeof dataChunk !== 'Buffer') {
      throw new Error('Invalid input data type');
    }

    if (!this.isProcessing && this.outputBuffer.length + dataChunk.length > 1e9) {
      throw new Error('Data exceeds maximum buffer size of 1GB');
    }

    this.processingQueue.push(dataChunk);
    if (!this.isProcessing) {
      this.startProcessing();
    }
  }

  async startProcessing() {
    this.isProcessing = true;
    while (this.processingQueue.length > 0 && this.outputBuffer.length < 1e9) {
      const dataChunk = this.processingQueue.shift();
      try {
        await this.sendDataToService(dataChunk);
      } catch (error) {
        if (this.retryCount < this.maxRetries) {
          setTimeout(() => this.startProcessing(), this.getExponentialBackoffInterval());
        } else {
          this.log('Error processing data: ' + error.message, 'error');
        }
        break;
      }
    }
    this.isProcessing = false;
  }

  async sendDataToService(dataChunk) {
    // Simulate asynchronous request to third-party service
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (this.outputBuffer.length + dataChunk.length > this.backpressureThreshold) {
          reject(new Error('Backpressure threshold exceeded'));
        } else {
          this.outputBuffer = Buffer.concat([this.outputBuffer, dataChunk]);
          resolve();
        }
      }, this.requestTimeout);
    });
  }

  getExponentialBackoffInterval() {
    return Math.min(
      this.maxRetries * this.exponentialBackoffFactor ** this.retryCount,
      1e3
    );
  }

  log(message, level) {
    if (this.logLevel === 'debug' || level === 'error') {
      console.log(`[${new Date().toISOString()}] [${level.toUpperCase()}] ${message}`);
    }
  }
}

module.exports = DataProcessor;
