#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} NFAPI_ARRAY_MANAGER_T;

void nfapi_array_init(NFAPI_ARRAY_MANAGER_T *manager, size_t initial_size) {
    manager->array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->array == NULL) {
        // Handle memory allocation failure
        return;
    }
    manager->allocated_size = initial_size;
    manager->used_size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void nfapi_array_insert(NFAPI_ARRAY_MANAGER_T *manager, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    pthread_mutex_lock(&manager->lock);
    if (manager->used_size >= manager->allocated_size) {
        size_t new_size = manager->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->array = new_array;
        manager->allocated_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_entry = &manager->array[manager->used_size];
    new_entry->ue_info = ue_info;
    new_entry->rnti = rnti;

    // Generate CRCFLAG based on a probability distribution
    double random_value = rand() / (double)RAND_MAX;
    if (random_value < 0.5) {
        new_entry->crc_indication.CRCFLAG = 0; // Example of setting CRCFLAG based on probability
    } else {
        new_entry->crc_indication.CRCFLAG = 1;
    }

    manager->used_size++;
    pthread_mutex_unlock(&manager->lock);
}

void nfapi_array_free(NFAPI_ARRAY_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
```

