#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_NF_API_CRC_INDICATION_PDU_T 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    clock_t last_cleanup_time;
    int cleanup_interval;
} NFAPICRCArray;

NFAPICRCArray* nfapi_crc_array_init(int initial_capacity) {
    NFAPICRCArray* array = malloc(sizeof(NFAPICRCArray));
    if (array == NULL) {
        return NULL;
    }
    array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->array == NULL) {
        free(array);
        return NULL;
    }
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    array->last_cleanup_time = clock();
    array->cleanup_interval = 60; // Cleanup every 60 seconds
    return array;
}

void nfapi_crc_array_free(NFAPICRCArray* array) {
    if (array == NULL) {
        return;
    }
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    pthread_mutex_unlock(&array->mutex);
    free(array);
}

int nfapi_crc_array_add(NFAPICRCArray* array, NFAPI_CRC_INDICATION_PDU_T pdu, double crc_probability) {
    if (array == NULL || pdu.CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
        return -1;
    }
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = pdu;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int nfapi_crc_array_get_valid_count(NFAPICRCArray* array) {
    if (array == NULL) {
        return -1;
    }
    int count = 0;
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
            count++;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return count;
}

void nfapi_crc_array_cleanup(NFAPICRCArray* array) {
    if (array == NULL) {
        return;
    }
    clock_t now = clock();
    if ((now - array->last_cleanup_time) < array->cleanup_interval * CLOCKS_PER_SEC) {
        return;
    }
    pthread_mutex_lock(&array->mutex);
    size_t new_size = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
            array->array[new_size++] = array->array[i];
        }
    }
    array->size = new_size;
    pthread_mutex_unlock(&array->mutex);
    array->last_cleanup_time = now;
}
