typedef struct {
    // QoS parameters for the bearer
} RB_QoS;

typedef struct {
    UE_ID id;
    RRC_State rrc_state;
    RB_QoS qos_params;
    // List of active radio bearers
} UE_Context;

typedef struct {
    pthread_mutex_t lock;
    UE_Context *contexts[MAX_UE_CONTEXTS];
} LTE_UE_Manager;

// Function to initialize the manager
LTE_UE_Manager* lte_ue_manager_init() {
    LTE_UE_Manager *manager = (LTE_UE_Manager*)malloc(sizeof(LTE_UE_Manager));
    if (manager == NULL) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        manager->contexts[i] = NULL;
    }
    return manager;
}

// Function to add a new UE context
void lte_ue_manager_add(LTE_UE_Manager *manager, UE_ID id, RRC_State state, RB_QoS qos) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->contexts[i] == NULL) {
            manager->contexts[i] = (UE_Context*)malloc(sizeof(UE_Context));
            if (manager->contexts[i] != NULL) {
                manager->contexts[i]->id = id;
                manager->contexts[i]->rrc_state = state;
                manager->contexts[i]->qos_params = qos;
            }
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to remove an existing UE context
void lte_ue_manager_remove(LTE_UE_Manager *manager, UE_ID id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->contexts[i] != NULL && manager->contexts[i]->id == id) {
            free(manager->contexts[i]);
            manager->contexts[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to get the RRC state of a UE
RRC_State lte_ue_manager_get_rrc_state(LTE_UE_Manager *manager, UE_ID id) {
    RRC_State state = RRC_IDLE; // Default if not found
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->contexts[i] != NULL && manager->contexts[i]->id == id) {
            state = manager->contexts[i]->rrc_state;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return state;
}

// Function to clean up the manager
void lte_ue_manager_cleanup(LTE_UE_Manager *manager) {
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->contexts[i] != NULL) {
            free(manager->contexts[i]);
        }
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
