char* append_slash(char* str, int max_size, int flag) {
    if (!str || !max_size) return NULL;

    int len = strlen(str);
    if (len >= max_size - 1) return NULL;

    if (flag == 1) {
        // Memory-efficient operation
        memmove(str + len + 1, str, len + 1);
        str[len] = '/';
    } else {
        str[len] = '/';
        str[len + 1] = '\0';
    }

    return str;
}

