void *loadAndResolveDNS(void *arg) {
    char *hostname = (char *)arg;
    u_char ip[MAX_IP_LEN] = {0};
    int ttl = 0;

    // Check cache
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memcpy(ip, cache[i].ip, MAX_IP_LEN);
            ttl = cache[i].ttl;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    if (ttl > 0) {
        return ip;
    }

    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), ip, INET_ADDRSTRLEN);

    freeaddrinfo(res);

    // Update cache
    pthread_mutex_lock(&cache_lock);
    if (cache_size < CACHE_SIZE) {
        strcpy(cache[cache_size].hostname, hostname);
        memcpy(cache[cache_size].ip, ip, MAX_IP_LEN);
        cache[cache_size].ttl = 3600; // TTL in seconds
        cache_size++;
    }
    pthread_mutex_unlock(&cache_lock);

    return ip;
}

