['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>

// Define error codes
#define ERR_SUCCESS 0
#define ERR_NO_HOSTENT -1
#define ERR_INVALID_IP -2
#define ERR_RESOLVER_FAILURE -3
#define ERR_TIMEOUT -4

// DNS cache entry structure
typedef struct {
    char hostname[256];
    uint8_t ip[4];
    time_t last_access;
} DnsCacheEntry;

// LRU Cache structure
typedef struct {
    DnsCacheEntry *entries;
    int capacity;
    int count;
    pthread_mutex_t lock;
} DnsCache;

// Initialize the DNS cache
DnsCache* dns_cache_init(int capacity) {
    DnsCache *cache = (DnsCache*)malloc(sizeof(DnsCache));
    cache->entries = (DnsCacheEntry*)calloc(capacity, sizeof(DnsCacheEntry));
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Free the DNS cache
void dns_cache_free(DnsCache *cache) {
    pthread_mutex_lock(&cache->lock);
    free(cache->entries);
    pthread_mutex_unlock(&cache->lock);
    free(cache);
}

// Insert or update an entry in the DNS cache
int dns_cache_insert(DnsCache *cache, const char *hostname, uint8_t ip[4]) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->capacity; ++i) {
        if (strcmp(cache->entries[i].hostname, hostname) == 0) {
            memcpy(cache->entries[i].ip, ip, sizeof(ip));
            cache->entries[i].last_access = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return ERR_SUCCESS;
        }
    }
    // Evict least recently used item
    int min_index = 0;
    for (int i = 1; i < cache->capacity; ++i) {
        if (cache->entries[i].last_access < cache->entries[min_index].last_access) {
            min_index = i;
        }
    }
    memcpy(cache->entries[min_index].hostname, hostname, sizeof(hostname));
    memcpy(cache->entries[min_index].ip, ip, sizeof(ip));
    cache->entries[min_index].last_access = time(NULL);
    pthread_mutex_unlock(&cache->lock);
    return ERR_SUCCESS;
}

// Lookup an entry in the DNS cache
int dns_cache_lookup(DnsCache *cache, const char *hostname, uint8_t ip[4]) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->capacity; ++i) {
        if (strcmp(cache->entries[i].hostname, hostname) == 0) {
            memcpy(ip, cache->entries[i].ip, sizeof(ip));
            cache->entries[i].last_access = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return ERR_SUCCESS;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return ERR_NO_HOSTENT;
}

// Perform DNS resolution
int dns_resolve(const char *hostname, uint8_t ip[4], DnsCache *cache) {
    int status = dns_cache_lookup(cache, hostname, ip);
    if (status == ERR_SUCCESS) {
        return ERR_SUCCESS;
    }

    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return ERR_RESOLVER_FAILURE;
    }

    p = res;
    struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
    memcpy(ip, &ipv4->sin_addr, sizeof(ip));

    freeaddrinfo(res);

    status = dns_cache_insert(cache, hostname, ip);
    if (status != ERR_SUCCESS) {
        return status;
    }

    return ERR_SUCCESS;
}

// Example usage
int main() {
    DnsCache *cache = dns_cache_init(100);
    uint8_t ip[4];

    int status = dns_resolve("www.example.com", ip, cache);
    if (status == ERR_SUCCESS) {
        printf("IP address: %d.%d.%d.%d\n", ip[0], ip[1], ip[2], ip[3]);
    } else {
        printf("DNS resolution failed with status: %d\n", status);
    }

    dns_cache_free(cache);
    return 0;
}
