    int active_bearers[10];
    // Add fields for connection history and QoS parameters
} LTE_UE_Context;

typedef struct {
    pthread_mutex_t mutex;
    LTE_UE_Context contexts[1000]; // Example size, adjust as needed
    int next_id;
} LTE_Region;

LTE_Region regions[MAX_REGIONS]; // MAX_REGIONS should be defined

void init_region(LTE_Region *region) {
    pthread_mutex_init(&region->mutex, NULL);
    region->next_id = 0;
}

int add_ue_to_region(LTE_Region *region, int rrc_state, int bearers[]) {
    pthread_mutex_lock(&region->mutex);
    if (region->next_id >= sizeof(region->contexts) / sizeof(region->contexts[0])) {
        pthread_mutex_unlock(&region->mutex);
        return -1; // Error: No available IDs
    }
    LTE_UE_Context *new_context = &region->contexts[region->next_id++];
    new_context->ue_id = region->next_id - 1;
    new_context->rrc_state = rrc_state;
    memcpy(new_context->active_bearers, bearers, sizeof(bearers));
    pthread_mutex_unlock(&region->mutex);
    return new_context->ue_id;
}

