#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_HOSTNAME_LEN 256
#define IP_ADDR_SIZE (sizeof(struct in6_addr))

typedef struct {
    u_char ip[IP_ADDR_SIZE];
    int family;
} IPAddress;

void* resolve_dns(void* arg) {
    char* hostname = (char*)arg;
    struct addrinfo hints, *res, *p;
    int status;
    IPAddress ip_address;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET || p->ai_family == AF_INET6) {
            memcpy(ip_address.ip, &((struct sockaddr_in*)p->ai_addr)->sin_addr, IP_ADDR_SIZE);
            ip_address.family = p->ai_family;
            freeaddrinfo(res);
            return (void*)&ip_address;
        }
    }

    fprintf(stderr, "Failed to resolve hostname: %s\n", hostname);
    freeaddrinfo(res);
    return NULL;
}

int main() {
    char hostname[MAX_HOSTNAME_LEN];
    printf("Enter a hostname: ");
    fgets(hostname, MAX_HOSTNAME_LEN, stdin);

    // Remove newline character
    hostname[strcspn(hostname, "\n")] = 0;

    pthread_t thread;
    if (pthread_create(&thread, NULL, resolve_dns, hostname) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    void* result;
    if (pthread_join(thread, &result) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    IPAddress *ip_address = (IPAddress*)result;
    if (ip_address != NULL) {
        char ip_str[INET6_ADDRSTRLEN];
        if (inet_ntop(ip_address->family, ip_address->ip, ip_str, INET6_ADDRSTRLEN) != NULL) {
            printf("Resolved IP: %s\n", ip_str);
        } else {
            perror("Failed to convert IP address");
        }
    }

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of the DNS resolution function with error handling and threading support. It uses the `getaddrinfo` function to perform DNS resolution and returns the IP address in the most appropriate format (IPv4 or IPv6). The result is stored in an `IPAddress` structure, which is then printed in main after the thread completes execution. This example demonstrates basic synchronization and error handling for a multi-threaded DNS resolution scenario.']

