// Function prototypes
void fetch_commit_history(const char *repo_url, const char *branch, const char *output_file);
int parse_command_line(int argc, char **argv, char **repo_url, char **branch, char **output_file);

int main(int argc, char **argv) {
    char *repo_url = NULL;
    char *branch = NULL;
    char *output_file = NULL;

    if (parse_command_line(argc, argv, &repo_url, &branch, &output_file)) {
        printf("Error parsing command line arguments.\n");
        return 1;
    }

    fetch_commit_history(repo_url, branch, output_file);

    free(repo_url);
    free(branch);
    free(output_file);

    return 0;
}

int parse_command_line(int argc, char **argv, char **repo_url, char **branch, char **output_file) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-r") == 0 || strcmp(argv[i], "--repo") == 0) {
            *repo_url = argv[++i];
        } else if (strcmp(argv[i], "-b") == 0 || strcmp(argv[i], "--branch") == 0) {
            *branch = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            *output_file = argv[++i];
        }
    }

    if (*repo_url == NULL || *branch == NULL) {
        return 1;
    }

    return 0;
}

void fetch_commit_history(const char *repo_url, const char *branch, const char *output_file) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct MemoryStruct chunk;
        chunk.memory = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point

        curl_easy_setopt(curl, CURLOPT_URL, repo_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Process commit history data here
            printf("Commit history fetched successfully.\n");
        }

        free(chunk.memory);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}
