NFAPI_CRC_INDICATION_PDU_T* manage_dynamic_array(int N, int max_size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    int current_size = 0;

    while (current_size < N && current_size <= max_size) {
        if (current_size == 0 || array == NULL) {
            array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_size);
            if (array == NULL) {
                perror("Failed to allocate memory");
                return NULL;
            }
        }

        pthread_mutex_lock(&mutex);

        // Populate and randomize CRCFLAG here
        array[current_size].RX_UE_INFORMATION_TAG = current_size;
        array[current_size].RNTI = rand() % 65536; // Random RNTI between 0 and 65535
        array[current_size].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG

        pthread_mutex_unlock(&mutex);

        current_size++;
    }

    if (current_size > max_size) {
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_size);
        if (array == NULL) {
            perror("Failed to resize memory");
            return NULL;
        }
    }

    return array;
}
