typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_array(size_t initial_size) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->size = 0;
    da->capacity = initial_size > MAX_SIZE ? MAX_SIZE : initial_size;
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(da->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_array(DynamicArray *da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->mutex);
        free(da);
    }
}

int insert_element(DynamicArray *da, int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2 > MAX_SIZE ? MAX_SIZE : da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *elem = &da->array[da->size++];
    elem->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    elem->RNTI = RNTI;
    // Initialize other fields...

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

