#include <string.h>

#define MAX_UE_CONTEXTS 1000
#define MAX_BEARERS_PER_UE 5
#define ROLLING_HISTORY_DAYS 30

typedef enum {
    UE_CONNECTED,
    UE_DISCONNECTED,
    UE_IDLE
} RRC_State;

typedef struct {
    int bearer_id;
    // QoS parameters and other bearer-specific data
} RadioBearer;

typedef struct {
    int ue_id;
    RRC_State rrc_state;
    RadioBearer bearers[MAX_BEARERS_PER_UE];
    time_t connection_history[ROLLING_HISTORY_DAYS];
    pthread_mutex_t mutex;
} UE_Context;

typedef struct {
    UE_Context ues[MAX_UE_CONTEXTS];
    int total_ues;
    pthread_rwlock_t rwlock;
} LTE_Network;

LTE_Network network;

void init_network() {
    memset(&network, 0, sizeof(network));
    pthread_rwlock_init(&network.rwlock, NULL);
}

void add_ue_context(int ue_id) {
    pthread_rwlock_wrlock(&network.rwlock);
    if (network.total_ues < MAX_UE_CONTEXTS) {
        UE_Context *ue = &network.ues[network.total_ues++];
        memset(ue, 0, sizeof(*ue));
        ue->ue_id = ue_id;
        pthread_mutex_init(&ue->mutex, NULL);
    }
    pthread_rwlock_unlock(&network.rwlock);
}

void remove_ue_context(int ue_id) {
    pthread_rwlock_wrlock(&network.rwlock);
    for (int i = 0; i < network.total_ues; ++i) {
        if (network.ues[i].ue_id == ue_id) {
            pthread_mutex_destroy(&network.ues[i].mutex);
            memmove(&network.ues[i], &network.ues[i + 1], sizeof(UE_Context) * (network.total_ues - i - 1));
            network.total_ues--;
            break;
        }
    }
    pthread_rwlock_unlock(&network.rwlock);
}

void update_rrc_state(int ue_id, RRC_State state) {
    pthread_rwlock_wrlock(&network.rwlock);
    for (int i = 0; i < network.total_ues; ++i) {
        if (network.ues[i].ue_id == ue_id) {
            pthread_mutex_lock(&network.ues[i].mutex);
            network.ues[i].rrc_state = state;
            pthread_mutex_unlock(&network.ues[i].mutex);
            break;
        }
    }
    pthread_rwlock_unlock(&network.rwlock);
}

void add_bearer(int ue_id, RadioBearer bearer) {
    pthread_rwlock_wrlock(&network.rwlock);
    for (int i = 0; i < network.total_ues; ++i) {
        if (network.ues[i].ue_id == ue_id) {
            pthread_mutex_lock(&network.ues[i].mutex);
            int empty_slot = -1;
            for (int j = 0; j < MAX_BEARERS_PER_UE; ++j) {
                if (!network.ues[i].bearers[j].bearer_id) {
                    empty_slot = j;
                    break;
                }
            }
            if (empty_slot != -1) {
                network.ues[i].bearers[empty_slot] = bearer;
            } else {
                // Handle error: no room for new bearer
            }
            pthread_mutex_unlock(&network.ues[i].mutex);
            break;
        }
    }
    pthread_rwlock_unlock(&network.rwlock);
}

void remove_bearer(int ue_id, int bearer_id) {
    pthread_rwlock_wrlock(&network.rwlock);
    for (int i = 0; i < network.total_ues; ++i) {
        if (network.ues[i].ue_id == ue_id) {
            pthread_mutex_lock(&network.ues[i].mutex);
            for (int j = 0; j < MAX_BEARERS_PER_UE; ++j) {
                if (network.ues[i].bearers[j].bearer_id == bearer_id) {
                    network.ues[i].bearers[j] = (RadioBearer){0};
                    break;
                }
            }
            pthread_mutex_unlock(&network.ues[i].mutex);
            break;
        }
    }
    pthread_rwlock_unlock(&network.rwlock);
}
