using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;

public interface IHttpResult
{
    int StatusCode { get; }
    string Content { get; }
}

public class CustomerRequestProcessor
{
    public async Task<IHttpResult> ProcessCustomerRequests(List<RequestParameter> parameters, IDbConnection connection, string baseRouteTemplate)
    {
        // Filter and sort data based on request parameters
        var query = "SELECT * FROM Customers";
        if (parameters.Any())
        {
            query += " WHERE 1=1";
            foreach (var param in parameters)
            {
                query += $" AND {param.Key} = @{param.Key}";
            }
        }

        // Execute the database query asynchronously
        using (var command = new SqlCommand(query, connection))
        {
            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue("@" + param.Key, param.Value);
            }

            using (var reader = await command.ExecuteReaderAsync())
            {
                var dataTable = new DataTable();
                dataTable.Load(reader);

                // Sort data if needed
                if (!string.IsNullOrEmpty(parameters.FirstOrDefault(p => p.Key == "OrderBy")?.Value))
                {
                    var orderByColumn = parameters.First(p => p.Key == "OrderBy").Value;
                    dataTable.DefaultView.Sort = orderByColumn + (parameters.Any(p => p.Key == "SortOrder" && p.Value == "desc") ? " DESC" : "");
                    dataTable = dataTable.DefaultView.ToTable();
                }

                // Generate the API endpoint
                var apiRoute = string.Format(baseRouteTemplate, parameters.FirstOrDefault(p => p.Key == "TenantId")?.Value);
                var responseContent = $"Data for tenant {parameters.First(p => p.Key == "TenantId").Value}: " + DataTableToJson(dataTable);

                return new HttpResult(200, responseContent);
            }
        }
    }

    private string DataTableToJson(DataTable dataTable)
    {
        // Convert DataTable to JSON string
        var json = Newtonsoft.Json.JsonConvert.SerializeObject(dataTable, Formatting.Indented);
        return json;
    }
}

public class RequestParameter
{
    public string Key { get; set; }
    public object Value { get; set; }
}

public class HttpResult : IHttpResult
{
    public int StatusCode { get; private set; }
    public string Content { get; private set; }

    public HttpResult(int statusCode, string content)
    {
        StatusCode = statusCode;
        Content = content;
    }
}
