int run_command_in_background(const char* command, const char* output_file) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        FILE* output = fopen(output_file, "w");
        if (!output) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        int fd = fileno(output);
        dup2(fd, STDOUT_FILENO);
        close(fd);
        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("execlp");
        fclose(output);
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    }
}

int main() {
    init_UEContext(12345);
    if (run_command_in_background("ls -l > output.log", "output.log") != 1) {
        printf("Command execution failed\n");
    } else {
        printf("Command executed successfully\n");
    }
    return 0;
}
