typedef enum {
    CIPHER_MODE_ECB,
    CIPHER_MODE_EDE,
    CIPHER_MODE_EDE3,
    CIPHER_MODE_CFB,
    CIPHER_MODE_NULL
} CipherMode;

typedef struct {
    CipherMode mode;
    int key_length;
    // Add other configuration parameters here
} CryptoConfig;

EVP_CIPHER* get_cipher(EVP_CIPHER** cipher, const CryptoConfig* config) {
    if (cipher == NULL || config == NULL) {
        fprintf(stderr, "Invalid arguments\n");
        return NULL;
    }

    switch (config->mode) {
        case CIPHER_MODE_ECB:
            *cipher = EVP_des_ecb();
            break;
        case CIPHER_MODE_EDE:
            *cipher = EVP_des_ede3_cbc();
            break;
        case CIPHER_MODE_CFB:
            *cipher = EVP_des_cfb8();
            break;
        case CIPHER_MODE_NULL:
            *cipher = NULL; // Null cipher for testing
            break;
        default:
            fprintf(stderr, "Unsupported cipher mode\n");
            return NULL;
    }

    if (*cipher == NULL) {
        fprintf(stderr, "Cipher initialization failed\n");
        return NULL;
    }

    if (config->key_length != EVP_CIPHER_key_length(*cipher)) {
        fprintf(stderr, "Invalid key length for the selected cipher mode\n");
        return NULL;
    }

    printf("Cipher initialized successfully: %s\n", EVP_CIPHER_name(*cipher));
    return *cipher;
}

int main() {
    CryptoConfig config = {CIPHER_MODE_ECB, 8};
    EVP_CIPHER* cipher;

    if (get_cipher(&cipher, &config) != NULL) {
        // Use the cipher for encryption/decryption
        printf("Cipher used: %s\n", EVP_CIPHER_name(cipher));
        EVP_CIPHER_free(cipher);
    }

    return 0;
}
