LTE_Region_Manager *region_manager = NULL;

void initialize_region_manager() {
    region_manager = (LTE_Region_Manager *)malloc(sizeof(LTE_Region_Manager));
    pthread_mutex_init(&region_manager->lock, NULL);
    memset(region_manager->ue_contexts, 0, sizeof(region_manager->ue_contexts));
}

void add_ue_context(int ue_id) {
    pthread_mutex_lock(&region_manager->lock);
    if (region_manager->next_index < MAX_UE_CONTEXTS) {
        LTE_UE_Context *new_context = (LTE_UE_Context *)malloc(sizeof(LTE_UE_Context));
        new_context->ue_id = ue_id;
        new_context->rrc_state = RRC_STATE_IDLE;
        region_manager->ue_contexts[region_manager->next_index++] = new_context;
    }
    pthread_mutex_unlock(&region_manager->lock);
}

void update_rrc_state(int ue_id, int new_state) {
    pthread_mutex_lock(&region_manager->lock);
    for (int i = 0; i < region_manager->next_index; i++) {
        if (region_manager->ue_contexts[i]->ue_id == ue_id) {
            region_manager->ue_contexts[i]->rrc_state = new_state;
            break;
