int update_ue_context(LTEUEManager* manager, int ue_id, UERadioResourceControlState rrc_state) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (manager->contexts[i] != NULL && manager->contexts[i]->ue_id == ue_id) {
            manager->contexts[i]->rrc_state = rrc_state;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    LTEUEContext* new_context = create_ue_context(ue_id, rrc_state);
    if (new_context == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (manager->contexts[i] == NULL) {
            manager->contexts[i] = new_context;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    destroy_ue_context(new_context);
    return -1;
