namespace http = boost::beast::http;

class LTEUEContext {
public:
    LTEUEContext(int id, std::string rrc_state)
        : ue_id(id), rrc_state(rrc_state) {}

    int getUeId() const { return ue_id; }
    void setRrcState(const std::string& state) { rrc_state = state; }
    std::string getRrcState() const { return rrc_state; }

private:
    int ue_id;
    std::string rrc_state;
};

class UEMap {
public:
    std::mutex mutex_;
    std::unordered_map<int, LTEUEContext> contexts_;

    void addOrUpdate(int id, const std::string& state) {
        std::lock_guard<std::mutex> lock(mutex_);
        contexts_[id] = LTEUEContext(id, state);
    }

    bool get(int id, LTEUEContext& context) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = contexts_.find(id);
        if (it != contexts_.end()) {
            context = it->second;
            return true;
        }
        return false;
    }
};

class SandeshClient : public boost::enable_shared_from_this<SandeshClient> {
public:
    SandeshClient(boost::asio::io_context& ioc, std::string url)
        : resolver_(ioc), socket_(ioc), url_(std::move(url)) {}

    void start() {
        resolve_and_connect();
    }

private:
    boost::beast::tcp_stream socket_;
    boost::beast::flat_buffer buffer_;
    boost::asio::ip::tcp::resolver resolver_;
    std::string url_;
    boost::asio::strand<boost::asio::io_context::executor_type> strand_;

    void resolve_and_connect() {
        auto [ec, endpoints] = resolver_.async_resolve(url_, "http", {}, boost::asio::use_future).get();
        if (!ec) {
            connect(endpoints);
        }
    }

    void connect(const boost::asio::ip::tcp::resolver::results_type& endpoints) {
        boost::asio::async_connect(socket_, endpoints, [this](boost::system::error_code ec, const boost::asio::ip::tcp::endpoint&) {
            if (!ec) {
                send_request();
            }
        });
    }

    void send_request() {
        http::request<http::string_body> req{http::verb::get, "/", 11};
        req.set(http::field::host, "example.com");
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        http::async_write(socket_, req, [this](boost::system::error_code ec, std::size_t) {
            if (!ec) {
                read_response();
            }
        });
    }

    void read_response() {
        http::async_read(socket_, buffer_, [this](boost::system::error_code ec, std::size_t bytes_transferred) {
            if (!ec) {
                handle_response();
                send_request_with_delay();
            } else {
                log_error(ec);
            }
        });
    }

    void send_request_with_delay() {
        auto delay = std::chrono::milliseconds(10 + rand() % 40);
        boost::asio::post(strand_, [this, delay]() {
            boost::asio::steady_timer timer(socket_.get_executor().context(), delay);
            timer.async_wait([this](boost::system::error_code ec) {
                if (!ec) {
                    send_request();
                }
            });
        });
    }

    void handle_response() {
        http::response<http::string_body> res;
        boost::beast::flat_buffer buffer;
        http::read(socket_, buffer, res);
    }

    void log_error(const boost::system::error_code& ec) {
        std::cerr << "Error: " << ec.message() << "\n";
    }
};

int main() {
    boost::asio::io_context ioc{2};
    UEMap ue_map;
    SandeshClient client1{ioc, "http://example.com"};
    SandeshClient client2{ioc, "https://example.com"};

    client1.start();
    client2.start();

    ioc.run();

    return 0;
}
