            for (size_t i = 0; i < length; i++) {
                printf("%02x", encrypted[i]);
            }
            printf("\n");

            // Decrypt data
            if (module->decrypt) {
                module->decrypt(key, iv, length, decrypted);
                decrypted[length] = '\0';
