    manager->service_count = 0;
    manager->channel_count = 0;
    return manager;
}

void add_service_instance(NetworkServiceManager *manager, ServiceInstance *instance) {
    if (manager->service_count < MAX_SERVICE_INSTANCES) {
        manager->services[manager->service_count++] = instance;
    } else {
        printf("Error: Maximum service instances reached.\n");
    }
}

void add_transport_channel(NetworkServiceManager *manager, TransportChannel *channel) {
    if (manager->channel_count < MAX_TRANSPORT_CHANNELS) {
        manager->channels[manager->channel_count++] = channel;
    } else {
        printf("Error: Maximum transport channels reached.\n");
    }
}

