import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.spec.SecretKeySpec;

public class DirectoryProcessor {

    private static final int MAX_DEPTH = 10;
    private static final String[] TEXT_EXTENSIONS = {".txt", ".log"};
    private static final Set<String> hiddenFiles = new HashSet<>(Arrays.asList(".DS_Store"));

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java DirectoryProcessor <directory> <outputFile>");
            return;
        }

        Path directoryPath = Paths.get(args[0]);
        Path outputPath = Paths.get(args[1]);

        try {
            long totalLines = processDirectory(directoryPath, MAX_DEPTH, new HashSet<>());
            writeOutput(outputPath, "Total lines: " + totalLines);
        } catch (IOException | InterruptedException e) {
            System.err.println("Error processing directory: " + e.getMessage());
        }
    }

    private static long processDirectory(Path path, int depth, Set<Path> visited) throws IOException, InterruptedException {
        if (depth <= 0 || !Files.isDirectory(path)) {
            return 0;
        }

        if (!visited.add(path)) {
            return 0; // Avoid infinite loops for cyclic directory structures
        }

        long lineCount = 0;

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(path)) {
            for (Path entry : stream) {
                if (Files.isHidden(entry) || Files.isSymbolicLink(entry)) {
                    continue;
                }

                if (Files.isDirectory(entry)) {
                    lineCount += processDirectory(entry, depth - 1, visited);
                } else {
                    String fileName = entry.toString();
                    int lastDotIndex = fileName.lastIndexOf('.');
                    if (lastDotIndex != -1 && Arrays.asList(TEXT_EXTENSIONS).contains(fileName.substring(lastDotIndex))) {
                        lineCount += countLinesInFile(entry);
                    }
                }
            }
        }

        return lineCount;
    }

    private static long countLinesInFile(Path path) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            return reader.lines().count();
        }
    }

    private static void writeOutput(Path outputPath, String content) throws IOException {
        try (PrintWriter writer = new PrintWriter(Files.newOutputStream(outputPath))) {
            writer.println(content);
        }
    }

    // Additional methods for cryptographic operations can be added here
}
