// Define the TCP connection context structure
struct ConnectionContext {
    std::string clientIP;
    bool isConnected;
    std::vector<int> dataChannels;

    ConnectionContext(std::string ip, bool connected) : clientIP(ip), isConnected(connected) {}
};

// Define the NFAPI CRC indication PDU structure
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;

    NFAPI_CRC_INDICATION_PDU_T(int tag, int rnti, bool crcflag) : RX_UE_INFORMATION_TAG(tag), RNTI(rnti), CRCFLAG(crcflag) {}
};

// Define the SQL command execution structure
struct SQLCommandExecution {
    std::string values;
    std::string connection;
    std::string sqlCommand;

    SQLCommandExecution(std::string v, std::string conn, std::string cmd) : values(v), connection(conn), sqlCommand(cmd) {}
};

// Dynamic pool of TCP connection contexts
class ConnectionPool {
private:
    std::vector<std::unique_ptr<ConnectionContext>> pool;
    std::mutex poolMutex;
    std::atomic<int> nextIndex;

public:
    ConnectionPool(int initialSize = 10) : nextIndex(0) {
        for (int i = 0; i < initialSize; ++i) {
            pool.push_back(std::make_unique<ConnectionContext>("", false));
        }
    }

    std::unique_ptr<ConnectionContext> allocate() {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (nextIndex >= static_cast<int>(pool.size())) {
            resizePool();
        }
        return std::move(pool[nextIndex++]);
    }

    void deallocate(std::unique_ptr<ConnectionContext>& context) {
        std::lock_guard<std::mutex> lock(poolMutex);
        context->isConnected = false;
        context->dataChannels.clear();
        pool[--nextIndex] = std::make_unique<ConnectionContext>("", false);
    }

private:
    void resizePool() {
        int newSize = static_cast<int>(pool.size()) * 2;
        for (int i = pool.size(); i < newSize; ++i) {
            pool.push_back(std::make_unique<ConnectionContext>("", false));
        }
    }
};

