    std::string line;
    while (std::getline(file, line)) {
        // Process each line and update the octree
        size_t pos = line.find_last_of(',');
        if (pos != std::string::npos) {
            double lastField1 = std::stod(line.substr(0, pos));
            double lastField2 = std::stod(line.substr(pos + 1));
            double average = (lastField1 + lastField2) / 2.0;
            line.append(",").append(std::to_string(average));
        }
    }

    file.close();
}

