#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct Semaphore {
    char name[20];
    int value;
    int max_value;
    sem_t *sem;
    pthread_mutex_t mutex;
    struct Semaphore *next;
} Semaphore;

Semaphore *sem_list = NULL;

void log_operation(const char *operation, const char *name) {
    printf("%s: %s\n", operation, name);
}

Semaphore* create_semaphore(const char *name, int initial_value, int max_value) {
    Semaphore *new_sem = (Semaphore *)malloc(sizeof(Semaphore));
    if (!new_sem) return NULL;
    snprintf(new_sem->name, sizeof(new_sem->name), "%s", name);
    new_sem->value = initial_value;
    new_sem->max_value = max_value;
    sem_init(&new_sem->sem, 0, initial_value);
    pthread_mutex_init(&new_sem->mutex, NULL);
    new_sem->next = sem_list;
    sem_list = new_sem;
    log_operation("Created", name);
    return new_sem;
}

void destroy_semaphore(Semaphore *sem) {
    sem_destroy(sem->sem);
    pthread_mutex_destroy(&sem->mutex);
    free(sem);
    log_operation("Destroyed", sem->name);
}

int acquire_semaphore(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    if (sem->value < sem->max_value) {
        sem_wait(sem->sem);
        sem->value++;
        log_operation("Acquired", sem->name);
        pthread_mutex_unlock(&sem->mutex);
        return 0;
    }
    pthread_mutex_unlock(&sem->mutex);
    return -1; // Semaphore limit reached
}

void release_semaphore(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    if (sem->value > 0) {
        sem_post(sem->sem);
        sem->value--;
        log_operation("Released", sem->name);
    }
    pthread_mutex_unlock(&sem->mutex);
}

int resize_semaphore(Semaphore *sem, int new_max_value) {
    pthread_mutex_lock(&sem->mutex);
    if (new_max_value < sem->max_value) {
        sem_destroy(sem->sem);
        sem_init(sem->sem, 0, new_max_value);
        sem->max_value = new_max_value;
        log_operation("Resized", sem->name);
    }
    pthread_mutex_unlock(&sem->mutex);
    return 0;
}

void list_semaphores() {
    Semaphore *current = sem_list;
    while (current) {
        printf("%s: Value=%d, MaxValue=%d\n", current->name, current->value, current->max_value);
        current = current->next;
    }
}

void cleanup_semaaphores() {
    Semaphore *current = sem_list;
    Semaphore *temp;
    while (current) {
        temp = current;
        destroy_semaphore(temp);
        current = current->next;
    }
}
```

This code provides a basic implementation of a semaphore manager in C, with functions to create, resize, acquire, release, list, and cleanup semaphores. It includes threading safety and logging for operations.']
